\begin{definition}[$\smallintroduce$]\label{def:smallintro}
    Let $\mathcal{T}=(T,\{X_t\}_{t\in V(T)})$ be a \slim $S$-nice tree decomposition of $G$. %a graph $G=(V,E)$ and some $S\subseteq V$. 
    Let $t$ be an $S$-bottom node in $\mathcal{T}$ that admits $S$-operation $\introduce(v)$. Let $t_1$ be the $S$-child of $t$ and let $t_0$ be the parent of $t$. If $X_t=\smallbag(X^S_t,d)$, $X_{t_0}=\nbag(X_t,d,P)$, and $X_{t_1}=\nbag(X_t,d,L)$, then we say that node $t$ admits $S$-operation $\smallintroduce(v,d)$.
\end{definition}


\begin{definition}[$\smalljoin$]\label{def:smalljoin}
    Let $\mathcal{T}=(T,\{X_t\}_{t\in V(T)})$ be a \slim $S$-nice tree decomposition of~$G$. % a graph $G=(V,E)$ and some $S\subseteq V$. 
    Let $t$ be an $S$-bottom node in $\mathcal{T}$ that admits $S$-operation $\join(X_t^S,X_1^S,X_2^S,L_{1}^S, L_{2}^S)$ and is not contained in a full join tree. Let $t_1,t_2$ be the two $S$-children of $t$ and let~$t_0$ be the parent of $t$. If $X_t=\smallbag(X^S_t,d)$, $X_{t_0}=\nbag(X_t,d,P)$, $X_{t_1}=\nbag(X_t,d,L)$, and $X_{t_2}=\nbag(X_t,d,R)$, then we say that node $t$ admits $S$-operation $\smalljoin(X^S_t,X_1^S,X_2^S,L_{1}^S, L_{2}^S,d)$.
\end{definition}

