\title{A Minimal Substitution Basis for the Kalmar Elementary Functions}

\author{Mihai Prunescu \footnote{Research Center for Logic, Optimization and Security (LOS) (Faculty of Mathematics and Computer Science, University of Bucharest, Academiei 14, Bucharest (RO-010014), Romania), e-mail address: {\tt mihai.prunescu@gmail.com}. Simion Stoilow Institute of Mathematics of the Romanian Academy (Research unit 5, P.\ O.\ Box 1-764, Bucharest (RO-014700), Romania), e-mail address: {\tt mihai.prunescu@imar.ro}. Institute of Logic and Data Science (Bucharest, Romania).}, Lorenzo Sauras-Altuzarra \footnote{Kurt Gödel Society, Austria, e-mail address: {\tt lorenzo@logic.at}.}, Joseph M. Shunia \footnote{Wraithwatch, Austin, Texas, United States, e-mail address: {\tt jshunia@gmail.com}.}}

