%\appendix[detailed calculation process of Christoffel symbol and geodesic equation]
\section{Appendix}
\subsection{The case of two-dimensional smooth manifolds in $\mathbb{R}^n$}

The Christoffel symbols are defined as:
$$
\small\begin{aligned}
  \Gamma_{ij}^k =\frac{1}{2} h^{kl}\left(\frac{\partial h_{il} }{\partial x^{j} }+\frac{\partial h_{lj} }{\partial x^i}-\frac{\partial h_{ij} }{\partial x^{l} } \right) 
\end{aligned}
$$

According to Einstein summation convention, they can be calculated in detail as below.

$$\small
\begin{aligned}
\Gamma_{11}^{1}&=\frac{1}{d}\left[1+\sum\limits_{k=3}^n\left(\frac{\partial x_k}{\partial x_2}\right)^2\right]  
\cdot
\left[\sum\limits_{k=3}^n \frac{\partial x_k}{\partial x_1} \cdot\frac{\partial^2 x_k}{\partial x_1 \partial x_1}\right]
-\frac{1}{d} \left[\sum\limits_{k=3}^n\frac{\partial x_k}{\partial x_1}\cdot \frac{\partial x_k}{\partial x_2}\right]
\cdot 
\left[\sum\limits_{k=3}^n\frac{\partial^2 x_k}{\partial x_1\partial x_1}\cdot\frac{\partial x_k}{\partial x_2}\right]\\
\Gamma_{11}^{2}&=-\frac{1}{d}\left[ \sum\limits_{k=3}^n \frac{\partial x_k}{\partial x_1}\cdot\frac{\partial x_k}{\partial x_2}\right]
\cdot
\left[\sum\limits_{k=3}^n \frac{\partial x_k}{\partial x_1}\cdot \frac{\partial^2 x_k}{\partial x_1 \partial x_1}\right]
+\frac{1}{d}\left[1+\sum\limits_{k=3}^n\left(\frac{\partial x_k}{\partial x_1}\right)^2\right]
\cdot
\left[\sum\limits_{k=3}^n\frac{\partial^2 x_k}{\partial x_1 \partial x_1}\cdot\frac{\partial x_k}{\partial x_2}\right]\\
\Gamma_{12}^{1}&=\Gamma_{21}^{1} = \frac{1}{d} \left[ 1+\sum\limits_{k=3}^n \left(\frac{\partial x_k}{\partial x_2}\right)^2\right]
\cdot
\left[\sum\limits_{k=3}^n \frac{\partial x_k}{\partial x_1}\cdot \frac{\partial^2 x_k}{\partial x_1 \partial x_2}\right]
-\frac{1}{d}\left[\sum\limits_{k=3}^n\frac{\partial x_k}{\partial x_1}\cdot \frac{\partial x_k}{\partial x_2}\right]\cdot
\left[\sum\limits_{k=3}^n \frac{\partial x_k}{\partial x_2}\cdot\frac{\partial^2 x_k}{\partial x_1 \partial x_2}\right]\\
\Gamma_{12}^{2}&=\Gamma_{21}^{2} = -\frac{1}{d} \left[\sum\limits_{k=3}^n \frac{\partial x_k}{\partial x_1}\cdot\frac{\partial x_k}{\partial x_2}\right]\cdot
\left[\sum\limits_{k=3}^n \frac{\partial x_k}{\partial x_1}\cdot
\frac{\partial^2 x_k}{\partial x_1 \partial x_2}\right]
+\frac{1}{d} \left[1+\sum\limits_{k=3}^n \left(\frac{\partial x_k}{\partial x_1}\right)^2\right]\cdot
\left[\sum\limits_{k=3}^n \frac{\partial x_k}{\partial x_2}\cdot
\frac{\partial^2 x_k}{\partial x_1 \partial x_2}\right]
\end{aligned}$$
$$
\begin{aligned}
\Gamma_{22}^{1}&= \frac{1}{d} \left[1+\sum\limits_{k=3}^n \left(\frac{\partial x_k}{\partial x_2}\right)^2\right]\cdot
\left[\sum\limits_{k=3}^n \frac{\partial x_k}{\partial x_1}\cdot
\frac{\partial^2 x_k}{\partial x_2 \partial x_2}\right]
-\frac{1}{d} \left[\sum\limits_{k=3}^n \frac{\partial x_k}{\partial x_1}\cdot\frac{\partial x_k}{\partial x_2}\right]\cdot
\left[\sum\limits_{k=3}^n \frac{\partial x_k}{\partial x_2}\cdot
\frac{\partial^2 x_k}{\partial x_2 \partial x_2}\right]\\
\Gamma_{22}^{2}&= -\frac{1}{d} \left[\sum\limits_{k=3}^n \frac{\partial x_k}{\partial x_1}\cdot \frac{\partial x_k}{\partial x_2}\right]\cdot
\left[\sum\limits_{k=3}^n \frac{\partial x_k}{\partial x_1}\cdot \frac{\partial^2 x_k}{\partial x_2 \partial x_2}\right]
+\frac{1}{d}\left[1+\sum\limits_{k=3}^n \left(\frac{\partial x_k}{\partial x_1}\right)^2\right]\cdot
\left[\sum\limits_{k=3}^n \frac{\partial x_k}{\partial x_2}\cdot \frac{\partial^2  x_k}{\partial x_2 \partial x_2}\right]
\end{aligned}$$


Substitute the above eight symbols into the geodesic equation:
$${\small\left\{\begin{aligned}
\frac{d x_1}{d t}=&y_1 \\
\frac{d x_2}{d t}=&y_2 \\
\frac{d y_1}{d t}=&-\left(y_1\right)^2 \Gamma_{11}^{1}-2 y_1 y_2 \Gamma_{12}^{1}-\left(y_2\right)^2 \Gamma_{22}^{1} \\
\frac{d y_2}{d t}=&-\left(y_1\right)^2 \Gamma_{11}^{2}-2 y_1 y_2 \Gamma_{12}^{2}-\left(y_2\right)^2 \Gamma_{22}^{2}
\end{aligned}\right.}$$

\subsection{The case of two-dimensional smooth manifolds in $\mathbb{R}^3$}

Denote the normal distribution surface as $x_3=e^{-\left(x_1^2+x_2^2\right)}$. Calculate the Christoffel symbol as follows.
$$
\small\begin{aligned}
  \Gamma_{11}^1 &=\frac{-8 x_1^3+4 x_1}{e^{2\left(x_1^2+x_2^2\right)}+4 x_1^2+4 x_2^2} ,
  \Gamma_{11}^2 =\frac{-8 x_1^2 x_2+4 x_2}{e^{2\left(x_1^2+x_2^2\right)}+4 x_1^2+4 x_2^2}\\
  \Gamma_{12}^1 &=\Gamma _{21}^{1}=\frac{-8 x_1^2 x_2}{e^{2\left(x_1^2+x_2^2\right)}+4 x_1^2+4 x_2^2},
  \Gamma_{12}^2 =\Gamma_{21}^2=\frac{-8 x_1 x_2^2}{e^{2\left(x_1^2+x_2^2\right)}+4 x_1^2+4 x_2^2}\\
  \Gamma_{22}^1 &=\frac{-8 x_1 x_2^2+4 x_1}{e^{2\left(x_1^2+x_2^2\right)}+4 x_1^2+4 x_2^2},
  \Gamma_{22}^2 =\frac{-8 x_2^3+4 x_2}{e^{2\left(x_1^2+x_2^2\right)}+4 x_1^2+4 x_2^2}
\end{aligned}
$$


A smooth curve $\gamma: I \rightarrow \mathbb{R}^2$ on this surface is geodesic if and only if the curve satisfies geodesic equation below
$$\small{\left\{\begin{aligned}
\frac{d x_1}{d t}=&y_1 \\
\frac{d x_2}{d t}=&y_2 \\
\frac{d y_1}{d t}=&-\left(y_{1}\right)^2 \cdot \frac{-8 x_1^3+4 x_1}{e^{2\left(x_1^2 + x_2^2\right)}+4 x_1^2+4 x_2^2}
-2 y_1 y_2 \cdot \frac{-8 x_1^2 x_2}{e^{2\left(x_1^2+x_2^2\right)}+4 x_1^2+4 x_2^2}
-\left(y_2\right)^2 \cdot \frac{-8 x_1 x_2^2+4 x_1}{e^{2\left(x_1^2+x_2^2\right)}+4 x_1^2+4 x_2^2} \\
\frac{d y_2}{d t}=&-\left(y_1\right)^2 \cdot \frac{-8 x_1^2 x_2+4 x_2}{e^{2\left(x_1^2+x_2^2\right)}+4 x_1^2+4 x_2^2}
-2 y_1 y_2 \cdot \frac{-8 x_1 x_2^2}{e^{2\left(x_1^2+x_2^2\right)}+4 x_1^2+4 x_2^2}
-\left(y_2\right)^2 \cdot \frac{-8 x_2^3+4 x_2}{e^{2\left(x_1^2+x_2^2\right)}+4 x_1^2+4 x_2^2}
\end{aligned}\right.} $$





