\section{Algorithm for Similarly Sized Homothetic Hypercubes in $\IR^d$ Using Points in $\mathbb{Z}^d$} \label{sec: hypercube_upperb}
% In this section, we give a randomized algorithm inspired from~\cite{DeS24b, DumitrescuT22} for hitting homothetic hypercubes in $\IR^d$ using points in $\mathbb{Z}^d$. Also, we present a randomized lower bound of $\Omega(d\log M)$ for the problem. It improves both the current best-known upper bound and deterministic lower bound of $25^d\log M$ and $\Omega(\log M)$, respectively~\cite{AlefkhaniKM23}. Throughout the section, if explicitly not mentioned, all distances are $L_{\infty}$ distances, and all hypercubes are axis-aligned.
% In this section, we give a randomized algorithm inspired from~\cite{DeS24b, DumitrescuT22} for hitting homothetic hypercubes in $\IR^d$ using points in $\mathbb{Z}^d$. It improves both the current best-known upper bound of $25^d\log M$, known due to Alefkhani et al.~\cite{AlefkhaniKM23}. Throughout the section, if explicitly not mentioned, all distances are $L_{\infty}$ distances, and all hypercubes are axis-aligned.\subsection{Upper Bound for $d\geq 3$}\label{hypercube_UB}
In this section, we consider the hitting set problem for similarly sized homothetic hypercubes in $\IR^d$ having {widths} in the range $[1, M]$ using points in $\mathbb{Z}^d$. Note that an axis-aligned hypercube's width is half of its side length.
% Since the value of $\alpha$ is $1$ for axis-aligned hypercubes, the deterministic algorithm $\ANC$ attains a competitive ratio of at most~$4^d({\lfloor}\log_{2} M{\rfloor}+1)$ (due to Theorem~\ref{thm:fat_ub}) for this problem. 
For this, we propose an $O(d^2\log M)$ competitive randomized algorithm $\LIR$. Throughout this section, if explicitly not mentioned, all distances are $L_{\infty}$ distances, and all hypercubes are axis-aligned. We use $\Q_s(\sigma)$ to denote the set $\sigma \cap (s\mathbb{Z})^d$. 


For different values of $s\in \Z$, our algorithm $\LIR$ evokes a randomized iterative reweighting algorithm  $\RIR_s$ as a subroutine. The algorithm $\RIR_s$ considers a sequence of hypercubes of width $s$ as input and uses points of $(s\Z)^d$ to hit them. This algorithm is a generalization of an algorithm in~\cite{DeS24b}.  Here, first, we present a description of the algorithm $\RIR_s$ below.




\vspace{1mm}\noindent\textbf{Algorithm $\RIR_s$.} Let ${\cal I}^{(s)}$ be the set of hypercubes having width $s$, presented to the algorithm $\RIR_s$. Let $\A^{(s)}$ be the set of points chosen by our algorithm such that each hypercube in $\I^{(s)}$ contains at least one point from $\A^{(s)}$. The algorithm maintains two disjoint sets $\A_1^{(s)}$ and $\A_2^{(s)}$ such that $\A^{(s)}= \A_1^{(s)} \cup \A_2^{(s)}$. The algorithm also maintains another set $\B^{(s)}$ of points for bookkeeping purpose; initially, each of the sets $\I^{(s)},\A^{(s)}\text{ and }\B^{(s)}$ are empty. A weight function  $w$ over all integer points from ${(s\mathbb{Z})}^d$ is also maintained by the algorithm; initially, $w(p)=3^{-(d+1)}$, for all points $p \in (s\mathbb{Z})^d$. One iteration of the algorithm is as follows.
Let $\sigma$ be a new hypercube of width $s$; update $\I^{(s)} = \I^{(s)} \cup\{\sigma\}$. 
% \red{Note that $|\Q_s(\sigma)|$ is at least $2^d$ and at most $3^d$.}
\begin{enumerate}
    \item If the hypercube $\sigma$ contains a point from $\A^{(s)}$, then do nothing.
    \item Else if the hypercube $\sigma$ contains a point from $\B^{(s)}$, then let $p\in \B^{(s)}\cap\Q_s(\sigma)$ be an arbitrary point, and update $\A_1^{(s)} = \A_1^{(s)} \cup\{p\}$.
    \item Else if $\sum_{p\in \Q_s(\sigma)} w(p)\geq 1$, then let $p$ be an arbitrary point in $\Q_s(\sigma)$, and update $\A_2^{(s)} = \A_2^{(s)} \cup\{p\}$.
    \item Else, the weights give a probability distribution on $\Q_s(\sigma)$. Successively choose points from $\Q_s(\sigma)$ at random with this distribution in $\lceil\frac{5d}{2}\rceil$ independent trials and add them to $\B^{(s)}$. Let $p\in \B^{(s)}\cap\Q_s(\sigma)$ be an arbitrary point, and update $\A_1^{(s)} = \A_1^{(s)} \cup\{p\}$. Triple the weight of every point in $\Q_s(\sigma)$.
\end{enumerate}



% \noindent \blue{To prove the below lemma, we need to ensure that $|\Q_s(\sigma)|$ is at least $2^d$ and at most $3^d$.}
\begin{lemma}\label{thm:rir}\cite[Theorem~8]{DeS24b}
{For a given $s\in \Z$, the randomized algorithm $\RIR_s$ achieves a competitive ratio of~$O(d^2)$ for hitting hypercubes having width $s$ using points in $(s\mathbb{Z})^d$, where~$d\geq3$.} 
