\vspace{1mm}
\noindent\emph{Identifying Extreme Points.}
Here, we use \emph{$d_{C}(.,.)$ function} (also known as \emph{convex distance function}), induced by a convex object $C$, and its following property~\cite{DeJKS24, IckingKLM95}.
%We refer to~\cite{DeJKS24, IckingKLM95} for the definition of it. 
% Here, we mention the following property of the $d_{C}$ function that we use.

\begin{property}\label{prop:conv}~\cite{DeJKS24}
    Let $C$ be a convex object centered at a point $c$, and let $x,y$ be two points in $\IR^d$. Then, we have the following properties:
    \begin{enumerate}
        \item[(i)] $x\in C$ if and only if $d_C(c,x)\leq 1$. In particular, $x\in \partial C$ if and only if $d_C(c,x)=1$.
        \item[(ii)] $d_C(x,y)=d_{-C}(y,x)$, where $-C$ is a reflected copy of $C$ through the origin.
    \end{enumerate}
\end{property}

Let $p\in\P\cap s$ be a point, and $o_{\tau}$ be the center of a quadrant of the super-square of the tile $s$. 
Let $\bm{\sigma'}(o_{\tau})$ and ${\bm\sigma'}({p})$ be two copies of $-\sigma$, centered at $o_{\tau}$ and  $p$, respectively. {Now, we define the Voronoi diagram for the points in $\P\cap s$ with respect to the $d_{\sigma}$ function, induced by the convex object $\sigma$}.
We define \emph{Voronoi cell} of $p\in \P\cap s$ as $\Cell({p})=\{x\in \IR^2\ |\  {d}_{\sigma}(x,p)\leq {d}_{\sigma}(x,q) \text{~for all } q(\neq p)\in \P\cap s\}$. 
The \emph{Voronoi diagram} is a partition on the plane imposed by the collection of cells of all the points in $\P\cap s$.
Note that one can compute this Voronoi diagram in $O(|\P\cap s|\log(|\P\cap s|))$ time~\cite{ChewD85}.
A point $x$ is in $\Cell({p})$  implies that if we place a homothetic (i.e., translated and scaled) copy $\sigma'$ of $\sigma$ centered at $x$ with a scaling factor $d_{\sigma}(x,p)$, then $\sigma'$ touches  $p$, and the interior of $\sigma'$ does not contain any point of $\P\cap s$. The following lemma offers a method to decide whether $p$ is an extreme point (without knowing the input set $\S$).
\begin{lemma}\label{clm:ext}
A point $p\in \P\cap s$ belongs to $V_{s,\tau}$ if and only if {$\bm{\sigma'}(o_{\tau})\cap \partial {\bm\sigma'}(p)\cap \interior{(\Cell(p))}$} is non-empty.
\end{lemma}
\begin{proof}
For the forward part, let us assume that $p\in V_{s,\tau}$. Due to the definition of  extreme points, {there exists an object $\sigma'\in D_{s,\tau}$} such that 
$p\in\partial\sigma'$ and $ \sigma'\cap s\cap\P=\{p\}$. Let $c$ be the center of $\sigma'$. To show $\bm{\sigma'}(o_{\tau})\cap \partial {\bm\sigma'}(p)\cap \interior{(\Cell(p))}$ is non-empty, we will show that $c\in\bm{\sigma'}(o_{\tau})\cap \partial {\bm\sigma'}(p)\cap \interior{(\Cell(p))}$. 
Since $\sigma'$ does not contain any point other than $p$ from $\P\cap s$, the distance $d_{\sigma}(c,p)$ is strictly less than $d_{\sigma}(c,q)$, where $q(\neq p)$ is any point in $\P\cap s$. As a result, we have $c\in \interior(\Cell(p))$.
Since $o_{\tau}\in \sigma'$ (respectively, $p\in\partial\sigma'$ ), we have $d_{\sigma}(c,o_{\tau})\leq1$ (respectively, $d_{\sigma}(c,p)=1$).
Due to Property~\ref{prop:conv}, we have $d_{-\sigma}(o_{\tau},c)=d_{\sigma}(c,o_{\tau})$ (respectively, $d_{-\sigma}(p,c)=d_{\sigma}(c,p)$). Hence, we have $d_{-\sigma}(o_{\tau},c)\leq 1$ (respectively, $d_{-\sigma}(p,c)=1$). Thus,  $c\in\bm{\sigma'}(o_{\tau})$ (respectively, $c\in\partial {\bm\sigma'}(p)$). As a result, we have $c\in\bm{\sigma'}(o_{\tau})\cap\partial {\bm\sigma'}(p)\cap\interior(\Cell(p))$. 

For the converse part, let us assume that $\bm{\sigma'}(o_{\tau})\cap \partial {\bm\sigma'}(p)\cap \interior{(\Cell(p))}$ is non-empty. Let $c\in\bm{\sigma'}(o_{\tau})\cap \partial {\bm\sigma'}(p)\cap \interior{(\Cell(p))}$ be a point.
Since $c\in \bm{\sigma'}(o_{\tau})\cap \partial {\bm\sigma'}(p)$, we have $d_{-\sigma}(o_{\tau},c)\leq1$ and $d_{-\sigma}(p,c)=1$.
Due to Property~\ref{prop:conv}, we have $d_{-\sigma}(o_{\tau},c)=d_{\sigma}(c,o_{\tau})$ (respectively, $d_{-\sigma}(p,c)=d_{\sigma}(c,p)$). Thus,  $d_{\sigma}(c,o_{\tau})=d_{-\sigma}(o_{\tau},c)\leq 1$ (respectively, $d_{\sigma}(c,p)=d_{-\sigma}(p,c)=1$). Hence, $\sigma(c)$, a translated copy of $\sigma$ centered at $c$, contains both $o_{\tau}$ and $p$ ($\in \partial \sigma(c)$). Now, we only need to show that $\sigma(c)$ contains only $p$ from $\P\cap s$. Since $c\in \partial {\bm\sigma'}(p)\cap \interior{(\Cell(p))}$, the distance $d_{\sigma}(c,p)\ (= 1)$ is strictly less than $d_{\sigma}(c,q)$, where $q(\neq p)$ is any other point in $\P\cap s$. As a result, we have $\sigma(c)\cap\P\cap s=\{p\}$. Hence, $p$ is an extreme point.
 \end{proof}


