\vspace{1mm}\noindent\textbf{Preprocessing Procedure for $L_j$.}
Let $\sigma^{j}$ be a regular $k$-gon having diameter $2^j$. (i) Consider the partition $P_{\sigma^{j}}$ of the plane as described above. (ii) For every tile $s$ in $P_{\sigma^{j}}$, compute four sets of extreme points $V_{s,{\tau}}$.
(iii) For each $V_{s,{\tau}}$, construct a path graph $G_{s,\tau}$ over the set $V_{s,{\tau}}$ and then, compute a vertex ranking $c_{s,\tau}$ of the graph $G_{s,\tau}$ that uses $\lfloor\log_2(2|V_{s,\tau}|)\rfloor$ colors~\cite[Proposition~5]{EvenS14}.





\vspace{1mm}\noindent\textbf{Shrunk Set ${\cal K}_{\sigma}$ of a Regular $k$-gon $\sigma$.} Let $\sigma$ be a regular $k$-gon having diameter $w$ such that $2^j\leq w<2^{j+1}$, for some $j\in\mathbb{Z}^{+}\cup\{0\}$. If $w=2^j$, then we set  the shrunk set ${\cal K}_{\sigma}=\{\sigma\}$; otherwise,  ${\cal K}_{\sigma}$ is defined as follows. Let $\sigma_0'$ be a concentric scaled copy of $\sigma$ having diameter $w'=2^j$. Let $c_1,c_2,\ldots,c_k$ be $k$ corners of  $\sigma$. For each $j\in[k]$, we consider an exact copy $\sigma_{j}$  of $\sigma$, and  we shrink $\sigma_j$, keeping $c_j$ as the corner, such that $\sigma_j$ becomes a translated copy of $\sigma_0'$. Let $\sigma_j'$ be the obtained shrunk copy (see Figure~\ref{fig:bounded_scaled}).
We define ${\cal K}_{\sigma}=\{\sigma'_0,\sigma_1',\sigma_2',\ldots,\sigma_k'\}$.
For proof of the following lemma, we refer to Appendix~\ref{App_lem:shrunk}.                     




\begin{lemma}\label{lem:shrunk}
    $\sigma=\cup_{\sigma'\in{\cal K}_{\sigma}} \sigma'$.
\end{lemma}


% \noindent\emph{Algorithm Description.} \label{Algo_HHK}
% \vspace{1mm}
\noindent\textbf{Description of Algorithm $\HHR$.}
We use $ES_{\sigma}$ to denote the algorithm $\ES$ for points in $\IR^2$, and translated copies of $\sigma$.
For each $j\in\mathbb{Z}^{+}\cup\{0\}$, let $L_j$ be the $j$th layer containing all objects with diameters between $[2^j,2^{j+1})$. 
The algorithm maintains a hitting set $\H=\cup_j\H_{j}$ for all objects that have been the part of input so far, where $\H_{j}$ is a hitting set maintained by our algorithm for objects of layer $L_j$ that have been the part of input so far. 
Upon the arrival of a new object $\sigma$, if it is already hit by $\H$, then do nothing. 
Otherwise, first, determine the layer $L_j$ in which the object $\sigma$ belongs. 
If $\sigma$ is the first arrived object from the layer $L_j$, then first proceed with the preprocessing procedure for $L_j$ as described above.
Now, irrespective of whether $\sigma$ is the first object of $L_{j}$ or not, consider the shrunk set ${\cal K}_{\sigma}$ of $\sigma$.
Each with equal probability, a sequence of the shrunk objects $\sigma_0',\sigma_1',\ldots,\sigma_k'$ in ${\cal K}_{\sigma}$ will be selected at random, and the shrunk objects arrive one at a time according to the selected sequence. 
Upon the arrival of each shrunk object of $\K_{\sigma}$, we apply $ES_{\sigma^j}$,
and update $\H_j$ by adding the hitting set for objects in ${\cal K}_{\sigma}$.
Note that to hit $\sigma$, one needs to hit only one of the objects in ${\cal K}_{\sigma}$, but to guarantee the competitive ratio, we hit all the objects in ${\cal K}_{\sigma}$.
Also note that if an (original/ shrunk) object does not contain any points of $\P$, it should be ignored. 
% The pseudo-code of the algorithm is depicted in Algorithm~\ref{alg:cap:bound} (see Appendix~\ref{App_alg:cap:bound}).





\begin{theorem}\label{Theo:Main_Bounded}
    The randomized algorithm $\HHR$ achieves a competitive ratio of {$4m_{\sigma}(k+1)^2\lfloor \log_2 2M \rfloor\lfloor \log_2 2n\rfloor$} for the hitting set problem of homothetic copies of a regular $k$-gon $\sigma$, for $(k\geq 4)$, having diameters in the range $[1, M]$ using $n$ points in $\IR^2$, {where $m_{\sigma}$ is a constant that depends on $k$}.
\end{theorem}

\begin{proof}
    Let $\I$ be a collection of homothetic objects presented to the online algorithm, and let $\I'\subseteq\I$ be the subset of objects that are unstabbed upon their arrivals. Let ${\cal K}=\cup_{\sigma\in{\I'}} {\cal K}_{\sigma}$ and let ${\cal K}'\subseteq{\cal K}$ be the subset of shrunk objects that are unstabbed upon their arrivals.
    For each $j\in\{0,1,\ldots,\lfloor \log M\rfloor\}$, let $\I'_j$ be the collection of all objects in $\I'$ having diameters in the range $\left[2^j, 2^{j+1}\right)$, and ${\cal K}'_j$ be the collection of all objects in ${\cal K}'$ having diameter $2^j$.
    Let $\A$ and $\OO$ represent the hitting sets returned by the online algorithm and the optimum offline algorithm, respectively, for the input sequence~$\I$. Let $x$ be a point in $\OO$. Let $\I'(x)\subseteq \I'$ (respectively, ${\cal K}'(x)\subseteq {\cal K}'$) be the  set of objects that contains the point $x$.
    % Let $\I''(x)\subseteq \I''$ be the  set of objects that contains the point $x$.
    For each $j\in\{0,1,\ldots,\lfloor \log M\rfloor\}$, let $\I'_j(x)=\I'(x)\cap\I'_j$ and  ${\cal K}'_j(x)={\cal K}'(x)\cap{\cal K}'_j$.
    Let $s$ be the tile containing $x$. Let $\A_{s,j}\subseteq \A$ be the set of points the online algorithm explicitly places on the tile $s$ to hit when some object in ${\cal K}'_j(x)$ arrives. 
    % In other words, the set $\A_{s,j}$ is the output given by the algorithm $ES_{\sigma_j}$. 
    Note that ${\cal K}'_{j}(x)$ is the collection of all unstabbed shrunk objects containing the point $x$, and our algorithm places a hitting point for each unstabbed object. Thus, it is easy to observe that $|{\cal K}'_j(x)|\leq |\A_{s,j}|$.
    Due to Lemma~\ref{lem:distinct}, for  objects in ${\cal K}'_j(x)\cap{\cal D}_{s,{\tau}}$ our algorithm places distinct-colored extreme points from $V_{s,{\tau}}$, where $\tau \in [4]$. Due to~\cite[Proposition~5]{EvenS14}, the vertex ranking for $V_{s,\tau}$ uses at most $\lfloor \log_2(2|V_{s,{\tau}}|)\rfloor$ colors. Thus, $|\A_{s,j}| \leq 4\lfloor \log_2(2|V_{s,{\tau}}|)\rfloor$. 
    Since $|{\cal K}'_{j}(x)|\leq |\A_{s,j}|$ and $|\A_{s,j}| \leq 4\lfloor \log_2(2|V_{s,{\tau}}|)\rfloor$, we have $|{\cal K}'_j(x)|\leq 4\lfloor \log_2(2|V_{s,{\tau}}|)\rfloor\leq 4\lfloor \log_2 2n\rfloor$.

% \vspace{-2mm}
% \begin{equation}\label{eqn:log}
%     |{\cal K}'_j(x)|\leq 4\lfloor \log_2(2|V_{s,{\tau}}|)\rfloor\leq 4\lfloor \log_2(2n)\rfloor.
%     % O(\log |V_{s,{\tau}}|)= O(\log n).
% \end{equation}


    Let $\A(X)\subseteq \A$ be the set of points the online algorithm explicitly places on all the tiles to hit when some object in $X\subseteq\I'$ arrives.
    Now, $\mathbb{E}(|\A(\I'(x))|) \leq \sum_{j=0}^{\lfloor \log_2 M \rfloor} \mathbb{E}(|\A(\I_j'(x))|)$.
    Since each object in $\I_j'(x)$ contains $(k+1)$ shrunk objects, and for each shrunk object, the algorithm places at most $m_{\sigma}$ number of points, we have, $\mathbb{E}(|\A(\I_j'(x))|) \leq m_{\sigma}(k+1)\mathbb{E}(|\I_j'(x)|)$.
    Now, we bound the cardinality of $\mathbb{E}(|\I_j'(x)|)$. Due to Lemma~\ref{lem:shrunk} and Markov's inequality, we have that $\mathbb{E}(|\I_j'(x)|) \leq (k+1)\mathbb{E}(|{\cal K}_j'(x)|)$. As a result, $\mathbb{E}(|\A(\I'(x))|) \leq \sum_{j=0}^{\lfloor \log_2 M \rfloor} m_{\sigma}(k+1)^2 \mathbb{E}|{\cal K}_j'(x)| \leq 4m_{\sigma}(k+1)^2\lfloor \log_2 2M \rfloor\lfloor \log_2 2n\rfloor$ (last inequality is due to $|{\cal K}'_j(x)| \leq 4\lfloor \log_2 2n\rfloor$).
    % Due to Lemma~\ref{lem:shrunk}, for any object $\hat{\sigma}\in \I'_j(x)$, we have $\K'_j(x)\cap\K_{\hat{\sigma}}\neq \phi$. From the definition of $\K_{\hat{\sigma}}$, we need at most $(k+1)$ shrunk objects. As a result, we have $|\I'_j(x)| \leq (k+1)|{\cal K}'_j(x)|$. Since for each object in ${\cal K}'_j(x)$, the online algorithm places at most $m_{\sigma}$ number of points, we have $|\A(\I'(x))| \leq \sum_{j=0}^{\lfloor \log M \rfloor} m_{\sigma}(k+1)|{\cal K}'_j(x)| \leq m_{\sigma}(k+1) (\lfloor \log M \rfloor+1)(4\lfloor \log_2(2n)\rfloor) = O(\log n\log M)$ (last equality is due to $|{\cal K}'_j(x)|\leq 4\lfloor \log_2(2n)\rfloor$).
    % \vspace{-3mm}
    % \begin{align*}
    %     |\A(\I'(x))|
    %         \leq&\sum_{j=0}^{\lfloor \log M \rfloor}   m_{\sigma}(k+1)|{\cal K}'_j(x)|\\
    %         % \leq&m_{\sigma}(k+1)(\lfloor \log M \rfloor+1)|{\cal K}'_j(x)|\\
    %         \leq&m_{\sigma}(k+1) (\lfloor \log M \rfloor+1)(4\lfloor \log_2(2n)\rfloor)\tag{Since, $|{\cal K}'_j(x)|\leq 4\lfloor \log_2(2n)\rfloor$}\\
    %         =&O(\log n\log M).
    % \end{align*}
    As  a result, we have $\mathbb{E}(|\A|)\leq \sum_{x\in\OO} \mathbb{E}{|\A(\I'(x))|} \leq \left(4m_{\sigma}(k+1)^2\lfloor \log_2 2M \rfloor\lfloor \log_2 2n\rfloor\right)|\OO|$. Hence, the theorem follows.
\end{proof}

