\subsection{Missing Proof of Lemma~\ref{obs: homothetic child node relation}}\label{App_obs: homothetic child node relation}

\noindent
$\blacktriangleright$ 
\textbf{Lemma~\ref{obs: homothetic child node relation}.} 
        \textit{Let $N$, $N'$ and $N''$ be three nodes of the tree $\T$ such that $N'$ and $N''$ are the two children of $N$. Also, let $\sigma'$ and $\sigma''$ be two hypercubes corresponding to the nodes $N'$ and $N''$, respectively. Then, $\sigma'$ and $\sigma''$ are interior disjoint.}

    \begin{proof}
        Let $N=N^{k,l}_{i,j}$ for some $k\in[\log_4 M]$, $l\in [2^{d(k-1)}]$, $i\in [d]$ and $j\in [2^{i-1}]$. First, consider the case when $N=N^{k,l}_{i,j}$ is an internal node of $T^{k,l}_{B}$, i.e., 
       $k\in[\log_4 M]$, $l\in [2^{d(k-1)}]$, $i\in [d-1]$ and $j\in [2^{i-1}]$. Then, we have $N'=N^{k,l}_{i+1,2j-1}$ and $N''=N^{k,l}_{i+1,2j}$, and the two hypercubes $\sigma'$ and $\sigma''$ are centered at points $c^{k,l}_{i+1,2j-1}$ and $c^{k,l}_{i+1,2j}$, respectively, having a width $\frac{M}{4^{k-1}}$. Recall that $c^{k,l}_{i+1,2j-1}=c^{k,l}_{i,j}+\frac{M}{4^{k-1}}{\bf e}_{i}$ and $c^{k,l}_{i+1,2j}=c^{k,l}_{i,j}-\frac{M}{4^{k-1}}{\bf e}_{i}$. Thus, the centers of the two hypercubes $\sigma'$ and $\sigma''$ only differ in the $i$th coordinate, and the distance between them is exactly $\frac{2M}{4^{k-1}}$. Since both $\sigma'$ and $\sigma''$ are of width $\frac{M}{4^{k-1}}$,  they are interior disjoint.

        Now, consider the case when $N=N^{k,l}_{d,j}$ is a leaf node of $T^{k,l}_{B}$, i.e., $k\in[\log_4 M-1]$, $l\in [2^{d(k-1)}]$ and $j\in [2^{d-1}]$. Then, we have $N'=N^{k+1,2^d(l-1)+2j-1}_{1,1}$ and $N''=N^{k+1,2^d(l-1)+2j}_{1,1}$, and  the two hypercubes $\sigma'$ and $\sigma''$ are centered at points $c^{k+1,2^d(l-1)+2j-1}_{1,1}$ and $c^{k+1,2^d(l-1)+2j}_{1,1}$, respectively, having a width $\frac{M}{4^{k}}$. Recall that $c^{k+1,2^d(l-1)+2j-1}_{1,1}=\frac{c^{k,l}_{1,1}+c^{k,l}_{d,j}}{2}+\frac{M}{2^{2k-1}}{\bf e}_{d}$ and $c^{k+1,2^d(l-1)+2j}_{1,1}=\frac{c^{k,l}_{1,1}+c^{k,l}_{d,j}}{2}-\frac{M}{2^{2k-1}}{\bf e}_{d}$. Thus, the centers of the two hypercubes $\sigma'$ and $\sigma''$ only differ in the $d$th coordinate, and the distance between them is exactly $\frac{M}{2^{2k-2}}=\frac{4M}{4^{k}}$. Since both $\sigma'$ and $\sigma''$ are of width $\frac{M}{4^{k}}$, they are interior disjoint.
    \end{proof}





