\begin{claim}\label{clm: r closest point}
    The point $r$ is the closest point of $(2^{i+1}\mathbb{Z})^d$ from the centre $c$.
\end{claim}

\begin{proof}
    Let $r'(\neq r)$ be any point of $(2^{i+1}\mathbb{Z})^d$.
    % Then, the point $r'$ can be written as $ r'=a_1{\bf e}_1+a_2{\bf e}_2+\ldots+a_d{\bf e}_d$, where $a_j\in2^{i+1}\mathbb{Z}$ and ${\bf e}_j$ is the standard unit vector, for all $j\in[d]$.
    Notice that for any $j\in[d]$, we have 
    \begin{align*}
    |r'(x_j)-c(x_j)|&=|r'(x_j)- z_j-f_j|\tag{$c(x_j)=z_j+f_j$, where $z_j\in 2^{i+1}\mathbb{Z}$ and $f_j\in\left[0,2^{i+1}\right)$}\\
        &\geq ||r'(x_j)-z_j|-|f_j||\tag{Reverse triangle inequality, i.e., $|a-b|\geq||a|-|b||$}\\
        &\geq|0-|f_j||=|f_j| \tag{Since $r'(x_j)\in(2^{i+1}\mathbb{Z})^d$, we have $|r'(x_j)-z_j|\geq 0$}\\
        &\geq|r(x_j)-c(x_j)|\tag{As per the construction of $r$, $|r(x_j)-c(x_j)|\leq|f_j|$}. 
    \end{align*}

    Since for each $j\in[d]$, we have $|r'(x_j)-c(x_j)|\geq |r(x_j)-c(x_j)|$,  the point $r$ is the closest point of $(2^{i+1}\mathbb{Z})^d$ from the center $c$. Hence, the claim follows.
\end{proof}



