% \noindent\emph{Analysis of the Algorithm.}
In the following lemma, it is demonstrated that upon the arrival of two unstabbed translated copies of $\sigma$ that have a common point $p\in s$ and are of the same type $\tau$, then they are stabbed by extreme points in $V_{s,{\tau}}$ of different colors. We prove this by using the Lemma~\ref{lem:interval}.



\vspace{1mm}\noindent
$\blacktriangleright$ \textbf{Lemma~\ref{lem:distinct}.}\label{App_lem:distinct}
\textit{For any $\tau\in[4]$, if  $\sigma_i,\sigma_j\in{\cal D}_{s,{\tau}}$ are unstabbed upon their arrivals, and there exists a point $p\in \sigma_i\cap \sigma_j\cap\P \cap s$, then $c_{s,\tau}(v_{s,\sigma_i})\neq c_{s,\tau}(v_{s,\sigma_j})$.}
% \begin{lemma}\label{lem:distinct}
    % For any $\tau\in[4]$, if  $\sigma_i,\sigma_j\in{\cal D}_{s,{\tau}}$ are unstabbed upon their arrivals, and there exists a point $p\in \sigma_i\cap \sigma_j\cap\P \cap s$, then $c_{s,\tau}(v_{s,\sigma_i})\neq c_{s,\tau}(v_{s,\sigma_j})$.
% \end{lemma}
\begin{proof}
    Assume for a contradiction that $c_{s,\tau}(v_{s,\sigma_i})=c_{s,\tau}(v_{s,\sigma_j})$. According to Lemma~\ref{lem:interval}, the intersection $\sigma_i\cap V_{s,{\tau}}$ is an interval, i.e., $\sigma_i\cap V_{s,{\tau}}=I_i=[a_i, b_i]$. Likewise, $I_j=[a_j, b_j]$ represents the interval for $\sigma_j\cap V_{s,{\tau}}$. Given that $I_i=[a_i, b_i]$ and $I_j=[a_j, b_j]$ are both intervals having a common point, thus $I_i\cup I_j$ is also an interval. 
    According to the definition of vertex ranking, $I_i\cup I_j$ contains a vertex $k$ having color $c(k)$ such that $c(k)>c_{s,\tau}(v_{s,\sigma_i})$. Now, either $I_i$ or $I_j$ contains the vertex $k$. W.l.o.g., let us assume that $I_i$ contains the vertex $k$ having color $c(k)$ such that $c(k)>c_{s,\tau}(v_{s,\sigma_i})$. But according to our algorithm, $c_{s,\tau}(v_{s,\sigma_i})$ is the largest color in $I_i$. This leads to a contradiction.
\end{proof}


