\begin{proof}
    Observe Figure~\ref{fig:clm_3} and consider the right angle triangle $\triangle b'fc$ right angled at $\angle b'fc$. Since we partition $\sigma$ using $k$ congruent kites, the angle $\angle b'cd'=\frac{2\pi}{k}$.  As a result, the angle $\angle b'cf=\frac{\pi}{k}$. Thus, due to the angle sum property of a triangle, we have $\angle cb'f=\left(\frac{\pi}{2}-\frac{\pi}{k}\right)$.

    Now, using the law of sines, we have the following

   \begin{align*}
       d(f,b')&=d(f,c)\frac{\sin \left(\frac{\pi}{k}\right)}{\sin \left(\frac{\pi}{2}-\frac{\pi}{k}\right)}\leq d(f,c)\frac{\sin \left(\frac{\pi}{k}\right)}{\cos \left(\frac{\pi}{k}\right)}\tag{$\sin \left(\frac{\pi}{2}-\theta\right)=\cos (\theta)$}\\
        &\leq (r_{out}-r_{out}'-r_{in}')\frac{\sin \left(\frac{\pi}{k}\right)}{\cos \left(\frac{\pi}{k}\right)}\tag{$d(f,c)=r_{out}-r_{out}'-r_{in}'$}\\
        &\leq \left(r_{out}-\frac{r_{out}}{2}-\frac{r_{in}}{2}\right)\frac{\sin \left(\frac{\pi}{k}\right)}{\cos \left(\frac{\pi}{k}\right)}\tag{$r_{out}'\geq \frac{r_{out}}{2}$ and $r_{in}'\geq \frac{r_{in}}{2}$}\\
        &\leq \left(\frac{r_{out}}{2}-\frac{r_{out}\cos\left(\frac{\pi}{k}\right)}{2}\right)\frac{\sin \left(\frac{\pi}{k}\right)}{\cos \left(\frac{\pi}{k}\right)}\tag{$r_{in}= r_{out}\cos\left(\frac{\pi}{k}\right)$}\\
        &\leq \frac{r_{out}}{2}\left(\frac{1}{\cos \left(\frac{\pi}{k}\right)}-1\right)\sin \left(\frac{\pi}{k}\right)\\
         &< \frac{r_{out}}{2}\left(\sqrt{2}-1\right)\sin \left(\frac{\pi}{k}\right)<\frac{r_{out}}{2}\sin \left(\frac{\pi}{k}\right)\tag{$\frac{1}{cos\left(\frac{\pi}{k}\right)}\leq \sqrt{2}$, for $k\geq 4$}\\
          &< \frac{s}{4}\tag{Since $s=2r_{out}\sin\left(\frac{\pi}{k}\right)$ }\\
          &< \frac{s'}{2} \tag{Since $s'\geq \frac{s}{2}$}.
   \end{align*}
\end{proof}

