\begin{proof}
    See Figure~\ref{fig:clm_3} and consider the right angle $\angle b'fc$. Recall that the angle $\angle b'cf=\frac{\pi}{k}$, $\angle b'fc=\frac{\pi}{2}$ and $\angle cb'f=\left(\frac{\pi}{2}-\frac{\pi}{k}\right)$.

    Now, using the law of sines, we have the following

   \begin{align*}
       d(b',c)&=d(f,c)\frac{\sin \left(\frac{\pi}{2}\right)}{\sin \left(\frac{\pi}{2}-\frac{\pi}{k}\right)}\leq d(f,c)\frac{1}{\cos \left(\frac{\pi}{k}\right)}\tag{$\sin\left(\frac{\pi}{2}\right)=1$ and $\sin \left(\frac{\pi}{2}-\theta\right)=\cos (\theta)$}\\
        &\leq \frac{(r_{out}-r_{out}'-r_{in}')}{\cos \left(\frac{\pi}{k}\right)}\tag{$d(f,c)=r_{out}-r_{out}'-r_{in}'$}\\
        &\leq \frac{1}{\cos \left(\frac{\pi}{k}\right)}{\left(r_{out}-\frac{r_{out}}{2}-\frac{r_{in}}{2}\right)}=\frac{1}{\cos \left(\frac{\pi}{k}\right)}{\left(\frac{r_{out}}{2}-\frac{r_{in}}{2}\right)}\tag{$r_{out}'\geq \frac{r_{out}}{2}$ and $r_{in}'\geq \frac{r_{in}}{2}$}\\
        &\leq \frac{1}{\cos \left(\frac{\pi}{k}\right)}{\left(\frac{r_{in}}{2\cos \left(\frac{\pi}{k}\right)}-\frac{r_{in}}{2}\right)}\tag{$r_{in}= r_{out}\cos\left(\frac{\pi}{k}\right)$}\\
         &\leq \sqrt{2}{\left(\frac{r_{in}\sqrt{2}}{2}-\frac{r_{in}}{2}\right)}\tag{$\frac{1}{cos\left(\frac{\pi}{k}\right)}\leq \sqrt{2}$, for $k\geq 4$}\\
         &\leq \frac{r_{in}}{2}{\left(2-\sqrt{2}\right)}< \frac{r_{in}}{2}\tag{Since $r_{in}'\geq \frac{r_{in}}{2}$}\\
         &< r_{in}'\tag{Since $r_{in}'\geq \frac{r_{in}}{2}$}.
   \end{align*}
\end{proof}

    Due to Claim~\ref{clm:tri}, we have $d(b',c)\leq r_{in}'$. As a result, all points $b',c$ and $d'$ lie in $\sigma_0'$. Thus, $\sigma_0'$ contains $\triangle b'cd'$. Notice that $\cup_{i\in[k]} C_i=\sigma$ and $C_i\subseteq\sigma_i'\cup\sigma_0'$. Thus, $\sigma\subseteq\cup_{\sigma_0'\in K_{\sigma}}\sigma_0'$. Hence, the lemma follows.
\end{proof}





