\subsubsection{\textbf{Pre-processing Algorithm}}
Based on the above techniques, we compute $uscore_{k}(\mathbf{p})$ for each $\mathbf{p} \in \mathbf{P}$ and $k \in [1, k_{max}]$.
Our pre-processing algorithm has the following five steps.
Algorithm \ref{algo:pre-processing} details this pre-processing.

\begin{algorithm}[!t]
    \caption{\textsc{Pre-processing}}
    \label{algo:pre-processing}
    \DontPrintSemicolon
    \KwIn {$\mathbf{U}$, $\mathbf{P}$, and $k_{max}$}

    \textbf{foreach} $\mathbf{u}_{i} \in \mathbf{U}$ and $\mathbf{p}_{j} \in \mathbf{P}$ \textbf{do} Compute $\|\mathbf{u}_{i}\|$ and $\|\mathbf{p}_{j}\|$\;            \label{algo:pre-processing:norm_b}
    Sort $\mathbf{P}$ in descending order of norm\;                                                                                                                     \label{algo:pre-processing:norm_e}
    SVD transformation of $\mathbf{U}$ and $\mathbf{P}$, $\mathbf{U'} \gets \varnothing$, $\mathbf{U''} \gets \varnothing$\;                                            \label{algo:pre-processing:svd_b}
    \textbf{foreach} $\mathbf{u}_{i} \in \mathbf{U}$ and $\mathbf{p}_{j} \in \mathbf{P}$ \textbf{do} Compute $\|\mathbf{u}^{r}_{i}\|$ and $\|\mathbf{p}^{r}_{j}\|$\;    \label{algo:pre-processing:svd_e}
    \ForEach {$\mathbf{u}_{i} \in \mathbf{U}$}{                                                                                                                         \label{algo:pre-processing:uniform_b}
        $\theta \leftarrow 0$   \Comment*[r]{\scriptsize threshold initialization}
        \ForEach {$j \in [1,B_{1} / n]$}{
            \eIf {$|\|\mathbf{u}_{i}\|\|\mathbf{p}_{j}\| > \theta$}{                                                                                                    \label{algo:pre-processing:mips_b}
                \If {$\mathbf{u}^{l}_{i} \cdot \mathbf{p}^{l}_{j} + |\|\mathbf{u}^{r}_{i}\|\|\mathbf{p}^{r}_{j}\| > \theta$}{                                           \label{algo:pre-processing:update_b}
                    Compute $\mathbf{u}_{i} \cdot \mathbf{p}_{j}$\;
                    Update $A_{i}$ and $\theta$ if necessary                                                                                                            \label{algo:pre-processing:update_e}
                }
            }{
                \textbf{break}                                                                                                                                          \label{algo:pre-processing:mips_e}
            }
        }
        \If {$\theta < \|\mathbf{u}_{i}\|\|\mathbf{p}_{j}\|$}{
            Compute $j'$ such that $\theta \geq \|\mathbf{u}_{i}\|\|\mathbf{p}_{j'}\|$\;                                                                                \label{algo:pre-processing:bs}
            Add $\langle \mathbf{u}_{i}, j' + 1 - B_{1} / n\rangle$ into $\mathbf{U'}$\;
        }
    }
    Sort $\mathbf{U'}$ in ascending order of $j + 1 - \frac{B_{1}}{n}$\;
    Determine $\beta$ in Equation (\ref{eq:f_x}) by Equation (\ref{eq:dynamic}), $B' \gets 0$\;                                                                         \label{algo:pre-processing:uniform_e}
    \ForEach {$\mathbf{u}_{i} \in \mathbf{U'}$}{                                                                                                                        \label{algo:pre-processing:dynamic_b}
        $B_{2,i} \gets$ the budget determined by Equation (\ref{eq:f_x})\;
        \ForEach {$j \in [\frac{B_{1}}{n} + 1, \frac{B_{1}}{n} + 1 + B_{2,i} + B']$}{
            \eIf {$\|\mathbf{u}_{i}\|\|\mathbf{p}_{j}\| > A^{k_{max}}_{i}$}{
                Run lines \ref{algo:pre-processing:update_b}--\ref{algo:pre-processing:update_e}
            }{
                $B' \gets \frac{B_{1}}{n} + 1 + B_{2,i} + B' - j$\;
                \textbf{break}
            }
        }
        \textbf{if} $A^{k_{max}}_{i} < \|\mathbf{u}_{i}\|\|\mathbf{p}_{j}\|$ \textbf{then} $pos_{i} \gets j$, Add $\mathbf{u}_{i}$ into $\mathbf{U''}$                  \label{alg:pre-processing:record}
    }
    $uscore_{k}(\mathbf{p}_{i}) \gets 0$ for each $\mathbf{p}_{j} \in \mathbf{P}$ and $k \in [1, k_{max}]$\;                                                            \label{alg:pre-processing:ub_b}
    \ForEach {$\mathbf{u}_{i} \in \mathbf{U''}$}{
        $\lambda^{*}_{i} \gets 0$\;
        \ForEach {$j \in [pos_{i} + 1, m]$}{
            \textbf{if} $\theta \geq \|\mathbf{u}_{i}\|\|\mathbf{p}_{j}\|$ \textbf{then} \textbf{break}\;
            $\lambda \gets \mathbf{u}^{l}_{i} \cdot \mathbf{p}^{l}_{j} + \|\mathbf{u}^{r}_{i}\|\|\mathbf{p}^{r}_{j}\|$\;
            $\lambda^{*}_{i} \gets \max \{\lambda^{*}_{i}, \lambda\}$   \Comment*[r]{\scriptsize Equation (\ref{eq:ip_upper-bound})}
            \ForEach {$k \in [1,k_{max}]$}{
                \textbf{if} $\lambda \geq A_{i}^{k}$ \textbf{then} $uscore_{k}(\mathbf{p}_{i}) \gets uscore_{k}(\mathbf{p}_{i}) + 1$                                    \label{algo:pre-processing:ub}
            }
        }
    }
    \ForEach {$i \in [1, n]$ and $k \in [1, k_{max}]$}{
        \If {$\mathbf{p}_{j}$ is included in the first $k$ elements of $A_{i}$}{
            $uscore_{k}(\mathbf{p}_{j}) \gets uscore_{k}(\mathbf{p}_{j}) + 1$                                                                                           \label{alg:pre-processing:ub_e}
        }
    }
\end{algorithm}

\vs
\noindent
\underline{\textbf{(1) Norm computation} (lines \ref{algo:pre-processing:norm_b}--\ref{algo:pre-processing:norm_e}).}
For each user vector $\in \mathbf{U}$, we compute its norm.
We do the same for each item vector, then sort the item vectors in descending order of norm.
Without loss of generality, we assume that $\|\mathbf{p}_{i}\| \geq \|\mathbf{p}_{i+1}\|$ for each $i \in [1, n-1]$, i.e., $\mathbf{p}_{i}$ is the $i$-th vector in this sort order.

\vs
\noindent
\underline{\textbf{(2) SVD transformation} (lines \ref{algo:pre-processing:svd_b}--\ref{algo:pre-processing:svd_e}).}
Notice that $\mathbf{U}$ and $\mathbf{P}$ respectively are represented as a matrix, where each row and column correspond to a vector and dimension.
Therefore, we can apply SVD (Singular Value Decomposition) to $\mathbf{U}$ and $\mathbf{P}$, then compute $\|\mathbf{u}^{r}_{i}\|$ and $\|\mathbf{p}^{r}_{j}\|$ for each $\mathbf{u}_{i} \in \mathbf{U}$ and $\mathbf{p}_{j} \in \mathbf{P}$.

SVD corresponds to a global re-ordering of the $d$ dimensions \cite{feng2023reinforcement}, and after SVD, the first dimensions of each vector have higher absolute values than those of the remaining dimensions.
Therefore, we have $\mathbf{u}_{i} \cdot \mathbf{p} \approx \mathbf{u}_{i}^{l} \cdot \mathbf{p}^{l}$, suggesting that SVD can make the bound in Inequality (\ref{eq:inc}) tighter.

\vs
\noindent
\underline{\textbf{(3) Uniform budget assignment} (lines \ref{algo:pre-processing:uniform_b}--\ref{algo:pre-processing:uniform_e}).}
We assign $B_{1} / n$ to each user $\mathbf{u}_{i} \in \mathbf{U}$ as a budget.
For each $\mathbf{u}_{i} \in \mathbf{U}$, to obtain the initial $A_{i}$, we run a sequential scan of $\mathbf{P}$ to at most the $\frac{B_{1}}{n}$-th item vectors while applying Inequality (\ref{eq:inc}).
Note that whenever we have $A_{i}^{k_{max}} \geq \|\mathbf{u}_{i}\|\|\mathbf{p}\|$, we stop the scan, since the remaining item vectors cannot be in $\mathbf{S}_{k_{max}}(\mathbf{u}_{i})$.
In this early stop case, we have $A_{i} = \mathbf{S}_{k_{max}}(\mathbf{u}_{i})$.

On the other hand, if $\mathbf{u}_{i}$ does not have this case, $A_{i}$ is not guaranteed to be $\mathbf{S}_{k_{max}}(\mathbf{u}_{i})$.
We then search for the minimum $j$ such that $A_{i}^{k_{max}} \geq \|\mathbf{u}_{i}\|\|\mathbf{p}_{j}\|$, which can be efficiently done by a binary search.
We maintain such user vectors in $\mathbf{U}'$ and sort them in ascending order of $j + 1 - B_{1} / n$.
After that, we determine $\beta$ in Equation (\ref{eq:f_x}) via Equation (\ref{eq:dynamic}).

\vs
\noindent
\underline{\textbf{(4) Dynamic budget assignment} (lines \ref{algo:pre-processing:dynamic_b}--\ref{alg:pre-processing:record}).}
For each $\mathbf{u}_{i} \in \mathbf{U}'$, we assign its next budget via Equation (\ref{eq:f_x}).
Let $f(x_{i}) = B_{2,i}$.
We scan $\mathbf{P}$ from the $(\frac{B_{1}}{n} + 1)$-th item vector to at most the $(\frac{B_{1}}{n} + 1 + B_{2,i})$-th one.
During the scan, we update $A_{i}$.
If we have $A_{i} = \mathbf{S}_{k_{max}}(\mathbf{u}_{i})$ before consuming the assigned budget, we pool the unconsumed budget so that the next user vector can use the pooled budget.
On the other hand, if $\mathbf{u}_{i}$ does not guarantee that $A_{i} = \mathbf{S}_{k_{max}}(\mathbf{u}_{i})$, we record the last accessed position $pos_{i} = (\frac{B_{1}}{n} + 1 + B_{2,i})$ and add $\mathbf{u}_{i}$ into $\mathbf{U}''$.

\vs
\noindent
\underline{\textbf{(5) Upper-bound score computation} (lines \ref{alg:pre-processing:ub_b}--\ref{alg:pre-processing:ub_e}).}
For each user vector $\mathbf{u}_{i} \in \mathbf{U}''$, we have $pos_{i}$, and  $\mathbf{u}_{i}$ has not accessed item vector $\mathbf{p}_{j}$ such that $j \in [pos_{i}+1,m]$.
For such $\mathbf{p}_{j}$, if we have
\begin{equation}
    \mathbf{u}^{l}_{i} \cdot \mathbf{p}^{l}_{j} + \|\mathbf{u}^{r}_{i}\|\|\mathbf{p}^{r}_{j}\| \geq A_{i}^{k}   \label{eq:upper-bound}
\end{equation}
for a given $k \in [1, k_{max}]$, $\mathbf{p}_{j}$ may be included in $\mathbf{S}_{k}(\mathbf{u_{i}})$.
Therefore, we increment $uscore_{k}(\mathbf{p}_{j})$ by one.
For $\mathbf{u}_{i}$ this is done by scanning a set of $\mathbf{p}_{j}$ such that $j \in [pos_{i}+1,m]$ until we have $A^{k_{max}}_{i} \geq \|\mathbf{u}_{i}\|\|\mathbf{p}_{j}\|$.
In addition, we record 
\begin{equation}
    \lambda_{i} = \max_{j \in [pos_{i}+1,m]} (\mathbf{u}^{l}_{i} \cdot \mathbf{p}^{l}_{j} + \|\mathbf{u}^{r}_{i}\|\|\mathbf{p}^{r}_{j}\|),  \label{eq:ip_upper-bound}
\end{equation}
which is the maximum upper-bound of the inner product of $\mathbf{u}_i$ and $\mathbf{p}'$, where $\mathbf{p}' \in \mathbf{P}$ has not been accessed for $\mathbf{u}_i$. 
This will be used in a query phase.
Notice that the above evaluation does not compute inner products and update $A^{i}$, so it is not within the scope of $B$.
Last, for each $k \in [1, k_{max}]$, if $\mathbf{p}$ is included in the first $k$ elements of $A_{i}$, we increment $uscore_{k}(\mathbf{p})$ by one.


\subsubsection{\textbf{Analysis}}
We here analyze the space complexity, time complexity, and correctness of our pre-processing algorithm.

\begin{theorem} \label{theorem:offline}
The space and time complexities of Algorithm \ref{algo:pre-processing} are $O((n+m))d)$ and $O(nm)$, respectively. 
\end{theorem}

\noindent
\textsc{Proof.}
Algorithm \ref{algo:pre-processing} makes (i) the norm of each vector, (ii) a transformed vector for each one, (iii) $A_{i}$ for each $\mathbf{u}_{i} \in \mathbf{U}$, and (iv) $\lambda_{j}$, the value obtained in Equation (\ref{eq:ip_upper-bound}), for each $\mathbf{u}_{j} \in \mathbf{U}''$.
Therefore, we have $O(n+m)$ norm values, $O(n+m)$ $d$-dimensional transformed vectors, $O(n)$ arrays, each of which has $O(k_{max})$ space, and $O(|\mathbf{U}''|)$ values. 
Since $k_{max} = O(1)$ and $|\mathbf{U}''| \leq n$, the space complexity is $O((n+m)d)$.

Next, step (1) needs $O((n+m)d)$ and $O(m\log m)$ times to compute the norm of all vectors and sorting, respectively.
Step (2) needs $O((n+m)d^2)$ and $O((n+m)d)$ times for SVD transformation and norm computation, respectively.
By setting $B = O(nk_{max})$, step (3) needs $O(nk_{max}d + |\mathbf{U}'|\log m + |\mathbf{U}'|\log |\mathbf{U}'|) = O(n(k_{max}d + \log m + \log n))$ time.
Because Equation (\ref{eq:dynamic}) can be solved in $O(1)$ time, step (4) needs $O(|\mathbf{U}'|k_{max}d) = O(nk_{max}d)$ time.
Last, step (5) needs $O(\sum_{|\mathbf{U}''|}(m - pos_{i})) = O(nm)$ time in the worst case.
Summarizing the time complexities of steps (1)--(5) with the fact of $d \ll n,m$, the time complexity of Algorithm \ref{algo:pre-processing} is $O(nm)$.
\wsq

\begin{remark}
Theorem \ref{theorem:offline} shows that our pre-processing obtains upper-bound scores as if without inner product computations, since its time complexity does not have a factor of $d$.
This means that our pre-processing algorithm is much faster than a brute-force-like upper-bounding approach that needs $O(nmd)$ time, as $d$ is usually hundreds.
In addition, thanks to the dynamic assignment approach, many user vectors can have $\mathbf{S}_{k_{max}}(\cdot)$ in pre-processing.
This means that $|\mathbf{U}''| \ll n$, so Algorithm \ref{algo:pre-processing} practically scales better than $O(nm)$.
\end{remark}

\begin{theorem}
Algorithm \ref{algo:pre-processing} guarantees that $uscore_{k}(\mathbf{p}) \geq score_{k}(\mathbf{p})$ for each $k \in [1, k_{max}]$ and $\mathbf{p} \in \mathbf{P}$.
\end{theorem}

\noindent
\textsc{Proof.}
To prove this theorem, it is sufficient to show that whenever $\mathbf{p}$ is in $\mathbf{S}_{k}(\mathbf{u}_{i})$, $uscore_{k}(\mathbf{p})$ is incremented by using $A_{i}$.
This is trivially true for $\mathbf{u}_{i}$ such that $A_{i} = \mathbf{S}_{k_{max}}(\mathbf{u}_{i})$.
Hence, we focus on each $\mathbf{u}_{j} \in \mathbf{U}''$, i.e., $\mathbf{u}_{j}$ such that $A_{j}$ is not guaranteed to be $\mathbf{S}_{k_{max}}(\mathbf{u}_{j})$.

Assume that $\mathbf{p} \in \mathbf{S}_{k}(\mathbf{u}_{j})$ is not included in $A_{j}$.
Recall that $uscore_{k}(\mathbf{p})$ is incremented by one if $\mathbf{u}^{l}_{j} \cdot \mathbf{p}^{l} + \|\mathbf{u}^{r}_{j}\|\|\mathbf{p}^{r}\| \geq A_{j}^{k}$, see Inequality (\ref{eq:upper-bound}) and line \ref{algo:pre-processing:ub}.
From Inequality (\ref{eq:inc}) and the assumption of $\mathbf{p} \in \mathbf{S}_{k}(\mathbf{u}_{j})$, we have $\mathbf{u}^{l}_{j} \cdot \mathbf{p}^{l} + \|\mathbf{u}^{r}_{j}\|\|\mathbf{p}^{r}\| \geq \mathbf{u}_{j} \cdot \mathbf{p} \geq A_{j}^{k}$, which proves the correctness of this theorem.
\wsq


\subsection{Query Processing}
Given $N$ and $k$, we compute the top-$N$ result set $\mathbf{R}$, by exploiting the upper-bound scores obtained in pre-processing.
Before presenting our query processing algorithm, we introduce our reverse $k$-MIPS algorithm that exploits the information obtained in our pre-processing.


\subsubsection{\textbf{Incremental Reverse $k$-MIPS Algorithm.}}    \label{sec:proposal:rmips}
Recall that $\mathbf{U}''$ is a set of user vectors $\mathbf{u}_{i}$ such that $A_i$ is not guaranteed to be $\mathbf{S}_{k_{max}}(\mathbf{u}_{i})$ (i.e., its ``$k_{max}$''-MIPS result is not guaranteed).
Even in this case, $A_i$ may contain $\mathbf{S}_{k}(\mathbf{u}_{i})$ (i.e., its ``$k$''-MIPS result is guaranteed), which can be confirmed in $O(1)$ time by using $\lambda_{i}$, because 
\begin{equation}
    \lambda_{i} \geq \max_{j \in [pos_{i}+1,m]} \mathbf{u}_{i} \cdot \mathbf{p}_{j}.    \label{eq:lambda}
\end{equation}
That is, if $A^{k}_{i} \geq \lambda_{i}$, $\mathbf{u}_{i}$ has $\mathbf{S}_{k}(\mathbf{u}_{i})$.
We therefore need to focus only on each user vector that does not have $\mathbf{S}_{k}(\cdot)$.
Let $\mathbf{X}$ be a set of such user vectors.

Given an item vector $\mathbf{p}$, to obtain $score_{k}(\mathbf{p}_{j})$, we need to check whether $\mathbf{p}_{j} \in \mathbf{S}_{k}(\mathbf{u}_{i})$ for each $\mathbf{u}_{i} \in \mathbf{X}$.
If $pos_{i} \geq j$ and $\mathbf{p}_{j}$ is not included in the first $k$ elements of $A_{i}$, it is trivial that $\mathbf{p}_{j} \notin \mathbf{S}_{k}(\mathbf{u}_{i})$.
Otherwise, we check whether $\|\mathbf{u}_{i}\|\|\mathbf{p}_{j}\| > A^{k}_{i}$.
If yes, we next check whether $\mathbf{u}_{i}^{l} \cdot \mathbf{p}_{j}^{l} + \|\mathbf{u}_{i}^{r}\|\|\mathbf{p}_{j}^{r}\| > A^{k}_{i}$.
If this is still yes, we compute $\mathbf{u}_{i} \cdot \mathbf{p}_{j}$.
If and only if $\mathbf{u}_{i} \cdot \mathbf{p}_{j} > A^{k}_{i}$ and $\mathbf{u}_{i} \cdot \mathbf{p}_{j} \geq \lambda_{i}$, it is guaranteed that $\mathbf{p}_{j} \in \mathbf{S}_{k}(\mathbf{u}_{i})$.
If $\mathbf{u}_{i} \cdot \mathbf{p}_{j} > A^{k}_{i}$ but $\mathbf{u}_{i} \cdot \mathbf{p}_{j} < \lambda_{i}$, we run a linear scan of $\mathbf{P}$ from the $(pos_{i}+1)$-th item vector to obtain $\mathbf{S}_{k}(\mathbf{u}_{i})$ in the same way in pre-processing.
% In this case, we update $pos_{i}$, which is the last position of inner product computation for $\mathbf{u}_{i}$.
Finally, we return the number of user vectors in $\mathbf{X}$ such that $\mathbf{p}_{j} \in \mathbf{S}_{k}(\cdot)$.
(Once we obtain $\mathbf{S}_{k}(\mathbf{u}_{i})$ for $\mathbf{u}_{i} \in \mathbf{X}$ online, we (i) update the score of the item vectors in $\mathbf{S}_{k}(\mathbf{u}_{i})$ while avoiding duplicate counting and (ii) remove  $\mathbf{u}_{i}$ from $\mathbf{X}$.)

\begin{remark}  \label{remark:rmips}
The above approach is considered as an extended version of Simpfer \cite{amagata2021reverse} because our approach also solves the $k$-MIPS decision problem.
Simpfer is optimized for reverse $k$-MIPS for a given item vector.
That is, it does not consider that Simpfer is conducted for other item vectors $\in \mathbf{P}$ in a sequential manner.
Simply running Simpfer on different item vectors can incur duplicate linear scans for the same user vectors.
Our algorithm avoids such duplication by using $pos_{i}$, which enables incremental scan.
\end{remark}


\subsubsection{\textbf{The Algorithm}}
Now we are ready to introduce our query processing algorithm.
Algorithm \ref{algo:query} describes it, and \textsc{Inc-RMIPS} in Algorithm \ref{algo:query} represents the algorithm in Section \ref{sec:proposal:rmips}.
Our algorithm consists of two steps.

\vs
\noindent
\underline{\textbf{(1) Initialization.}}
We first initialize the score of each $\mathbf{p} \in \mathbf{P}$.
Each $\mathbf{u}_{i} \in \mathbf{U}$ such that $A^{k}_{i} \geq \lambda_{i}$ has $\mathbf{S}_{k}(\mathbf{u}_{i})$.
Hence, for each $\mathbf{p}$ in the first $k$ elements of $A_{i}$, we increment $score_{k}(\mathbf{p})$ by one.
On the other hand, if $A^{k}_{i} < \lambda_{i}$, we add $\mathbf{u}_{i}$ into a set $\mathbf{X}$.
After that, we make a copy of $\mathbf{P}$, denoted by $\mathbf{P}_{cpy}$, and sort the item vectors in $\mathbf{P}_{cpy}$ in descending order of $uscore_{k}(\cdot)$.
Note that $\mathbf{P}$ is used for reverse $k$-MIPS, which requires a norm-based sort order.

\begin{algorithm}[!t]
    \caption{\textsc{Query processing algorithm}}
    \label{algo:query}
    \DontPrintSemicolon
    \KwIn {$\mathbf{U}$, $\mathbf{P}$, $k$, and $N$}

    $\mathbf{R} \gets \varnothing$, $\tau \gets 0$, $\mathbf{X} \gets \varnothing$\;
    \ForEach {$\mathbf{u}_i \in \mathbf{U}$}{
        \eIf {$A_{i}^{k} \geq \lambda_{i}$}{ 
            \ForEach {$\mathbf{p}$ in the first $k$ elements of $A_{i}$}{
                $score_{k}(\mathbf{p}) \gets score_{k}(\mathbf{p}) + 1$
            }
        }{
            Add $\mathbf{u}_{i}$ into $\mathbf{X}$
        }
    }
    $\mathbf{P}_{cpy} \gets \mathbf{P}$\;
    Sort $\mathbf{P}_{cpy}$ in descending order of $uscore_{k}(\cdot)$\;
    \ForEach {$\mathbf{p} \in \mathbf{P}_{cpy}$}{
        \eIf {$uscore_{k}(\mathbf{p}) > \tau$}{
            $score_{k}(\mathbf{p}) \gets score_{k}(\mathbf{p}) +$ \textsc{Inc-RMIPS}$(\mathbf{p}, \mathbf{X}, \mathbf{P}, k)$\;
            Update $\mathbf{R}$ and $\tau$ if necessary
        }{
            \textbf{return} $\mathbf{R}$
        }
    }
\end{algorithm}

\vs
\noindent
\underline{\textbf{(2) Computing the top-$N$ result.}}
We compute the score of each item vector in $uscore_{k}(\cdot)$-based order.
Given an item vector $\mathbf{p}$, we update $score_{k}(\mathbf{p})$ via our reverse $k$-MIPS algorithm introduced above.
After evaluating $N$ item vectors, we obtain an intermediate result set $\mathbf{R}$ and a threshold $\tau$, the current $N$-th largest score.
Assume that we now evaluate the $(N+1)$-th item vector, say $\mathbf{p}'$.
If $uscore_{k}(\mathbf{p}') > \tau$, $\mathbf{p}'$ can be in the final result, so we need to compute $score_{k}(\mathbf{p}')$.
On the other hand, if $uscore_{k}(\mathbf{p}') \leq \tau$, we can guarantee that the current $\mathbf{R}$ is the final result.
Therefore, whenever we have $uscore_{k}(\mathbf{p}') \leq \tau$, we terminate the query processing.

\begin{remark}
Algorithm \ref{algo:query} incurs $O(nk + m\log m + nmd) = O(nmd)$ time because, in the worst case, Algorithm \ref{algo:query} needs to run $k$-MIPS for each user vector (during reverse $k$-MIPS).
However, this rarely occurs in practice, as our experimental results confirm.
Furthermore, this worst case theoretically means that our algorithm is reduced to the baseline algorithm.
This is not a negative result but a positive, because it is theoretically guaranteed that our algorithm cannot be beaten by the baseline.
% (Due to the properties in Remark \ref{remark:rmips}, our algorithm practically has less sequential scan costs than the baseline.)
\end{remark}


\section{Experiment}    \label{sec:experiment}
This section reports our experimental results.
All experiments were conducted on a Ubuntu 22.04 LTS machine with 24GB RAM and 2.8GHz Core i9-10900 CPU.


\subsection{Setting}    \label{sec:experiment:setting}
\noindent
\underline{\textbf{Dataset.}}
We used the following four commonly used real datasets.
\begin{itemize}
    \setlength{\leftskip}{-5.0mm}
    \item   Amazon-Kindle \cite{he2016ups}:
            A rating dataset for books in Amazon Kindle.
            The numbers of users and items are respectively 1,406,890 and 430,530.
    \item   Amazon-Movie \cite{he2016ups}:
            A rating dataset for movies in Amazon.
            The numbers of users and items are respectively 2,088,620 and 200,941.
    \item   MovieLens\footnote{\url{https://grouplens.org/datasets/movielens/}}:
            This is the MovieLens 25M dataset.
            The numbers of users and items are respectively 162,541 and 59,047.
    \item   Netflix\footnote{\url{https://www.cs.uic.edu/liub/Netflix-KDD-Cup-2007.html}}:
            This is a rating dataset used in Netflix Prize.
            The numbers of users and items are respectively 480,189 and 17,770.
\end{itemize}
As with the existing reverse $k$-MIPS works \cite{amagata2021reverse,amagata2023reverse,huang2023sah}, we used Matrix Factorization \cite{chin2016libmf} to generate user and item vectors.
The dimensionality of each vector was 200.

\vs
\noindent
\underline{\textbf{Competitors.}}
We compared our algorithm with the following baselines.
\begin{itemize}
    \setlength{\leftskip}{-5.0mm}
    \item   LEMP \cite{teflioudi2015lemp}:
            A state-of-the-art algorithm that runs $k$-MIPS for each user.
            We used this algorithm to obtain the score of each item vector, as introduced in Section \ref{sec:preliminary:baseline}.
    \item   FEXIPRO \cite{li2017fexipro}:
            A state-of-the-art $k$-MIPS algorithm.
            We ran this algorithm for each user vector, as with LEMP.
    \item   Simpfer \cite{amagata2021reverse}:
            A state-of-the-art reverse $k$-MIPS algorithm.
            We ran this algorithm for each item to obtain its score.
            (We did not run duplicate linear scans of $\mathbf{P}$ for the same users by using $pos_{i}$, for fair comparison.)
\end{itemize}
All algorithms were implemented in C++, compiled by g++ 11.4.0 with -O3 optimization, and single threaded. 
All evaluated algorithms return the exact answer, so our experiments focused on computational time.
We set $k_{max} = 25$ \cite{amagata2021reverse,amagata2023reverse} and $d' = 10$.


\subsection{Pre-processing Result}
We first show that our pre-processing algorithm terminates within a reasonable time.
Table \ref{tab:pre-processing} shows the result.
