\paragraph{Restriction of Functionals  in $H^{-1/2}(\Gamma)$ to $\widetilde{\Gamma}$}
Consider the extension operator $E_{0, \widetilde{\Gamma}} : H^{1/2}(\widetilde{\Gamma}) \to L^2(\Gamma)$, defined by $ 	E_{0,\widetilde{\Gamma}}(v) =v$ on $\widetilde{\Gamma} $, and $ 	E_{0,\widetilde{\Gamma}}(v)=0$ on $\widetilde{\Gamma}^c$.
We define the space $H^{1/2}_{00}(\widetilde{\Gamma})$ as
$	H^{1/2}_{00}(\widetilde{\Gamma}) := \big\{ v \in H^{1/2}(\Gamma) :\,\, E_{0,\widetilde{\Gamma}}(v) \in H^{1/2}(\Gamma) \big\}$, 
equipped with the norm 
\begin{equation}\label{def.normH12}
	\| v \|_{1/2,00,\widetilde{\Gamma}}\, :=\, \|E_{0,\widetilde{\Gamma}}(v)\|_{1/2,\Gamma}\,.
\end{equation}
Its dual space is denoted by $H^{-1/2}_{00}(\widetilde{\Gamma})$.
For any $\varphi \in H^{-1/2}(\Gamma)$, its restriction to $\widetilde{\Gamma}$, denoted as $\varphi|_{\widetilde{\Gamma}}$, is given by:
\begin{equation}\label{def.E0}
	\langle \varphi|_{\widetilde{\Gamma}}, v \rangle_{\widetilde{\Gamma}} := \langle \varphi, E_{0,\widetilde{\Gamma}}(v) \rangle_{\Gamma}\qquad \forall\, v \in H^{1/2}_{00}(\widetilde{\Gamma})\,.
\end{equation}
It follows that $\varphi|_{\widetilde{\Gamma}}\in H^{-1/2}_{00}(\widetilde{\Gamma})$.  Conversely, the boundary condition $ \varphi|_{\widetilde{\Gamma}}=0$ implies that $	\langle \varphi, E_{0,\widetilde{\Gamma}}(v) \rangle_{\Gamma} = 0$ for all $ v \in H^{1/2}_{00}(\widetilde{\Gamma})$.
