\paragraph{Decomposition of $H^{1/2}(\Gamma)$-Functions}
%	For $\zeta \in H^{1/2}(\Gamma)$, it follows from \cite[Lemma 2.2]{gs-ETNA-2007} that there exist unique functions $\zeta_{\widetilde{\Gamma}} \in H^{1/2}(\widetilde{\Gamma})$ and $\zeta_{\widetilde{\Gamma}^c} \in H^{1/2}_{00}(\widetilde{\Gamma}^c)$ such that:
According to \cite[Lemma 2.2]{gs-Elec-2007}, for any $\zeta \in H^{1/2}(\Gamma)$, there exist unique $\zeta_{\widetilde{\Gamma}} \in H^{1/2}(\widetilde{\Gamma})$ and $\zeta_{\widetilde{\Gamma}^c} \in H^{1/2}_{00}(\widetilde{\Gamma}^c)$ satisfying $	\zeta = E_{\widetilde{\Gamma}}(\zeta_{\widetilde{\Gamma}}) + E_{0, \widetilde{\Gamma}^c}(\zeta_{\widetilde{\Gamma}^c})$. 
This yields the decomposition:
\begin{equation}
	\langle \varphi, \zeta \rangle_{\Gamma} = \langle \varphi, E_{\widetilde{\Gamma}}(\zeta_{\widetilde{\Gamma}}) \rangle_{\Gamma} + \langle \varphi, E_{0, \widetilde{\Gamma}^c}(\zeta_{\widetilde{\Gamma}^c}) \rangle_{\Gamma} \quad \forall \varphi \in H^{-1/2}(\Gamma)\,.
\end{equation}

