\begin{equation}\label{eq2}
	\dfrac{1}{\nu}\int_{\Omega}\bdev(\bsi):\bta\,=\,\int_{\Omega}\boldsymbol{\nabla}\bu:\bta\qan \dfrac{1}{\kappa}\int_{\Omega}\brho\cdot\bet  \,=\,\int_{\Omega}\nabla\varphi\cdot\bet \quad\text{for a.e}\,\, t\in \mathrm{J}\,.
