		\mathscr{A}^{C}(\brho , \bet)+\mathscr{B}^{C}(\bet,\vec{\varphi})&= 0\quad \text{for a.e.}\,  t\in \mathrm{J} \,,\\
		\hspace{-.25cm}\disp \int_{\Omega}\partial_t \varphi \, \psi-	\mathscr{B}^{C}(\brho,\vec{\psi})+\mathscr{C}^{C}(\vec{\varphi}, \vec{\psi})-\mathscr{O}^{C}_1 (\bu;\brho,\vec{\psi})+\mathscr{O}^{C}_2(\lambda;\vec{\varphi}, \vec{\psi})&=\mathscr{F}^C(\vec{\psi}) \quad \text{for a.e.}\,  t\in \mathrm{J}  \,,
	\end{split}
\end{equation}
for any $ (\bta, \bv)\in\mathbb{H}\times\mathbf{V} $ and $ (\bet, \vec{\psi})\in \mathbf{H}\times\mathcal{V}$, 
where the bilinear forms 
$ \mathscr{A}^F: \mathbb{H}\times \mathbb{H}\rightarrow \mathrm{R} $, 
$ \mathscr{B}^F: \mathbb{H}\times \mathbf{V}\rightarrow \mathrm{R} $,  
$\mathscr{A}^{C} : \mathbf{H}\times \mathbf{H}\rightarrow \mathrm{R}$,  
$ \mathscr{B}^T: \mathbf{H}\times \mathcal{V}\rightarrow \mathrm{R} $  and
$\mathscr{C}^{C} : \mathrm{Q}\times\mathrm{Q}\rightarrow \mathrm{R}$ are defined as
\begin{equation}\label{def-a-b-tilde-a-tilde-b}
	\begin{array}{rcll}
		\mathscr{A}^F( \bze , \bta )&:=& \disp\frac{1}{\nu}\int_{\Omega}\bdev(\bze) : \bdev(\bta)  \,,\quad &	\mathscr{A}^{C}( \bxi , \bet ):= \disp\frac{1}{\kappa}\int_{\Omega}\bxi \cdot \bet  \,, \\
		\mathscr{B}^F(\bta,\bv)&:=& \disp  \int_{\Omega}\textbf{v}\cdot\bdiv(\bta)\,,   	\quad &
		\mathscr{B}^{C}(\bet, \vec{\psi}):=
		\disp\int_{\Omega}\psi\, \div(\bet)+\langle\bet\cdot\bn,\, \xi\rangle_{\Gamma_{\mathtt{i}}^{c}}  \,,\\
		\mathscr{C}^{C}(\vec{\phi}, \vec{\psi})&:=&a_2\disp\int_{\Gamma_{\mathtt{w}}}\chi\,\xi\,,
	\end{array}
\end{equation}

whereas, for each $ (\bz,\chi)\in\mathbf{V}\times\mathrm{Q} $, $\mathscr{O}_1^{F}(\bz;\cdot,\cdot):\mathbb{H}\times\mathbf{V}\rightarrow\mathbb{R}$, $\mathscr{O}_2^{F}(\bz;\cdot,\cdot):\mathbf{V}\times\mathbf{V}\rightarrow\mathbb{R} $, $\mathscr{O}_1^{C}(\bz;\cdot,\cdot):\mathbf{H}\times\mathrm{Q}\rightarrow\mathbb{R}$ and $\mathscr{O}_2^{C}(\chi;\cdot,\cdot):\mathrm{Q}\times\mathrm{Q}\rightarrow\mathbb{R}$ are the bilinear forms given by
\begin{equation}\label{def-c-tilde-c}
	\begin{array}{rcll}
		\mathscr{O}_1^F(\bz;\bta,\bv) &:=& \disp\frac{1}{\nu} \int_{\Omega}
		(\bdev(\bta)\,\bz)\cdot \bv \,,\quad & 	\mathscr{O}^{C}_1(\bz; \bet , \psi) := \disp\dfrac{1}{\kappa} \int_{\Omega}(\bet\,\bz)\, \psi\,,\\
		\mathscr{O}_2^F(\bz;\bw,\bv)&:=& \disp \mathtt{F}\int_{\Omega}
		|\bz|^{p-2}\,\bw\, \cdot\bv \,,\quad & \mathscr{O}^{C}_2(\chi;\vec{\varphi}, \vec{\psi})\,:=\, a_1 \disp\int_{\Gamma_{\mathtt{w}}}\chi\,\lambda\,\xi \,.
	\end{array}
\end{equation}
Finally, 
given $ \chi\in \mathrm{Q} $, the linear functionals $ \mathscr{F}^F_{\chi}\in \mathbb{H}^{'} $ and 
$\mathscr{F}^C \in  \mathrm{Q}^{'} $ are  defied by
\begin{equation}\label{def-f-tilde-f}
	\begin{array}{c}
		\mathscr{F}_{\chi}^F(\bta) \,:=\,  \langle \bta\bn\,, \, \mathbf{g}+\mathbf{g}^{\chi} \rangle_{\Gamma_{\mathtt{o}}^{c}}\quad\forall\,\bta \in \mathbb{H}\qan
		\mathscr{F}^C(\xi) \,:=\,-\tilde{a}_0 \disp\int_{\Gamma_{\mathtt{w}}}\xi\quad\forall\, \xi\in \mathrm{Q}\,.
	\end{array}
\end{equation}

