\subsection{Preliminaries}

We first state the boundedness of the variational forms in \eqref{eq:v1a-eq:v4}. Using Cauchy-Schwarz, the bilinear forms \(\mathscr{A}^F\), \(\mathscr{A}^C\), and \(\mathscr{B}^F\) are bounded with constants \(c_{\mathscr{A}^F} = \nu^{-1}\), \(c_{\mathscr{A}^C} = \kappa^{-1}\), and \(c_{\mathscr{B}^F} = 1\).  
For any \(\bz \in \mathbf{V}\), from the definitions of \(\mathscr{O}_1^F\), \(\mathscr{O}_2^F\), and \(\mathscr{O}_1^C\) (cf. \eqref{def-c-tilde-c}) and \eqref{eq:bound.tr2}, we have
\begin{subequations}
	\begin{alignat}{2}
		\big| \mathscr{O}_1^F(\bz; \bze, \bv)\big| &\,\leq\, \dfrac{1}{\nu}\Vert \bz\Vert_{\mathbf{V}}\, \Vert\bze\Vert_{\mathbb{H}}\, \Vert\bv\Vert_{\mathbf{V}}\qquad\forall\, (\bze, \bv)\in \mathbb{H}\times\mathbf{V}\,,\label{eq1:bound.c.ct}\\	
		\big| \mathscr{O}_2^F(\bz; \bw, \bv)\big| &\,\leq\, |\Omega|^{(4-p)/4}\Vert \bz\Vert_{\mathbf{V}}^{p-2}\, \Vert\bw\Vert_{\mathbf{V}}\, \Vert\bv\Vert_{\mathbf{V}}\qquad\forall\, \bw, \bv\in \mathbf{V}\,,\label{eq2:bound.c.ct}\\	
		\big|\mathscr{O}^{C}_1(\bz; \bxi, \psi)\big|& \, \leq \, \dfrac{1}{\kappa}\Vert \bz\Vert_{\mathbf{V}}\, \Vert \bxi\Vert_{\mathbf{H}}\, \Vert\psi\Vert_{\mathrm{V}}\qquad\forall\, (\bxi, \psi)\in \mathbf{H}\times\mathrm{V}\,.\label{eq3:bound.c.ct}
	\end{alignat}
\end{subequations}
The boundedness of $\mathscr{B}^{C}$, $\mathscr{C}^{C}$, $\mathscr{O}_2^{C}$, and the functionals $\mathscr{F}_{\lambda}^F$, $\mathscr{F}^C$ is shown in the next lemma.
\begin{lemma}
	There exist positive constants $c_{\mathscr{B}^C}$, $c_{\mathscr{C}^{C}}$, $c_{\mathscr{O}_2^{C}}$, $c_{\mathscr{F}^F}$ and $c_{\mathscr{F}^C}$ such that
	\begin{subequations}\label{bund.BCO2}
		\begin{alignat}{2}
			\big|\mathscr{B}^{C}(\bet,\vec{\psi})\big|\,&\le\, c_{\mathscr{B}^{C}}\,\Vert \bet\Vert_{\mathbf{H}}\,\Vert\vec{\psi}\Vert_{\mathcal{V}}\qquad & \forall\, (\bet,\vec{\psi})\in\mathbf{H}\times\mathcal{V}\,,\label{bund.Bc}\\
			\big|\mathscr{C}^C(\vec{\phi},\vec{\psi})\big|\,&\le\, c_{\mathscr{C}^C}\,\Vert\vec{\psi}\Vert_{\mathcal{V}}\Vert\vec{\psi}\Vert_{\mathbf{V}}\qquad & \forall\, \vec{\phi},\vec{\psi}\in\mathcal{V}\,,\label{bund.Cc}\\
			\big|\mathscr{O}_2^C(\chi;\vec{\lambda},\vec{\xi})\big|\,&\le\, c_{\mathscr{O}_2^C}\,\Vert\chi\Vert_{\mathrm{Q}}\,\Vert\vec{\lambda}\Vert_{\mathcal{V}}\,\Vert\vec{\xi}\Vert_{\mathcal{V}} \qquad & \forall\,\vec{\chi},\vec{\lambda},\vec{\xi}\in\mathcal{V}\,,\label{bund.O2c}
		\end{alignat}
	\end{subequations}
	and
	\begin{subequations}\label{bund.F}
		\begin{alignat}{2}
			\big|\mathscr{F}_{\chi}^F(\bta)\big|\,&\le\, c_{\mathscr{F}^F}\,\Big(\Vert\mathbf{g}\Vert_{1/2,\Gamma_{\mathtt{o}}^c}+a_1\,\Vert\chi\Vert_{\mathrm{Q}}\Big)\Vert\bta\Vert_{\mathbb{H}}\qquad & \forall\, \bta\in\mathbb{H}\,,\label{bund.Ff}\\
			\big|\mathscr{F}^C(\vec{\psi})\big|\,&\le\, c_{\mathscr{F}^C}\,\Vert\vec{\psi}\Vert_{\mathcal{V}}& \forall\, \vec{\psi}\in\mathcal{V}\,.\label{bund.Fc}
		\end{alignat}
	\end{subequations}
\end{lemma}
