			\,=\,\disp\int_{\Omega}\bet\cdot\nabla\tilde{\gamma}_{0}^{-1}\big(E_{0,\Gamma_{\mathtt{i}}^c}(\xi)\big)\,+\, \int_{\Omega}\tilde{\gamma}_{0}^{-1}\big(E_{0,\Gamma_{\mathtt{i}}^c}(\xi)\big)\,\div(\bet)\,,
