\subsection{A fixed point strategy}\label{s:fix}
We begin by  reformulating the variational formulation \eqref{eq:v1a-eq:v4} as a fixed point problem.  For this, we define the operator  $ \mathscr{L}^F:  \mathbf{V} \times \mathrm{Q}\rightarrow \mathbb{H}\times\mathbf{V}$ by
\begin{equation}\label{eq:opr1}
	\mathscr{L}^F(\bz(t), \chi(t))\, =\,\big(\mathscr{L}^F_1(\bz(t), \chi(t)), \mathscr{L}^F_2(\bz(t), \chi(t))\big)\, :=\,
	(\bsi_{\star}(t), \bu_{\star}(t))\,\quad\text{for a.e.}\,  t\in \mathrm{J} \,,
\end{equation}
for each $ (\bz(t), \chi(t))\in \mathbf{V} \times \mathrm{Q} $, where $ (\bsi_{\star}(t), \bu_{\star}(t))\in \mathbb{H}\times\mathbf{V} $ 
%is the unique solution (to be confirmed in Lemma \ref{l_wel.S}) of the following system of equations
satisfying
\begin{equation}\label{eq:subp1}
	\begin{array}{rcll}
		\hspace{-.5cm}	\mathscr{A}^F(\bsi_\star , \bta)+\mathscr{B}^F(\bta, \bu_\star)&=& \mathscr{F}_{\chi}^F(\bta)\quad \text{for a.e.}\,  t\in \mathrm{J}\,,\\
		\hspace{-.5cm}	\disp \int_{\Omega}\partial_t \bu_\star \cdot\bv-\mathscr{B}^F(\bsi_\star,\bv)-\mathscr{O}_1^F(\bz;\bsi_\star, \bv)+\mathscr{O}_2^F(\bz;\bu_\star, \bv)&=&0\quad \text{for a.e.}\,  t\in \mathrm{J}
		\,, 
	\end{array}
\end{equation}
with initial condition $ \bu_{\star}(\cdot,0)=\bu_0 $, for all $(\bta,\bv)\in\mathbb{H}\times\mathbf{V}$.

\smallskip

In turn, we also introduce the operator $ \mathscr{L}^C: \mathbf{V}\times \mathrm{Q}\rightarrow  \mathbf{H}\times\mathcal{V} $ as
\begin{equation}\label{eq:opr2}
	\mathscr{L}^C(\bz(t) , \chi(t))\, =\, \big(\mathscr{L}^C_1(\bz(t) , \chi(t)), \mathscr{L}^C_2(\bz(t) , \chi(t)), \mathscr{L}^C_3(\bz(t) , \chi(t))\big)\,:=\,
	(\brho_{\star}(t), \vec{\varphi}_{\star}(t))\,, 
\end{equation}
for a.e. $ t\in \mathrm{J} $ and each $ (\bz(t), \chi(t))\in\mathbf{V}\times\mathrm{Q} $,	where $ (\brho_{\star}(t), \vec{\varphi}_{\star}(t))=(\brho_{\star}(t), (\varphi_{\star}(t), \lambda_{\star}(t)))\in  \mathbf{H}\times\mathcal{V} $ satisfying
%is the unique solution (to be confirmed in Lemma \ref{l_wel.T}) of the following system of equations
\begin{equation}\label{eq:subp2}
	\begin{array}{rcll}
		\hspace{-.3cm}	\mathscr{A}^{C}(\brho_\star , \bet)+\mathscr{B}^{C}(\bet,\vec{\varphi}_\star)&=&0\quad \text{for a.e.}\,  t\in \mathrm{J}\,,\\
			\hspace{-.3cm}	\disp \int_{\Omega}\partial_t \varphi_\star \, \psi-	\mathscr{B}^{C}(\brho_\star,\vec{\psi})+\mathscr{C}^{C}(\vec{\varphi}_\star, \vec{\psi})-\mathscr{O}^{C}_1 (\bz;\brho_\star,\vec{\psi})
		+\mathscr{O}^{C}_2(\chi;\lambda_\star, \vec{\psi})&=&\mathscr{F}^C(\vec{\psi})\quad \text{for a.e.}\,  t\in \mathrm{J}  \,,
	\end{array}
\end{equation}
with initial condition $ \varphi_{\star}(\cdot,0)=\varphi_{0} $ and each $(\bet,\vec{\psi})\in\mathbf{H}\times\mathcal{V}$. 

Thus, for a.e. $ t\in \mathrm{J} $, defining the operator $ \mathscr{T} :\mathbf{V}\times \mathrm{Q}\rightarrow \mathbf{V}\times \mathrm{Q} $ as
\begin{equation}\label{eq:def.opr.E}
	\mathscr{T}(\bz(t) , \chi(t))\, :=\,  \big( \mathscr{L}_2^F(\bz(t) , \mathscr{L}_3^T(\bz(t), \chi(t))),\, \mathscr{L}_3^T(\bz(t), \chi(t))\big)\quad\forall\, (\bz(t), \chi(t))\in \mathbf{V}\times \mathrm{Q} \,,
\end{equation}

we find out that solving  \eqref{eq:v1a-eq:v4} is equivalent to finding a fixed point of $ \mathscr{T} $, that is, given initial data
$ (\bu_{0}, \varphi_{0})\in \mathbf{V}\times\mathrm{V} $, find $ (\bu(t) , \lambda(t))\in \mathbf{V}\times \mathrm{Q} $ such that
\begin{equation}\label{eq:fixp}
	\begin{array}{l}
		\mathscr{T}(\bu , \lambda)\, =\,(\bu , \lambda)  \qquad \text{for a.e.}\,  t\in \mathrm{J}\,.
	\end{array}
\end{equation}
