Next, we adopted the approach taken from \cite{hjjkr-SIAMNA-2013} to the uncoupled problems \eqref{eq:subp1} and \eqref{eq:subp2}. 
We first need to introduce some notations:  Let
\begin{equation}\label{n1}
	\Big\{\big(\bta_k,\bv_k\big):\quad k\in \mathbb{N}  \Big\} \qan \Big\{\big(\bet_k,(\psi_k,\xi_k)\big):\quad k\in \mathbb{N}  \Big\}\,, 
\end{equation}
be a Hilbert bases
of $ \mathbb{H}\times\mathbf{V}$ and $ \mathbf{H}\times(\mathrm{V}\times\mathrm{Q}) $, respectively and denote $ \mathbb{H}_n \subseteq\mathbb{H} $, $\mathbf{V}_m \subseteq \mathbf{V} $,
and
$ \mathbf{H}_{\tilde{n}} \subseteq\mathbf{H} $, $\mathrm{V}_{\tilde{m}} \subseteq \mathrm{V} $, $ \mathrm{Q}_{\tilde{s}} \subseteq\mathrm{Q}$ 
as finite dimensional subspaces spanned by $ \{\bta_i\}_{i=1}^{n} $, $ \{\bv_j\}_{j=1}^{m} $
and $ \{\bet_k\}_{k=1}^{\tilde{n}} $, $ \{\psi_l\}_{l=1}^{\tilde{m}} $, $ \{\xi_p\}_{p=1}^{\tilde{s}} $ respectively. For each positive integers $ n, m, s, \tilde{n}, \tilde{m}, \tilde{s}  $, and $ (\bz , \chi)\in \mathbf{V}_m \times\mathrm{Q}_{\tilde{s}} $ we let $ \bsi_{\star,n}: \mathrm{J}\rightarrow \mathbb{H}_{n} $, $ \bu_{\star,m}: \mathrm{J}\rightarrow \mathbf{V}_{m} $ and $ \brho_{\star,s}: \mathrm{J}\rightarrow \mathbf{H}_{s} $, $ \vec{\varphi}_{\star,\tilde{m}\tilde{s}}=(\varphi_{\star,\tilde{m}},\lambda_{\star,\tilde{s}}): \mathrm{J}\rightarrow\mathcal{V}_{\tilde{m}\tilde{s}} =\mathrm{V}_{\tilde{m}}\times\mathrm{Q}_{\tilde{s}} $ be the solution of the following problems, respectively,
\begin{equation}\label{eq:subp1.a}
	\begin{array}{rcll}
		\hspace{-.3cm}	\mathscr{A}^F(\bsi_{\star,n} , \bta_i)+\mathscr{B}^F(\bta_i, \bu_{\star,m})&=& \mathscr{F}_{\chi}^F(\bta_i)\quad \text{for a.e.}\,  t\in \mathrm{J}
		\,,
		\\
	\hspace{-.5cm}	\disp \int_{\Omega}\partial_t \bu_{\star,m} \cdot\bv_j-\mathscr{B}^F(\bsi_{\star,n},\bv_{j})-\mathscr{O}_1^F(\bz;\bsi_{\star,n}, \bv_j)
		\,+\,\mathscr{O}_2^F(\bz;\bu_{\star,m}, \bv_j)&=&0  \quad \text{for a.e.}\,  t\in \mathrm{J} \\
		\hspace{-.3cm}	\disp \int_{\Omega}\bu_{\star,m}^{0}\cdot \bv_j&=&\disp \int_{\Omega}\bu_{0}\cdot\bv_j \quad \text{for a.e.}\,  t\in \mathrm{J}\,,
	\end{array}	
\end{equation}
for any $ i=1,\cdots,n $, $ j=1,\cdots,m $ and
\begin{equation}\label{eq:subp2.a}
	\begin{array}{rcll}
		\mathscr{A}^{C}(\brho_{\star,\tilde{n}} , \bet_i)+\mathscr{B}^{C}(\bet_i,\vec{\varphi}_{\star,\tilde{m}\tilde{s}})&=& 0\quad \text{for a.e.}\,  t\in \mathrm{J}
		\,,\\
		\disp \int_{\Omega}\partial_t \varphi_{\star,\tilde{m}} \, \psi_j-	\mathscr{B}^{C}(\brho_{\star,\tilde{n}},\vec{\psi}_{j,k})+\mathscr{C}^{C}(\vec{\varphi}_{\star,\tilde{m}\tilde{s}}, \vec{\psi}_{j,k})&&\\
		-\mathscr{O}^{C}_1 (\bz;\brho_{\star,\tilde{n}},\vec{\psi}_{j,k})+\mathscr{O}^{C}_2(\chi;\lambda_{\star,\tilde{s}}, \vec{\psi}_{j,k})&=&\mathscr{F}^C(\vec{\psi}_{j,k})\quad \text{for a.e.}\,  t\in \mathrm{J}  \,,\\
		\disp \int_{\Omega}\varphi_{\star,\tilde{m}}^{0}\, \psi_j&=&\disp \int_{\Omega} \varphi_{0}\, \psi_j	\,,
	\end{array}	
\end{equation}
for any $ i=1,\cdots,\tilde{n} $, $ j=1,\cdots,\tilde{m} $, $ k=1,\cdots,\tilde{s} $.
\begin{lemma}
Given \( (\bz, \chi) \in \mathbf{V}_m \times \mathrm{Q}_{\tilde{s}} \), and for each \( n, m, s \in \mathbb{N} \), there exist unique solutions \( (\bsi_{\star,n}, \bu_{\star,m}) \) and \( (\brho_{\star,\tilde{n}}, \vec{\varphi}_{\star,\tilde{m}\tilde{s}}) \) to problems~\eqref{eq:subp1.a} and~\eqref{eq:subp2.a}, respectively.
\end{lemma}
\begin{proof}
	First, we introduce the following notations
	\begin{equation}\label{eq:not1}
		\begin{array}{c}
(\mathbf{A}_n)_{ij} \, :=\, \mathscr{A}^F(\bsi_j, \bta_i),\,\,
(\mathbf{B}_{nm})_{ik}\,:=\, \mathscr{B}^F(\bta_i, \bu_{k}),\,\,(\mathbf{O}_{1,mn})_{ik}\,:=\, \mathscr{O}_1^F(\bz;\bsi_{k},\bv_i)\ \,,\\
(\mathbf{D}_m)_{kl}:= \disp\int_{\Omega}\bu_l \cdot \bv_k ,\,\,
(\mathbf{O}_{2,m})_{kl}:= \mathscr{O}_2^F(\bz;\bu_{l},\bv_k)\,,\,\,
(\mathbf{F}_n(t))_i := \mathscr{F}_{\chi}^F(\bta_i),\,\, (\mathbf{U}_0)_k  := \disp\int_{\Omega}\bu_{0}\cdot \bv_k \,\,,
		\end{array}
	\end{equation}
for $i,j=1,\cdots, n,\,\,$  $k,l=1,\cdots,m$	and
	\begin{equation}\label{eq:not2}
		\begin{array}{c}
(\widetilde{\mathbf{A}}_{\tilde{n}})_{ij} \, :=\, \mathscr{A}^{C}(\brho_j, \bet_i),\,\,
(\widetilde{\mathbf{B}}_{1,\tilde{n}\tilde{m}})_{ik}\,:=\, \mathscr{B}^{C}_1(\bet_i, \varphi_k),
\,\,
(\widetilde{\mathbf{D}}_{\tilde{m}})_{kl}\,:=\, \disp\int_{\Omega}\varphi_l \, \psi_k ,\quad
\\[1ex]
(\widetilde{\mathbf{O}}_{1,\tilde{m}\tilde{n}})_{ki}\,:=\, \mathscr{O}^{C}_{1}(\bz;\brho_i,\psi_k),\quad(\widetilde{\mathbf{C}}_{\tilde{s}})_{pq}\,=\, \mathscr{C}^{C}(\lambda_{q}, \xi_p),\,\,\,
(\widetilde{\mathbf{O}}_{2,\tilde{s}})_{pq}\,=\, \mathscr{O}^{C}_2(\chi;\lambda_{q}, \xi_p)\,,\\
(\mathbf{F}_{1,\tilde{n}}(t))_i \,:=\, \mathscr{F}_1^C(\bet_i),\,\,			 \,\,
(\widetilde{\mathbf{B}}_{2,\tilde{n}\tilde{s}})_{iq}\,:=\, \mathscr{B}^{C}_2(\bet_i, \lambda_q),\,\,
(\mathbf{F}_{2,\tilde{s}}(t))_p \,:=\,\mathscr{F}_2^C(\xi_p),\,\,(\boldsymbol{\Phi}_0)_l \, :=\, \disp\int_{\Omega}\varphi_{0}\, \psi_l \,,
		\end{array}
	\end{equation}
	for $i,j = 1,\cdots,\tilde{n},\,\,$ $k,l=1,\cdots,\tilde{m},\,\,$ $p,q=1,\cdots,\tilde{s} $, 
	also we denote by $ \boldsymbol{\Sigma}_{n}(t) $, $ \mathbf{U}_m(t) $, and $ \boldsymbol{\Upsilon}_{\tilde{n}}(t) $, $ \boldsymbol{\Phi}_{\tilde{m}}(t) $, $ \boldsymbol{\Lambda}_{\tilde{s}}(t) $ the vectors of degrees of freedom of $ \bsi_{\star,n}(t) $, $ \bu_{\star,m}(t) $ and $ \brho_{\star,\tilde{n}}(t) $, $ \varphi_{\star,\tilde{m}}(t) $, $ \lambda_{\star,\tilde{s}}(t) $, respectively,  with respect to the bases $ \{\bta_i\}_{i=1}^{n} $, $ \{\bv_j\}_{j=1}^{m} $ and $ \{\bet_k\}_{k=1}^{\tilde{n}} $, $ \{\psi_l\}_{l=1}^{\tilde{m}} $, $ \{\xi_p\}_{p=1}^{\tilde{s}} $, respectively.
	Hence, thanks to the above notations, the matrix form of problems \eqref{eq:subp1.a} and \eqref{eq:subp2.a} may be rewritten as
	\begin{subequations}
		\begin{align}
\mathbf{A}_n\,	\boldsymbol{\Sigma}_{n}(t)+\mathbf{B}_{nm}\,\mathbf{U}_{m}(t)&\,=\, \mathbf{F}_n(t)\,,\label{eq:sub.1a}\\
\mathbf{D}_m\,\dfrac{d\mathbf{U}_m (t)}{dt} -\left(\mathbf{B}_{1,nm}^{\mathtt{t}}+\mathbf{O}_{1,mn}\right)\,\boldsymbol{\Sigma}_{n}(t)-\mathbf{O}_{2,ms}\boldsymbol{\vartheta}_{s}(t)+\mathbf{O}_{3,m}\mathbf{U}_m(t)
&\,=\,	0	\,,\label{eq:sub.1b}\\
\mathbf{U}_m(0) &\,=\, \mathbf{U}_0\,,\label{eq:sub.1c}
		\end{align}
	\end{subequations}
	and
	\begin{subequations}
		\begin{align}
\widetilde{\mathbf{A}}_{\tilde{n}}\,	\boldsymbol{\Upsilon}_{\tilde{n}}(t)+\widetilde{\mathbf{B}}_{1,\tilde{n}\tilde{m}}\,\boldsymbol{\Phi}_{\tilde{m}}(t)+\widetilde{\mathbf{B}}_{2,\tilde{n}\tilde{s}}\,\boldsymbol{\Lambda}_{\tilde{s}}(t)&\,=\, \mathbf{0}\,,\label{eq:sub.2a}\\
\widetilde{\mathbf{D}}_{\tilde{m}}\,
\dfrac{d\boldsymbol{\Phi}_{\tilde{m}} (t)}{dt} -\left(\widetilde{\mathbf{B}}_{1,\tilde{n}\tilde{m}}^{\mathtt{t}}+\widetilde{\mathbf{O}}_{1,\tilde{m}\tilde{n}}\right)\,\boldsymbol{\Upsilon}_{\tilde{n}}(t)&\,=\,\textbf{0}\,,	\label{eq:sub.2b}\\
\widetilde{\mathbf{B}}_{2,\tilde{n}\tilde{s}}^{\mathtt{t}}\, \boldsymbol{\Upsilon}_{\tilde{n}}(t)+
\left(\widetilde{\mathbf{O}}_{2,\tilde{s}}+\widetilde{\mathbf{C}}_{\tilde{s}}\right)\,\boldsymbol{\Lambda}_{\tilde{s}}(t)
&\,=\,	\widetilde{\mathbf{F}}_{\tilde{s}}(t)\label{eq:sub.2d}\\
\boldsymbol{\Phi}_r(0) &\,=\, \boldsymbol{\Phi}_0\,.\label{eq:sub.2c}
		\end{align}
	\end{subequations}
%	Since $ \mathbf{A}_n $ and $ \widetilde{\mathbf{A}}_{\tilde{n}} $ are symmetric and positive definite square matrices of sizes $ n $ and $ \tilde{n} $ due to \eqref{eq:ell.a.at}, then they are invertible.
%	Thus equations \eqref{eq:sub.1a} and \eqref{eq:sub.2a} imply
Since $ \mathbf{A}_n $ and $ \widetilde{\mathbf{A}}_{\tilde{n}} $ are symmetric positive definite (by \eqref{eq:ell.a.at}), they are invertible. Hence, \eqref{eq:sub.1a} and \eqref{eq:sub.2a} imply
	\begin{subequations}
		\begin{alignat}{2}
		\boldsymbol{\Sigma}_{n}(t)
		\,=\,\mathbf{A}_n^{-1}\Big(\mathbf{F}_n(t)-\mathbf{B}_{nm}\,\mathbf{U}_{m}(t)
		\Big)\label{eq:sig}	\qan\\	
%	\end{subequations}
%	and
%	\begin{equation}	
		\boldsymbol{\Upsilon}_{\tilde{n}}(t)\,=\,\widetilde{\mathbf{A}}_{\tilde{n}}^{-1}\,\left( \widetilde{\mathbf{F}}_{1,\tilde{n}}(t)-\widetilde{\mathbf{B}}_{1,\tilde{n}\tilde{m}}\,\boldsymbol{\Phi}_{\tilde{m}}(t)-\widetilde{\mathbf{B}}_{2,\tilde{n}\tilde{s}}\,\boldsymbol{\Lambda}_{\tilde{s}}(t)\right)\,,\label{eq:rho}
		\end{alignat}
	\end{subequations}

	Now, substituting \eqref{eq:sig} and \eqref{eq:rho} into \eqref{eq:sub.1b} and \eqref{eq:sub.2b}-\eqref{eq:sub.2d}, respectively, we deduce that there exist square matrices $\widehat{\mathbf{A}}_m^F$, $\widehat{\mathbf{A}}_{\tilde{m}}^C$ and vectors $\widehat{\mathbf{F}}_m^F$, $\widehat{\mathbf{F}}_{\tilde{m}}^C$ satisfying
	\begin{subequations}
		\begin{alignat}{2}
			\dfrac{d\mathbf{U}_m (t)}{dt}+\widehat{\mathbf{A}}_{m}^F\mathbf{U}_{m}(t)\,=\,\widehat{\mathbf{F}}_{m}^F(t)\,,\label{eq:sub.1b.}\\
			\dfrac{d\boldsymbol{\Phi}_{\tilde{m}} (t)}{dt}+\widehat{\mathbf{A}}_{\tilde{m}}^C\boldsymbol{\Phi}_{\tilde{m}}(t)\,+\,\widehat{\mathbf{B}}_{\tilde{m}\tilde{s}}^C\boldsymbol{\Lambda}_{\tilde{s}}(t)\,=\,\mathbf{0}\,.\label{eq:sub.2b.}
		\end{alignat}
	\end{subequations}	
%	Also, by substituting \eqref{eq:rho} into \eqref{eq:sub.2d}, we obtain the matrix $\widehat{\mathbf{D}}{\tilde{s}}^C$ and the vector $\widehat{\mathbf{G}}{\tilde{s}}^C$ satisfying
Substituting \eqref{eq:rho} into \eqref{eq:sub.2d} gives the matrix $\widehat{\mathbf{D}}_{\tilde{s}}^C$ and vector $\widehat{\mathbf{G}}_{\tilde{s}}^C$ such that
	\begin{equation}\label{eq:sub.2b-}
		\boldsymbol{\Lambda}_{\tilde{s}}(t)\,=\, \widehat{\mathbf{G}}_{\tilde{s}}^C (t)+\widehat{\mathbf{D}}_{\tilde{s}}^C\,\boldsymbol{\Phi}_{\tilde{m}}(t)\,.
	\end{equation}

	Thus, using \eqref{eq:sub.1b.} and substituting \eqref{eq:sub.2b-} into \eqref{eq:sub.2b.}, we obtain for a.e. $t \in \mathrm{J}$
	\begin{equation}\label{n2}
			\dfrac{d\mathbf{U}_m (t)}{dt}+\widehat{\mathbf{A}}_{m}^F\mathbf{U}_{m}(t)\,=\,\widehat{\mathbf{F}}_{m}^F(t)\qan
			\dfrac{d\boldsymbol{\Phi}_{\tilde{m}} (t)}{dt}+\big(\widehat{\mathbf{A}}_{\tilde{m}}^C+\widehat{\mathbf{B}}_{\tilde{m}\tilde{s}}^C\widehat{\mathbf{D}}_{\tilde{s}}^C\big)\boldsymbol{\Phi}_{\tilde{m}}(t)\,=\,-\widehat{\mathbf{G}}_{\tilde{s}}^C (t)
	\end{equation}
	The two systems above are linear first-order ODEs with initial conditions \eqref{eq:sub.1c} and \eqref{eq:sub.2c}, respectively, ensuring the existence of unique solutions $ \mathbf{U}_m(t)\in (C(\mathrm{J}))^{m} $ and $ \boldsymbol{\Phi}_{\tilde{m}}(t)\in (C(\mathrm{J}))^{\tilde{m}} $ with $ \partial_t\mathbf{U}_m \in (L^{2}(\mathrm{J}))^{m}$ and $ \partial_t\boldsymbol{\Phi}_{\tilde{m}}\in (L^{2}(\mathrm{J}))^{\tilde{m}} $ (see e.g. \cite[Theorem 3.8-2]{c-SIAM-2025}). From \eqref{eq:sig}, \eqref{eq:rho} and \eqref{eq:sub.2b-}, the functions $ \boldsymbol{\Sigma}_{n}\in (C(\mathrm{J}))^{n} $, $ \boldsymbol{\Upsilon}_{\tilde{n}}\in (C(\mathrm{J}))^{\tilde{n}} $ and $\boldsymbol{\Lambda}_{\tilde{s}}\in (C(\mathrm{J}))^{\tilde{s}}$ are obtained, with their time derivatives in $(L^{2}(\mathrm{J}))^{n} $,  $(L^{2}(\mathrm{J}))^{\tilde{n}} $ and $(L^{2}(\mathrm{J}))^{\tilde{s}} $, respectively. Consequently, the pairs 	$ (\bsi_{\star,n},\bu_{\star,m}) $ and $ (\brho_{\star,\tilde{n}},\vec{\varphi}_{\star,\tilde{m}\tilde{s}}) $ uniquely solve
	\eqref{eq:subp1.a} and \eqref{eq:subp2.a}.
\end{proof}
