%The operators $\mathscr{L}^F$ and $\mathscr{L}^C$, and consequently $\mathscr{L}$, are well-defined. We now turn our attention to the solvability of  \eqref{eq:fixp}. To proceed, we first identify sufficient conditions under which $\mathscr{L}$ maps a closed ball in $\mathbf{V} \times \mathrm{Q}$ into itself.
\subsection{Solvability of the fixed-point equation}
Since $\mathscr{L}^F$, $\mathscr{L}^C$, and thus $\mathscr{L}$ are well-defined, we now study solvability of \eqref{eq:fixp}. First, we identify conditions ensuring $\mathscr{L}$ maps a closed ball in $\mathbf{V} \times \mathrm{Q}$ into itself.
Thus, denoting \begin{equation*}%\label{def.r}
	\begin{array}{c}
		r_1 \,:=\, \max\bigg\{ \left(\dfrac{\beta_F^2\nu}{8}|\Omega|^{(p-4)/4}\right)^{1/(p-2)},\,\dfrac{\beta_F\nu}{2\sqrt{2}} \bigg\}\,,\quad
		r_2 \,:=\, \max\Big\{\dfrac{\beta_C\kappa}{2\sqrt{3}},\,\dfrac{\beta_C^2\kappa}{12c_{\mathscr{O}_2^C}}\Big\}\qan
		r:=\min\{r_1, r_2\}\,,
	\end{array}
\end{equation*} 
we define
\begin{equation}\label{eq:def.ball}
	\mathbf{W}(r)\,:=\, \Big\{(\bz(t),\chi(t))\in \mathbf{V}\times\mathrm{Q}:\quad \big\Vert(\bz,\chi)\big\Vert_{L^{\infty}(\mathrm{J};\mathbf{V}\times\mathrm{Q})}\,  \leq\, r  \Big\}\,.
\end{equation}

Given $ (\bz,\chi)\in \mathbf{W}(r) $, and bearing in mind the definition of 
$ \mathscr{L} $ (cf. \eqref{eq:def.opr.E}), integration from $ 0 $ to $ t\in \mathrm{J} $ along with the a {\it priori} estimates \eqref{eq:apr1} and \eqref{eq:apr2}, yields
\begin{equation}\label{eq:l2}
	\begin{array}{c}
		\big\Vert \mathscr{T}(\bz,\chi)\big\Vert_{L^{\infty}(\mathrm{J};\mathbf{V}\times\mathrm{Q})}^{2}
		\, \leq\, 2\left(\big\Vert \mathscr{L}^F_2(\bz , \mathscr{L}^C_3(\bz, \chi))\big\Vert_{L^{\infty}(\mathrm{J};\mathbf{V})}^{2}+\big\Vert \mathscr{L}^C_3(\bz, \chi)\big\Vert_{L^{\infty}(\mathrm{J};\mathrm{Q})}^{2}\right)\\[1ex]
%		\,\leq\,2 \mathcal{C}_{\mathscr{L}^F}^2 \mathcal{N}_{F}(\bu_{0},\mathbf{g},\mathscr{L}^C_3(\bz, \chi))+2\Vert\mathscr{L}^C_3(\bz, \chi)\Vert_{L^{\infty}(\mathrm{J};\mathrm{Q})}^2\\[1ex]
%		\,\leq\,2 \mathcal{C}_{\mathscr{L}^F}^2 \mathcal{N}_{F}(\bu_{0},\mathbf{g}) + 2 (\mathcal{C}_{\mathscr{L}^F}^2+1)\mathcal{C}_{\mathscr{L}^C}^2\mathcal{N}_{T}(\varphi_{0},c_{\mathscr{F}^C})\\[1ex]
		\,\le\,\mathcal{C}_{\mathscr{T}}\widetilde{\mathcal{N}}(\bu_{0},\varphi_{0},\mathbf{g},c_{\mathscr{F}^C})\,,
	\end{array}
\end{equation}

where $ \mathcal{C}_{\mathscr{T}} = 2\max\big\{\mathcal{C}_{\mathscr{L}^F}^{2},  (\mathcal{C}_{\mathscr{L}^F}^{2}+1)\mathcal{C}_{\mathscr{L}^C}^2 \big\} $ and
$\widetilde{\mathcal{N}}(\bu_{0},\varphi_{0},\mathbf{g},c_{\mathscr{F}^C}):=
\mathcal{N}_F(\bu_{0},\bg,0)+\mathcal{N}_C(\varphi_{0},c_{\mathscr{F}^C})$.

We have therefore proved the following result.	
\begin{lemma}\label{l_cons.W}
	Assume that the data are sufficiently small so that there hold 
	\begin{equation}\label{eq:as1.data}
		\begin{array}{c}
			\mathcal{C}_{\mathscr{T}}\,\widetilde{\mathcal{N}}(\bu_{0},\varphi_{0},\mathbf{g},c_{\mathscr{F}^C})\, \le\, r \,,
		\end{array}
	\end{equation}
	then, $ \mathscr{T}(\mathbf{W}(r))\subseteq\mathbf{W}(r) $.
\end{lemma}	
\begin{proof}
	It is a direct consequence of the estimate \eqref{eq:l2}.
\end{proof}
