Then, problem \eqref{eq:v1a-eq:v4} admits a unique solution $ (\bsi(t),\bu(t))\in \mathbb{H}\times\mathbf{V} $ and $ (\brho(t),\vec{\varphi}(t))\in \mathbf{H}\times\mathcal{V} $ with $ (\bu(t),\lambda(t))\in \mathbf{W}(r) $ for a.e.\ $ t\in \mathrm{J} $. Furthermore, the following a~{\it priori} estimates hold:
	\begin{subequations}
		\begin{alignat}{2}
			\Vert\bsi\Vert_{L^{2}(\mathrm{J};\mathbb{H})}+\Vert\bsi\Vert_{L^{\infty}(\mathrm{J};\mathbb{L}^2)}+\Vert\bu\Vert_{L^{\infty}(\mathrm{J};\mathbf{L}^{2})}+\Vert\partial_t\bu\Vert_{L^{2}(\mathrm{J};\mathbf{L}^{2})}+\Vert\bu\Vert_{L^{2}(\mathrm{J};\mathbf{V})}
			\leq \mathcal{C}_{1}\,\widetilde{\mathcal{N}}\big(\bu_{0},\varphi_{0},\mathbf{g},c_{\mathscr{F}^C}\big)\,,\label{eq:apr.est1}\\[1ex]
			\Vert \brho\Vert_{L^{2}(\mathrm{J};\mathbf{H})}+\Vert \brho\Vert_{L^{\infty}(\mathrm{J};\mathbf{L}^2)}+\Vert\varphi\Vert_{L^{\infty}(\mathrm{J};\mathrm{L}^{2})}+\Vert\partial_t \vec{\varphi}\Vert_{L^{2}(\mathrm{J};\mathrm{L}^{2}\times\mathrm{Q})}+\Vert\vec{\varphi}\Vert_{L^{2}(\mathrm{J};\mathrm{V}\times\mathrm{Q})}
			\, \leq\,  \mathcal{C}_{2} \mathcal{N}_T(\varphi_{0},c_{\mathscr{F}^C})\,.\label{eq:apr.est2}
		\end{alignat}
	\end{subequations}
\end{theorem}
\begin{proof}
Recalling from Lemma \ref{l_cons.W} that \eqref{eq:as1.data} ensures $\mathscr{T}$ maps $\mathbf{W}(r)$ into itself, and given the equivalence between \eqref{eq:v1a-eq:v4} and \eqref{eq:fixp}, along with the Lipschitz continuity of $\mathscr{T}$ (cf. \eqref{eq:lip.Xi}) and assumption \eqref{eq:as2.data}, the Banach fixed-point theorem guarantees a unique solution $(\bu(t),\lambda(t)) \in \mathbf{W}(r)$ to \eqref{eq:fixp} for a.e.\ $t \in \mathrm{J}$. Moreover, the a~{\it priori} bounds \eqref{eq:apr.est1}--\eqref{eq:apr.est2} follow directly from \eqref{eq:apr1} and \eqref{eq:apr2}.
\end{proof}
