\subsection{Preliminaries}\label{s.4.1}
Let \( \{\mathcal{T}_h\}_{h>0} \) be a sequence of triangulations of \( \Omega \) into triangles \( T \) with diameters \( h_T \), and define \( h := \max_{T \in \mathcal{T}_h} h_T \) as usual. The induced partition of \( \Gamma_{\mathrm{in}}^{\mathrm{c}} \) is denoted by \( \Gamma_{\mathrm{in}, h}^{\mathrm{c}} \), assumed to have an even number of edges (modified if necessary). The coarser partition \( \Gamma_{\mathrm{in}, 2h}^{\mathrm{c}} \) is formed by merging adjacent edge pairs. For \( k \geq 0 \), let \( \mathrm{P}_k(T) \) be the space of polynomials up to degree \( k \) on \( T \), with vector and tensor counterparts \( \mathbf{P}_k(T) \) and \( \mathbb{P}_k(T) \). The local Raviart–Thomas space of order \( k \) is defined as \( \mathbf{RT}_k(T) := \mathbf{P}_k(T) + \mathrm{P}_k(T) \mathbf{x} \). Using these, we define the finite element spaces for each decoupled problem as follow:
\begin{subequations}
	\begin{alignat}{2}
		\mathbb{H}_{h}&\,:=\, \Big\{
		\bta_h \in \mathbb{H}(\bdiv;\Omega):\quad \bta_{i,h}|_{T}\in\mathbf{RT}_{0}(T),\,\,\,\forall\, i\in \{1,2\},\quad\forall\, T\in\mathcal{T}_{h}\Big\}\cap \mathbb{H}_{\Gamma_{\mathtt{o}}}(\bdiv_{4/3};\Omega)\,,\\
		\mathbf{V}_{h}&\,:=\,\Big\{\bv_{h}\in\mathbf{L}^{2}(\Omega):\quad\bv_{h}|_{T}\in\mathbf{P}_{0}(T)\quad\forall\, T\in\mathcal{T}_{h}\Big\}\,,\\
			\mathbf{H}_{h}&\,:=\,  \Big\{
		\bet_h\in\mathbf{H}(\div;\Omega):\quad \bet_h |_{T}\in \mathbf{RT}_{0}(T)\quad\forall\, T\in\mathcal{T}_h
		\Big\}\,,\\
		\mathrm{V}_h &\,:=\,\Big\{
		\psi_h\in\mathrm{L}^{2}(\Omega):\quad\psi_h |_{T}\in \mathrm{P}_{0}(T)\quad\forall\, T\in \mathcal{T}_h \Big\}\,.
	\end{alignat}
\end{subequations}
