Similarly as for continuous case, we define the space $\mathcal{V}_h\, :=\,\mathrm{V}_h\times\mathrm{Q}_h$		 and set the notation $		\vec{\varphi}_{h}\, :=\, (\varphi_{h} , \lambda_{h})\,,\,\, \vec{\psi}_{h}\,:=\, (\psi_{h} , \xi_{h}) \,,\,\, \vec{\phi}_{h}\,:=\, (\phi_{h} , \chi_{h})\in \mathcal{V}_{h}$.
Next,  applying the backward Euler method with uniform time steps  $ t_n =n \Delta t$, $ n=1,\cdots,N $ and defining $ f^{n}:=f(\cdot,t_n) $, $ \delta_t f^{n}:=(f^{n}-f^{n-1})/\Delta t $  for a generic function $ f $, we derive the fully discrete scheme:
Given initial data $ (\bu_h^0 , \varphi_h^0)\in \mathbf{V}_h \times\mathrm{V}_h $,
find $ (\bsi_h^{n},\bu_h^{n})\in \mathbb{H}_h \times\mathbf{V}_h$ and $ (\brho_h^{n},\vec{\varphi}_h^{n})\in \mathbf{H}_h  \times\mathcal{V}_h$, for each $ n=1,\cdots,N $, such that 
\begin{equation}\label{eq:fuldis-v1a-eq:v4}
	\begin{split}
		\mathscr{A}^{F}(\bsi_h^n , \bta_h)+\mathscr{B}^{F}(\bta_h, \bu_h^n)&= \mathscr{F}_{\lambda_h^n}^{F}(\bta_h)\,,\\
		\disp \int_{\Omega}\delta_t \bu_h^n \cdot\bv_h-\mathscr{B}^{F}(\bsi_h^n,\bv_h)-\mathscr{O}^{F}_1(\bu_h^n;\bsi_h^n, \bv_h)+\mathscr{O}^{F}_2(\bu_h^n;\bu_h^n, \bv_h)&=0   \,,\\
		\mathscr{A}^{C}(\brho_h^n , \bet_h)+\mathscr{B}^{C}(\bet_h,\vec{\varphi}_h^n)&= 0\,,\\
		\disp \int_{\Omega}\delta_t \varphi_h^n \, \psi_h-	\mathscr{B}^{C}(\brho_h^n,\vec{\psi}_h)+\mathscr{C}^{C}(\vec{\varphi}_h^n, \vec{\psi}_h)-\mathscr{O}^{C}_1 (\bu_h^n;\brho_h^n,\vec{\psi}_h)+\mathscr{O}^{C}_2(\lambda_h^n;\vec{\varphi}_h^n, \vec{\psi}_h)&=\mathscr{F}^C(\vec{\psi}_h) \,,
	\end{split}
\end{equation}
for any $ (\bta_h, \bv_h)\in\mathbb{H}_h \times\mathbf{V}_h$ and $ (\bet_h, \vec{\psi}_h)\in \mathbf{H}_h \times\mathrm{V}_h$.

%Then, we adopt the discrete version of the strategy employed in Sec. \ref{s:fix} to analyze the solvability of \eqref{eq:fuldis-v1a-eq:v4}. To this end, we let $ \mathscr{L}^F_{\mathtt{d}}:  \mathbf{V}_{h} \times \mathrm{Q}_{h}\rightarrow \mathbb{H}_h\times\mathbf{V}_h$ be the discrete operator defined by
We adopt the discrete version of the strategy from Sec.~\ref{s:fix} to analyze the solvability of \eqref{eq:fuldis-v1a-eq:v4}, defining the discrete operator \( \mathscr{L}^F_{\mathtt{d}}: \mathbf{V}_{h} \times \mathrm{Q}_{h} \to \mathbb{H}_h \times \mathbf{V}_h \) by
\begin{equation*}%\label{key}
	\mathscr{L}^F_{\mathtt{d}}(\bz_h^{n}, \chi_h^{n})\, =\,\big(\mathscr{L}^F_{1,\mathtt{d}}(\bz_h^{n}, \chi_h^{n}),\, \mathscr{L}^F_{2,\mathtt{d}}(\bz_h^{n}, \chi_h^{n})\big)\, :=\,
	(\bsi_{h,\star}^{n}, \bu_{h,\star}^{n})\,,
\end{equation*}

for each $ 1\leq n \leq N $, and $ (\bz_h^{n}, \chi_h^{n})\in  \mathbf{V}_{h}\times \mathrm{Q}_{h} $, where $ (\bsi_{h,\star}^{n}, \bu_{h,\star}^{n})\in \mathbb{H}_h \times\mathbf{V}_h $ satisfying
\begin{equation}\label{eq:dis.sub1}
	\begin{array}{rcll}
		\mathscr{A}^F(\bsi_{h,\star}^{n} , \bta_h)+\mathscr{B}^F(\bta_h, \bu_{h,\star}^{n})&=& \mathscr{F}^F_{\chi_h^{n}}(\bta_h)\,,\\
		\disp \int_{\Omega}\delta_t \bu_{h,\star}^{n} \cdot\bv_h-\mathscr{B}^F(\bsi_{h,\star}^{n},\bv_h)-\mathscr{O}_1^F(\bz_h^{n};\bsi_{h,\star}^{n}, \bv_h)+\mathscr{O}_2^F(\bz_h^{n};\bu_{h,\star}^{n}, \bv_h)&=&0  \,,
	\end{array}
\end{equation}
for any $ (\bta_h, \bv_h)\in\mathbb{H}_h \times\mathbf{V}_h $, with $\bu_{h,\star}^{0}=\Pcalbf_{0}^{h}\bu_0$.

In addition, we also let $ \mathscr{L}^C_{\mathtt{d}}: \mathbf{V}_{h}\times \mathrm{Q}_{h}\rightarrow  \mathbf{H}_h \times\mathcal{V}_h $ be the discrete operator given by
\begin{equation*}%\label{key}
	\mathscr{L}^C_{\mathtt{d}}(\bz_h^{n}, \chi_h^{n})\, =\, \big(\mathscr{L}^C_{1,\mathtt{d}}(\bz_h^{n}, \chi_h^{n}),\, \mathscr{L}^C_{2,\mathtt{d}}(\bz_h^{n}, \chi_h^{n}),\, \mathscr{L}^C_{3,\mathtt{d}}(\bz_h^{n}, \chi_h^{n})\big)\,:=\,
	(\brho_{h,\star}^{n}, \vec{\varphi}_{h,\star}^{n}) \,,
\end{equation*}

for each $1\leq n\leq N $ and $ (\bz_h^{n}, \chi_h^{n})\in\mathbf{V}_{h}\times \mathrm{Q}_{h} $, where $ (\brho_{h,\star}^{n}, \vec{\varphi}_{h,\star}^{n})\in  \mathbf{H}_h \times\mathcal{V}_h $  satisfying
\begin{equation}\label{eq:dis.sub2}
	\begin{split}
		\mathscr{A}^{C}(\brho_{h,\star}^{n} , \bet_h)+\mathscr{B}^{C}(\bet_h,\vec{\varphi}_{h,\star}^{n})=& \mathscr{F}_1^C(\bet_h)\,,\\
		\disp \int_{\Omega}\delta_t \varphi_{h,\star}^{n} \, \psi_h-	\mathscr{B}^{C}(\brho_{h,\star}^{n},\vec{\psi}_h)+\mathscr{C}^{C}(\lambda_{h,\star}^{n}, \xi_h)-\mathscr{O}^{C}_1 (\bz_h^{n};\brho_{h,\star}^{n},\psi_h)
		+\mathscr{O}^{C}_2(\chi_h^{n};\lambda_{h,\star}^{n}, \xi_h)=&\mathscr{F}_2^C(\xi_h)  \,,
	\end{split}
\end{equation}

for all $ (\bet_h, \vec{\psi}_h)\in \mathbf{H}_h \times\mathcal{V}_h$, with $\varphi_{h,\star}^0 \,=\,\mathcal{P}_0^h(\varphi_{0})$.
\smallskip

Finally, we define $ \mathscr{T}_{\mathtt{d}} :\mathbf{V}_{h}\times\mathrm{Q}_{h}\rightarrow \mathbf{V}_{h}\times\mathrm{Q}_{h}$ as
\begin{equation}\label{eq:def.dis.opr.E}
	\mathscr{T}_{\mathtt{d}}(\bz_h^{n}, \chi_h^{n})\, =\,  \big( \mathscr{L}^F_{2,\mathtt{d}}(\bz_h^{n} , \mathscr{L}^C_{3,\mathtt{d}}(\bz_h^{n}, \chi_h^{n})),\, \mathscr{L}^C_{3,\mathtt{d}}(\bz_h^{n}, \chi_h^{n})\big)\,,
\end{equation}
and realize that solving  \eqref{eq:fuldis-v1a-eq:v4} is equivalent to finding a fixed point of $ 	\mathscr{T}_{\mathtt{d}} $,
i.e., given initial data $ (\bu_h^0 , \varphi_h^0)\in \mathbf{V}_h \times\mathrm{V}_h $, find $ (\bu_{h}^{n},\lambda_{h}^n)\in \mathbf{V}_h\times\mathrm{Q}_h $ such that
\begin{equation}\label{eq:dis.fixp}
	\begin{array}{c}
		\mathscr{T}_{\mathtt{d}}(\bu_h^{n} , \lambda_h^{n})\, =\,(\bu_h^{n} , \lambda_h^{n})\qquad\forall \, 1\leq n\leq N \,.
	\end{array}
\end{equation}
