\subsection{Well-posedness of the discrete operators \( \mathscr{L}^F_{\mathtt{d}} \) and \( \mathscr{L}^C_{\mathtt{d}} \)}
Following Sec.~\ref{sec.2.2}, we establish the well-posedness of discrete systems \eqref{eq:dis.sub1} and \eqref{eq:dis.sub2}. 
First, we recall from \cite[Lemma 4.3]{cgo-NMPDE-2021} the existence of a constant \( \beta_{F,\mathtt{d}} > 0 \), independent of \( h \), such that
\begin{equation}\label{eq:dis.inf.b}
	\sup_{\mathbf{0}\neq \bta_h\in \mathbb{H}_h}\dfrac{\mathscr{B}^F(\bta_h, \bv_h)}{\Vert \bta_h\Vert_{\mathbb{H}}}\,\geq\,\beta_{F,\mathtt{d}}\,\Vert \bv_h\Vert_{\mathbf{V}}\qquad\forall\, \bv_h\in \mathbf{V}_h \,.
\end{equation}

The following result establishes the discrete version of \eqref{eq:inf.bit}.
\begin{lemma}
	There exists a constant $\beta_{C,\mathtt{d}}$, independent of $h$, such that
	\begin{equation}\label{eq:dis.inf.bit}
		\sup_{\mathbf{0}\neq \bet_h\in \mathbf{H}_h}\dfrac{\mathscr{B}^C(\bet_h, \vec{\psi}_h)}{\Vert \bet_h\Vert_{\mathbf{H}}}\,\geq\,\beta_{C,\mathtt{d}}\,\Vert \vec{\psi}_h\Vert_{\mathcal{V}}\qquad\forall\, \psi_h\in \mathcal{V}_h \,.
	\end{equation}
\end{lemma}
\begin{proof}
%	First, we recall from \cite[Lemma 5.2]{gos-IMA-2012} that there exists a constant $\beta_{1,C,\mathtt{d}}>0$, independent of $h$, such that
First, from \cite[Lemma 5.2]{gos-IMA-2012}, there exists a constant \(\beta_{1,C,\mathtt{d}} > 0\), independent of \(h\), such that
	\begin{equation}\label{l1}
		\sup_{\mathbf{0}\neq \bet_h\in \mathbf{H}_h}\dfrac{\mathscr{B}^C(\bet_h, \vec{\psi}_h)}{\Vert \bet_h\Vert_{\div;\Omega}}\,\geq\,\beta_{1,C,\mathtt{d}}\,\left(\Vert\psi_h\Vert_{0,\Omega}+\Vert\xi_{h}\Vert_{\mathrm{Q}}\right)\quad\forall\, \vec{\psi}_h \in\mathcal{V}_h \,.
	\end{equation}
	%Proceeding as in~\cite[Section 4.4.1]{gors-CMA-2021}, and using the fact that there exists a constant \( c_{\Omega} > 0 \), such that \( \Vert\bet_h\Vert_{\mathbf{H}}\,\le\, c_{\Omega}\, \Vert\bet_h\Vert_{\mathbf{H}} \) holds for all \( \bet_h\in \mathbf{H}_h \), together with~\eqref{l1}, we deduce that
%	Proceeding as in~\cite[Section 4.4.1]{gors-CMA-2021}, and employing the inequality
