Proceeding as in~\cite[Sec.~4.4.1]{gors-CMA-2021} and using
$\Vert \bet_h \Vert_{\mathbf{H}} \le c_{\Omega} \Vert \bet_h \Vert_{\div;\Omega}$
for all \(\bet_h \in \mathbf{H}(\div;\Omega)\) with constant \(c_{\Omega}>0\), along with~\eqref{l1}, we deduce that
	\begin{equation}\label{l2}
		\sup_{\mathbf{0}\neq \bet_h\in \mathbf{H}_h}\dfrac{\mathscr{B}^C(\bet_h, \vec{\psi}_h)}{\Vert \bet_h\Vert_{\mathbf{H}}}\,\geq\,\dfrac{\beta_{1,C,\mathtt{d}}}{c_{\Omega}}\,\Vert\xi_{h}\Vert_{\mathrm{Q}}\quad\forall\, \vec{\psi}_h \in\mathcal{V}_h \,.
	\end{equation}
%	On the other hand, from~\cite[Lemma 4.1]{cov-Calcolo-2020}, it is inferred that there exists a constant \( \beta_{2,C,\mathtt{d}} \), independent of \( h \), such that
From~\cite[Lemma 4.1]{cov-Calcolo-2020}, there exists a constant \( \beta_{2,C,\mathtt{d}} \), independent of \( h \), such that
	\begin{equation}\label{l3}
		\sup_{\mathbf{0}\neq \bet_h\in \mathbf{H}_h}\dfrac{\mathscr{B}^C(\bet_h, \vec{\psi}_h)}{\Vert \bet_h\Vert_{\mathbf{H}}}\,\geq\,	\sup_{\mathbf{0}\neq \bet_h\in \mathbf{H}_h}\dfrac{\mathscr{B}^C(\bet_h, (\psi_h,0))}{\Vert \bet_h\Vert_{\mathbf{H}}}\,\ge\,\beta_{2,C,\mathtt{d}}\,\Vert\psi_{h}\Vert_{\mathrm{V}}\,.
	\end{equation}
	Therefore, a direct combination of~\eqref{l2} and~\eqref{l3} leads to \eqref{eq:dis.inf.bit} with $ \beta_{C,\mathtt{d}}=\frac{1}{2}\min\{\beta_{1,C,\mathtt{d}}/c_{\Omega}, \, \beta_{2,C,\mathtt{d}}\}$.
\end{proof}
