We now present discrete counterparts of Lemmas~\ref{l_wel.S} and~\ref{l_wel.T}.
\begin{lemma}\label{l_wel.dis.S}
	Assume that for each $ 1\leq n\leq N $, and $ (\bz_h^{n},\chi_h^{n})\in \mathbf{V}_{h}\times \mathrm{Q}_{h} $ satisfy
	\begin{equation}\label{eq:dis.as.z.var}
		\Vert\bz_h^n\Vert_{\mathbf{V}}\,\le\,\max\Big\{ \left(\dfrac{\beta_{F,\mathtt{d}}^2\nu}{8}|\Omega|^{(p-4)/4}\right)^{1/(p-2)},\,\dfrac{\beta_{F,\mathtt{d}}\nu}{2\sqrt{2}} \Big\}\,.
	\end{equation}

	Then, there exist the positive constant $ \mathcal{C}_{\mathscr{L}^F,\mathtt{d}} $, depending only on $ \nu $, $ \beta_{F,\mathtt{d}} $, such that there hold
	\begin{equation}\label{eq:dis.apr1}
		\begin{array}{c}
			\Vert\mathscr{L}^F_{2,\mathtt{d}}(\bz_h^n,\chi_h^n)\Vert_{0,\Omega}^{2}+\Vert\bdev(\mathscr{L}^F_{1,\mathtt{d}}(\bz_h^n,\chi_h^n))\Vert_{0,\Omega}^{2}
			\\
			+\Delta t\disp\sum_{j=1}^{n}\Big(\Vert\mathscr{L}^F_{1,\mathtt{d}}(\bz_h^j,\chi_h^j)\Vert_{\mathbb{H}}^{2}+\Vert\delta_t\mathscr{L}^F_{2,\mathtt{d}}(\bz_h^j,\chi_h^j)\Vert_{0,\Omega}^{2}\,+\,\Vert\mathscr{L}^F_{2,\mathtt{d}}(\bz_h^j,\chi_h^j)\Vert_{\mathbf{V}}^{2}\Big)\\
			\,\leq\, \mathcal{C}_{\mathscr{L}^F,\mathtt{d}}\,\Big\{\Vert \bu_{0}\Vert_{\mathbf{H}^{1}(\Omega)}^{2}+\Delta t\disp\sum_{j=1}^{n}\left(\Vert\mathbf{g}^j\Vert_{1/2,\Gamma_{\mathtt{o}}^c}^2+\Vert\chi_h^{j}\Vert_{\mathrm{Q}}^{2}+\Vert\delta_t\mathbf{g}^j\Vert_{1/2,\Gamma_{\mathtt{o}}^c}^2+\Vert\delta_t\chi_h^{j}\Vert_{\mathrm{Q}}^{2}\right) \Big\}\\
			\,:=\, \mathcal{C}_{\mathscr{L}^F,\mathtt{d}}\,\mathcal{N}_{F,\mathtt{d}}(\bu_{0},\mathbf{g},\chi_{h})\,.
		\end{array}
	\end{equation}
\end{lemma}
\begin{proof}
