	and
	\begin{equation*}%\label{key}
		\dfrac{\beta_{F,\mathtt{d}}^{2}\nu}{2}\,\Vert \bu_{h,\star}^{n}\Vert_{\mathbf{V}}^{2}\,\leq \, 2\nu c_{\mathscr{F}^F}^2\left(\Vert\mathbf{g}^n\Vert_{1/2,\Gamma_{\mathtt{o}}^c}+a_1\Vert\chi_h^n\Vert_{\mathrm{Q}}\right)^{2}+\dfrac{1}{2\nu}\Vert\bdev(\bsi_{h,\star}^{n})\Vert_{0,\Omega}^{2}\,.
