Substituting into \eqref{eq:dis.j1}, applying Young’s inequality, summing over \( n \), and using assumption \eqref{eq:dis.as.z.var}, we obtain
	\begin{equation}\label{eq:dis.f4}
		\begin{array}{c}
			\Vert\bu_{h,\star}^{n}\Vert_{0,\Omega}^{2}+\Delta t\disp\sum_{j=1}^{n}\left(\Vert \bdev(\bsi_{h,\star}^{j})\Vert_{0,\Omega}^{2} + \Vert \bu_{h,\star}^{j}\Vert_{\mathbf{V}}^{2}\right)\\
			\,\leq\,\mathcal{C}_1 \, \Big\{\Vert\bu_{0}\Vert_{0,\Omega}^{2}+\Delta t\disp\sum_{j=1}^{n}\left(\Vert\mathbf{g}^j\Vert_{1/2,\Gamma_{\mathtt{o}}^c}+a_1\Vert\chi_h^j\Vert_{\mathrm{Q}}\right)^{2}  +\epsilon\Delta t\disp\sum_{j=1}^{n}\Vert\bsi_{h,\star}^{j}\Vert_{\mathbb{H}}^{2} \Big\}\,,
		\end{array}
	\end{equation}
	where $ \mathcal{C}_1 $ is a positive constant depending on $ \beta_{F,\mathtt{d}} $, $ \nu $, $ \epsilon  $ and $|\Omega|$.

