%	$ (\bta_h,\bv_{h})=(\bsi_{h,\star}^{n}, \delta_t \bu_{h,\star}^{n}) $, and applying Young's inequality, then summing the resulting inequality over $n$, which yields	
To bound the last term, we follow the approach of \eqref{eq:f6}, using the time-discrete derivative of the first row of \eqref{eq:dis.sub1} with \( (\bta_h,\bv_{h}) = (\bsi_{h,\star}^{n}, \delta_t \bu_{h,\star}^{n}) \), applying Young's inequality, and summing over \( n \), we obtain	
	\begin{equation}\label{eq:dis.f6}
		\begin{array}{c}
			\Delta t\disp\sum_{j=1}^{n}\Vert\delta_t \bu_{h,\star}^{j}\Vert_{0,\Omega}^{2}+ \Vert \bdev(\bsi_{h,\star}^{n})\Vert_{0,\Omega}^{2} \,\leq\,\mathcal{C}_2 \, \Big\{ \Vert \bdev(\bsi_{h,\star}^{0})\Vert_{0,\Omega}^{2}\\
			+\Delta t\disp\sum_{j=1}^{n}\Big(\Vert\delta_t\mathbf{g}^j\Vert_{1/2,\Gamma_{\mathtt{o}}^c}^2+\Vert\delta_t\chi_h^{j}\Vert_{\mathrm{Q}}^{2}+ \epsilon_1 \Vert\bsi_{h,\star}^{j}\Vert_{\mathbb{H}}^{2}\Big)\,+\,\Delta t\disp\sum_{j=1}^{n}\left(\Vert\bdev(\bsi_{h,\star}^{j})\Vert_{0,\Omega}^{2}+\Vert\bu_{h,\star}^{j}\Vert_{\mathbf{V}}^{2}\right)\Big\}\,.
		\end{array}
	\end{equation}
%	Then, replacing \eqref{eq:dis.f6} in \eqref{eq:dis.f7}, and combining the resulting inequality with \eqref{eq:dis.f4} along with \eqref{kkk}, yield:
Substituting \eqref{eq:dis.f6} into \eqref{eq:dis.f7} and combining with \eqref{eq:dis.f4} and \eqref{kkk}, we get
	\begin{equation}\label{k1}
		\begin{array}{c}
			\Delta t	\disp\sum_{j=1}^{n}\Vert\bsi_{h,\star}^{j}\Vert_{\mathbb{H}}^{2} \, \leq\,\mathcal{C}_3\,\Big\{\Vert \bdev(\bsi_{h,\star}^{0})\Vert_{0,\Omega}^{2}+\Vert\bu_{0}\Vert_{0,\Omega}^{2}\\
			\,+\, \Delta t\disp\sum_{j=1}^{n}\left(\Vert\mathbf{g}^j\Vert_{1/2,\Gamma_{\mathtt{o}}^c}^2+\Vert\chi_h^{j}\Vert_{\mathrm{Q}}^{2}+\Vert\delta_t\mathbf{g}^j\Vert_{1/2,\Gamma_{\mathtt{o}}^c}^2+\Vert\delta_t\chi_h^{j}\Vert_{\mathrm{Q}}^{2}\right) \Big\}\,.
		\end{array}
	\end{equation}
%	Finally, similarly to \eqref{eq:a3} and \eqref{eq:a4}, \( \Vert \bdev(\bsi_{h,\star}^{0})\Vert_{0,\Omega} \) is bounded by \( \Vert \bu_{0}\Vert_{\mathbf{H}^{1}(\Omega)} \) by taking \( \bta_h = \bsi_{h,\star}^{0} \) in the first row of \eqref{eq:dis.sub1} with \( n=0 \), using Green's formula, along with the fact that \( \bu_{h,\star}^{0} = \Pcalbf_0^h\bu_{0} \). Thus, by combining \eqref{k1} and \eqref{eq:dis.f4}, we conclude that \eqref{eq:dis.apr1} holds.
	Finally, as in \eqref{eq:a3} and \eqref{eq:a4}, testing the first row of \eqref{eq:dis.sub1} at \( n=0 \) with \( \bta_h = \bsi_{h,\star}^{0} \), applying Green's formula, and noting \( \bu_{h,\star}^{0} = \Pcalbf_0^h\bu_{0} \), we bound \( \Vert \bdev(\bsi_{h,\star}^{0})\Vert_{0,\Omega} \) by \( \Vert \bu_{0} \Vert_{\mathbf{H}^1(\Omega)} \). Combining this with \eqref{k1} and \eqref{eq:dis.f4} yields \eqref{eq:dis.apr1}.
\end{proof}
