\begin{theorem}\label{theorem-rates-of-convergence}
	Assume that the data satisfy \eqref{eq:as1.conv}, \eqref{eq:as2.conv} and
%	\begin{equation}\label{eq:asG.conv}
		$\mathcal{D}_{\mathtt{st}}\mathcal{N}_{T}(\varphi_{0},\varphi_{D})\, \leq\, \dfrac{1}{2}$.
%	\end{equation}
