	\begin{equation*}%\label{key}
		\Vert\btet_{\bu}^{n}\Vert_{0,\Omega}^{2}+\Vert\theta_{\varphi}^{n}\Vert_{0,\Omega}^{2}+\Delta t\disp\sum_{j=1}^{n}\left(\Vert (\btet_{\bsi}^{j},\btet_{\bu}^j)\Vert_{\mathbb{H}\times\mathbf{V}}^{2}+\Vert (\btet_{\brho}^{j},\theta_{\vec{\varphi}}^j)\Vert_{\mathbf{H}\times\mathcal{V}}^{2}\right) \,\leq\,\mathcal{C}\,\big(\Delta t^{2} +h^{2}\big) \,.
	\end{equation*}
\end{theorem}
\begin{proof}
	It suffices to employ $\mathcal{D}_{\mathtt{st}}\mathcal{N}_{T}(\varphi_{0},\varphi_{D})\, \leq\, \dfrac{1}{2}$ in \eqref{eq:fin.est}.
\end{proof}	
