\section{Algorithm of Semantic-Driven Rule Learning}
\label{Appendix:semantic_driven_rule_learning}

In this section we introduce the Semantic-Driven Rule Learning algorithm in DCRM. The pseudo code can be found at algorithm \ref{alg:semantic_driven_rule_learning}.

\begin{algorithm}
\caption{Semantic-Driven Rule Learning}
\label{alg:semantic_driven_rule_learning}
\begin{algorithmic}[1]
\REQUIRE Historical context $\mathcal{H}_n$ at time $t_n$, Query $(S_q, R_e, ?, t_{n})$, target $O_y$
\ENSURE Causal Rules $\mathcal{CRB}^n(R_e)$

\STATE \textbf{Initialize:} $\mathcal{H}_c \gets \emptyset$, $\mathcal{CRB}^n(R_e) \gets \mathcal{CRB}^{n-1}(R_e)$, $supp \gets \emptyset$, $cove \gets \emptyset$

\FOR{each event $(S_q, r_{c_i}, o_i, t_i)$ in $\mathcal{H}_n$}
    \IF{$o_i$ aligns with $O_y$}
        \STATE $\mathcal{H}_c \gets \mathcal{H}_c \cup \{(S_q, r_{c_i}, o_i, t_i)\}$
        \STATE $supp[r_{c_i}] \gets supp[r_{c_i}] + 1$
    \ENDIF
\ENDFOR

\FOR{each $r_{c_i}$ in $\mathcal{H}_c$}
    \STATE $p_i \gets$ LLM-Causality-Assessment$(r_{c_i}, R_e)$ 
    \STATE Compute $cove_i \gets \frac{supp[r_{c_i}]}{|\mathcal{H}_c|}$
\ENDFOR
\STATE $\mathcal{H}_{c_{topk}} \gets$ Select top-$k$ $r_{c_i}$ based on $p_i$

\FOR{each $r_{c_i}$ in $\mathcal{H}_{c_{topk}}$}
    \STATE Compute $conf_i^n \gets \alpha \cdot p_i + (1 - \alpha) \cdot cove_i$
    \STATE $CR^n(R_e, r_{c_i}) \gets (X, R_e, Y, T_2) \Leftarrow (X, r_{c_i}, Y, T_1)$
    \STATE $\mathcal{CRB}^n(R_e) \gets \mathcal{CRB}^n(R_e) \cup CR^n(R_e, r_{c_i})$
\ENDFOR
\RETURN $\mathcal{CRB}^n(R_e)$

\end{algorithmic}
\end{algorithm}

\label{alg:semantic_driven_rule_learning}

