\section{Derivation of governing equations}
\label{app:govEqn}
A vector quantity $\VECTOR_{\mathcal{F}_j}$ or a tensor quantity $\TENSOR_{\mathcal{F}_j}$ given in frame $\mathcal{F}_j$ can be resolved in an other frame $\mathcal{F}_i$ with 
\begin{equation}
	\VECTOR_{\mathcal{F}_i} = \mathbf T_{ij}\,\VECTOR_{\mathcal{F}_j},\qquad
	\TENSOR_{\mathcal{F}_i} = \mathbf T_{ij}\,\TENSOR_{\mathcal{F}_j}\mathbf T_{ji},
\end{equation}
where the transformation matrices corresponding to the coordinate frames introduced in Section~\ref{sec:mechmodel} are
\begin{align}
	\mathbf T_{01} &= \left[\arraycolsep=4pt
	\begin{matrix}
		\cos{\psi_{}\,\!} & - \sin{\psi_{}\,\!} & 0\\
		\sin{\psi_{}\,\!} & \cos{\psi_{}\,\!} & 0\\
		0 & 0 & 1
	\end{matrix}\right]\!,
	~
	\begin{array}{l}%
		\mathbf T_{12} = \left[\arraycolsep=4pt
		\begin{matrix}
			1 & 0 & 0\\
			0 & \cos{\vartheta_{}\,\!} & - \sin{\vartheta_{}\,\!}\\
			0 & \sin{\vartheta_{}\,\!}    & \cos{\vartheta_{}\,\!}
		\end{matrix}\right]\!,
	\end{array}
	\nonumber\\
	\mathbf T_{23} &= \left[\arraycolsep=4.5pt
	\begin{matrix}
		\cos{\gamma_{}\,\!} & 0 & \sin{\gamma_{}\,\!}\\
		0 & 1 & 0\\
		- \sin{\gamma_{}\,\!} & 0 & \cos{\gamma_{}\,\!}
	\end{matrix}\right]\!,
	~
	\begin{array}{l}%
		\mathbf T_{02} = \mathbf T_{01} \mathbf T_{12},\\
		\mathbf T_{03} = \mathbf T_{01} \mathbf T_{12}\mathbf T_{23}, \\ 
		\mathbf T\makebox[0pt][l]{$_{ji}$}%
		\phantom{_{02}} = \mathbf T_{ij}^{-1}.
	\end{array}
\end{align}

The Appellian approach~\cite{Appell_1900, Gibbs_1879, qin2022nonholonomic} assumes the equation of motion in the form 
\begin{equation}\label{eq:appell}\arraycolsep=1pt
	\begin{array}{rll}
		\dfrac{\partial S}{\partial \dot\sigma_{\!j}} &= \Pi_j, & j=1,\dots,n_\sigma\,,  
		\\[1em]
		\dot q_k &= \sum_{1}^{n_\sigma} f_{kj} \sigma_j,\qquad~ & k=1,\dots,n_q\,,
	\end{array}
\end{equation}
where $S$ is the the acceleration energy, $\Pi_j$ is a pseudoforce.
The acceleration energy 
\begin{equation}
	\label{eq:acc_energy_disc}
	\begin{split}
		S = S_\mathrm{w} + S_{m_1} + S_{m_2}
	\end{split}
\end{equation}
of the unicycle is composed of three parts related to wheel and the point masses:
\begin{equation}\label{eq:accel_energy_wheel}
	\begin{split}
		S_\mathrm{\!w} &= \frac{1}{2} m \mathbf a_{\rm C}^2 + \frac{1}{2}\bm\alpha \cdot \mathbf J_{\rm C} \bm\alpha + \bm\alpha \cdot ( \bm\omega \times \mathbf J_{\rm C} \bm\omega )\,,\\
		S_{\!m_1} &= \frac{1}{2} m_1 \mathbf a_{\rm A}^2,
		\qquad
		S_{\!m_2} = \frac{1}{2} m_2 \mathbf a_{\rm B}^2,
	\end{split}
\end{equation}
where the acceleration of the wheel center, mass moment of inertia of the wheel and the angular acceleration of the wheel are
\begin{align}
		\mathbf a_{\rm C} &= 
		\begin{bmatrix}
			R (\dot \omega_{2} + \omega_{1} \omega_{3})   \\
			- R (\dot \omega_{1} - \omega_{2} \omega_{3}) \\
			- R (\omega_{1}^{2} + \omega_{2} \omega_{3} \tan{\vartheta})
		\end{bmatrix}_{{\mathcal F}_{2}}\!\!,%
		\quad
		\mathbf J_{\rm C} = \frac{mR^2}{4}
		\arraycolsep3pt
		\begin{bmatrix}
			1 & 0 & 0\\
			0 & 2 & 0\\
			0 & 0 & 1
		\end{bmatrix}_{{\mathcal F}_{2}}\!\!,
		\nonumber\\&\qquad\qquad
		\bm\alpha = 
		\begin{bmatrix}
			\dot \omega_{1} - \omega_{2} \omega_{3} + \omega_{3}^{2} \tan{\vartheta}\\
			\dot \omega_{2}\\
			\dot \omega_{3} + \omega_{1} \omega_{2} - \omega_{1} \omega_{3} \tan{\vartheta}
		\end{bmatrix}_{{\mathcal F}_{2}}\!,\label{eq:angularaccel_disc}
\end{align}
respectively.
The velocity and the acceleration of $m_1$ are
\begin{equation}\label{eq:vA_aA}
\begin{split}
	\mathbf v_{\!\rm A} &= 
	\begin{bmatrix}
		\omega_{2} R  - \omega_{3} r
		\\ 
		\sigma_r
		\\ 
		\omega_{1} r
	\end{bmatrix}_{{\mathcal F}_{2}},
	\\
	\mathbf a_{\rm A} &= \begin{bmatrix}
		\dot \omega_{2}  R  - \dot \omega_{3} r  +  \omega_{1} \omega_{3}  \big(r \tan{\vartheta} - R\big)- 2 \omega_{3}\sigma_r
		\\
		\dot \sigma_r- \omega_{1}^{2} r - \omega_{3}^{2} r  + \omega_{2} \omega_{3} R \ \ \ 
		\\
		\dot \omega_{1} r + \omega_{1}^{2} R  + 2 \omega_{1}  \sigma_r + (\omega_{3}^{2} r - \omega_{2} \omega_{3} R  )\tan{\vartheta} 
	\end{bmatrix}_{{\mathcal F}_{2}} \!\!,
\end{split}
\end{equation} 
while the velocity and the acceleration of $m_2$ are
\begin{equation}\label{eq:vB_aB}
	\begin{split}
		\mathbf v_{\!\rm B} &= 
		\begin{bmatrix}
			\sigma_{\gamma}
			\\
			\omega_{1} ( h  \cos{\gamma} - R)  + \omega_{3} h  \sin{\gamma}
			\\
			\omega_{2}R  \sin{\gamma}
		\end{bmatrix}%
		_{{\mathcal F}_{3}}\!\!,%
		\quad
		\mathbf a_{\rm B} = \begin{bmatrix}
			a_{\mathrm{B}x} \\ a_{\mathrm{B}y} \\ a_{\mathrm{B}z}
		\end{bmatrix}_{{\mathcal F}_{3}}\!\!,
	\end{split}
\end{equation}
with
\begin{equation} \label{eq:aB_componenets}
	\begin{split}
		a_{\mathrm{B}x} &=  \frac{1}{h}\big(
		\dot \sigma_{\gamma} h
		+ \omega_{1}^{2}(R  + h \cos{\gamma}) h \sin{\gamma}
		- \omega_{2}^{2}  R^{2} \sin{\gamma} \cos{\gamma} 
		\\&\quad  - \omega_{3}^{2} h^{2}  \sin{\gamma} \cos{\gamma} 
		+ \omega_{2} \sigma_{\gamma}  R \sin{\gamma}
		\\&\quad  + \omega_{1} \omega_{3} (R  \cos{\gamma} 
		+ 2 h \cos^{2}{\gamma} 
		- h) h 
		\big),\\
		a_{\mathrm{B}y} &=   
		- \dot \omega_{1} (R + h \cos{\gamma}) 
		+ \dot \omega_{3}  h \sin{\gamma} 
		- \omega_{3}^{2} h  \cos{\gamma} \tan{\vartheta} 
		\\&\quad  - 2 \omega_{1} \omega_{2}  R \sin{\gamma} \cos{\gamma} 
		-\omega_{1} \omega_{3} h  \sin{\gamma} \tan{\vartheta} 
		\\&\quad  + \omega_{2} \omega_{3} (1\!-\!2 \cos^{2}{\gamma}) R
		+ 2 \omega_{1} \sigma_{\gamma}  \sin{\gamma} 
		+ 2 \omega_{3} \sigma_{\gamma}  \cos{\gamma},
		\\
		a_{\mathrm{B}z} &=  \frac{1}{h}\big(
		\dot \omega_{2}  R h \sin{\gamma}
		-   \omega_{1}^{2} ( R +  h \cos{\gamma}) h \cos{\gamma}
		- \sigma_{\gamma}^{2}
		\\&\quad  
		- \omega_{2}^{2}  R^{2} \cos^{2}{\gamma} 
		-  \omega_{3}^{2}  \sin^{2}{\gamma} h^{2} - \omega_{2} \omega_{3} R h  \cos{\gamma} \tan{\vartheta} 
		\\&\quad 
		+ 2 R \sigma_{\gamma} \omega_{2} \cos{\gamma} 
		+  \omega_{1} \omega_{3}  (R \sin{\gamma} + 2  \sin{\gamma} \cos{\gamma}) h
		\big).
	\end{split}
\end{equation}
The acceleration energies of the corresponding parts are
\begin{equation}
	\label{eq:acc_energy_all}
	\begin{split}
		S_\mathrm{\!w} &= \frac{m R^2}{8} \Big(
		5 \dot \omega_{1}^{2} + 6 \dot \omega_{2}^{2} + \dot \omega_{3}^{2} 
		+ (2 \omega_{3}^{2} \tan{\vartheta} - 12 \omega_{2} \omega_{3})\dot \omega_{1}
		\\&\quad
		+ 8 \omega_{1} \omega_{3} \dot \omega_{2}
		+ (4 \omega_{1} \omega_{2} - 2 \omega_{1} \omega_{3} \tan{\vartheta}) \dot \omega_{3} 
		\Big)
		+ \dots\,, 
		\\
		S_{\!m_1} &= \frac{m_{1} }{2}\Big(
		r^{2}  \dot \omega_{1}^{2} 
		+ R^{2}  \dot \omega_{2}^{2} 
		+ r^{2}  \dot \omega_{3}^{2} 
		+ \dot \sigma_{\mathrm{r}}^{2}
		- 2 R r \dot \omega_{2} \dot \omega_{3} 
		\\&\quad
		+ 2 \big(\omega_{1}^{2} R - \omega_{2} \omega_{3} R  \tan{\vartheta} + 2 \omega_{1} \sigma_{\mathrm{r}}  + \omega_{3}^{2} r \tan{\vartheta}\big) r \dot \omega_{1} 	
		\\&\quad
		- 2 R  \omega_{3} \big(\omega_{1} R + 2 \sigma_{\mathrm{r}} - \omega_{1} 
		r \tan{\vartheta}\big) \dot \omega_{2} 
		\\&\quad
		+ 2  \omega_{3} \big(\omega_{1} (R  - r \tan{\vartheta}) + 2 \sigma_{\mathrm{r}} \big)r \dot \omega_{3} 
		\\&\quad
		- 2 \big(\omega_{1}^{2} r + \omega_{3}^{2} r - R \omega_{2} \omega_{3}\big) \dot \sigma_{\mathrm{r}} 	
		\Big)
		+ \dots\,, 
		\\
		S_{\!m_2} &= \frac{m_{2}}{2 h}\Big(
		\big( R^{2} h + 2 R h^{2} \cos{\gamma} + h^{3} \cos^{2}{\gamma}\big)  \dot \omega_{1}^{2} 
		\\&\quad
		+ R^{2} h \sin^{2}{\gamma}  \dot \omega_{2}^{2} + h^{3} \sin^{2}{\gamma}  \dot \omega_{3}^{2} + h  \dot \sigma_{\gamma}^{2}
		\\&\quad
		- \big(	2 R h^{2} \sin{\gamma} + 2 h^{3} \sin{\gamma} \cos{\gamma}\big) \dot \omega_{1}  \dot \omega_{3} 
		\\&\quad
		+ \big(
		\omega_{3}^{2} ( 2 R h^{2} \cos{\gamma} \tan{\vartheta} + 2 h^{3} \cos^{2}{\gamma} \tan{\vartheta}) 
		\\&\qquad	
		+ 4 \omega_{1} \omega_{2} Rh( R  \cos{\gamma} + h \cos^{2}{\gamma} ) \sin{\gamma}
		\\&\qquad
		+ 2 \omega_{1} \omega_{3} (  R h^{2}  +  h^{3} \cos{\gamma} ) \sin{\gamma} \tan{\vartheta}
		\\&\qquad	
		- 4 \omega_{1}  \sigma_{\gamma} ( R h  
		+  h^{2}  \cos{\gamma}) \sin{\gamma}
		\\&\qquad	
		- 4 \omega_{3}  \sigma_{\gamma} ( R h \cos{\gamma} 
		+  h^{2} \cos^{2}{\gamma})
		\\&\qquad	
		+ 2Rh\omega_{2} \omega_{3} ( 2R \cos^{2}{\gamma} - R + 2h \cos^{3}{\gamma} 
		\\&\qquad\quad
		- h \cos{\gamma})
		\big) \dot \omega_{1} 
		\\&\quad
		- \big(
		\omega_{1}^{2} (2 R^{2} h \sin{\gamma} \cos{\gamma} - 2 R h^{2} \sin^{3}{\gamma} + 2 R h^{2} \sin{\gamma})
		\\&\qquad	
		+ 2 \omega_{2}^{2}  R^{3} \cos^{2}{\gamma} \sin{\gamma}
		+ 2 \omega_{3}^{2}R h^{2}  \sin^{3}{\gamma} 
		\\&\qquad	
		+ 2 \sigma_{\gamma}^{2} R  \sin{\gamma} 
		+2 \omega_{2} \omega_{3} R^{2} h \sin{\gamma} \cos{\gamma} \tan{\vartheta} 
		\\&\qquad	
		- 2 \omega_{1} \omega_{3} Rh( R  + 2h  \cos{\gamma}) \sin^{2}{\gamma}
		\\&\qquad	
		- 4 \omega_{2}  \sigma_{\gamma} R^{2} \sin{\gamma} \cos{\gamma}
		\big) \dot \omega_{2}
		\\
		&\quad
		- 2 \big(
		\omega_{3}^{2}  h^{3}\sin{\gamma} \cos{\gamma} \tan{\vartheta} 
		+ 2 \omega_{1} \omega_{2} R h^{2}  \sin^{2}{\gamma} \cos{\gamma} 
		\\&\qquad
		+  \omega_{1} \omega_{3} h^{3}  \sin^{2}{\gamma} \tan{\vartheta}  
		- 2  \omega_{1} \sigma_{\gamma} h^{2} \sin^{2}{\gamma}   
		\\&\qquad
		+  \omega_{2} \omega_{3}  R h^{2} (2  \cos^{2}{\gamma}  - 1 )\sin{\gamma}
		\\&\qquad
		- 2 \omega_{3} \sigma_{\gamma}  h^{2}  \sin{\gamma} \cos{\gamma}  
		\big) \dot \omega_{3} 
		\\
		&\quad
		+ \big(
		\omega_{1}^{2}  ( 2 R h \sin{\gamma} + 2 h^{2} \sin{\gamma} \cos{\gamma})
		\\&\qquad
		-2 \omega_{2}^{2}  R^{2} \sin{\gamma} \cos{\gamma} 
		- 2 \omega_{3}^{2} h^{2}  \sin{\gamma} \cos{\gamma} 
		\\&\qquad
		+ 2 \omega_{1} \omega_{3} (  R h \cos{\gamma} + 2 h^{2} \cos^{2}{\gamma} - h^{2}) 
		\\&\qquad
		+ 2 \omega_{2} \sigma_{\gamma} R  \sin{\gamma} 
		\big) \dot \sigma_{\gamma} 
		\Big)
		+ \dots\,,
	\end{split}
\end{equation}
where the ellipses (\,$\dots$) refer to further terms which are independent of the pseudo accelerations, so they do not appear in the equations of motion.


The pseudoforces can be expressed using the virtual power 
\begin{equation}
	\begin{split}
		\delta P &= \mathbf G \cdot \delta \mathbf v_{\rm C} + \mathbf G_{\!\rm A} \cdot \delta \mathbf v_{\!\rm A} + \mathbf G_{\!\rm B} \cdot \delta \mathbf v_{\!\rm B} +
		\mathbf F \cdot \delta\mathbf v_{\rm C}
		\\&\quad
		- \mathbf F \cdot \delta\mathbf v_{\!\rm A} 
		+ \mathbf T \cdot \delta\bm \omega -  \mathbf T \cdot \delta\bm \Omega = \sum_{j=1}^{n_\sigma} \Pi_j\,\delta \sigma_{\!j}
	\end{split}
\end{equation}%
of the external active forces and torques,
where the angular velocity of the pendulum actuator is
\begin{equation}
	\bm \Omega = \begin{bmatrix}
		\omega_{1}
		\\
		\frac{ 1}{h} (\sigma_{\gamma}{\!}-{\!} \omega_{2}{ R  \cos{\gamma}} )
		\\
		\omega_{3}
	\end{bmatrix}_{{\mathcal F}_{2}} .
\end{equation}
The pseudoforces are calculated to be
\begin{equation} \label{eq:pseudo_forces}
	\begin{split}
		\Pi_1 &= -F R + m g R \sin{\vartheta} - m_{1} g r \cos{\vartheta} 
		\\&\quad
		+ m_{2} g \big(R + h \cos{\gamma}\big) \sin{\vartheta}
		\,,\\ 
		\Pi_2 &= \frac{T}{h} \big({R \cos{\gamma}} + h\big) - m_{2} g R \sin{\gamma} \cos{\gamma} \cos{\vartheta} 
		\,,\\ 
		\Pi_3 &= - m_{2} g h \sin{\gamma} \sin{\vartheta}
		\,,\\ 
		\Pi_4 &= 	-F - m_{1} g \sin{\vartheta}
		\,,\\ 
		\Pi_5 &= -\frac{T}{h} + m_{2} g \sin{\gamma} \cos{\vartheta}\,.
	\end{split}
\end{equation}

The first set of equations in \eqref{eq:appell} are the dynamical equations, which assume the form \eqref{eq:dynamicEQS}. The second set of equations in \eqref{eq:appell} are the kinematic equations expressing the generalized velocities \eqref{eq:gen_coords} based on the pseudo-velocities \eqref{eq:pseudoVelocDefinition} as \eqref{eq:kinematicEQS}.


The mass matrix in \eqref{eq:dynamicEQS} has the form 
\begin{equation}\label{eq:massMtrx}
	\mathbf M = \begin{bmatrix}M_{11} & 0 & M_{13} & 0 & 0\\0 & M_{22} & M_{23} & 0 & 0\\M_{31} & M_{32} & M_{33} & 0 & 0\\0 & 0 & 0 & M_{44} & 0\\0 & 0 & 0 & 0 & M_{55}\end{bmatrix},
\end{equation}
where the matrix elements are
\begin{equation}\label{eq:massMtrxElements}
	\begin{split}
		M_{11} &= {5 m R^{2}}/{4} + m_{1} r^{2} + m_{2} \big(R + h \cos{\gamma}\big)^{2},\\
		M_{13} &\equiv M_{31} = - m_{2} h \big(R + h \cos{\gamma}\big) \sin{\gamma},\\
		M_{22} &= R^{2} \big({3 m}/{2} + m_{1} + m_{2} \sin^{2}{\gamma}\big),\\
		M_{23} &\equiv M_{32} = - m_{1} R r,\\
		M_{33} &= {m R^{2}}/{4} + m_{2} h^{2} \sin^{2}{\gamma} + m_{1} r^{2},\\
		M_{44} &= m_{1}, \\
		M_{55} &= m_{2}.
	\end{split}
\end{equation}
The elements of the inertial forces $\mathbf C(\mathbf q, \bm\sigma)$ in \eqref{eq:dynamicEQS}--\eqref{eq:CandPI} are 
\begin{equation*}%
	\begin{split}
		C_1 & = \frac{1}{4}\Big(
		4 \omega_{1}^{2} m_{1} R  r + 8 \omega_{1}  \sigma_r m_{1} r 
		\\&
		+   \omega_{1} \omega_{2} m_{2} ((8 R^{2} \cos{\gamma} + 8 R h ) \sin{\gamma}- 8 R h \sin^{3}{\gamma})  
		\\&
		- \omega_{1} \sigma_{\gamma} m_{2}   ( 8 R + 8 h \cos{\gamma}) \sin{\gamma}  
		\\&
		+ \omega_{1} \omega_{3}  m_{2} (4 R h  + 4 h^{2} \cos{\gamma} ) \sin{\gamma} \tan{\vartheta}   
		\\&
		- \omega_{3} \sigma_{\gamma} m_{2} (8 R \cos{\gamma} + 8 h \cos^{2}{\gamma})  
		\\&
		+ \omega_{3}^{2} ((m R^{2} + 4 m_{1} r^{2} + m_{2} (4 R h \cos{\gamma} + 4 h^{2}  \cos^2{\gamma})) \tan{\vartheta})   
		\\&
		- \omega_{2} \omega_{3} (6 m R^{2} + 4 m_{1} R r \tan{\vartheta} 
		\\&
		\quad- m_{2} (4 R^{2} + 4 R h \cos{\gamma} )(\cos^2\gamma - \sin^2\gamma)) 
		\Big),
	\end{split}
\end{equation*}
\begin{equation}\label{eq:vecInertialForcesElements}
	\begin{split}
		C_2 &= \frac{1}{h}\Big(
		- \omega_{1}^{2} m_{2}  R h  ( R  + h \cos{\gamma}) \sin{\gamma} \cos{\gamma}
		\\&
		- \omega_{2}^{2} m_{2}  R^{3}  \sin{\gamma} \cos^{2}{\gamma}
		- \omega_{3}^{2}  m_{2} R h^{2} \sin^{3}{\gamma} 
		\\&
		- \sigma_{\gamma}^{2}  m_{2} R \sin{\gamma} 
		+ \omega_{1} \omega_{3} (m h R^{2}  -  m_{1} R^{2} h +  m_{2} R^{2} h \sin^{2}{\gamma} 
		\\&
		\quad + 2 m_{2} R h^{2} \sin^{2}{\gamma} \cos{\gamma} + m_{1} R h r \tan{\vartheta}) 
		\\&
		-\omega_{2} \omega_{3}  m_{2} R^{2} h  \sin{\gamma} \cos{\gamma} \tan{\vartheta} 
		\\&
		+ 2  \omega_{2} \sigma_{\gamma} m_{2} R^{2}  \sin{\gamma} \cos{\gamma} 
		- 2 \omega_{3} \sigma_r   m_{1} R h 
		\Big),\\
		C_3 &= \frac{1}{4}\Big(
		- 4 \omega_{3}^{2} m_{2} h^{2}  \sin{\gamma} \cos{\gamma} \tan{\vartheta} 
		\\&
		+ \omega_{1} \omega_{2} (2 m R^{2} - 8 m_{2} R h \sin^{2}{\gamma} \cos{\gamma}) 
		\\&
		+ \omega_{1} \omega_{3} (- m R^{2} \tan{\vartheta} + 4 m_{1} R r - 4 m_{2} h^{2} \sin^{2}{\gamma} \tan{\vartheta} 
		\\&\quad
		- 4 m_{1} r^{2} \tan{\vartheta}) 
		+ 8  \omega_{1} \sigma_{\gamma} m_{2} h  \sin^{2}{\gamma} 
		\\&
		+ \omega_{2} \omega_{3} (8 m_{2} R h \sin^{3}{\gamma} - 4 m_{2} R h \sin{\gamma})
		\\&
		+ 8 \omega_{3}  \sigma_r  m_{1} r 
		+ 8 \omega_{3} \sigma_{\gamma}   m_{2} h \sin{\gamma} \cos{\gamma} 
