\section{Calculation of the contact force}\label{app:NewtonEuler_contactForce}


The Newton--Euler approach is used in order to calculate the constraining force $\mathbf K$ acting between the wheel and the ground. 
The unicycle consists of a wheel, a (massless) fork, and two point masses, see Figure~\ref{fig:motivation};
the corresponding free body diagrams are shown in Figure~\ref{fig:freeBodyDiagrams}.


The Newton--Euler equations for the wheel are
\begin{align}\label{eq:NEwheel1}
	m \mathbf{a}_{\mathrm C}  &= 
	m \mathbf{g} + \mathbf K + {\mathbf F}_\mathrm{A} + \bar{\mathbf F}_\mathrm{C} ,
	\\
	\label{eq:NEwheel2}
	\mathbf{J}_{\mathrm C} \bm \alpha 
	+ \bm{\omega}\times \mathbf{J}_{\mathrm C} \bm \omega 
	&=
	{\mathbf T}_\mathrm{C} 
	+ \mathbf{r}_{\mathrm{CP}}\times\mathbf K 
	+ \mathbf{r}_{\mathrm{CA}}\times {\mathbf F}_\mathrm{A}, 
	\intertext{%
		while for the fork they become
	}
	\label{eq:NEfork1}
		m_{\mathrm{f}} \mathbf{a}_{\mathrm C} &= m_{\mathrm{f}}\mathbf g + \bar{\mathbf F}_\mathrm{B} - \bar{\mathbf F}_\mathrm{C} ,
		\\
		\label{eq:NEfork2}
		\mathbf{J}_{\mathrm{f}} \bm\Lambda
		+ \bm{\Omega}\times \mathbf{J}_{\mathrm{f}} \bm \Omega 
		&=
		-{\mathbf T}_\mathrm{C} 
		+ \mathbf{r}_{\mathrm{CB}}\times\bar{\mathbf F}_\mathrm{B}.
	\intertext{%
		The Newton equation for point mass $m_1$ is
	}
	\label{eq:NEpm1}
	m_1 \mathbf{a}_{\mathrm A}  &= m_1 \mathbf{g} - {\mathbf F}_\mathrm{A} ,
	\intertext{%
		and for the point mass $m_2$ it is
	}
	\label{eq:NEpm2}
	m_2 \mathbf{a}_{\mathrm B}  &= m_2 \mathbf{g} - \bar{\mathbf F}_\mathrm{B} .
\end{align}



Equations \eqref{eq:NEwheel1}-\eqref{eq:NEpm2} form the Newton--Euler equations of the unicycle; 
where the accelerations, angular accelerations and angular velocities can be expressed as
\begin{align}\arraycolsep=0pt\renewcommand{\arraystretch}{1.5}
	\begin{array}{rlccccclcrlcccccl}
		\mathbf a_{\mathrm{A}} \,&= \big[ &a_{\mathrm{A}x} &\quad~& a_{\mathrm{A}y} &\quad~& a_{\mathrm{A}z}&\big]_{{\mathcal F}_{2}}^{\mathsf{T}},     && \mathbf a_{\mathrm{B}}\,&= \big[& a_{\mathrm{B}x} &\quad~ &a_{\mathrm{B}y} &\quad~& a_{\mathrm{B}z}&\big]_{{\mathcal F}_{3}}^{\mathsf{T}},
		\\
		\mathbf a_{\rm C}                 \,& = \big[ &a_{\mathrm C x} & \quad~ & a_{\mathrm C y}& \quad~ & a_{\mathrm C z}&\big]_{{\mathcal F}_{0}}^{\mathsf{T}},    &\qquad~& \mathbf{g} \,&= \big[&0&\quad~& -g&\quad~ &0&\big]_{\mathcal F_0}^{\mathsf T},                           \\
		\bm\alpha \,& = \big[& \alpha_x&\quad~& \alpha_y &\quad~& \alpha_z&\big]_{{\mathcal F}_{2}}^{\mathsf{T}}, &       & \bm\Lambda  \,& = \big[& \Lambda_{x}&\quad~ &\Lambda_{y} &\quad~& \Lambda_{z}&\big]_{{\mathcal F}_{2}}^{\mathsf{T}}, \\
		\bm\omega \,&= 	\big[&\omega_1 &\quad~& \omega_2 &	\quad~& \omega_3 &\big]^{\mathsf T}_{{\mathcal F}_{2}}, && \bm\Omega \,&= 	\big[&\Omega_{x} &\quad~& \Omega_{y} &	\quad~ &\Omega_{z} &\big]^{\mathsf T}_{{\mathcal F}_{2}}.\\
	\end{array}\nonumber\\
\end{align}\renewcommand{\arraystretch}{1}%
The internal force $ {\mathbf F}_\mathrm{A}$  and  torque $\mathbf{T}_\mathrm{f}$ consist of the actuator force $\mathbf F$  and torque $\mathbf{T}$ and the constraining force $\bar{\mathbf F}_\mathrm{A} $ and torque $\bar{{\mathbf T}}_\mathrm{f} $, respectively; these can be expressed with 
\begin{align}\arraycolsep=0pt\renewcommand{\arraystretch}{1.5}
	\begin{array}{rlccccclcrlcccccl}
		{\mathbf F}_\mathrm{A}     \,& \multicolumn{7}{l}{ =\mathbf F + \bar{\mathbf F}_\mathrm{A},  }                                                     & \qquad~ & \mathbf{T}_\mathrm{C}        \,&  \multicolumn{7}{l}{=\mathbf{T} + \bar{{\mathbf T}}_\mathrm{C} ,   }                                              \\
		\mathbf F                  \,& = \big[ &0& \quad~& F& \quad~ &0&\big]_{{\mathcal F}_{2}}^{\mathsf{T}},                                 &       & \mathbf T                    \,& = \big[ &0 &\quad~ &T &\quad~ &0& \big]_{{\mathcal F}_{2}}^{\mathsf{T}} ,                             \\
		\bar{\mathbf F}_\mathrm{A} \,& = \big[ &F_{\!\mathrm{A}x}& \quad~& 0& \quad~& F_{\!\mathrm{A}z}&\big]_{{\mathcal F}_{2}}^{\mathsf{T}}, &       & \bar{{\mathbf T}}_\mathrm{C} \,& = \big[& T_{\mathrm{C}x}&  \quad~ &0& \quad~& T_{\mathrm{C}z} &\big]_{{\mathcal F}_{2}}^{\mathsf{T}}.
	\end{array}
	\nonumber\\
\end{align}\renewcommand{\arraystretch}{1}%
The other constraining forces are the internal forces $\bar{\mathbf F}_\mathrm{B}, \bar{\mathbf F}_{\mathrm{C}}$ and the wheel-ground contact force $\mathbf K $, these are
\begin{equation}\arraycolsep=0pt\renewcommand{\arraystretch}{1.5}
	\begin{array}{rlccccclcrlcccccl}
		\bar{\mathbf F}_{\mathrm{B}} \, & = \big[&	F_{\!\mathrm{B}x} &\quad~& F_{\!\mathrm{B}y}& \quad~ &F_{\!\mathrm{B}z}&	\big]_{{\mathcal F}_{2}}^{\mathsf{T}},&\qquad~& \bar{\mathbf F}_{\mathrm{C}} \, & = \big[&	F_{\!\mathrm{C}x} &\quad~& F_{\!\mathrm{C}y}& \quad~ &F_{\!\mathrm{C}z}&	\big]_{{\mathcal F}_{2}}^{\mathsf{T}}.\\
		\multicolumn{17}{c}{\mathbf{K} = \big[K_x\quad~ K_y\quad~ K_z\big]_{\mathcal F_1}^{\mathsf T}.}
	\end{array}
\end{equation}\renewcommand{\arraystretch}{1}%
The position vectors needed to calculate the torques of forces with respect to the center of masses are
\begin{equation}\label{eq:geoMConstrS}\arraycolsep=0pt\renewcommand{\arraystretch}{1.5}
	\begin{array}{rlccccclcrlcccccl}
		\mathbf r_{\mathrm{CA}} &= 	\big[&0 &\quad~& r &	\quad~& 0&\big]^{\mathsf T}_{{\mathcal F}_{2}}, &\qquad~& \mathbf r_{\mathrm{CB}} &= 	\big[&0 &\quad~& 0 &	\quad~& h &\big]^{\mathsf T}_{{\mathcal F}_{3}},  \\
		\multicolumn{17}{c}{\mathbf r_{\mathrm{CP}} = 	\big[0 \quad~ 0 	\quad\! -R \big]^{\mathsf T}_{{\mathcal F}_{2}}.}
	\end{array}
\end{equation}\renewcommand{\arraystretch}{1}%

\begin{figure}[!t]
	\centering
	\includegraphics[scale=0.9]{fig_FBDs.pdf}
	\caption{Free body diagrams of the parts.}
	\label{fig:freeBodyDiagrams}
\end{figure}

Considering frame $\mathcal F_0$, the components of \eqref{eq:NEwheel1} became
\begin{align}\label{eq:NEwheel_comp}
		m a_{\mathrm C x} &=  (K_{x} + F_{\!\mathrm{A}x}+ F_{\!\mathrm{C}x})\cos{\psi} - K_{y} \sin{\psi},
		\nonumber\\&\quad
		- (F_{\!\mathrm{C}y} + F) \sin{\psi} \cos{\vartheta} + (F_{\!\mathrm{A}z}  + F_{\!\mathrm{C}z}) \sin{\psi} \sin{\vartheta}
		\nonumber\\
		m a_{\mathrm C y} &=( K_{x} + F_{\!\mathrm{A}x}+ F_{\!\mathrm{C}x}  )\sin{\psi} + K_{y} \cos{\psi} ,
		\nonumber\\&\quad
		+(F_{\!\mathrm{C}y} + F )\cos{\psi} \cos{\vartheta}   - (F_{\!\mathrm{A}z}  + F_{\!\mathrm{C}z} )\sin{\vartheta} \cos{\psi}
		\nonumber\\
		m a_{\mathrm C z} &= K_{z} - mg + (F_{\!\mathrm{A}z} + F_{\!\mathrm{C}z}) \cos{\vartheta} +(F_{\!\mathrm{C}y}   + F )\sin{\vartheta} ,
\end{align}
while the components of \eqref{eq:NEwheel2} in frame $\mathcal{F}_2$ are
\begin{align}
	\tfrac{m R^{2}}{4} (\alpha_x - {\omega_{2} \omega_{3}})&= T_{\mathrm{C}x} + F_{\mathrm Az} r + K_{y} R \cos{\vartheta} + K_{z} R \sin{\vartheta},
	\nonumber\\
	\tfrac{m R^{2}}{2} \alpha_y &= T - K_{x} R,
	\\\nonumber
	\tfrac{m R^{2}}{4}(\alpha_z + { \omega_{1} \omega_{2}})/&= T_{\mathrm{C}z} - F_{\mathrm Ax} r.
\end{align}
Neglecting the mass of the fork, ${ m_{\mathrm{f}}=0}$, the components of \eqref{eq:NEfork1} in frame  $\mathcal F_2$ are
\begin{equation}
	\begin{split}
		0 &= F_{\!\mathrm{B}x} - F_{\!\mathrm{C}x},
		\\
		0 &= F_{\!\mathrm{B}y} - F_{\!\mathrm{C}y},
		\\
		0 &= \makebox[0pt][l]{$F_{\!\mathrm{B}z} - F_{\!\mathrm{C}z};$}%
		\phantom{ - M -  F_{\!\mathrm{B}x} h \cos{\gamma} + F_{\!\mathrm{B}z} h \sin{\gamma},}
	\end{split}
\end{equation}
similarly, neglecting the mass moment of inertia of the fork, 
${\mathbf{J}_{\mathrm{f}} = \mathbf 0 }$, 
\eqref{eq:NEfork2} resolved in frame  $\mathcal F_2$ yield
\begin{equation}
	\begin{split}
		0 &= -  T_{\mathrm{C}x} - F_{\!\mathrm{B}y} h \cos{\gamma},
		\\
		0 &= - T +  F_{\!\mathrm{B}x} h \cos{\gamma} - F_{\!\mathrm{B}z} h \sin{\gamma},
		\\
		0 &= - T_{\mathrm{C}z} - F_{\!\mathrm{B}y} h \sin{\gamma}.
	\end{split}
\end{equation}
Equation \eqref{eq:NEpm1} resolved in frame $\mathcal F_2$ has the components
\begin{equation}
	\begin{split}
		m_1 a_{\mathrm{A}x}&= - F_{\!\mathrm{A}x},
		\\
		m_1 a_{\mathrm{A}y}& = - F - m_{1} g \sin{\vartheta},
		\\
		m_1 a_{\mathrm{A}z}& = - F_{\!\mathrm{A}z} - m_{1} g \cos{\vartheta};
	\end{split}
\end{equation}
while \eqref{eq:NEpm2} in frame $\mathcal F_3$ gives 
\begin{equation}\label{eq:NEpm2_comp}
	\begin{split}
		m_{2} a_{\mathrm B x}&= - F_{\!\mathrm{B}x} \cos{\gamma} + (F_{\!\mathrm{B}z} + m_{2} g \cos{\vartheta}) \sin{\gamma} ,
		\\
		m_{2} a_{\mathrm B y} &= -F_{\!\mathrm{B}y} - m_{2} g \sin{\vartheta} ,
		\\
		m_{2}  a_{\mathrm B z} &= - F_{\!\mathrm{B}x} \sin{\gamma} - (F_{\!\mathrm{B}z} + m_{2} g \cos{\vartheta}) \cos{\gamma} .
	\end{split}
\end{equation}
Equations \eqref{eq:NEwheel_comp}--\eqref{eq:NEpm2_comp} form 18 equations for 25 unknowns which are the acceleration and constraint force/torque components:
\begin{equation}\arraycolsep=4pt
	\begin{array}{llllllllll}
		a_{\mathrm A x},  & a_{\mathrm A y},   & a_{\mathrm A z}, & a_{\mathrm B x},   & a_{\mathrm B y},   & a_{\mathrm B z},  & a_{\mathrm C x},   & a_{\mathrm C y},   & a_{\mathrm C z},  \\
		\alpha_x,          & \alpha_y,          & \alpha_z,          & K_{x},            & K_{y},             & K_{z},           &
		F_{\!\mathrm{B}x}, & F_{\!\mathrm{B}y}, & F_{\!\mathrm{B}z}, \\
		F_{\!\mathrm{C}x}, & F_{\!\mathrm{C}y}, & F_{\!\mathrm{C}z}, & F_{\!\mathrm{A}x} & F_{\!\mathrm{A}z}, &  T_{\mathrm{C}x}, & T_{\mathrm{C}z}.   &
	\end{array}
\end{equation}
Due to the kinematic constraints \eqref{eq:kinemConstraints} and geometric constraints \eqref{eq:geom_constr_eq_z}, \eqref{eq:geoMConstrS}, the acceleration components are not independent.
The acceleration components can be substituted from \eqref{eq:angularaccel_disc}, \eqref{eq:vA_aA} and  \eqref{eq:vB_aB}.
Consequently, 18 independent unknowns remain which are
\begin{equation}\arraycolsep=4pt
	\begin{array}{lllllllll}
		K_{x},             & K_{y},             & K_{z},           & F_{\!\mathrm{B}x}, & F_{\!\mathrm{B}y}, & F_{\!\mathrm{B}z}, & F_{\!\mathrm{C}x}, & F_{\!\mathrm{C}y}, & F_{\!\mathrm{C}z},  \\
		F_{\!\mathrm{A}x}, & F_{\!\mathrm{A}z}, & T_{\mathrm{C}x}, & T_{\mathrm{C}z}  & \dot\omega_{1},    & \dot\omega_{2},     & \dot\omega_{3},     & \dot\sigma_{r},    & \dot\sigma_{\gamma}.
	\end{array}
\end{equation}
Expressing the constraint forces and torques from \eqref{eq:NEwheel_comp}--\eqref{eq:NEpm2_comp} yields the components 
\begin{equation}\label{eq:contactForceComps}
	\begin{split}
		K_x &=  \frac{m_2 \sin{\gamma} }{h}\Big(
		3 \omega_{2}\sigma_{\gamma}  R \cos{\gamma} - 2 \omega_{2}^{2}  R^{2} \cos^{2}{\gamma}  
		- \sigma_{\gamma}^{2} 
		\Big)
		\\&\quad 
		- m_{1} \big( \dot \omega_{3} r  + 2 \omega_{3} \sigma_r \big) 
		+ \dot \omega_{2} \big(
		m R 
		+ m_{1} R 
		+ m_{2} R \sin^{2}{\gamma}\big) 
		\\&\quad
		+ m_{2} \big(
		\dot \sigma_{\gamma} \cos{\gamma} 
		-  \omega_{2} \omega_{3} R \sin{\gamma} \cos{\gamma} \tan{\vartheta} 
		- \omega_{3}^{2} h  \sin{\gamma} 
		\big) 
		\\&\quad 
		+ \omega_{1} \omega_{3} \big(m R + m_{1} ( r \tan{\vartheta} - R ) 
		+ m_{2} (R + h \cos{\gamma})\big) 
		\,,\\
		K_y &=  
		\frac{m_2 \sin{\vartheta} }{h}\Big(
		\omega_{2} \sigma_{\gamma} R \big(3  \sin^{2}{\gamma}  
		- 2  \big) 
		+ \sigma_{\gamma}^{2}  \cos{\gamma}
		\\&\quad
		+ \omega_{2}^{2} R^{2}  \cos{\gamma} \big( 1 - 2  \sin^{2}{\gamma} 
		\big) 
		\Big)
		- \dot \omega_{1} \big(
		m R  + m_{1} r \tan{\vartheta} 
		\\&\quad%
		+ m_{2} ( R  + h \cos{\gamma} ) 
		\big) \cos{\vartheta}
		+ \omega_{1}^{2} \big(
		m R  \sin{\vartheta} 	
		\\&\quad%
		- m_{1} (R \sin{\vartheta}  + r \cos{\vartheta}) 
		+ m_{2} (R  + h  \cos{\gamma}) \sin{\vartheta}
		\big) 
		\\&\quad
		- \omega_{3}^{2} \big( 
		m_{1}  r ( { \sin{\vartheta} \tan{\vartheta}} + \cos{\vartheta}) +
		m_{2} h  \sin{\vartheta} \cos{\gamma} 
		\big)  
		\\&\quad
		+ \omega_{2} \omega_{3} \big(
		{m R}/{\cos{\vartheta}} + m_{1} R ({ \sin{\vartheta}}{\tan{\vartheta}} +  \cos{\vartheta}) 
		\\&\quad%
		+ m_{2} R (
		{ \cos^{2}{\gamma} \sin{\vartheta}} {\tan{\vartheta}} 
		-  (1-2  \sin^{2}{\gamma} ) \cos{\vartheta} 
		)
		\big) 
		\\&\quad
		+ m_{1} \big(\dot \sigma_r \cos{\vartheta}  - 2 \sigma_r \omega_{1} \sin{\vartheta} 
		\big) 
		+ m_{2} \big(
		\dot \sigma_{\gamma} \sin{\gamma} \sin{\vartheta} 
		\\&\quad%
		- \dot \omega_{2} R \sin{\gamma} \sin{\vartheta} \cos{\gamma} 
		+  \dot \omega_{3} h \sin{\gamma} \cos{\vartheta} 
		\\&\quad%
		- 2 \omega_{1} \omega_{2} R  \sin{\gamma} \cos{\gamma} \cos{\vartheta} 
		- 2 \omega_{1} \omega_{3} h \sin{\gamma} \sin{\vartheta} 
		\\&\quad%
		+ 2 \omega_{1} \sigma_{\gamma}  \sin{\gamma} \cos{\vartheta} 
		+ 2 \omega_{3} \sigma_{\gamma}  \cos{\gamma} \cos{\vartheta} 
		\big) 
		\,,\\
		K_z &= \frac{m_2 \cos{\vartheta}}{h}\Big(
		\omega_{2}^{2} R^{2} \big(2  \sin^{2}{\gamma}
		- 1\big)  \cos{\gamma}
		- \sigma_{\gamma}^{2} \cos{\gamma} 
		\\&\quad 
		+ \omega_{2} \sigma_{\gamma}  R \big(
		2  
		- 3  \sin^{2}{\gamma} \big) 
		\Big)
		- \dot \omega_{1} \big(
		m R \sin{\vartheta} 
		- m_{1} r \cos{\vartheta} 
		\\&\quad%
		+ m_{2} (
		R 
		+ h  \cos{\gamma}) \sin{\vartheta}
		\big) 
		-  \omega_{1}^{2} \big(
		m R  
		- m_{1} (R 
		- r \tan{\vartheta}) 
		\\&\quad%
		+ m_{2} (
		R 
		+ h \cos{\gamma} )
		\big) \cos{\vartheta}
		+ m_{1} \big( 
		\dot \sigma_r \sin{\vartheta}  
		+ 2 \sigma_r \omega_{1} \cos{\vartheta} 
		\big) 
		\\&\quad 
		+ m_{2} \big(
		\dot \omega_{2}  R \sin{\gamma} \cos{\gamma} \cos{\vartheta}
		+ \dot \omega_{3}h\sin{\gamma} \sin{\vartheta}
		\\&\quad%
		- \dot \sigma_{\gamma} \sin{\gamma} \cos{\vartheta}
		- {\omega_{3}^{2}h \sin{\vartheta} \cos{\gamma}}{\tan{\vartheta}}  
		\\&\quad%
		- 2  \omega_{1} \omega_{2} R \sin{\gamma} \sin{\vartheta} \cos{\gamma} 
		+ 2 \omega_{1} \sigma_{\gamma} \sin{\gamma} \sin{\vartheta} 
		\\&\quad%
		+  \omega_{1} \omega_{3}h(
		\cos{\vartheta}- { \sin{\vartheta}}{\tan{\vartheta}} 
		)  \sin{\gamma}
		+ 2 \omega_{3} \sigma_{\gamma} \sin{\vartheta} \cos{\gamma} 
		\\&\quad%
		+  \omega_{2} \omega_{3} R (3  \sin^{2}{\gamma} 
		- 2  )\sin{\vartheta}
		\big) 
		+ \big(m + m_{1} + m_{2}\big) g 
	\end{split}
\end{equation}
of the contact force $\mathbf K$.
Note that these contact force components depend on the control inputs $F$ and $T$ through the pseudo-accelerations according to \eqref{eq:dsigmaDynEQS}.






