\centering
\subcaptionbox{The right-handed setup \label{fig:right_handed_integration_t12}}{
  \includegraphics[height=0.22\linewidth]{images/integration_setups/right_hand_setup.png} 
}\hspace{0.4cm}
\subcaptionbox{The left-handed setup
\label{fig:left_handed_integration_t12}}{
  \includegraphics[height=0.22\linewidth]{images/integration_setups/left_hand_setup.png}
