\section{Identifiability of Multi-Objective Reward Functions}

Let 
\[
\mathbf{R}(\tau_i) = \sum_{t=0}^{T} \gamma^t \mathbf{r}(s_t^i, a_t^i) \in \mathbb{R}^d,
\]
denote the vector return of a trajectory \(\tau_i\), and define the difference vector
\[
\Delta_{ij} \coloneqq \mathbf{R}(\tau_i) - \mathbf{R}(\tau_j).
\]
Under the Plackett--Luce model, the probability that \(\tau_i\) is preferred over \(\tau_j\) given a latent preference direction \(\mathbf{w}\) is 
\[
P(\tau_i \succ \tau_j) = \frac{\exp(\eta \, \mathbf{w}^\top \mathbf{R}(\tau_i))}{\exp(\eta\, \mathbf{w}^\top \mathbf{R}(\tau_i))+\exp(\eta\, \mathbf{w}^\top \mathbf{R}(\tau_j))},\quad \eta>0.
\]
Let \(\mathcal{C}\subset \mathbb{R}^d\) be a compact, convex cone representing the set of admissible preference directions.

\subsection*{Pareto Identifiability}

\begin{definition}[Pareto Identifiability]\label{def:pareto-identifiability}
We say that \(\mathcal{C}\) is \emph{Pareto-identifiable} from a dataset 
\[
\mathcal{D} = \{(\tau_i,\tau_j,y_{ij})\},
\]
(with \(y_{ij} = 1\) if \(\tau_i \succ \tau_j\) and \(y_{ij} = 0\) otherwise) if there exists an estimator \(\hat{\mathcal{C}}\) such that 
\[
\sup_{\mathbf{w}\in\hat{\mathcal{C}}}\inf_{\mathbf{w}'\in\mathcal{C}} \angle(\mathbf{w},\mathbf{w}') \le \epsilon,
\]
with probability at least \(1-\delta\), provided that the sample size satisfies
\[
N = \mathcal{O}\!\left(\frac{d\log(1/\delta)}{\epsilon^2}\right).
\]
\end{definition}

\subsection*{Cone Identifiability Guarantee}

\begin{theorem}[Cone Identifiability]\label{thm:cone-identifiability}
Assume that the set of difference vectors \(\{\Delta_{ij}\}\) spans \(\mathbb{R}^d\) and that \(\|\Delta_{ij}\|_2 \le B\) for some constant \(B>0\). Then, under the Plackett--Luce noise model, for any \(\epsilon,\delta>0\) there exists a sample size 
\[
N = \mathcal{O}\!\left(\frac{d\log(1/\delta)}{\epsilon^2}\right)
\]
such that an empirical risk minimizer \(\hat{\mathbf{w}}\), obtained via logistic loss minimization over the dataset, satisfies
\[
\|\hat{\mathbf{w}}-\mathbf{w}^\star\|_2 \le c\,\epsilon,
\]
for some constant \(c>0\). Consequently, the estimated cone 
\[
\hat{\mathcal{C}} = \operatorname{cone}(\{\hat{\mathbf{w}}_k\}_{k=1}^K)
\]
satisfies
\[
\sup_{\mathbf{w}\in\hat{\mathcal{C}}}\inf_{\mathbf{w}'\in\mathcal{C}} \angle(\mathbf{w},\mathbf{w}') \le \epsilon,
\]
with probability at least \(1-\delta\).
\end{theorem}

