\textcolor{black}{To prove the following corollary}, we use a fact that, for a homogeneous ideal $I$ in $R$, the equality $\sum_{i=0}^d \mathrm{dim}_K I_i = \mathrm{dim}_K (IR')_d$ holds for each $d \geq 0$.   
\textcolor{black}{Also we take a graded ordering $\prec$ (preferably a DRL ordering) on monomials in $X$ and its homogenization on monomials in $X\cup\{y\}$. }

\begin{corollary}\label{cor:LM}
With notation as above, assume that $\bm{F} = (f_1,\ldots , f_m) \in R^m$ is affine cryptographic semi-regular.
Put $\overline{I} := \langle \bm{F}^{\rm top} \rangle_R$ and $\tilde{I} := \langle \bm{F}^h \rangle_{R'}$.
Then, we have $(\langle \mathrm{LM}(\tilde{I}) \rangle_{R'})_d = (\langle \mathrm{LM}(\overline{I}) \rangle_{R'})_d $ for each $d$ with $d < D:=d_{\rm reg} (\overline{I})$.
\end{corollary}

\begin{proof}
We prove $(\langle \mathrm{LM}(\tilde{I}) \rangle_{R'})_d \subset (\langle \mathrm{LM}(\overline{I}) \rangle_{R'})_d $ by the induction on $d$.
The case where $ d =0$ is clear from Theorem \ref{thm:main}, and so we assume $d >0$.
{Any element in $(\langle \mathrm{LM}(\tilde{I}) \rangle_{R'})_d$ is represented as a finite sum of elements in $R'$ of the form $g \cdot \mathrm{LM}(h)$ with $g \in R'$, $h \in \tilde{I}$, and $\mathrm{deg}(gh) = d$.
Hence, we can also write each $g \cdot \mathrm{LM}(h)$ as a $K$-linear combination of elements of the form $\mathrm{LM}(t h)$ for a monomial $t$ in $R'$ of 
\textcolor{black}{degree} $\mathrm{deg}(g)$, where $t h$ is an element in $\tilde{I}$ of degree $d$. 
Therefore, it suffices for showing ``$\subset$'' to prove that $\mathrm{LM}(f) \in (\langle \mathrm{LM}(\overline{I}) \rangle_{R'})_d$ for any $f \in \tilde{I}$ with $\mathrm{deg}(f) = d$.}
We may assume that $f$ is homogeneous.
It is straightforward that $f|_{y=0} \in \overline{I}_{\leq d}$.
If $\mathrm{LM}(f) \in R=K[x_1,\ldots , x_{n}]$, then we have $\mathrm{LM}(f) = {\rm LM}(f|_{y=0}) \in \mathrm{LM}(\overline{I})$.
Thus, we may also assume that $y \mid \mathrm{LM}(f)$.
In this case, it follows from the definition of the DRL ordering that any other term in $f$ is also divisible by $y$, so that $f \in \langle y \rangle_{R'}$.
Thus, we can write $f = y h$ for some $h \in R'$, where $h$ is homogeneous of degree $d-1$.
As in the proof of Theorem \ref{thm:main}, the multiplication map
\[
(R'/\tilde{I})_{d'-1} \to (R'/\tilde{I})_{d'} \ ; \ h' \bmod{\tilde{I}} \mapsto  y h' \bmod{\tilde{I}}
\]
is injective for any $d' < d_\mathrm{reg}( \overline{I} )$, since $F$ is cryptographic semi-regular. 
Therefore, it follows from $f \in \tilde{I}_d$ that $h \in \tilde{I}_{d-1}$, whence $f = y h \in y \tilde{I}_{d-1}$.
By the induction hypothesis, there exists $g\in \overline{I}$ such that $\mathrm{LM}(g) \mid \mathrm{LM}(h)$, whence $\mathrm{LM}(f) \in (\langle \mathrm{LM}(\overline{I}) \rangle_{R'})_d$.

Here, it follows from Theorem \ref{thm:main} that
\begin{eqnarray*}
    \mathrm{dim}_K (R')_d - \mathrm{dim}_K \tilde{I}_d & = & \sum_{i=0}^d \left( \mathrm{dim}_K R_i -  \mathrm{dim}_K {\overline{I}}_i \right) = \sum_{i=0}^d \mathrm{dim}_K R_i - \sum_{i=0}^d  \mathrm{dim}_K {\overline{I}}_i \\
    &=& \mathrm{dim}_K (R')_d - \mathrm{dim}_K (\overline{I} R')_d,
\end{eqnarray*}
and thus $\mathrm{dim}_K \tilde{I}_d = \mathrm{dim}_{K} (\overline{I} R')_d$.
Hence, it follows from $\langle \mathrm{LM}(\overline{I})\rangle_{R'} = \langle \mathrm{LM}(\overline{I}R') \rangle_{R'}$ that
\[
\mathrm{dim}_K (\langle \mathrm{LM}(\tilde{I}) \rangle_{R'})_d = \mathrm{dim}_K (\langle \mathrm{LM}(\overline{I}) \rangle_{R'})_d,
\]
whence $(\langle \mathrm{LM}(\tilde{I}) \rangle_{R'})_d = (\langle \mathrm{LM}(\overline{I}) \rangle_{R'})_d $, as desired.
\end{proof}



