\section{Preliminaries}
A graph is typically represented as a pair, $G=(V,E)$, where $V$ is a set of vertices and $E$ is a set of edges connecting pairs of vertices.
In this basic representation, all edges are considered equivalent. However, in many cases, edges have distinct values or significance. For example, in a transportation network, an edge might represent an actual distance or transportation cost. To capture this, an edge-weight function $w: E \to \mathbb{R}$ is introduced. A graph equipped with such a function, denoted $V=(G,E,w)$, is called an \textit{edge-weighted graph}. 
Alternatively, assigning values to vertices rather than edges can provide a more accurate representation in certain contexts. For example, in a transaction network, a vertex weight could represent the market capitalization or size of a company. Similarly, a vertex-weight function $m:V \to \mathbb{R}$ can be defined. A graph with this function, denoted $G=(V,E,m)$, is called a \textit{vertex-weighted graph}. 
A graph incorporating both types of weights, denoted as $G=(V,E,w,m)$, is termed a \textit{doubly-weighted graph}.

To integrate these graphs and represent them as multilayer graphs, it is necessary to add a new element, i.e., a set of “layers,” to this graph representation.
\begin{definition}
A \textit{multiplex graph} s defined by the structure $M = (V_M, E_M, V, \mathcal{L})$, where 
\begin{enumerate}
    \item $V = \left\{u_1, u_2, \cdots, u_n \right\}$ is the set of state vertices, 
    \item $\mathcal{L} = \left\{1, \cdots, L \right\}$ is the set of layers,
    \item $V_M = V \times \mathcal{L}$ is the set of vertices in each layer. Each element ($x^i$) in $V_M$ represents the vertex $x$ in layer $i$, and the subset of state vertices belonging to a specific layer $i$ is denoted by $V_M^i = V \times \left\{i\right\}$.
    \item $E_M \subseteq V_M \times V_M$ is the set of edges, and $E_M$ is typically partitioned into a set of intra-layer edges, defined as $E_A := \left\{(x^i, y^j) \in E_M \mid i = j \right\}$, and a set of inter-layer edges, defined as $E_C := \left\{(x^i, y^j) \in E_M \mid x = y \right\}$. The set of edges in layer $i$ is denoted by $E_M^i$.
\end{enumerate}
Specifically, when $L=1$, $M$ is referred to as a \textit{monolayer graph} and corresponds to a standard graph.
\end{definition}
\begin{remark}
    As noted by Kivel\"{a} et al. \cite{kivela2014}, the term multilayer graph encompasses various constructions for  integrating several graph layers, and specific terminology often depends on the characteristics of the graphs to be integrated and the method of integration. This study focuses on multiplex graphs, characterized by having the same vertex set in each layer and inter-layer edges that connect only corresponding vertices across different layers.
\end{remark}
 \begin{figure}[h]
     \centering
     \includegraphics[scale=0.5]{Figures/multilayer.png} 
     \caption{Example of a multiplex graph $M=(V_M,E_M,V,\mathcal{L})$, where $V=\left\{0,1,2,3,4,5,6 \right\}$, $\mathcal{L}=\left\{1,2\right\}$, and $E_M$ comprises 11 edges.
     }
     %$E_M = \left\{(0^1, 2^1),(0^1, 3^1),(0^1, 4^1), (0^1,5^1),(0^1,6^1),(4^1,5^1),(5^1,6^1),(1^2,2^2),(2^2,3^2),(3^2,6^2),(1^2,5^2)\right\}$.}
     \label{multilayer}
 \end{figure}

Similar to monolayer graphs, weight functions can be defined for multiplex graphs. Specifically, $w : E_M \to \mathbb{R}$ is an edge-weight function and $m : V_M \to \mathbb{R}$ is a vertex-weight function. A multiplex graph, denoted by $M=(V_M,E_M,V,\mathcal{L},w,m)$, is called a \textit{doubly-weighted multiplex graph}.

Henceforth, unless stated otherwise, the term “multiplex graph” in this paper will refer to a doubly-weighted multiplex graph.

We now adapt fundamental graph concepts to the multiplex setting.
\begin{definition}
    Let $M = (V_M, E_M, V, \mathcal{L}, w, m)$ be a multiplex graph. 
    \begin{enumerate}
    \item For any state vertex $x^i \in V_M$, the \textit{neighborhood} of $x^i$ is defined by
    \begin{eqnarray*}
    \Gamma (x^i) &=& \Gamma_A(x^i) \cup \Gamma_C (x^i)\\
    &:=&\left\{ y^i \in V_M \mid (x^i, y^i) \in E_A \right\} \cup \left\{ x^j \in V_M \mid (x^i, x^j) \in E_C \right\}.
    \end{eqnarray*}
    We also use the notation $\Gamma^{i,j}_C (x) := \Gamma_C(x^i) \setminus \left\{x^j \right\} = \Gamma_C (x^j) \setminus \left\{x^i \right\}$.
    \item For any state vertex $x^i \in V_M$, the \textit{degree} of $x^i$ is defined as
    \begin{eqnarray*}
    \deg (x^i) = \sum_{y^i \in \Gamma (x^i)}w((x^i,y^i)).
    \end{eqnarray*}
    \end{enumerate}
\end{definition}

When constructing a multiplex graph by combining multiple doubly-weighted graphs, the intra-layer weight of each edge of $E_A$ can be directly inherited from the original graph. However, it is important to define the weights of each inter-layer edge. Therefore, we introduce the concept of a compile graph. For this purpose, we first define the following quantity for any state vertex $x^i \in V_M$:
\begin{eqnarray*}
    W(x^i) := 
    \begin{cases}
        \left( \sum_{y^i \in \Gamma_A (x^i)} \cfrac{1}{\sqrt{w((x^i,y^i))}}\right)^{-1},& \text{if}\ \Gamma_A(x^i) \neq \emptyset,\\
        0,& \text{if}\ \Gamma_A(x^i) = \emptyset.
    \end{cases}
\end{eqnarray*}
\begin{definition}
    Let $\left\{G_l = (V, E_l, w_l, m_l) \right\}_{l=1}^L$ be a sequence of doubly-weighted graphs with the same number of vertices. 
    A \textit{compile graph} $CG$ is then defined as the multiplex graph     \begin{eqnarray*}
        V(CG) &=& V,\ \mathcal{L} = \left\{1, \cdots, L \right\},\ V_{CG} = \bigsqcup_l (V(G_l) \times \left\{l \right\}),\\
        E_A &:=& \left\{(x^i,y^j) \in V_{CG} \times V_{CG} \mid i=j,\ (x,y) \in E(G_i)\right\},\\
        E_C &:=& \left\{ (x^i,x^j) \mid x \in V,\ i,j\in \mathcal{L},\ i \neq j \right\},
    \end{eqnarray*}
   where $m(x^i) = m_i(x)$ for any vertex $x^i \in V_{CG}$, $w((x^i,y^i)) = w_i ((x,y))$ for any intra-layer edge $(x^i, y^i) \in E_A$, and
    \begin{eqnarray*}
    w((x^i,x^j)) = \min \left\{ W^2_i(x), W^2_j(x) \right\} 
    \end{eqnarray*}
    for any inter-layer edge $(x^i,x^j) \in E_C$.  
\end{definition}

\begin{remark}
    If all intra-layer edge weights equal 1, then $W(x^i)=1/|\Gamma_A(x^i)|$. In this case, the smaller the number of edges connected to a vertex $x^i$, the larger the value of $W(x^i)$.
    To further investigate the behavior of $W(x^i)$ in more detail when intra-layer edge weights are not equal to 1, we consider the function $f(x, y) = 1/\sqrt{x} + 1/\sqrt{y}$. If $x>0$, then     \begin{eqnarray*}
        \frac{\partial f}{\partial x} = - \frac{1}{x^{3/2}} < 0.
    \end{eqnarray*}
    Thus, $f(x,y)$ is a monotonically decreasing function when $x>0$ and $y>0$. This is because the partial derivatives of $y$ are obtained similarly.
    As $W(x^i)$ can be expressed as an inverse function of $f(x,y)$,  $W(x^i)$ monotonically increases with respect to each incident intra-layer edge weight. That is, $W(x^i) < W(x^j)$ suggests that the overall weight associated with the intra-layer edges connected to vertex $x^j$ is greater than that for those connected to vertex $x^i$. 
\end{remark} 
