\title{Path degeneracy and applications}
\thanks{\ERCagreement}
\author[Y. Lin]{Yuquan Lin}
\address{Southeast University, Nanjing, Jiangsu, China \and Centre d'Analyse et de Mathématique Sociales CNRS UMR 8557, France.}
\email{yqlin@seu.edu.cn}
\author[P. Ossona de Mendez]{Patrice Ossona de Mendez}
\address{Centre d'Analyse et de Mathématique Sociales CNRS UMR 8557, France \and Computer Science Institute of Charles University (IUUK), Praha, Czech Republic}
\email{pom@ehess.fr}
\begin{abstract}
In this work, we relate girth and path-degeneracy in classes with sub-exponential expansion, with explicit bounds for classes with polynomial expansion and proper minor-closed classes that are tight up to a constant factor (and tight up to second order terms if a classical conjecture on existence of $g$-cages is verified). As an application, we derive bounds on the generalized acyclic indices, on the generalized arboricities, and on the weak coloring numbers of high-girth graphs in such classes.
Along the way, we prove a conjecture 
proposed in 
[T.~Bartnicki \emph{et al.}, \emph{Generalized arboricity of graphs with large girth},
  Discrete Mathematics \textbf{342} (2019), no.~5, 1343--1350.],~which asserts that, for every integer $k$, there is an integer $g(p,k)$ such that every $K_k$ minor-free graph with girth at least $g(p,k)$  has $p$-arboricity at most $p+1$. 
\end{abstract}
\maketitle

 \section{Introduction}

The original notion of path-degeneracy
was introduced in \cite{NO2015} in a study of the circular chromatic number of graphs with large girth excluding a minor. 
In this paper, we consider a slightly different definition, which will be suitable in a broader context (bounding the generalized $p$-arboricity, the generalized $p$-acyclic chromatic number, or the weak coloring number of graphs with large girth in a ``nice'' monotone class $\mathscr C$).

A graph is  \emph{$p$-path degenerate} if it can be constructed from the empty graph by successively adding an isolated vertex, a vertex of degree one, or a path of length $p$ with both endpoints in the previously constructed graph (see \Cref{sec:def,fig:PD}).
\begin{figure}[h!]
\begin{center}
\includegraphics[width=.75\textwidth]{constr}
\end{center}.
    \caption{Construction of a $p$-path degenerate  graph}
    \label{fig:PD}
\end{figure}


In this paper, we denote by $|G|$ the \emph{order} of a graph $G$ (that is, its number of vertices), and by $\|G\|$ its \emph{size}
(that is, its number of edges).
Recall that a  minor  of a graph $G$  at \emph{depth} $r$ is a minor of $G$ obtained by contracting disjoint subgraphs with radius at most $r$ and removing edges, and that 
$\nabla_r(G)$ denotes the maximum ratio $\|H\|/|H|$ over all (non-empty) minors $H$ of $G$ at depth $r$.
The \emph{expansion function}
${\rm Exp}_{\mathscr C}$ of a class $\mathscr C$ is defined by
\[{\rm Exp}_{\mathscr C}(r)
=\sup\{\nabla_r(G)\colon G\in\mathscr C\}.\]

A class $\mathscr C$ has 
\begin{itemize}
    \item \emph{bounded expansion},  if ${\rm Exp}_{\mathscr C}(r)<\infty$;
    \item  \emph{sub-exponential expansion}, if ${\rm Exp}_{\mathscr C}(r)=2^{o(r)}$;
    \item \emph{polynomial expansion},  if ${\rm Exp}_{\mathscr C}(r)=r^{O(1)}$.
\end{itemize}
Formal definitions and basic facts about shallow minors will be recalled in~\Cref{Sec:Pre}, and we refer the interested reader to \cite{Sparsity} for an in-depth study.


\subsection{Our results}

As a warm-up, we consider the general case of classes with sub-exponential expansion and prove the following.
\begin{restatable}{theorem}{ThmSE}
 \label{th:pd-subexponential}
    Let $\mathscr C$ be a class with sub-exponential expansion.
    Then, for every integer $p$ there exists an integer $g_p$ such that every graph $G\in\mathscr C$ with girth at least $g_p$ is $p$-path degenerate.
\end{restatable}

Then, we consider more precisely the case of classes with polynomial expansion, and provide a bound on $g_p$  in terms of the $\W$ branch of Lambert's $W$ function.

\begin{restatable}{theorem}{ThmPol}
\label{th:pd-polynomial}
      Let $\mathscr C$ be a class with polynomial expansion, with ${\rm Exp}_{\mathscr C}(r)\leq a(r+\frac12)^b$ for some positive reals
 	$a,b$.
We define
\[
g_p=\max\left(7,2\left\lfloor-\frac{2b}{\log 2}\W\left(-\frac{\log 2}{(24\sqrt{2}a)^{1/b}\,bp}\right)\right\rfloor+4\right)(p-1).
\]


    Then, every graph $G\in\mathscr C$ with
\[
\girth(G)>g_p\sim 4bp\log_2p\\
\]
is $p$-path degenerate.
\end{restatable}

Then, we prove that our bound is tight up to a constant factor.

\begin{restatable}{theorem}{ThmPolLower}
\label{thm:poly_lower}
    For every real $b>0$, there exists a class with expansion $O(r^b)$ such that  for infinitely many $p\in\mathbb N$ the class  contains a graph $G$ with
\[
\girth(G) \ge -\frac{8b}{3\log 2}\W\left(-\frac{\log 2}{(p-1)b}\right)(p-1)\sim\frac{8}{3}bp\log_2 p
\]
that is not $p$-path degenerate.
\end{restatable}

We conjecture that the bound given in \Cref{th:pd-polynomial} is tight up to second order term.

\begin{restatable}{conjecture}{ConjPolLower}
\label{conj:poly_lower}
    For every real $b>0$, there exists a class with expansion $O(r^b)$ such that  for infinitely many $p\in\mathbb N$ the class  contains a graph $G$ with
\[
\girth(G) \sim 4bp\log_2 p
\]
that is not $p$-path degenerate.
\end{restatable}

As a support to this conjecture, we note that its validity would follow from the following conjecture on the existence of $g$-cages (which will be used to support our other conjectures, too).

\begin{conjecture}[{\cite[p. 164]{B1978}}]
\label{conj:cage}
For infinitely many integers $g$ there
exists a cubic graph with girth at least $g$ and order at most $c2^{g/2}$.
\end{conjecture}

Then, we consider proper minor-closed classes of graphs and prove the following bound.

\begin{restatable}{theorem}{ThmMC}
  \label{th:pd-MC}
    Let $\mathscr{C}$ be a  proper minor-closed class of graphs and let $d$ be the maximum average degree of the graphs in $\mathscr C$.
    Then, for every integer $p\ge2$, every graph $G\in\mathscr{C}$ with %
    $$\girth(G)>(4\log_{2}d+2\log_{2}(\min\{d,576\})+3)(p-1)$$
    is $p$-path degenerate.  
\end{restatable}

Again, we prove that our bound is tight up to a constant factor.

\begin{restatable}{theorem}{ThmMClower}
\label{th:MC_lower}
There exists a constant $c$ with the following property:
for every real $d_0>0$ there exists a real $d\geq d_0$ and a proper minor closed class  with maximum average degree at most $d$ that contains,  for every integer $p\geq 2$, a graph $G_p$ with 
\[
\girth(G_p)\ge\left(\frac83\log_2(d-2)+c\right)(p-1)
\]
that is not $p$-path degenerate.
\end{restatable}

We conjecture that the bound given in \Cref{th:pd-MC} is essentially tight, what would be a consequence of  the validity of \Cref{conj:cage}.

\begin{restatable}{conjecture}{ConjMClower}
\label{conj:MC_lower}
There exists a constant $c$ with the following property:
for every real $d_0>0$ there exists a real $d\geq d_0$ and a proper minor closed class  with maximum average degree at most $d$ that contains,  for every integer $p\geq 2$, a graph $G_p$ with 
\[
\girth(G_p)\ge(4\log_2(d-2)+c)(p-1)
\]
that is not $p$-path degenerate.
\end{restatable}





In the case where the class $\mathscr C$ is the class of all graphs excluding $K_k$ as a minor, we derive (see \Cref{th:pd-KF}) that the maximum girth $g(K_k,p)$ of a $K_k$-minor free graph that is not $p$-path degenerate is bounded by
     $$\Bigl(\frac{8}{3}\log_{2}k+c\Bigr)(p-1)\le g(K_k,p)<(4\log_{2}k+2\log_{2}\log_{2}k+O(1))(p-1).$$

We conjecture that $g(K_k,p)$ is close to the upper bound:
\begin{restatable}{conjecture}{ConjKkp}
We have
 $$g(K_k,p)=(4\log_2 k+O(1))(p-1).$$
\end{restatable}

Note that \Cref{conj:cage} would imply that, for some constant $c$, we have
$g(K_k,p)\geq (4\log_2 k+c)(p-1)$ for all $p$ and infinitely many $k$.



\subsection{Applications}
We review here some of the applications of our study of path-degeneracy.

\subsubsection*{Generalized $r$-arboricity}
Given an integer $r\ge1$, 
the \emph{generalized $r$-arboricity} $\arb_r(G)$ of a graph $G$ \cite{NOZ2014}
    is the minimum number of colors in a coloration of the edges of $G$ such that every cycle $C$ of $G$ gets  at least $\min\{|C|,r+1\}$ colors.
    Note that if $r=1$, then $\arb_1(G)$ is the usual arboricity $\arb(G)$.

    The generalized $r$-arboricity $\arb_r(G)$ is  unbounded for planar graphs: for any $r\ge2$,  there are planar graphs with arbitrarily large $\arb_r(G)$ (see \cite{BBCFGM2019} for such examples).
However, for every  class  with bounded expansion,  $\arb_r(G)$ is  bounded  for graphs with sufficiently large girth (depending on $r$) \cite{NOZ2014}.
One can deduce from the definition of $\arb_r(G)$ that  if a graph $G$ has girth at least $r+1$, then $\arb_r(G)\ge r+1$.
We prove that every  $(r+1)$-path degenerate graph  $r$ satisfies $\arb_r(G)\le r+1$ in \Cref{th:arb-PD}.



In this context, we focus on the bound for the generalized $r$-arboricity of large girth graphs in a given class.
We study the invariant $\A_{r}(\mathscr{C})$ of a  class $\mathscr{C}$ with bounded expansion,
 which  was defined 
in \cite{BBCFGM2019} as
\[\A_r(\mathscr C):=\min\bigl\{k: \exists g \ \forall G\in \mathscr{C} \  (\girth(G)\ge g)\Rightarrow (\arb_{r}(G)\le k)\bigr\}.\]

Obviously,
the best possible for 
 $\A_{r}(\mathscr{C})$ is  $r+1$. %
 Bartnicki et al. 
  \cite{BBCFGM2019} 
  proved  that $\A_{r}(\mathscr{C})=r+1$ holds for planar graphs and more generally, for graphs with any fixed genus. They  also indicated that this equality  does not hold for every class with bounded expansion and  conjectured the following.

\begin{restatable}[{\cite[Conjecture 7]{BBCFGM2019}}]{conjecture}{ConjA}
\label{conj:A-MC}
    Every   proper minor-closed class of graphs
 $\mathscr{C}$  satisfies   $\A_{r}(\mathscr{C})=r+1$.
\end{restatable}


We  confirm this conjecture 
by proving the following theorem in a strong form.



\begin{restatable}{theorem}{ThmAr}\label{th:arb-subexponential}
Let $\mathscr C$ be a class with sub-exponential expansion and let $r$ be a positive integer.

If $\mathscr C$ contains some graph $G$ with  $r<\girth(G)<\infty$,
then  $\A_{r}(\mathscr{C})=r+1$; otherwise,  $\A_{r}(\mathscr{C})=1$.
\end{restatable}








\subsubsection*{Generalized $r$-acyclic chromatic index}
Given an integer $r\ge 3$, 
the \emph{generalized $r$-acyclic chromatic index} $\ap_r(G)$ of a graph $G$ \cite{GGW2006} is the minimum number of colors in a proper coloration of the edges of $G$ such that every cycle $C$ of $G$ gets  at least $\min\{|C|,r\}$ colors. (Thus, it is a strengthening of generalized $(r-1)$-arboricity requiring the edge coloration to be proper.)
    The case $r=3$ is the well-known acyclic edge coloring.

       Obviously, if  a graph $G$ has
 maximum degree $\Delta$ and girth at least $r$, then
             at least $\max\{\Delta,r\}$ colors are required for its  generalized $r$-acyclic edge colorings.
 We prove that every  $(r+1)$-path degenerate graph  $G$  satisfies $\ap_r(G)\le \max\{\Delta,r\}$ in \Cref{th:acyclic-pd}.

 In general, graphs with large girth can have arbitrary large generalized $r$-acyclic chromatic indices,
for instance, Greenhill and Pikhurko \cite{GP2005} proved that for  fixed integer $r\ge4$, there exist graphs $G$ such that 
 $\ap_r(G)\ge c\Delta^{\lfloor r/2 \rfloor}$ for some  positive constants $c$. 
However, if restricted to some  nice classes of graphs,    large girth graphs may be forced to have small generalized $r$-acyclic chromatic indices, in the sence that they are close to the best possible  value of $\max\{\Delta,r\}$. 
For example, combining \cite[Theorem 3.3]{HWLL2009} 
and \cite[Theorem 6]{ZWYLL2012} together, 
we obtain
for  every  integer  $r\ge3$, every planar graph $G$ with  $\Delta\ge3$ and $\girth(G)\ge5r + 1$ satisfies $\ap_r(G)=\max\{\Delta,r\}$. 


In this context, we extend the existence of a linear bound for the girth ensuring $\ap_{r}(G)\leq \max\{\Delta,r\}$ to all proper minor-closed classes in \Cref{cor:acyclic-PMCC}.
A more general form, for the class with sub-exponential expansion, is given as follows.


  \begin{restatable}{theorem}{ThmAcyclic}\label{th:acyclic-subexponetial}
Let $r\ge3$ be an integer, let $\mathscr{C}$ be a  class with sub-exponential class, and let $g(p)$ be the girth ensuring $p$-path degeneracy in $\mathscr C$.

Then, every graph $G\in \mathscr{C}$ with maximum degree $\Delta$ and girth at least $g(r+1)$ that is not a forest satisfies $\ap_{r}(G)= \max\{\Delta,r\}$.
\end{restatable}

\subsubsection*{Weak coloring number} Given an integer $r\ge1$,  the  \emph{weak $r$-coloring number} $\wcol_r(G)$ of a graph $G$ \cite{KY2003} is a minimum integer $k$ such that there exists a linear order $\pi$ on the vertices of $G$, so that for every vertex $v\in V(G)$, there are at most $k$ vertices $u\le_{\pi} v$ (possible $u=v$) that can be reached from $v$ by a path $P$ of length at most $r$, for which every internal vertex $w$ of $P$ satisfies $u< _{\pi} w$.



The growth rate of  weak $r$-coloring number for graphs in a fixed proper minor-closed class $\mathscr{C}$ has been extensively studied, see \cite[Table 1]{HLMR2025} for a summary on the lower and upper bounds on  $\max_{G\in\mathscr{C}} \wcol_r(G)$.
In particular, for the class  of all $K_k$-minor free graphs ($k\ge4$), the lower and upper bounds on  $\max_{G\in\mathscr{C}} \wcol_r(G)$ are 
$\Omega(r^{t-2})$ \cite{GKRSS2018} and $O(r^{t-1})$ \cite{VOQRS2017}, respectively.
Even for the class of planar graphs $\mathscr{C}$, the exact  growth rate of maximum weak $r$-coloring numbers
 is still unknown, and 
the known lower and upper bounds on $\max_{G\in\mathscr{C}} \wcol_r(G)$ are $\Omega(r^2\log r)$ \cite{JM2021} and $O(r^3)$ \cite{VOQRS2017}, respectively.

 In this context,  we first establish the path degeneracy conditions that ensure linear weak $r$-coloring numbers for general graphs in \Cref{th:wocl-pd}.
 Then, based on this theorem, 
 we prove that 
for  large girth graphs in any proper minor-closed class $\mathscr{C}$ and more generally, in the class with sub-exponential expansion,  
the weak $r$-coloring numbers grow linearly with $r$. 


  \begin{restatable}{theorem}{ThmWcol}\label{th:wcol-subexponential}
Let $r\ge 1$ be an integer, let $\mathscr{C}$ be a  class with sub-exponential class, and let $g(p)$ be the girth ensuring $p$-path degeneracy in $\mathscr C$.

Then, for every graph $G\in  \mathscr{C}$, we have

\[
\wcol_r(G)\leq\begin{cases}
r+2+\lfloor\log_2\bigl(\frac{q-1}{q-r}\big)\rfloor,&\text{if }\girth(G)\ge g(2q) \text{ and }r<q<2r,\\
r+2,&\text{if }\girth(G)\ge g(4r).
\end{cases}
\]
\end{restatable}

\subsection{Structure of the paper}

The paper is organized as follows:
In \Cref{Sec:Pre}, we recall some needed   preliminaries and notions. 
In \Cref{sec:pd}, we study the path degeneracy with graphs. In particular, we relate the path degeneracy and shallow (topological) minor, and further characterize the girth condition to ensure $p$-path degeneracy for some nice classes of graphs. 
Finally, in \Cref{sec:app}, we  discuss connections between path degeneracy and three different coloring problems:
generalized arboricity (in \Cref{sec:arboricity}),
general acyclic chromatic indices
(in \Cref{sec:acyclic}), 
and generalized coloring numbers
(in \Cref{sec:weak}).





