 \section{Preliminaries}\label{Sec:Pre}

 Let $G=(V(G),E(G))$ be a graph.
 The \emph{average degree} $\avd(G)$ is the average of the degrees of $G$, hence $2\|G\|/|G|$ (if $G$ is not empty, and $0$ by convention if $G$ is empty). 
The  \emph{maximum average degree} of a graph $G$, denoted by $\mad(G)$ is defined as the maximum of the average degrees of the  subgraphs of $G$: $\mad(G)=\max\{\avd(H)\colon H\subseteq G\}$.
The  maximum average degree of a class of  graphs $\mathscr{C}$ is defined by %
$\mad(\mathscr{C})=\sup\{\mad(G)\colon G\in \mathscr{C}\}$.

A graph $H$ is a \emph{minor} of $G$ if $H$ can be obtained from  $G$ by means of a sequence of vertex and edge deletions and edge contractions.
 A class of graphs $\mathscr{C}$ is \emph{minor-closed} if for every graph $G\in \mathscr{C}$, any minor of $G$ also belongs to $\mathscr{C}$;
a minor-closed class $\mathscr{C}$ is \emph{proper} if it does not contain all finite graphs.
The class of planar graphs is a traditional example of the proper minor-closed classes.

Let $r$ be a nonnegative  half-integer (that is, $r\in \frac{1}{2}\mathbb{N}$). A graph $H$ is a \emph{shallow topological minor of $G$ at depth $r$} if a $\le(2r)$-subdivision of $H$ is a subgraph of $G$.  More generally,
a graph $H$ is a \emph{shallow minor of $G$ at depth $r$}, if  each vertex $v\in V(H)$ corresponds to a rooted tree $(T_v,r_v)$ such that 
\begin{itemize}
\item for every vertex $v\in V(H)$,   $T_v$   has  radius at most $\lceil r \rceil$, where the radius of $(T_v,r_v)$ is the maximum length of a path of $T_v$ with one endpoint $r_v$,
    \item  the graphs $T_v$ (for  $v\in V(H)$) are vertex-disjoint subgraphs of $G$,  
\item for every edge $uv\in E(H)$, there exists an edge $e$ between $T_u$ and $T_v$ such that the length of the path between  $r_u$ and $r_v$ in $T_u\cup T_v \cup \{e\}$ is at most $2r+1$.
\end{itemize}




We denote by $G\mathbin{\nabla}r$ the class of all shallow minors of $G$ at depth $r$, and denote by  $\nabla_{r}(G)$ the maximum density of a graph in $G\mathbin{\nabla}r$, that is:
$$\nabla_{r}(G)=\max\biggl\{\frac{\|H\|}{|H|}:H\in G\mathbin{\nabla}r \biggr\}.$$

The \emph{maximum density} of a minor of  $G$, denoted by $\nabla(G)$, is defined as  $$\nabla(G)=\max\left\{\nabla_{r}(G):r\in \mathbb{N}\right\}.$$





\begin{proposition}[{\cite[Proposition 4.1]{Sparsity}}]
\label{prop:arithmetic}
    Let $a,b,c\in  \frac{1}{2}\mathbb{N}$.
    If $(2c+1)\geq (2a+1)(2b+1)$, then for every graph $G$, it holds that
$$(G\mathbin{\nabla}a)\mathbin{\nabla}b\subseteq G\mathbin{\nabla}c.$$
\end{proposition}


The \emph{expansion} of a class $\mathscr{C}$ is the function ${\rm Exp}_{\mathscr C}:\frac{1}{2}\mathbb N\rightarrow [0,+\infty]$ defined by
\[
{\rm Exp}_{\mathscr C}(r)=\sup\{\nabla_r(G)\colon G\in\mathscr C\}.
\]
A class $\mathscr C$ has \emph{bounded expansion} (resp. \emph{sub-exponential expansion}, \emph{polynomial expansion}) if ${\rm Exp}_{\mathscr C}(r)$ is finite for every half-integer $r$ (resp. ${\rm Exp}_{\mathscr C}(r)=2^{o(r)}$, ${\rm Exp}_{\mathscr C}(r)=r^{O(1)}$). %
Note that a class $\mathscr C$ is included in a proper minor-closed class if and only if ${\rm Exp}_{\mathscr C}(r)=O(1)$.
















\section{Path degeneracy}
\label{sec:pd}
In  this section, we  consider bounds on  the girth  that ensures $p$-path degeneracy for graphs in  a fixed class. After two preliminary subsections, 
we will discuss the considered classes from the more general to the more specific:  classes with sub-exponential expansion (\Cref{sec:subexp}),  classes with polynomial expansion (\Cref{sec:pol}), and eventually proper minor-closed classes (\cref{sec:minor}).

\subsection{Definition and basic facts}
\label{sec:def}
A \emph{strict ear} of a graph $G$ is a path of $G$, whose internal vertices have degree $2$ in $G$ and whose endpoints are distinct.
Given an integer $p\ge1$, a 
 \emph{$p$-reduction} of a graph $G$ is the deletion of
\begin{itemize}
    \item either an isolated vertex,
    \item or a vertex with degree $1$,
    \item or the internal vertices of a strict ear of $G$ with length at least $p$.
\end{itemize}
\begin{remark}
\label{rem:exact}
In the third $p$-reduction, we can require the strict ear to have length exactly $p$. Indeed, if a strict ear $P=(u,w_1,\dots,w_{q-1},z$ has length $q>p$, we can first delete the strict ear $(u,w_1,\dots,w_p)$, then the remaining vertices $w_{p+1},\dots,w_{q-1}$ in order (as they will have degree $1$).
\end{remark}
 A graph $G$ is \emph{$p$-path degenerate} if it can be reduced to the empty graph by a sequence of $p$-reductions.
 As every graph is obviously $1$-path degenerate, we only consider $p$-path degeneracy for 
 $p\ge2$.

A graph $G$ is \emph{$p$-reducible} if there exists a  $p$-reduction that can be performed on $G$; otherwise, $G$ is called \emph{$p$-irreducible}.
It is clear that every $p$-irreducible graph has minimum degree at least 2.
A  \emph{minimal $p$-irreducible} graph $G$ is a $p$-irreducible graph such that every proper subgraph of $G$ is $p$-reducible.



The following useful fact is easy to establish.


\begin{fact}
\label{fact:hered}
If $H$ is a subgraph of a $p$-path degenerate graph $G$, then $H$ is $p$-path degenerate.
\end{fact}

Note that,   a graph is $p$-path degenerate if and only if all its connected components are $p$-path degenerate. However, the $p$-path degeneracy of a graph cannot be reduced to its  2-connected components. 
For an instance, 
see \Cref{fig:theta-graph},  where  all blocks of the graph  are $p$-path degenerate, but the graph itself is not $p$-path degenerate.
(In the figure, $\Theta(l_1,l_2,\ldots,l_t)$ denotes 
the \emph{generalized theta graph},  which is the graph consisting of $t$  internally disjoint paths with lengths  $l_1\le l_2\le \ldots \le l_t$ connecting two vertices.)


