    \centering
    \includegraphics[width=\textwidth]{cases}
    \caption{The different cases considered in the proof of \Cref{th:wocl-pd} to bound 
$|\WReach_x[G_{i+1},\pi_{i+1},v]|$.
    }
    \label{fig:cases}
\end{figure}

\begin{lemma}\label{th:wocl-pd}
	Let $r,q$ be positive integers with $q\ge r+1$, 
	 and let  $G$ be a  $2q$-path degenerate graph.
	Define $f(0)=1$ and, if $x\geq 1$, 
	\[
	f(x)=\begin{cases}
		x+2+\log_2\bigl(\frac{q-1}{q-x}\big),&\text{if }q <2r,\\
		x+2&\text{otherwise.}
	\end{cases}
	\]
	Then, $G$ has a good linear order $\pi$ with respect to $f$ up to $r$.
\end{lemma}
\begin{proof}
	Let $p=2q$.
	According to the definition of path degeneracy and  \Cref{rem:exact}, there exists a sequence $G_1 \subset \ldots \subset G_t=G$ such that $G_1$ is an isolated vertex, and  each $G_i$ ($i\ge1$) is obtained from $G_{i+1}$ by performing a $p$-reduction $R_{i+1}$ of $G_{i+1}$, where $R_{i+1}$ deletes either a vertex with degree at most $1$ or a strict ear with length  $p$
	of $G_{i+1}$

	We prove that $G_i$ has a good linear order with respect to $f$ up to $r$ by induction on $i$ (for $1\leq i\leq t$).
	The base case $i=1$ is trivial since $G_1$ is an isolated vertex. 
	Assume that every graph $G_j$ ($1\le j \le i$) has  a good linear order $\pi_j$ with respect to $f$  up to $r$. We prove that $G_{i+1}$  has  a good linear order $\pi_{i+1}$ with respect to $f$  up to $r$.   
	We may assume that $R_{i+1}$ deletes  a strict ear $P$ with length  $p$ of $G_{i+1}$ as otherwise the statement is true according to \Cref{lemma:wcol-01-vertex}.


	Let $u_1$ and $u_2$ be the two endpoints of $P$.
	We denote by 
	\[u_1,v^1_1,\dots,v^1_{q-1},w,v^2_{q-1},\dots,v^2_1,u_2\]
	 (in order) the vertices of $P$, and consider the linear order
	\[
	\pi_{i+1}:= w,\pi_i,v^1_1,\dots,v^1_{q-1},v^2_1,\dots,v^2_{q-1}
	\]
	of $V(G_{i+1})$.

    We aim to prove that $|\WReach_x[G_{i+1},\pi_{i+1},v]|\le f(x)$ holds for all vertices $v$ of $G_{i+1}$. We will consider several cases, as indicated on \Cref{fig:cases}.
	\medskip

	Since every vertex $v\in V(G_i)$ is at distance at least $r+1$  from $w$, we have 
	$$|\WReach_x[G_{i+1},\pi_{i+1},v]|=|\WReach_x[G_{i},\pi_{i},v]|\le f(x).$$

	Moreover, for every $0\le x \le r$, it is clear that $$|\WReach_x[G_{i+1},\pi_{i+1},w]|=1\le f(x).$$

	It remains to consider vertices $v^s_{z}$ (for $s\in\{1,2\}$ and $1\le z \le q-1$).

	If $x=0$, then $|\WReach_0[G_{i+1},\pi_{i+1},v^s_z]|=1= f(0)$. Hence, we can assume $x\geq 1$.
	We consider three different cases.
	\medskip

	$\bullet$ If $x<z$, then 	\[
	\WReach_x[G_{i+1},\pi_{i+1},v^s_z]=
	\begin{cases}
		\{v^s_{z-x},\dots,v^s_z\},&\text{if }x< q-z,\\
		\{v^s_{z-x},\dots,v^s_z,w\},&\text{otherwise}.
	\end{cases}
	\]
	Hence,
	\[	\max_{1\le x <z<q}|\WReach_x[G_{i+1},\pi_{i+1},v^s_z]|=x+2\le f(x). 
    \]
	\medskip

$\bullet$ If $x=z$, we have
$|\WReach_x[G_{i+1},\pi_{i+1},v^s_x]|\leq x+2\leq f(x)$.
\medskip

$\bullet$ Thus, we can assume $x>z$.

	It is easily checked that $\WReach_x[G_{i+1},\pi_{i+1},v^s_z]$ is the disjoint union of 
	$\WReach_{x-z}[G_i,\pi_i,u_s]$  and a subset $N_{x,s,z}$ of internal vertices of $P$ defined by
	\[
	N_{x,s,z}=
	\begin{cases}
		\{v^s_1,\dots,v^s_z\},&\text{if }x< q-z,\\
		\{v^s_1,\dots,v^s_z,w\},&\text{otherwise}.
	\end{cases}
	\] 

	As $\pi_i$ is a good linear order with respect to $f$ up to $r$ for $G_i$, we deduce that for every $s\in\{1,2\}$ and $1\le z < q$ we have
	\[
	|\WReach_x[G_{i+1},\pi_{i+1},v^s_z]|\leq f(x-z)+z+\begin{cases}
		0,&\text{if }x< q-z,\\
		1,&\text{if }x\geq q-z.
	\end{cases}
	\]

\begin{itemize}
\renewcommand{\labelitemi}{--}
\item Assume $q\ge 2r$ (in which case $f(x)=x+2$). 

Then, there is no $x\leq r$ and $z<x$ such that 
$x\geq q-z$. Thus, we have
\[
|\WReach_x[G_{i+1},\pi_{i+1},v^s_z]|\leq f(x-z)+z=f(x).\]
Hence, $\pi_{i+1}$ is a good linear order of $G_{i+1}$ with respect to $f$ up to $r$.

\item Otherwise,  $r+1\leq q<2r$  (in which case $f(x)=x+2+\log_2\bigl(\frac{q-1}{q-x}\big)$).

If $x<q-z$, we have
\[|\WReach_x[G_{i+1},\pi_{i+1},v^s_z]|\leq f(x-z)+z\leq f(x).\]
Otherwise, we have
$z\ge q-x$ (hence $q-x+z\ge 2(q-x)$), and thus
\begin{align*}
 \qquad\quad\ \mathrlap{|\WReach_x[G_{i+1},\pi_{i+1},v^s_z]|}\phantom{|\WReach_x[G_{i+1},}&\phantom{\pi_{i+1},v^s_z]|}\leq
f(x-z)+z+1\\
&=x-z+2+\log_2(q-1)-\log_2(q-x+z)+z+1\\
&\le x+2+\log_2(q-1)-\log_2(2(q-x))+1\\
&=x+2+\log_2(q-1)-\log_2(q-x)\\
&=f(x)
\end{align*}
Hence, $\pi_{i+1}$ is a good linear order of $G_{i+1}$ with respect to $f$ up to $r$.
\end{itemize}
\end{proof}




We derive bounds for the weak coloring numbers for graphs of high girth in classes with sub-exponential expansion.

\ThmWcol*
\begin{proof}
This is a direct consequence of 
\Cref{th:pd-subexponential,th:wocl-pd}.  
\end{proof}

In particular, \Cref{th:wcol-subexponential} gives the following bounds for the two extreme cases of $q=r+1$ and $q=2r-1$:
\begin{align*}
    \wcol_r(G)\leq\begin{cases}
        r+2+\lfloor
        \log_2 r\rfloor&\text{if }
        \girth(G)\ge g(2r+2),\\
    r+3&\text{if }\girth(G)\ge g(4r-2).
    \end{cases}
\end{align*}


Recall that even for the class of planar graphs $\mathscr{C}$, 
the  lower and upper bounds on $\max_{G\in\mathscr{C}} wcol_r(G)$ are $\Omega(r^2\log r)$ \cite{JM2021} and $O(r^3)$ \cite{VOQRS2017}, respectively.
\Cref{th:wcol-subexponential} indicates that 
for any 
 class $\mathscr{C}$ with sub-exponential expansion, the weak $r$-coloring number of large girth 
graphs in $\mathscr{C}$ is  close to $r+2$, which is the best possible upper bound on $\wcol_r(G)$.



















