\section{Proof of Lemma~\ref{lem:borel}}

\begin{proof}
Let $X_n=M(n)/n$, $Y_n=\E[M(n)]/n$, and $L=\sup_n\E[M(n)]/n$. Let $\varepsilon>0$ be a constant. From Equation~\eqref{eq3}, we have that 
\[
	\Pr\left(|X_n-Y_n|\ge \varepsilon/2\right) ~\le~ 2\, r^n, ~\text{where}~ r=\exp\left(-\frac{\varepsilon^2}{40}\right)<1.
\]
From Lemma~\ref{lemma:limit_exists}, we have for $n\ge n_0$, where $n_0\in\mathbb{N}$ is a constant, that 
\[
	\Pr\left(|Y_n-L|<\varepsilon/2\right) ~=~ 1.
\]
For $n\ge n_0$, we obtain that
\begin{align*}
	\Pr(|X_n-L|\le\varepsilon) 
		& ~\ge~ \Pr(|X_n-Y_n|+|Y_n-L|\le\varepsilon) \\
		& ~\ge~ \Pr\left(|X_n-Y_n|<\varepsilon/2,|Y_n-L|<\varepsilon/2 \right) \\
		& ~=~ \Pr\left(|X_n-Y_n|<\varepsilon/2 \right) \\
		& ~\ge~ 1 - 2\, r^n.
\end{align*}
Hence,
\begin{align*}
	\sum_{n=1}^{\infty}\Pr(|X_n-L|>\varepsilon)
	& ~<~ (n_0-1) + \sum_{n=n_0}^{\infty}\Pr(|X_n-L|>\varepsilon) \\
	& ~\le~ (n_0-1) + \sum_{n=n_0}^{\infty} 2\, r^n \\
	& ~=~ (n_0-1)+\frac{2\,r^{n_0}}{1 - r} \\
	& ~<~ \infty.
\end{align*}
The lemma thus follows.
\end{proof}

