    \begin{algorithmic}[1]
        \State $\mathit{est}_i \gets \mathit{init}$;~$r_i \gets 0$;
        \While{true}
              \State $r_i \gets r_i+1$; ~ $\operatorname{BV\_broadcast}$(\textsc{est},$r_i$,$\mathit{est}_i$);
              \State \textbf{wait until} ($\mathit{bin\_values}_i[r_i] \neq \emptyset $);
              \State $\operatorname{broadcast}$(\textsc{aux},$r_i$,$w$), where $w \in \mathit{bin\_values}_i[r_i]$;
              \State \textbf{wait until} ($\exists$ a set of $(n-t)$ (\textsc{aux},$r_i$,$x$) messages from distinct processes such that $\mathit{values}_i \subseteq \mathit{bin\_values}_i[r_i] $, where $\mathit{values}_i$ is the set of values in the messages);
              \State $s \gets \operatorname{random}()$; \quad \% common coin \%
              \If{ ($\mathit{values}_i=\{v\}$) \quad \% i.e., $|\mathit{values}_i|=1$ \% \\ \qquad }{
                    $\mathit{est}_i \gets v$; 
                    \If{ $v=s$ }{ $\operatorname{decide}$($v$) if not yet done;} \EndIf
              }\Else{ $\mathit{est}_i \gets s$; }
              \EndIf
        \EndWhile

    \end{algorithmic}
