\subsection{More Details of Training}
\label{sec:appendix 1.1}
\textbf{Data Construction.} The corpus for data construction is sourced from Wikipedia. We provide a detailed data construction pipeline and prompts.
\begin{algorithm}
\caption{Data Construction Algorithm}
\begin{algorithmic}[1]
    \STATE \textbf{Input:} Entire multi-theme set documents, D, Strong LLM, M(GPT-4o)
    \STATE \textbf{Source Data Acquisition:} Cluster similar documents, $ D_{\text{theme},i} \in D $ and single document $ D'\in D $
    \STATE \textbf{Generate query:} Q under query tasks $QT_{\text{filtering}}$, $QT_{\text{combination}}$, $QT_{\text{rag-reasoning}}$ according to documents $D$:
    \FOR{$QT'$ in ($QT_{\text{filter}}$, $QT_{\text{combination}}$, $QT_{\text{rag-reasoning}}$)}
        \STATE $Q_1$ = $M(QT'(D'))$
        \STATE $Q_2$ = $M(QT'(D_{\text{theme},i}))$)
    \ENDFOR
    \STATE \textbf{Generate thought\&answer} and golden document(s) $\tilde{D}$ under Thought\&Answer Tasks $T_{\text{filtering}}$, $T_{\text{combination}}$, $T_{\text{rag-reasoning}}$
    \FOR{$T'$ in $T_{\text{filtering}}$, $T_{\text{combination}}$, $T_{\text{rag-reasoning}}$}
        \STATE $Thought_1,Answer_1,\tilde{D}_1$ = $M(T'(Q_1,D'))$
        \STATE $Thought_2,Answer_2,\tilde{D}_2$ = $M(T'$($Q_2, D_{\text{theme},i}))$
    \ENDFOR
    \STATE \textbf{Validation}: Revise answer and classify task  $A',Task$ = $M_A(Q,\tilde{D},Thouht)$  and then do validation.
    \STATE \textbf{Add Noisy Documents:} $\bar{D}_i \notin \tilde{D}\in  D_{\text{theme},i}$, forms all training documents $  D_{final} = \{\bar{D}, \tilde{D}\}  $, and randomly shuffle $D_{final}$ 20\% of the Doc samples.
    \RETURN $Q, D_{final}, Thought, Answer$ when $A' == Answer$ and $Task$ matches
\end{algorithmic}
\end{algorithm}

\noindent\textbf{Training Settings.} The training dataset, consisting of approximately 120K samples, was constructed according to the pipeline. The training process was conducted using eight NVIDIA A100 GPUs. All models were trained with a learning rate of 3e-5, a batch size of 4, a warmup ratio of 0.5\%, and linear weight decay. The training duration was approximately 32 hours for Llama3-8B and around 28 hours for Llama2-7B. The maximum token length was set to 4096 for all models. We provide a specific example of the training data in Figure \ref{fig:train_data}.
