\title{A Dense Neighborhood Lemma: Applications of Partial Concept Classes to Domination and Chromatic Number}

\author[1]{Romain Bourneuf}
\affil[1]{Univ. Bordeaux, CNRS, Bordeaux INP, LaBRI, UMR 5800, F-33400 Talence, France.}
