\begin{definition}
A time series $P:[1, n]\rightarrow \mathbb{R}$ is \emph{$\delta$-monotone increasing (resp. decreasing)} if it holds that $P(s)\leq P(s')+\delta$ (resp. $P(s)\geq P(s')-\delta$)  for all $s<s'\in [1, n]$.
\end{definition}
\begin{definition}[extended $\delta$-signature]
    Let $P=\langle P(1), \dotso, P(n)\rangle$ be a time series and $\delta\geq 0$.
    Then, an \emph{extended $\delta$-signature} $P'=\langle P(i_1), \dotso, P(i_t)\rangle$ with $1=i_1\leq i_2<\ldots<i_{t-1}\leq i_t=n$ of $P$ is a time series with the following properties:
    \begin{enumerate}[(a)]
        \item \emph{(non-degenerate)} For $k=2, \dotso, t-1$, it holds that $P(i_k)\notin \overline{P(i_{k-1}) P(i_{k+1})}$.
        \item \emph{($2\delta$-monotone)} For $k=1, \dotso, t-1$, $P[i_k, i_{k+1}]$ is $2\delta$-monotone increasing or decreasing.
        \item \emph{(minimum edge length)} If $t>4$, then for $k=2, \dotso, t-2$,  $|P(i_k)-P(i_{k+1})|>2\delta$.
        \item \emph{(range)} 
        \begin{itemize}
            \item For $k=2, \dotso, t-2$, it holds that $\im(P[i_{k}, i_{k+1}])= \overline{ P(i_{k}) P(i_{k+1})}$, and
            \item %if $P(i_2)$ is a local minimum (resp. maximum), then 
            $\im(P[1, i_2])\subset [P(i_2), P(i_2)+2\delta]$ or $\im(P[1, i_2])\subset [P(i_2)-2\delta, P(i_2)]$, and 
            \item %if $P(i_{t-1})$ is a local minimum (resp. maximum), then 
            $\im(P[i_{t-1}, n])\subset [P(i_{t-1}),$ $ P(i_{t-1})+2\delta]$ or $\im(P[i_{t-1}, n])\subset [P(i_{t-1})-2\delta, P(i_{t-1})]$.
        \end{itemize}

        % For $k=2, \dotso, t-2$, it holds that 
        % $\im(P[i_{k}, i_{k+1}])= \overline{ P(i_{k}) P(i_{k+1})}$ and $\im(P[1, i_2])\subset [P(i_2), P(i_2)+2\delta]$ (resp. $\im(P[1, i_2])\subset [P(i_2)-2\delta, P(i_2)]$) 
        % if $P(i_2)$ is a local minimum (resp. local maximum)

        % and $\im(P[i_{t-1}, n])\subset [P(i_{t-1}), P(i_{t-1})+2\delta]$ (resp. $\im(P[i_{t-1}, n])\subset [P(i_{t-1})-2\delta, P(i_{t-1})]$) if $P(i_{t-1})$ is a local minimum (resp. local maximum).
    \end{enumerate}
    The vertices of $P'$ are called \emph{$\delta$-signature vertices} of $P$.
\end{definition}



Driemel, Krivo\v{s}ija and Sohler~\cite{DBLP:conf/soda/DriemelKS16} showed that there always exists a $\delta$-signature and 
%, that it is unique under general position assumptions and 
that it can be computed in $\mathcal{O}(n)$ time\footnote{They proved this statement for $\delta$-signatures, but it can easily be shown for extended $\delta$-signatures as~well.}.  
Bringmann, Driemel, Nusser and Psarros~\cite{DBLP:conf/soda/BringmannDNP22} defined $\delta$-visiting orders and Blank and Driemel~\cite{BD24} used this concept to define coupled $\delta$-visiting orders (see \Cref{fig:coupled_visiting_order}), which can be used to decide whether the \F between two time series is at most $\delta$. %\Cref{fig:coupled_visiting_order} visualizes a 

\begin{definition}[coupled $\delta$-visiting order]\label{def:coupledVisitingOrder}
    Consider two time series $P=\langle P(1), \dotso, P(n)\rangle$ and $Q=\langle Q(1), \dotso, Q(m)\rangle$. 
    Then, a $\delta$-visiting order of $Q$ on $P$ for the $\delta$-signature vertices $Q(j_1), \dotso, Q(j_{s_Q})$ is a sequence of indices $x_1\leq\cdots\leq x_{s_Q}$ such that $|P(x_k)-Q(j_k)|\leq \delta$ for all $k$.  We similarly define a $\delta$-visiting order $y_1\leq\cdots\leq y_{s_P}$ of $P$ on $Q$ for the $\delta$-signature vertices $P(i_1), \dotso, P(i_{s_P})$ of $P$.
    These two $\delta$-visiting orders are said to be crossing-free if there exists no $k, l$ such that $i_k< x_l$ and $j_l<y_k$, or $x_k< i_l$ and $y_l<j_k$. In this case, the ordered sequence containing all tuples $(x_k, j_k)$ and $(i_l, y_l)$, where $k=1, \dotso, s_Q$ and $l=1, \dotso, s_P$, is called \emph{coupled $\delta$-visiting order}.
\end{definition}

