\end{figure}

\begin{restatable}[Lemma 9 of~\cite{BD24}]{lemma}{keylemma}\label{l:key_lemma}
%\begin{lemma}[Blank and Driemel~\cite{BD24}] \label{l:key_lemma}
    Let $P$, $Q$ be two time series and $\langle P(i_1), \dots, P(i_{s_P})\rangle$ and $\langle Q(j_1), \dots, Q(j_{s_Q})\rangle$ their $\delta$-signatures. Then, $d_F(P, Q)\leq \delta$ if and only if there exist a coupled $\delta$-visiting order $((v_1, w_1), (v_2, w_2), \dotso, (v_t, w_t))$ of $P$ and $Q$ such that 
    \begin{enumerate}[(i)]
        \item if $v_2=i_2$ (resp. $w_2=j_2$), % is a $\delta$-signature vertex, 
        then $\exists w^*\in[w_2, \min\{w_2+1, j_2\}]$ (resp. $v^*\in[v_2, \min\{v_2+1, i_2\}]$) such that $d_F(P[1, v_2], Q[1, w^*])\leq \delta$ (resp. $d_F(P[1, v^*], Q[1, w_2])\leq \delta$), and
        \item if $v_{t-1}=i_{s_P-1}$ (resp. $w_{t-1}=j_{s_Q-1}$)%is a $\delta$-signature vertex
        , then $\exists w^{**}\in[\max\{j_{s_Q-1}, w_{t-1}-1\}, w_{t-1}]$ (resp. $v^{**}\in[\max\{i_{s_P-1}, v_{t-1}-1\}, v_{t-1}]$) such that $d_F(P[v_{t-1}, v_t], Q[w^{**}, w_t])\leq \delta$ (resp. $d_F(P[v^{**}, v_t], Q[w_{t-1}, w_{t}])\leq \delta$).
    \end{enumerate}
    %and values ${a_p\in[v_2, v_2+1]}$, ${a_q\in[w_2, w_2+1]}$, $b_p\in [v_{t-1}-1, v_{t-1}]$, and $b_q\in[w_{t-1}-1, w_{t-1}]$ such that ${d_F(P[1, a_p], Q[1, a_q])\leq \delta}$ and $d_F(P[b_p, n], Q[b_q, m])\leq \delta$. 
%\end{lemma}
\end{restatable}

 \begin{proof}
    There is a small difference to the cited lemma. Consider the case that $v_2=i_2$. The case that $w_2=j_2$ is symmetric as well as for the second last tuple.
    The statement in this lemma requires that
    \begin{compactenum}
        \item[(1)] $Q(w_2)$ is a vertex and $\exists\ w^*\in[w_2, \min\{w_2+1, j_2\}]$ such that $d_F(P[1, v_2], Q[1, w^*])\leq \delta$.
    \end{compactenum}
    The requirement in the cited lemma is that
    \begin{compactenum}
        \item[(2)] $d_F(P[1, v_2], Q[1, w_2])\leq \delta$ and $Q(w_2)$ does not need to be a vertex of $Q$.
    \end{compactenum}
    %Namely, there it is required that $d_F(P[1, v_2], Q[1, w_2])\leq \delta$. However, if $v_2=i_2$, then $w_2$ does not need to be an index; similarly if $w_2=j_2$, then $v_2$ does not need to be an index. We only consider the case that $v_2=i_2$, as the other case follows symmetrically. We show that this is equivalent to requiring that $w_2$ is an index and there exists an $w^*\in[w_2, w_2+1]$ with $d_F(P[1, i_2], Q[1, w^*])\leq \delta$. 
    We show that requiring $(1)$ or $(2)$ is equivalent. Let $w_2$ and $w^*$ be as in $(1)$. Then $w^*$ satisfies the condition of $(1)$. Now, let $w_2$ be as in $(2)$. Since $Q[1, j_2]$ is contained in some $\delta$-ball and $w_2\leq j_2$, it holds that $|P(i_2)-Q(\lfloor w_2\rfloor)|\leq \delta$ or $|P(i_2)-Q(\lceil w_2\rceil)|\leq \delta$. In the first case, $w_2=\lfloor w_2\rfloor$ and $w^*=w_2$ satisfy the conditions in $(1)$. In the second case, it holds that $\im(Q[w_2,\lceil w_2\rceil])\subset B(P(i_2), \delta)$. Hence, $w_2=\lceil w_2\rceil$ and $w^*=w_2$ satisfy the conditions in $(1)$.% In both cases, it holds that there exists a $w^*\in[w_2, w_2+1]$ such that $d_F(P[1, i_2], Q[1, w^*])\leq \delta$. Hence, the two statements are equivalent.
\end{proof}


\subsection{Grid Reachability}
\begin{definition}[Offline Dynamic Grid Reachability]
Let $G$ be the directed $n\times n$-grid graph in which every node is either activated or deactivated. We are given updates $u_1,\ldots,u_U$, which are of the form \enquote{activate node $(i,j)$} or \enquote{deactivate node $(i,j)$} in an offline manner. The task of \emph{offline dynamic grid reachibility} is to compute for all $1\leq\ell\leq U$ if $(n,n)$ can be reached by $(1,1)$ after updates $u_1,\ldots,u_{\ell}$ are performed.
\end{definition}
Our main results depend on the following theorem.
\begin{theorem}[Theorem 3.1 of \cite{DBLP:journals/talg/BringmannKN21}] \label{thm:offline_dyn_grid_reachability}
Offline Dynamic Grid Reachability can be solved in time $\Oh(n^2 + U n^{2/3} \log^2 n)$.
\end{theorem}

\section{The Static Algorithm}
First, we discuss how the \emph{modified free-space matrix} can be used to decide whether the \F between two time series is at most a given threshold $\delta$. \Cref{l:key_lemma} implies that, except for the beginning and the end, it is enough to look at pairs $(P(i), Q(j))$ of vertices, where one of the two vertices is a $\delta$-signature vertex.

\begin{definition}[prefix and suffix]
    Let $P$ be a time series of complexity $n$ and let $P(i_2)$ denote the second $\delta$-signature vertex of~$P$, and $P(i_{s_P-1})$ denote the penultimate $\delta$-signature vertex of~$P$. Then $P[1,i_2]$ is the prefix $\pre{P}$ and $P[i_{s_P-1},n]$ in reverse order defines the suffix $\suf{P}$ of $P$. That is, the time series $P[i_{s_P-1},n]$ is $\widehat{\suf{P}}$, where $\widehat{P}$ denotes the time series defined by the vertices of $P$ in reverse order.
%    Let $P$ be a time series of complexity $n$ and let $P(i_2)$ denote the second $\delta$-signature vertex of~$P$, and $P(i_{s_P-1})$ denote the penultimate $\delta$-signature vertex of~$P$. Then $P[1,i_2]$ is the prefix $\pre{P}$ of $P$ and the time series defined by the vertices of $P[i_{s_P-1},n]$ in reversed order is the suffix $\suf{P}$ of $P$.
\end{definition}


Observe that by the definition of the $\delta$-signature vertices the time series $\pre{P}$ and $\suf{P}$ are each contained in some ball of radius $\delta$.


\begin{definition}[minimal matcher]
    Let $P$ and $Q$ be two time series of complexity $n$ and $m$ respectively. The \emph{\ePQ{P}{Q}} is the smallest $w\in[m]$ such that
    \begin{compactenum}
        \item $|P(n)-Q(w)|\leq\delta$, and
        \item there is a $w^*\in[w,\min(w+1,m)]$ such that $\mathrm{d}_F(P,Q[1,w^*])\leq\delta$. 
    \end{compactenum}
    If no such value exists, we set it to $\infty$.
\end{definition}
\begin{figure}
    \centering
    \includegraphics{Figures/w_pre.pdf}
    \caption{Minimal $\pre{P}$-matcher on $\pre{Q}$, $\wpre$, and \ePQ{\suf{P}}{\suf{Q}}, $\wsuf$.}
    \label{fig:w_pre}
\end{figure}

We denote by $\wpre$ the \ePQ{\pre{P}}{\pre{Q}} and by $\vpre$ the \ePQ{\pre{Q}}{\pre{P}}. For the suffix, we denote by $\wsuf$ the index of the vertex in $Q$ corresponding to the \ePQ{\suf{P}}{\suf{Q}} (and similarly $\vsuf$ when the roles of $P$ and $Q$ are swapped). See \Cref{fig:w_pre} for an example.

Due to the next observation, we will only discuss how to process the prefix in \Cref{sec:prefSuff}, \Cref{sec:PrefTranslation} and \Cref{sec:PrefScaling}. 
\begin{observation}\label{obs:ConnectionSufPre}
    Let %$\wsuf$ be the \ePQ{\suf{P}}{\suf{Q}} and 
    $\widehat{\wpre}$ be the \ePQ{\pre{\widehat{P}}}{\pre{\widehat{Q}}}. If $m$ is the complexity of $Q$, then $\wsuf=m-(\widehat{\wpre}-1)$.
\end{observation}

With these notions, we define the modified free-space matrix. See \Cref{fig:modified_free_space_matrix} for an example. 

\begin{definition}[Modified Free-Space Matrix]\label{def:mod_free_space_matrix} Let $P$ and $Q$ be two time series of complexity $n$ and $m$. Further, let $\langle P(i_1), \dotso, P(i_{s_P})\rangle$ and $\langle Q(j_1), \dotso, Q(j_{s_Q})\rangle$ be their $\delta$-signatures. 
We construct a matrix $M_{\delta}\in \{0, 1\}^{n\times m}$, where the entry $M_{\delta}(i,j)=1$ if
\begin{enumerate}[a)]
    \item  $P(i)$ and $Q(j)$ are both not $\delta$-signature vertices, or
    \item $|P(i)-Q(j)|\leq \delta$ and $(i, j)\notin [1, i_2]\times [1, j_2]\cup [i_{s_P-1}, n]\times [j_{s_Q-1}, m]$, or
    \item $|P(i)-Q(j)|\leq \delta$ and $(i, j)\in \{(1, 1), (n,m)\}$, or
    \item $|P(i)-Q(j)|\leq \delta$ and $(i, j)=(i_2, j_2)$ and $d_F(\pre{P}, \pre{Q})\leq \delta$, or
    \item $|P(i)-Q(j)|\leq \delta$ and $(i, j)=(i_{s_P-1}, j_{s_Q-1})$ and $d_F(\suf{P}, \suf{Q})\leq \delta$, or
    \item $(i, j)\in \{(i_2, \wpre), (\vpre, j_2), (i_{s_P-1}, \wsuf), (\vsuf, j_{s_Q-1})\}$. 
\end{enumerate}
Otherwise, the entry $M_{\delta}(i, j)=0$.
Further, we say that an entry $M_{\delta}(i, j)$ is reachable if there exists a traversal $(1, 1)=(a_1, b_1), (a_2, b_2), \dotso, (a_k, b_k)=(i, j)$ such that $M_{\delta}(a_l, b_l)=1$ and $(a_l, b_l)\in\{(a_{l-1}+1, b_{l-1}),(a_{l-1}, b_{l-1}+1),(a_{l-1}+1, b_{l-1}+1)\}$ for all $l=2, \dotso, k$.
\end{definition}

\begin{figure}
    \centering
    \includegraphics[page=1]{Figures/Modified_Free_Space_Matrix.pdf}
    \caption{Example of a Modified Free-Space Matrix $M_{\delta}$. 
    The colored columns (resp. rows) correspond to the $\delta$-signature vertices of $P$ (resp. $Q$). The white entries are all $1$ by \Cref{def:mod_free_space_matrix}~a), the red entries are defined by~b), the purple entries by~c) and~d) and~e), and the yellow entries by~f). 
    The traversal drawn in blue uses only 1-entries of $M_\delta$. Hence, $M_\delta(n, m)$ is reachable.}
    \label{fig:modified_free_space_matrix}
\end{figure}
The importance of the modified free-space matrix is that it can be used to answer the decision problem of whether or not $d_F(P, Q)\leq \delta$ essentially in the same way as it is done for the discrete Fréchet distance using the free-space matrix. 
The next lemma follows mainly from a result of~\cite{BD24}. %For completeness, a proof is contained in~\Cref{app:static}.

\begin{restatable}{lemma}{dfModMatEquiv}\label{lem:dfModMatEquiv}
    It holds that $d_F(P, Q)\leq \delta$ if and only if $M_{\delta}(n, m)$ is reachable. This can be checked in $\mathcal{O}(nm)$ time. 
\end{restatable}
\begin{proof}
    We use \Cref{l:key_lemma} to prove correctness. If $d_F(P, Q)\leq \delta$, then there exists a coupled $\delta$-visiting order $V=((v_1, w_1), \dots, (v_t, w_t))$ such that the requirements of \Cref{l:key_lemma} are fulfilled. If $Q(w_2)$ (resp. $P(v_2)$) is not the second $\delta$-signature vertex of $Q$ (resp. $P$), then $V$ is still a coupled $\delta$-visiting order with the properties of \Cref{l:key_lemma} after setting $w_2$ to $\wpre$ (resp. $v_2$ to $\vpre$). 
    Similarly, we redefine $w_{t-1}$ or $v_{t-1}$ depending on whether $P(w_{t-1})$ or $Q(v_{t-1})$ is not the second last $\delta$-signature vertex, maintaining a coupled $\delta$-visiting order with the properties of \Cref{l:key_lemma}. The resulting sequence defines a traversal from $M_{\delta}(1, 1)$ to $M_{\delta}(n,m)$ in the modified free-space matrix in the following way. For two consecutive tuples $(v_k, w_k)$, $(v_{k+1}, w_{k+1})$, we add \[ (v_k+1, w_k), (v_k+2, w_k), \dots, (v_{k+1}, w_k), (v_{k+1}, w_k+1), (v_{k+1}, w_k+2), \dots, (v_{k+1}, w_{k+1})\] in between them to the traversal. For all those new added tuples, it holds that their corresponding entry in the modified free-space matrix is $1$, because none of them corresponds to a $\delta$-signature vertex, by  definition of a coupled $\delta$-visiting order. In this way, we constructed a traversal from $M_{\delta}(1, 1)$ to $M_{\delta}(n, m)$.
    Hence, $M_{\delta}(n, m)$ is reachable. 

    Now, let $M_{\delta}(n, m)$ be reachable. Then, there exists a traversal $(1, 1)=(a_1, b_1), \dotso, $ $(a_t, b_t)=(n, m)$ such that $M_{\delta}(a_l, b_l)=1$ and $(a_l, b_l)\in\{{(a_{l-1}+1}, b_{l-1}), (a_{l-1}, {b_{l-1}+1}),$ $ ({a_{l-1}+1}, b_{l-1}+1)\}$ for all $l=2, \dotso, t$. Deleting all the tuples $(a_k, b_k)$ from this sequence, where neither $P(a_k)$ nor $Q(b_k)$ is a $\delta$-signature vertex, leads to a coupled $\delta$-visiting order, by definition. Further, it satisfies the properties of \Cref{l:key_lemma} by the definition of the modified free-space matrix.
    Therefore, by \Cref{l:key_lemma} it holds that $d_F(P, Q)\leq \delta$, which concludes the proof of correctness. 
    The running time follows by using dynamic programming and \Cref{lem:searchprefixend} and \Cref{lem:(i_2j_2)}.
\end{proof}



\subsection{Prefix and Suffix}\label{sec:prefSuff}
This section is dedicated to identifying the \ePQ{\pre{P}}{\pre{Q}}. We often use the fact that \pre{P} and $\pre{Q}$ are each contained in some $\delta$-ball. %We start by finding, for two time series $P$ and $Q$, each contained in some $\delta$-ball and ending at a global extremum, the first index $w^*$ of a point on~$Q$ such that $d_F(P, Q[1, w^*])\leq \delta$. 
We will show that the vital behavior of such constricted time series can be captured by their extreme points.
\begin{definition}[extreme point sequence]
Let $P$ be a time series of complexity $n$, such that $P(n)$ is a global extremum of $P$ and $P$ is contained in some $\delta$-ball. We define the extreme point sequence $1=a_1< a_2 < \cdots< a_{\cpP}=n$ to be a 
%the unique 
sequence of indices, such that 
    \begin{itemize}
        \item (range-preserving) $\im(P[1, a_{k+1}])= \overline{P(a_k) P(a_{k+1})}$ for all $k$, and
        \item (extreme point) $P(a_k)=\min(P[1, a_k])$ or $P(a_k)=\max(P[1, a_k])$.
    \end{itemize}
\end{definition}

See \Cref{fig:extreme_point_sequence} and~\ref{fig:Prefix_Example} for an example of both an extreme point sequence and their associated preliminary assignments, defined next. 
\begin{figure}
    \centering
    \includegraphics[page=3]{Figures/Prefix_Example.pdf}
    \caption{An extreme point sequence of the depicted time series $P$ is $1=a_1<a_2<\dots<a_{\cpP}$ and the preliminary assignment $\Y(7)$ of $Q$ on $P$ is $7$, since $Q(a_7)$ is the first vertex on $P$ in $B(Q(b_7), \delta)$.}
    \label{fig:extreme_point_sequence}
\end{figure}

\begin{definition}[preliminary assignment]
    Let $P$ and $Q$ be two time series such that the image of each time series is contained in some ball of radius $\delta$. Let $a_1<\ldots<a_{\cpP}$ and $b_1<\ldots<b_{\cpQ}$ be extreme point sequences of time series $P$ and $Q$ respectively. Define the \emph{preliminary assignment}  $\X(k)$ of $P$ on $Q$ for every $k\leq \cpP$ to be the smallest index such that $|P(a_k)-Q(b_{\X(k)})|\leq \delta$. If no such index exists, we set $\X(k)=\infty$. Let similarly $\Y(l)$ be the preliminary assignment of $Q$ on $P$. We say that $\X(k)$ and $\Y(l)$ form a \emph{deadlock}, if $l<{\X(k)}$ and $k<{\Y(l)}$. 
\end{definition}

Before we show how the preliminary assignment can be used to find the \ePQ{\pre{P}}{\pre{Q}}, we state some of its structural properties.

\begin{restatable}{lemma}{preliminaryAssignmentStructure}\label{lem:preliminaryAssignmentStructure}
%\begin{lemma}\label{lem:preliminaryAssignmentStructure}
    Let $P$ and $Q$ be two time series such that the image of each time series is contained in some ball of radius $\delta$.
    Let $a_1<\ldots<a_{\cpP}$ and $b_1<\ldots<b_{\cpQ}$ be extreme point sequences of time series $P$ and $Q$.  
    If $\X(1)=1$, then the following holds.
    \begin{enumerate}[i)]
        \item For any $3\leq k\leq p$ it holds that $\X(k)\geq \X(k-2)$.
        \item It holds that $\X(2k)=1$ for all $k$ or $\X(2k-1)=1$ for all $k$.
        \item If $k<p$ and $\X(k)\neq 1$, then for any index $l\geq \X(k)$ there is a $t\in [b_{l-1},b_l]$ such that $\im(P[1,a_{k+1}])\subset B(Q(t),\delta)$. 
        \item If $X(k)>1$ and $Y(l)$ form a deadlock, then $X(k)$ and $Y(X(k)-1)$ form a deadlock.
    \end{enumerate}
%\end{lemma}
\end{restatable}
\begin{proof}
    Let $\X(k-2)>1$, since otherwise $i)$ trivially holds. This implies that $a_{k-2}\not\in B(b_1,\delta)$, which in turn implies the same for $a_k$, since $|a_k-b_1|\geq |a_{k-2}-b_1|$, by definition of the extreme point sequence and $a_1\in B(b_1,\delta)$. As $Q$ is range-preserving, $\X(k)\geq \X(k-2)$, which implies $i)$.

   For $ii)$, it suffices to note that $P[1, a_p]$ is contained in a ball of radius $\delta$ and $X(1)=1$.
    To prove $iii)$, let $k$ be the first index such that $\X(k)\neq 1$, that is, $a_k$ lies outside $B_\delta(b_1)$. Then $a_{k+1}$ must lie on the other side of $a_1$ than $a_k$, but at most a distance $2\delta$ away from $a_k$. As $\X(1)=1$, i.e., $a_1\in B(b_1,\delta)$, it holds that $a_{k+1}$ also lies inside $B_\delta(b_1)$, implying $\X(k+1)=1$. Now, $a_{k+2}$ must lie at least as far from $a_1$ as from $a_k$ and thus again lies outside $B_\delta(b_1)$, and so on for higher values of $k$.

    We thus have that $\max\{\X(k),\X(k+1)\}=\X(k)\leq l$. This in turn implies that \[\im(P[1,a_{k+1}])\subset \overline{P(a_k)\,P(a_{k+1})}\subset B(\overline{Q(b_{\X(k)})\,Q(b_{\X(k+1)})}, \delta)\subset B(\overline{Q(b_{l-1})\,Q(b_l)}, \delta).\]
    By definition, $P[1,a_{k+1}]$ is contained in a $2\delta$-range. Hence, there exists a value $t\in[b_{l-1},b_l]$ such that $\im(P[1,a_{k+1}])\subset B(Q(t), \delta)$, proving the claim.

    To prove $iv)$, let $\X(k)$ and $\Y(l)$ form a deadlock. Then, $l<\X(k)$ and $k<\Y(l)$. 
    By the symmetric argument of $i)$ for $\Y$, it holds that $k<\Y(l)\leq \Y(l+2)\leq \Y(l+4)\leq \cdots \Y(l')$ for $l'=\X(k)-1$ or $ l'= \X(k)$. By the definition of $X$ and $Y$, it holds that $Y(X(k))\leq k$. Hence, $k<\Y(\X(k)-1)$. As $\X(k)-1<\X(k)$, it holds that $X(k)$ and $Y(X(k)-1)$ form a deadlock.
\end{proof}



The importance of deadlocks is summarized in the following pivotal lemma.


\begin{restatable}{lemma}{startAndEnd}\label{l:startAndEnd}
%\begin{lemma}\label{l:startAndEnd}
    Let $P$ and $Q$ be time series such that the image of each time series is contained in some ball of radius $\delta$.
    Let $a_1<\ldots<a_{\cpP}$ and $b_1<\ldots<b_{\cpQ}$ be extreme point sequences of $P$ and $Q$. %, respectively.
    For any $w^*\leq b_{\cpQ}$, it holds that ${d_F(P[1, a_{\cpP}], Q[1, w^*])\leq \delta}$ if and only if
    \begin{enumerate} [(i)]
        \item $|P(1)-Q(1)|\leq \delta$ and $|P(a_{\cpP})-Q(w^*)|\leq \delta$, 
        \item $\im(P[1, a_{\cpP}])\subset B(Q[1, w^*], \delta)$, 
        \item $\im(Q[1, w^*])\subset B(P[1, a_{\cpP}], \delta)$, and
        \item $\X(k)$ and $\Y(l)$ do not form a deadlock for all $k=1, \dotso, \cpP$ and $l=1, \dotso, \cpQ$. 
    \end{enumerate}   
%\end{lemma}
\end{restatable}

Observe that if $\X(1)$ and $\Y(1)$ do not form a deadlock then already $|P(1)-Q(1)|\leq \delta$.

\begin{proof}
    We begin by showing that $d_F(P[1, a_{\cpP}], Q[1, w^*])\leq\delta$ implies Condition (i)-(iv). Conditions (i)-(iii) hold by definition.
    Next, observe that if $\X(k)$ and $\Y(l)$ form a deadlock, then $|P(a_k)-Q(t)|>\delta$ for all $t\leq b_l$. However, in this case any traversal of $P$ and $Q$ would have to match $Q(b_l)$ with some $P(s)$ with $s<a_k$, since the part of $Q$ before $Q(b_l)$ has to be traversed before reaching $P(a_k)$ as $d_F(P[1, a_{\cpP}], Q[1, w^*])\leq\delta$. As $\X(k)$ and $\Y(l)$ form a deadlock, also $|Q(b_l)-P(s)|>\delta$ for all $s\leq a_k$. Therefore, any traversal induces a cost greater than $\delta$. Thus $\X(k)$ and $\Y(l)$ cannot form a deadlock, implying Condition (iv).

    We now turn to proving that Conditions (i)-(iv) imply that $d_F(P[1, a_\cpP], Q[1, w^*])\leq\delta$. 
    The remainder of this proof consists of identifying points, via the preliminary assignments of $P$ and $Q$, that induce a traversal of $P$ and $Q$ with cost $\leq\delta$. 

    Observe that Conditions~(ii) and~(iii) imply that $\X(k)<\infty$ for all $k\leq t$ and $\Y(l)<\infty$ for all $b_l\leq w^*$.
    For now, we assume $\X\not\equiv 1$. Let $\mathcal{K}=\{1\leq k\leq \cpP-2\mid \X(k)\neq \X(k+2)\}\cup \{\cpP-1\leq k \leq \cpP \mid \X(k)\neq 1\}$ be the set of \textit{transition indices}, at which $\X(k)$ is about to change when ignoring all 1-entries. To construct a matching between $P[1, a_p]$ and $Q[1, w^*]$, we define values $t_k$ and $s_k$ for all transition indices $k\in \mathcal{K}$ with the following properties. See \Cref{fig:Prefix_Example} and \Cref{fig:beginning}.
    \begin{claim}\label{c:def_sk_and_tk}
    There exist values $\{s_k\}_{k\in\mathcal{K}}\in[1, a_\cpP]$ and $\{t_k\}_{k\in\mathcal{K}}\in[1, w^*]$ such that
        \begin{enumerate}[a)]
        \item If $k<\cpP-1$, then there is a $t_k\in[b_{\X(k)-1},b_{\X(k)}]$ such that $\im(P[1,a_{k+1}])\subset B(Q(t_k), \delta)$ and $t_k$ is minimal in the sense that $\im(Q[b_{\X(k)-1},t_k])\subset\overline{Q(b_{\X(k)-1})\,Q(t_k)}$.
        \item If $k\geq \cpP-1$, then there is a $t_k\in[b_{\X(k)-1},\min\{w^*, b_{\X(k)}\}]$ such that $\im(P[1,a_\cpP])\subset B(Q(t_k), \delta)$.
        \item If $k<\cpP-1$, then there is an $s_k\in[a_k,a_{k+1}]$ such that $\im(Q[t_k,t_l])\subset B(P(s_k), \delta)$, where $l$ is the transition index after $k$.
        \item If $k\geq \cpP-1$, then there is an $s_k\in [a_{\cpP-1}, a_{\cpP}]$ such that $\im(Q[t_k,w^*])\subset B(P(s_k), \delta)$ and $\im(P[s_k,a_\cpP])\subset B(Q(w^*), \delta)$.
    \end{enumerate}
    \end{claim}

    Utilizing $a)$-$d)$, we construct a traversal of $P$ and $Q$ as follows: Let $k$ be the smallest transition index. Match $P[1,s_k]$ to $Q(t_k)$ with $t_k=1$ via $a)$. Now let $k$ be the last handled transition index and let $l$ be the next transition index after $k$. First match $Q[t_k,t_l]$ to $P(s_k)$ via $c)$ (lightblue in \Cref{fig:beginning}) and then match $P[s_k,s_l]$ to $Q(t_l)$ via $a)$ (yellow in \Cref{fig:beginning}). Lastly, let $k$ be the last transition index. So far, the constructed matching matches $Q[1,t_k]$ to $P[1,s_k]$. We now match $Q(t_k,w^*)$ to $P(s_k)$ and lastly $P[s_k,a_\cpP]$ to $Q(w^*)$ via $d)$ (darkblue and orange in \Cref{fig:beginning}). 

    If instead $\X\equiv 1$, then by Condition $(iii)$ and the range-preservedness of $P$ there must be a point $s$ in $[a_{\cpP-1},a_{\cpP}]$, such that $\im(Q[1,w^*])\subset B(P(s),\delta)$. Choosing a maximal such $s$ also ensures that $\im(P[s,a_{\cpP}])\subset B(Q(w^*),\delta)$, since there are no deadlocks. However, then there is a traversal of $P$ and $Q$, by first matching $P[1,s]$ to $Q(1)$, then matching $Q[1,w^*]$ to $P(s)$, and lastly matching $P[s,a_{\cpP}]$ to $Q(w^*)$, which concludes the proof.
\end{proof}

\begin{proof}[Proof of Claim \ref{c:def_sk_and_tk}]
    \ 
    \begin{enumerate}[a)]
    \item The existence of $t_k$ in a) is an immediate consequence of \Cref{lem:preliminaryAssignmentStructure} iii). Further, by \Cref{lem:preliminaryAssignmentStructure} i) and since $k$ is a transition index, it holds that $t_k\leq b_{\X(k)}\leq b_{\X(k+2)-1}$. Since $\im(P[1, a_p])\subset B(Q[1, w^*], \delta)$, it follows that $b_{\X(k+2)-1}<w^*$.

    \item If $w^*\geq b_{\X(k)}$, the existence of $t_k$ in b) follows from \Cref{lem:preliminaryAssignmentStructure} iii). 
    So, assume that $w^*<b_{\X(k)}$. It holds by definition that $Q(b_{\X(k)-1})$ is either the maximum or the minimum of $Q[1, w^*]$. Further, no point on $Q[1, b_{\X(k)-1}]$ has distance at most $\delta$ to $P(a_k)$, by the definition of $\X(k)$. Hence, by Condition (ii) of \Cref{l:startAndEnd} and since $Q$ is contained in a $\delta$-ball, the other global maximum or minimum of $Q[1, w^*]$ lies on $Q[b_{\X(k)-1}, w^*]$. Therefore, there exists a point $t\in[b_{\X(k)-1}, w^*]$ such that $\im(Q[1,w^*])\subset\overline{Q(b_{\X(k)-1})\,Q(t)}$. Again by Condition (ii) of \Cref{l:startAndEnd}, $\im(P[1,a_\cpP])\subset B(Q[1,w^*],\delta)=B(\overline{Q(b_{\X(k)-1})\,Q(t)}, \delta)$. As $P[1,a_\cpP]$ is contained in a $2\delta$-range, there exists a value $t_k$ such that $b_{\X(k)-1}\leq t_k\leq t\leq w^*$ and $\im(P[1,a_\cpP])\subset B(Q(t_k), \delta)$.

    \item Let $l$ be the transition index following $k$, so that $\X(k+2)=\X(l)\neq \X(k)$. By the minimal choice of $t_l$ and the range-preservedness of $Q$, it suffices to show that there is a $s_k$ such that $Q[1,b_{\X(l)-1}]$ and $Q(t_l)$ lie in $B(P(s_k),\delta)$, as this already implies that $\im(Q[t_k,t_l])\subset \im(Q[1,t_l])\subset B(P(s_k),\delta)$.

    As $\X(k+2)=\X(l)$, neither $\Y(\X(l)-1)$ nor $\Y(\X(l)-2)$ can equal $k+2$. As $\Y$ and $\X$ do not form any deadlocks, in fact $k+1\geq \max(\Y(\X(l)-2),\Y(\X(l)-1))$. Hence, by \Cref{lem:preliminaryAssignmentStructure} (with the roles of $P$ and $Q$ reversed) there is a point $s_k\in[a_k,a_{k+1}]$, such that $Q[1,b_{\X(l)-1}]$ lies in  $B(P(s_k),\delta)$. As $P(s_k)\in \im(P[1,a_{k+1}])\subset \im(P[1,a_{l+1}])$, in particular, $P(s_k)\in B(Q(t_l),\delta)$, and as such $Q(t_l)\in B(P(s_k),\delta)$. Thus, $s_k$ is the sought-after point.

    \item By Condition~(iii) of \Cref{l:startAndEnd} and because $Q[1,w^*]$ is contained in a $2\delta$-range there is a point $s\in[a_{\cpP-1},a_\cpP]$ such that $\im(Q[t_k,w^*])\subset B(P(s), \delta)$. By choosing $s_k$ to be the maximal such  $s$ it follows that $s_k\geq s_l$ for any transition index $l$. 
    The second property follows from the maximality of $s_k$, as then $\im(P[s_k,a_\cpP])=\overline{P(s_k)\,P(a_\cpP)}$, and both $P(s_k)$ and $P(a_\cpP)$ have distance at most $\delta$ to $Q(w^*)$, by definition and Condition~(i), respectively.\qedhere
    \end{enumerate}
\end{proof}

