We use the next lemma to decide whether a \ePQ{\pre{P}}{\pre{Q}} exists.
%With the help of \Cref{l:startAndEnd}, we can show the following lemma, which can be used to decide whether a \ePQ{\pre{P}}{\pre{Q}} exists.

\begin{restatable}{lemma}{wip}\label{lem:wip}

%\begin{lemma}\label{lem:wip}
    Let $P$ and $Q$ be two time series and $P(i_2)$ be the second $\delta$-signature vertex~of~$P$ and $Q(j_2)$ of $Q$.
    There exists a \ePQ{\pre{P}}{\pre{Q}} if and only if $\X(k)< \infty$, and $\X(k)$ and $\Y(l)$ do not form a deadlock for all $k\in[\cpP]$ and $l\in[\cpQ]$.
    If it exists, it is 
    \[\min\{w=1, \dotso, j_2 \mid |P(i_2)-Q(w)|\leq \delta,\  \im(\pre{P})\subset B(Q([1, w+1], \delta)\}.\]
%\end{lemma}
\end{restatable}
\begin{proof}
    If there exists $k$, $l$ such that $\X(k)$ and $\Y(l)$ form a deadlock, then by \cref{l:startAndEnd} there cannot exist such a value $w^*\in [1, j_2]$ such that $d_F(\pre{P}, Q[1, w^*])\leq \delta$. Hence, a \ePQ{\pre{P}}{\pre{Q}} does not exist.

    Now, assume that $\X(k)$ and $\Y(l)$ do not form a deadlock for all $k=1, \dotso, \cpP$ and $l=1, \dotso, \cpQ$.
    Let $\X_{\max}=\max\{\X(\cpP-1), \X(\cpP)\}$. If $X_{\max}=1$, then $\im(\pre{P})\subset B(P(1), \delta)$. Hence, the \ePQ{\pre{P}}{\pre{Q}} is $P(1)$. 
    Otherwise by \Cref{lem:preliminaryAssignmentStructure} (iii), there exists a value $t\in [b_{\X_{\max}-1}, b_{\X_{\max}}]$ such that $\im(\pre{P})\subset B(Q(t), \delta)$. Let $w$ be one of these values such that in addition
    $\im(Q[b_{\X_{\max}-1}, w])\subset \overline{Q(b_{\X_{\max}-1})Q(w)}$. Note that $w\leq j_2$. Since by assumption there does not exist a deadlock, $\max(\Y(\X_{\max}-2), \Y(\X_{\max}-1))\leq \cpP$. Therefore, $Q(w)$, $Q(b_{\X_{\max}-1})$, and $Q(b_{\X_{\max}-2})$ lie in $B(\pre{P}, \delta)$ and \[\im(Q[1, w])\subset \overline{Q(b_{\X_{\max}-2})Q(b_{\X_{\max}-1})}\cup\overline{Q(b_{\X_{\max}-1})Q(w)}\subset B(\pre{P}, \delta).\] 
    Hence, all conditions of \cref{l:startAndEnd} are satisfied for $w$ and thus $d_F(\pre{P}, Q[1, w])\leq \delta$.
    As a result, $w^*=\min\{w\in[1, j_2]\mid d_F(\pre{P}, Q[1, w])\leq \delta\}$ is well-defined. It holds that $\im(Q[1, w^*])\subset \im(Q[1, w])\subset B(\pre{P}, \delta)$. Hence, 
    by \cref{l:startAndEnd} it holds that \[w^*=\min\{w\in[1, j_2]\mid |P(i_2)-Q(w)|\leq \delta,\ \im(\pre{P})\subset B(Q[1, w], \delta)\}.\] If $|P(i_2)-Q(\lfloor w^*\rfloor)|\leq \delta$, we define $\wpre=\lfloor w^*\rfloor$. 
    Then, $Q(\wpre)$ is the \ePQ{\pre{P}}{\pre{Q}}, since $w^*$ was defined as the minimum. Otherwise, we set $\wpre=\lceil w^*\rceil$. Since $\pre{Q}$ is contained in a $2\delta$-range, $|P(i_2)-Q(w^*)|\leq \delta$, and $|P(i_2)-Q(\lfloor w^*\rfloor)|> \delta$, it holds that $|P(i_2)-Q(\lceil w^*\rceil)|\leq \delta$. 
    Therefore, we have that $\im(Q[1, \wpre])\subset \im(Q[1, w^*])\cup \overline{Q(w^*) Q(\wpre)}\subset B(\pre{P}, \delta)$. Hence, all conditions of \cref{l:startAndEnd} are fulfilled and thus $d_F(\pre{P}, Q[1, \wpre])\leq \delta$, so that $\wpre$ is the \ePQ{\pre{P}}{\pre{Q}}. 
    Further, by the definition of $w^*$, it holds that \[\wpre=\min\{w\in\{1, \dotso, j_2\}|\ |P(i_2)-Q(w)|\leq \delta,\  \im(\pre{P})\subset B(Q([1, w+1], \delta)\}.\qedhere\] 
\end{proof}



Finally, we are ready to show how the \ePQ{\pre{P}}{\pre{Q}} can be computed.

\begin{restatable}{lemma}{searchprefixend}\label{lem:searchprefixend}
%\begin{lemma}\label{lem:searchprefixend}
    Let $P$ and $Q$ be time series and let $\im (Q[1, j])$ be given for every $j=1,\dots, q$. Further, assume the preliminary assignments $X$ and $Y$ of $\pre{P}$ and $\pre{Q}$ do not form a deadlock. Then we can compute the \ePQ{\pre{P}}{\pre{Q}} in $\mathcal{O}(\log n)$ time.
%\end{lemma}
\end{restatable}
\begin{proof}
    Let $P(i_2)$ be the last vertex of $\pre{P}$ %second $\delta$-signature of $P$
    and $Q(j_2)$ be the last vertex of $\pre{Q}$.  
    Using~\cref{lem:wip}, we can compute the \ePQ{\pre{P}}{\pre{Q}} as 
    \[\wpre=\min\{w\in\{1, \dotso, j_2\}|\ |P(i_2)-Q(w)|\leq \delta, \im(\pre{P})\subset B(Q([1, w+1], \delta)\}.\] 

    The second requirement is monotone, so that binary search can be used to identify the minimum $w\in \{1,\dotso, j_2\}$ that satisfies it. To further compute $\wpre$, observe that since $Q$ is range-preserving, the first edge of $Q$ that intersects $B(P(i_2),\delta)$ can also be found using binary search. Then, observe that among the edges intersecting $B(P(i_2),\delta)$, if the starting point of an edge is inside $B(P(i_2),\delta)$, then this is also true for proceeding edges since $Q$ is range-preserving, so that the first such starting point can again be found using binary search. 
\end{proof}


The following lemma shows how to decide for two time series $P$ and $Q$ whether the entry $M_{\delta}(i_2, j_2)$ of the modified free-space matrix is $0$ or $1$. 
\begin{restatable}{lemma}{itwojtwo}\label{lem:(i_2j_2)}
%\begin{lemma}\label{lem:(i_2j_2)}
    Let $P$ and $Q$ be two time series and let extreme point sequences of $\pre{P}$ and $\pre{Q}$ be given.
    If the preliminary assignments of $\pre{P}$ and $\pre{Q}$ do not form a deadlock,
    then we can decide whether $d_F(\pre{P}, \pre{Q})\leq \delta$ in $\Oh(1)$ time. Otherwise, it holds that $d_F(\pre{P}, \pre{Q})> \delta$.
%\end{lemma}
\end{restatable}
\begin{proof}
    We prove this lemma using~\Cref{l:startAndEnd}. Property (i) can be checked in constant time. By the definition of the extreme point sequence, it holds that $\im(\pre{P})= \overline{P(a_{\cpP-1}) P(a_\cpP)}$ and $\im(\pre{Q})= \overline{Q(b_{\cpQ-1})Q(b_\cpQ)}$. Therefore, we can check in constant time whether Properties~(ii) and~(iii) hold.
\end{proof}

The results of this section show how, using deadlocks, we can fill in the modified free-space matrix. In the following, we show that deadlocks allow efficient processing of updates of the transformations, which we crucially exploit for our algorithms.   

\section{1D Continuous Fréchet Distance Under Translation}\label{sec:translations}
We first describe the reduction of the 1D continuous Fréchet distance under translation to an offline dynamic grid graph reachability problem. Subsequently we describe how we solve this problem for two time series $P$ and $Q$ both of complexity $n$ in time $\Oh(n^{8/3} \log^3 n)$.


\subsection{\texorpdfstring{\boldmath The $\Oh(n^2)$ Events}{The O(n\textasciicircum 2) Events}}\label{sec:ArrangTrans}
In this section, we show how to compute a set of $\Oh(n^2)$ translation values such that the \F under translation between $P$ and $Q$ is at most $\delta$ if and only if there exists a translation value $t$ in this set such that the \F between $P$ and $Q_t$ is at most~$\delta$. We start by observing that it is sufficient to consider vertex-vertex events. 

\begin{restatable}{lemma}{pointpointtranslationevents}\label{lem:pointpointtranslationevents}
%\begin{lemma}\label{lem:pointpointtranslationevents}
    Let $M(P,Q)=(m_{i,j})_{(i,j)\in[n]\times[n]}$ be the matrix where $m_{i,j}=\mathbbm{1}_{|P(i)-Q(j)|\leq\delta}$. Let $t,t'\in\RR$ be given. If $M(P,Q_t)=M(P,Q_{t'})$, then $d_F(P,Q_t)\leq\delta\iff d_F(P,Q_{t'})\leq\delta$.
%\end{lemma}
\end{restatable}
\begin{proof}
    By \Cref{lem:dfModMatEquiv}, it suffices to show that if $M(P,Q_t)=M(P,Q_{t'})$ then the modified free-space matrices of $P$ and $Q_t$, and $P$ and $Q_{t'}$ agree. Observe that these modified free-space matrices do agree if the following conditions hold
    \begin{compactenum}
        \item $\forall(i,j)\in[n]\times[n]:M(P,Q_t)_{i,j}= M(P,Q_{t'}){i,j}$, \label{equivTrans:item1}
        \item the set of indices
        defining the $\delta$-signature vertices of $Q_t$ and $Q_{t'}$ agree, \label{equivTrans:item2}
        \item the \ePQ{\pre{P}}{\pre{Q_t}} is the \ePQ{\pre{P}}{\pre{Q_{t'}}}, \label{equivTrans:item3}
        \item the \ePQ{\pre{Q_t}}{\pre{P}} is the \ePQ{\pre{Q_{t'}}}{\pre{P}}, \label{equivTrans:item4}
        \item the \ePQ{\suf{P}}{\suf{Q_t}} is the \ePQ{\suf{P}}{\suf{Q_{t'}}}, and
        \item the \ePQ{\suf{Q_t}}{\suf{P}} is the \ePQ{\suf{Q_{t'}}}{\suf{P}}.\label{equivTrans:item6}
    \end{compactenum}
    Observe that \Cref{equivTrans:item1} holds as $M(P,Q_t)=M(P,Q_{t'})$. Further \Cref{equivTrans:item2} holds as by definition the extended $\delta$-signature is translation-invariant. \Cref{equivTrans:item3} holds as by \Cref{lem:wip} the \ePQ{\pre{P}}{\pre{Q_t}} only depends on $M(\pre{P},\pre{Q_t})$ and hence it agrees with the \ePQ{\pre{P}}{\pre{Q_{t'}}} as $M(\pre{P},\pre{Q_t})=M(\pre{P},\pre{Q_{t'}})$ as they are submatrices of $M(P,Q_t)$ and $M(P,Q_{t'})$ respectively. Similarly \Cref{equivTrans:item4} to \Cref{equivTrans:item6} hold implying the claim.
\end{proof}


\begin{observation}\label{obs:arrangement}
    Let $P$ and $Q$ be two time series of complexity $n$. There are at most $\Oh(n^2)$ many values $t$ such that there are values $i, j\in[n]$ such that $|P(i)-Q_t(j)|=\delta$. These values are precisely the interval boundaries of intervals of the form $\left[P(i)-Q(j)-\delta,P(i)-Q(j)+\delta\right]$.
\end{observation}

We briefly discuss how to deal with degenerate cases, that is, cases where it is not true that for every $t\in\RR$ exactly two values ${i\neq j\in[n]}$ exist such that $|P(i)-Q_t(j)|=\delta$, in \Cref{app:symbpert}.


\begin{restatable}[translation representatives]{corollary}{CompuTranslationArrangement}\label{cor:CompuTranslationArrangement}
%\begin{corollary}\label{cor:CompuTranslationArrangement}
    There exist a sorted set $\mathfrak{T}\subset\RR$ containing $\Oh(n^2)$ points and
    %of size $\Oh(n^2)$ 
    computable in $\Oh(n^2\log n)$ time with the following properties.
    \begin{itemize}
        \item It holds that $d_F^T(P,Q)\leq\delta$ if and only if $\exists t\in\mathfrak{T}$ such that $d_F(P,Q_t)\leq\delta$. 
        \item For two consecutive $t,t'$ in $\mathfrak{T}$, there exist only one pair of indices $k, l\in [n]$ such that $|P(k)-Q_t(l)|\leq \delta$ and $|P(k)-Q_{t'}(l)|>\delta$, or the other way round. Further, for the set of all pairs of consecutive $t, t'\in \mathfrak{T}$, those indices can be computed in $\Oh(n^2 \log n)$ time. 
    \end{itemize}
%\end{corollary}
\end{restatable}
We call the set $\mathfrak{T}$ of \cref{cor:CompuTranslationArrangement} $\Oh(n^2)$ points the \emph{translation representatives}.

\begin{proof}
    \Cref{obs:arrangement} implies that there is an arrangement of $\RR$ such that only one inter-point distance namely that of $k$ and $l$ is such that the arrangement boundary is induced by $|P(k)-Q_t(l)|=\delta$. 
    As this arrangement and a point from each interval in the arrangement can be computed in $\Oh(n^2\log n)$ the claim follows by \Cref{lem:pointpointtranslationevents}.
\end{proof}


\subsection{Dealing with degenerate cases using symbolic perturbation}\label{app:symbpert}

If the instance under consideration is degenerate, then in the set of intervals of the form $\left[P(i)-Q(j)-\delta,P(i)-Q(j)+\delta\right]$ there are at least two whose interval boundaries coincide in at least one point, by \Cref{obs:arrangement}. Let $\{[a_1,b_1],\ldots\}$ be this set of closed intervals. We introduce symbolic perturbation on every interval boundary $a_i$ and $b_i$ resulting in $\hat{a}_i$ and $\hat{b_i}$ and a total order such that, in particular, any right boundary $\hat{b}_i$ of such an interval is \emph{strictly} larger than a left boundary $\hat{a}_i$ of another interval if and only if $b_i\geq a_i$. Then there are $\Oh(n^2)$ (symbolically perturbed) values in $\RR$ such that between two successive values the membership in the symbolically perturbed intervals differs by exactly one. Hence, these symbolically perturbed values are such that for any $\hat{t}\in \RR$ exactly two values $i\neq j\in[n]$ exist such that $|P(i)-Q_{\hat{t}}(j)|=\delta$. 
Furthermore, for any value $t\in\RR$ with some interval membership in intervals $\{[a_i,b_i],\ldots\}$ there is a symbolically perturbed version of $\hat{t}$ that has the same membership in perturbed versions of the intervals $\{[\hat{a}_i,\hat{b}_i],\ldots\}$.

\subsection{Prefix and Suffix under Translation}\label{sec:PrefTranslation} 
In \cref{sec:prefSuff}, we showed that the preliminary assignment can be used to determine the \ePQ{\pre{P}}{\pre{Q}}. In particular, the \ePQ{\pre{P}}{\pre{Q}} can be computed in $\mathcal{O}(\log n)$ time, if we know whether there does exists a deadlock or not. Therefore, we define the translated preliminary assignment and show how to keep track of whether a deadlock exists while translating the time series $Q$ with the values in $\mathfrak{T}$.

\begin{definition}[translated preliminary assignment]
    Let $P$ and $Q$ be time series and let $t\in\RR$. Define the \emph{translated preliminary assignment} $\X_t$ to be the preliminary assignment of $\pre{P}$ on $\pre{Q_t}$. Let similarly $\Y_t$ be the preliminary assignment of $\pre{Q_t}$ on $\pre{P}$. We say that $\X_t(k)$ and $\Y_t(l)$ form a \emph{deadlock}, if $l<{\X_t(k)}$ and $k<{\Y_t(l)}$. 
\end{definition}

Given two time series $P$ and $Q$ together with extreme point sequences $a_1,\ldots,a_p$ and $b_1,\ldots,b_q$ of $\pre{P}$ and $\pre{Q}$, we show that we can compute the set $\mathcal{T}\subset\mathfrak{T}$ of translations for which $X_t$ and $Y_t$ do not form a deadlock in total time $\Oh(n^2\log n)$. 

\begin{observation}
    For every $t\in \mathbb{R}$, the extreme point sequences of $Q_t$ and $Q$ coincide.
\end{observation}

\begin{observation}
    $\mathcal{T}\subset \{t\in\RR|X_t(1) = 1\} = \{t\in\RR|Y_t(1) = 1\}$.
\end{observation}

The next observation and next lemma show that the preliminary assignments of two consecutive translations of the translation representatives differ only slightly.

\begin{observation}\label{obs:oneStepTrans}
    Let two consecutive translation representatives $t,t'$ be given. Then, $X_t$ and $X_{t'}$ (resp. $Y_t$ and $Y_{t'}$) agree everywhere except at the index that participates in the point-point distance inducing the arrangement boundary separating $t$ and~$t'$. 
\end{observation}

\begin{restatable}{lemma}{updateStepTrans}\label{lem:updateStepTrans}
%\begin{lemma}\label{lem:updateStepTrans}
    Let two consecutive translation representatives $t,t'$ be given. 
    Let $k$ be the index of $P$ and $l$ the index of $Q$ participating in the point-point distance inducing the arrangement boundary separating $t$ and $t'$. 
    Then, it holds that
    \begin{compactenum}
        \item $|Y_t(l) - Y_{t'}(l)| \leq 2$,
        \item $Y_t(l) = \infty$ and $Y_{t'}(l) \in \{p-1,p\}$, or
        \item $Y_{t'}(l) = \infty$ and $Y_t(l) \in \{p-1,p\}$.
    \end{compactenum}
    Similarly, it holds that 
    \begin{compactenum}
        \item $|X_t(k) - X_{t'}(k)| \leq 2$,
        \item $X_t(k) = \infty$ and $X_{t'}(k) \in \{q-1,q\}$, or
        \item $X_{t'}(k) = \infty$ and $X_t(k) \in \{q-1,q\}$.
    \end{compactenum}
%\end{lemma}
\end{restatable}
\begin{proof}
    We define the following nested family of closed sets \(\mathcal\{{F}_i=\bigcup_{i'\leq i}B(P(a_i),\delta)\mid 1\leq i\leq p\}\cup\{F_\infty=\RR\}\). 
    Let $\mathcal{A}$ be the arrangement of $\RR$ defined by these sets.
    By definition of $P$ and $a_1,\ldots,a_p$, each $F_i$ is a contiguous interval in $\RR$ and for $i\leq j-2$ it holds that $F_i$ and $F_j$ do not share a boundary. 
    Further, we have that 
    $Y_t(l) = \min\{k' \in [p]\cup\{\infty\}\mid  Q(b_l)+t\in F_{k'}\}$.  
    If $t,t'$ are two consecutive translation representatives, then $Q(b_l)+t$ and $Q(b_l)+t'$ must lie in neighboring intervals in $\mathcal{A}$ and thus their level in the set family can differ by at most two implying the claim for $Y_t$ and $Y_{t'}$. The claim for $X_t$ and $X_{t'}$ follows similarly.
\end{proof}


\begin{restatable}{lemma}{PrefixTranslation}\label{lem:PrefixTranslation}
%\begin{theorem}\label{lem:PrefixTranslation}
    There is an algorithm that correctly computes the set $\mathcal{T}$ of translations $t\in \mathfrak{T}$ for which $X_t$ and $Y_t$ do not form a deadlock in $\Oh(n^2\log n)$. This is the set of translations in $\mathfrak{T}$ for which the preliminary assignments of $\pre{P}$ and $\pre{Q_t}$ do not form a deadlock. Similarly, we can compute the set of translations in $\mathfrak{T}$ for which $\suf{P}$ and $\suf{Q_t}$ do not form a deadlock in $\Oh(n^2\log n)$ time.
%\end{theorem}
\end{restatable}
\begin{proof}
    We begin by computing the translation representatives $\mathfrak{T}$ of size $\Oh(n^2)$ and store it. This can be done in $\Oh(n^2\log n)$ time by~\cref{cor:CompuTranslationArrangement}. Next compute from the contiguous interval $[a,b]=\{t\in\RR|X_t(1) = 1\}$ in $\Oh(n^2)$ time the set $\mathcal{T}'=\mathfrak{T}\cap[a, b]$. 
    We define $\mathcal{D}_t=\{k\mid\exists l:\text{$X_t(k)$ and $Y_t(l)$ form a deadlock}\}$. 

    Initially, we compute $X_{t}$ and $Y_{t}$ for the smallest value $t\in \mathcal{T}'$. In addition, we store for every $1\leq k\leq \cpP$, whether $X_{t}(k)$ forms a deadlock with some $Y_{t}(l)$ or not, that is we decide whether $k\in\mathcal{D}_t$. Note that by \Cref{lem:preliminaryAssignmentStructure} (iv), it holds that $k\in \mathcal{D}_t$ if and only if $X_{t}(k)$ and $Y_{t}(X_{t}(k)-1)$ form a deadlock. Hence, this can be computed in $\mathcal{O}(n)$ time for all $k$. Further, we store the number $d_t = |\mathcal{D}_t|$. Then, $X_{t}$ and $Y_{t}$ do not form a deadlock if and only $d_t=0$.

    Now let the above data be given correctly for some translation $t\in\mathcal{T}'$ and let $t'$ be the next translation in $\mathcal{T}'$. Let $k\leq p$ and $l\leq q$ be the two indices that induced the arrangement boundary between $t$ and $t'$. We show how to update above data correctly.
    By \Cref{obs:oneStepTrans} and \Cref{lem:updateStepTrans}, for any $\hat{k}\in \mathcal{D}_t$ either $\hat{k} = k$ or $|\hat{k}-Y_t(l)|\leq 2$ or $\hat{k}\in \mathcal{D}_{t'}$. In the first two cases, we can check whether $\hat{k}\in\mathcal{D}_{t'}$ in $\Oh(1)$ time by \Cref{lem:preliminaryAssignmentStructure} (iv). Thus we can compute $d_{t'}$ given $d_t$ in time $\mathcal{O}(1)$.
    Repeating this update $\Oh(n^2)$ times sweeping over all translations in $\mathcal{T}'$ implies the claim. The claim for the suffix follows by~\Cref{obs:ConnectionSufPre}.
\end{proof}


\subsection{Solving the Decision Problem}
%\subsection{Computing the Fréchet Distance under Translation}
We are now ready to prove our result for the decision problem of the Fréchet distance under translation of time series.

\begin{lemma} \label{lem:fut_decider}
    We can decide the Fréchet distance under translation between two time series in time $\Oh(n^{8/3} \log^2 n)$.
\end{lemma}
\begin{proof}
The goal is to apply \cref{thm:offline_dyn_grid_reachability} to maintain reachability in the modified free-space matrix defined in \cref{def:mod_free_space_matrix} for all translations in $\mathfrak{T}$ from \cref{cor:CompuTranslationArrangement}.

In a pre-processing step, we first compute the signatures of both input time series and extreme point sequences of $\pre{P}, \pre{Q}, \suf{P}, \suf{Q}$, all in time $\Oh(n)$.
We use \cref{cor:CompuTranslationArrangement} to compute the set $\mathfrak{T}$ of candidate translations that we have to check reachability for, and fix the order in which we check them (e.g., from left to right).
Additionally, we invoke \cref{lem:PrefixTranslation} to compute the set $\mathcal{T} \subset \mathfrak{T}$ for which there are no deadlocks of the prefixes and suffixes.
The above steps take time $\Oh(n^2 \log n)$ each.
It now suffices to show that if we consider the the translations $\mathfrak{T}$ in order, there are only $\Oh(1)$ many updates per translation to the modified free-space matrix of \cref{def:mod_free_space_matrix}, for each type of entry (a) to (f). Furthermore, we need to determine all of these updates in time $\Oh(n^2 \log n)$.

Combining \cref{cor:CompuTranslationArrangement} and the information from the pre-computed signatures, we can pre-compute the $\Oh(1)$ many updates per translation in $\mathfrak{T}$ of type (a),(b), and (c) in time $\Oh(n^2 \log n)$.
For entries of type (d) and (e), we first check whether the translation at hand incurs a deadlock or not (i.e., we check for containment in the pre-computed set $\mathcal{T}$).
If it does not incur a deadlock, then we use \cref{lem:(i_2j_2)} to determine in constant time whether $d_F(\pre{P}, \pre{Q})\leq \delta$ and $d_F(\suf{P}, \suf{Q})\leq \delta$.
For type (f), we use the pre-computed signatures and \cref{lem:searchprefixend} to compute $\wpre, \vpre, \wsuf, \vsuf$ in $\Oh(\log n)$ time.

Note that by the above, each entry type incurs at most $\Oh(1)$ updates per translation, and we therefore have $\Oh(n^2)$ updates in total. All of these updates can be pre-determined, i.e., they are offline.
Consequently, we can apply~\Cref{thm:offline_dyn_grid_reachability} and obtain a running time of $\Oh(n^2 \cdot n^{2/3} \log^2 n) = \Oh(n^{8/3} \log^2 n)$.
\end{proof}

\subsection{Solving the Optimization Problem}\label{app:transoptimization}

Let us first consider a simple but inefficient variant to solve the optimization problem.
To that end, we define the set of all translations that align two vertices:
\[
T_{\text{align}} = \{ P(i) - Q(j) \mid i,j \in\{1, \dotso, n\} \}.
\]
By \cref{lem:pointpointtranslationevents}, for the optimal distance $\delta^*$ we have that there exist $t,t' \in T_{\text{align}}$ such that $|t-t'| = 2 \delta^*$.
Hence, for each pair $t, t' \in T_{\text{align}}$ we can test whether $d_F(P,Q + \frac{t+t'}{2}) \leq \frac{|t-t'|}{2}$, and the $t,t'$ with smallest $\frac{|t-t'|}{2}$ such that the decision query is positive is the Fréchet distance under translation $\delta^*$.
The above algorithm has running time $\Oh(|T_{\text{align}}|^2) = \Oh(n^4)$.
%
Fortunately, we can use parametric search to significantly reduce the running time and only incur an additional logarithmic factor compared to the running time of the decision problem.
We use a variant of Meggido's parametric search~\cite{Megiddo83} due to Cole~\cite{Cole87}, as was also used in~\cite{DBLP:journals/talg/BringmannKN21}.

For all $t_i \in T_{\text{align}}$, we define the functions $f_i^+(\delta) \coloneqq t_i + \delta$ and $f_i^-(\delta) \coloneqq t_i - \delta$.
These are the functions that we want to sort in our parametric search.
Note that, as argued above, the Fréchet distance under translation is realized for some $\delta^*$ such that there exist $i,j \in [|T_{\text{align}}|]$ with $f_i^+(\delta^*) = f_j^-(\delta^*)$.
To apply parametric search, we need two properties (see Section~3 in~\cite{Cole87}):
\begin{enumerate}
    \item Given any two functions $f_i^+(\delta), f_j^-(\delta)$, we can decide whether $f_i^+(\delta^*) \leq f_j^-(\delta^*)$ in time $T(n)$.\footnote{Note that we do not know the value of $\delta^*$!}
    \item Given a set of such comparisons, we can order them such that resolving any single comparison will resolve all comparisons before or after in the order. Also, determining the order of two \emph{comparisons} can be done in $\Oh(1)$ time.
\end{enumerate}

Consider the first property and assume $t_i < t_j$; all other cases are simple (as the comparison has the same result for all $\delta > 0$) or analogous.
Note that $f_i^+(\delta) = f_j^-(\delta)$ if and only if $\delta = \frac{t_j - t_i}{2}$, and $f_i^+(\delta) < f_j^-(\delta)$ for $\delta < \frac{t_j - t_i}{2}$ and $f_i^+(\delta) > f_j^-(\delta)$ for $\delta > \frac{t_j - t_i}{2}$.
Hence, using our decider of~\Cref{lem:fut_decider} to evaluate whether $\delta^* \leq \frac{t_j - t_i}{2}$, we can decide in which case we lie and hence decide $f_i^+(\delta^*) \leq f_j^-(\delta^*)$ in $T(n) = \Oh(n^{8/3} \log^2 n)$ time by~\Cref{lem:fut_decider} (without knowing $\delta^*$).

For the second property, consider that any pair of functions has a different threshold value at which the order flips.
Comparing the threshold value for two comparisons takes $\Oh(1)$ time.
If we now order the comparisons according to their threshold values, then deciding one of these comparisons will resolve either all comparisons before or after: if $f_1(\delta^*) \leq f_2(\delta^*)$, then this also holds for all comparisons with larger threshold value; if $f_1(\delta^*) > f_2(\delta^*)$, then this also holds for all comparisons with smaller threshold value.

Hence, we can apply parametric search as described in~\cite{Cole87} with a running time of $\Oh((|T_{\text{align}}| + T(n)) \cdot \log n) = \Oh((n^2 + n^{8/3}) \log^3 n) = \Oh(n^{8/3} \log^3 n)$, obtaining the following theorem:

\mainresulttranslations*

\section{1D Continuous Fréchet Distance Under Scaling}\label{app:scaling}
Our algorithm for the Fréchet distance under scaling works in a similar way as our algorithm for translations. An additional obstacle to overcome is that scaling a time series can change the $\delta$-signature.
We first describe the reduction of the 1D continuous \F under scaling to an offline dynamic grid graph reachability. Subsequently we describe how we solve this problem for two time series $P$ and $Q$ each of complexity $n$ in time $\Oh(n^{8/3}\log n)$.

\subsection{\texorpdfstring{\boldmath The $\Oh(n^2)$ Events}{The O(n\textasciicircum 2) Events}}

After translating a time series, the indices of the $\delta$-signature vertices remain the same. In contrast, the indices of the $\delta$-signature vertices can change when we scale a time series. Therefore, we begin by showing how the indices of the $\delta$-signature vertices change through scaling and show that there exists only $\Oh(n)$ different sets of indices of the $\delta$-signature vertices for scaled time series.

\begin{lemma}\label{lem:connectionSignature}
    Let $\langle Q(j_1), Q(j_2), \dots, Q(j_{s_Q})\rangle$ be the extended $\delta$-signature of $Q$. Then, the extended $s\delta$-signature of $sQ$ is $\langle sQ(j_1), sQ(j_2), \dots, sQ(j_{s_Q})\rangle$.
\end{lemma}
\begin{proof}
    This lemma follows directly by the definition of the extended $\delta$-signature, since $s|Q(j)-Q(j')|=|sQ(j)-sQ(j')|$ for all $j, j'\in[n]$. 
\end{proof}

\begin{restatable}{lemma}{lemorderSignature}\label{lemma:orderSignatures}
    We can compute in $\mathcal{O}(n\log n)$ time all values $s_j$ with $j=1, \dots, n$ such that the following holds. 
    The vertex $sQ(j)$ is a $\delta$-signature vertex of $sQ$ if and only if $s>s_j$.
\end{restatable}
\begin{proof}
    By Lemma 6.1 of \cite{DBLP:conf/soda/DriemelKS16}, there exists values $\delta_j$ with $j\in [n]$ such that $Q(j)$ is a $\delta$-signature vertex of $Q$ for every $\delta<\delta_j$ and no $\delta$-signature vertex for every $\delta\geq \delta_j$. Those values can be computed in $\Oh(n\log n)$ time by the proof of Theorem 6.1 of \cite{DBLP:conf/soda/DriemelKS16}. We set $s_j=\delta/\delta_j$ for every $j\in [n]$. By~\cref{lem:connectionSignature}, it holds that $sQ(j)$ is a $\delta=s\delta'$-signature vertex of $sQ(j)$ if and only if $Q(j)$ is a $\delta'$-signature vertex of $Q$. Hence, the claim follows.
\end{proof}


By~\cref{lemma:orderSignatures}, we get the following:
\begin{corollary}[coarse arrangement]\label{obs:coarseArragement}
    There exists an ordered set $\mathfrak{S'}$ of $\Oh(n)$ distinct intervals computable in $\Oh(n\log n)$ time such that the following holds.
    For any two $s,s'$ in the same interval of $\mathfrak{S}'$, the set of indices defining the $\delta$-signature vertices of $sQ$ and $s'Q$ agree. 
\end{corollary}

With the definition of the coarse arrangement, we can now proceed in a similar way to \Cref{sec:ArrangTrans}, to compute a set of scaling values that are sufficient to decide whether the \F under scaling is at most $\delta$.

\begin{lemma}\label{lem:pointpointscaleevents}
    Let $M(P,Q)=(m_{i,j})_{(i,j)\in[n]\times[n]}$ be the matrix where $m_{i,j}=\mathbbm{1}_{|P(i)-Q(j)|\leq\delta}$. Let $s,s'$ be in the same interval in $\mathfrak{S}'$. If $M(P,sQ)=M(P,s'Q)$, then ${d_F(P,sQ)\leq\delta}\iff d_F(P,s'Q)\leq\delta$.
\end{lemma}
\begin{proof}
    By \Cref{lem:dfModMatEquiv}, it suffices to show that if $M(P,sQ)=M(P,s'Q)$ and $M(sQ,sQ)=M(s'Q,s'Q)$ then the modified free-space matrices of $P$ and $sQ$, and $P$ and $s'Q$ agree. Observe that these modified free-space matrices do agree if the following conditions hold
    \begin{compactenum}
        \item $\forall(i,j)\in[n]\times[n]:M(P,sQ)_{i,j}= M(P,s'Q)_{i,j}$,\label{equivScale:item1}
        \item the set of indices %$(j_{1,s},\ldots)$ and $(j_{1,s'},\ldots)$ 
        defining the $\delta$-signature vertices of $sQ$ and $s'Q$ agree,\label{equivScale:item2}
        \item the \ePQ{\pre{P}}{\pre{sQ}} is the \ePQ{\pre{P}}{\pre{s'Q}},\label{equivScale:item3}
        \item the \ePQ{\pre{sQ}}{\pre{P}} is the \ePQ{\pre{s'Q}}{\pre{P}},\label{equivScale:item4}
        \item the \ePQ{\suf{P}}{\suf{sQ}} is the \ePQ{\suf{P}}{\suf{s'Q}}, and
        \item the \ePQ{\suf{Q_t}}{\suf{P}} is the \ePQ{\suf{s'Q}}{\suf{P}}.\label{equivScale:item6}
    \end{compactenum}
    Observe that \Cref{equivScale:item1} holds as $M(P,sQ)=M(P,s'Q)$. Further, by definition of $\mathfrak{S}'$ and \Cref{obs:coarseArragement},
    %definition the extended $\delta$-signature of a time series depends only on inter-point distances of vertices of that time series. Thus, as $M(sQ,sQ)=M(s'Q,s'Q)$, 
    \Cref{equivScale:item2} holds. 
    \Cref{equivScale:item3} holds as by \Cref{lem:wip} the \ePQ{\pre{P}}{\pre{sQ}} only depends on $M(\pre{P},\pre{sQ})$ and hence it agrees with \ePQ{\pre{P}}{\pre{s'Q}} as $M(\pre{P},\pre{sQ})=M(\pre{P},\pre{s'Q})$ as they are submatrices of $M(P,sQ)$ and $M(P,s'Q)$ respectively. Similarly \Cref{equivScale:item4} to \Cref{equivScale:item6} hold implying the claim.
\end{proof}

\begin{observation}\label{obs:arrangement1}
    Let $P$ and $Q$ be two time series. There are at most $\Oh(n^2)$ many values $s$ such that there are values $i\in[n]$ and $j\in[m]$ such that $|P(i)-sQ(j)|=\delta$. These values are precisely the interval boundaries of intervals of the form $\left[\frac{P(i)-\delta}{Q(j)},\frac{P(i)+\delta}{Q(j)}\right]$.
\end{observation}

We assume that for every $s\in\RR$ exactly two values $i\neq j\in[n]$ exist such that ${|P(i)-sQ(j)|=\delta}$. Otherwise the set of intervals $\left[\frac{P(i)-\delta}{Q(j)},\frac{P(i)+\delta}{Q(j)}\right]$ has two intervals that intersect in exactly one point. Let $\{[a_1,b_1],\ldots\}$ be this set of closed intervals. Introducing symbolic perturbation on every interval boundary $a_i$ and $b_i$ results, similarly to the case of translations, in a well-defined ordering of all the interval boundaries. These symbolically perturbed values are such that for any $\hat{s}$ exactly two values $i\neq j\in[n]$ exist such that $|P(i)-\hat{s}Q(j)|=\delta$.  Moreover, for any value $s\in\RR$ with some interval membership in intervals $\{[a_i,b_i],\ldots\}$ there is a symbolically perturbed version of $\hat{s}$ that has the same membership in perturbed versions of the intervals $\{[\hat{a}_i,\hat{b}_i],\ldots\}$.

\begin{corollary}[scaling representatives] \label{cor:CompuScalingArrangement}
    There exists a sorted set $\mathfrak{S}\subset \RR$ containing $\Oh(n^2)$ points and computable in $\Oh(n^2\log n)$ time with the following properties. 

    \begin{itemize}
    \item Every value $s_i$ of \Cref{lemma:orderSignatures} is contained in $\mathfrak{S}$.
        \item It holds that $d_F^S(P,Q)\leq\delta$ if and only if $\exists s\in\mathfrak{S}$ such that $d_F(P,sQ)\leq\delta$. 
    \item For two consecutive $s,s'$ in $\mathfrak{S}$, there exist only $\Oh(1)$ pairs of indices $k, l\in [n]$ such that $|P(k)-sQ(l)|\leq \delta$ and $|P(k)-s'Q(l)|> \delta$ or the other way round. Further, for the set of all pairs of consecutive $s, s'$ in $\mathfrak{S}$, these indices can be computed in $\Oh(n^2\log n)$ time.
    \end{itemize}

\end{corollary}
We call the set $\mathfrak{S}$ of \cref{cor:CompuScalingArrangement} the \emph{scaling representatives}.
\begin{proof}
    \Cref{obs:coarseArragement} and \Cref{obs:arrangement1} imply that there is an arrangement of $\RR$ such that for every neighboring cells of the arrangement such that the following holds. There exists indices $k$ and $l$ such that the arrangement boundary is induced by $|P(k)-sQ(l)|=\delta$ or $sQ(l)$ is not a $\delta$-signature vertex of $s Q$ and $s'Q(l)$ is a $\delta$-signature vertex of $s' Q$ for all $s'>s$.
    %and $s' Q(l)$ not of $s'Q$ or the other way round.
    %exactly one inter-point distance of $P$ and $sQ$ differs or the set of $\delta$-signature indices differs by one index. Namely, there exists  $k$ and $l$ such that the arrangement boundary is induced by $|P(k)-sQ(l)|=\delta$ or $l$ and $l'$ such that the arrangement boundary is induced by $|sQ(l)-sQ(l')|=\delta$. 
    As this arrangement and a point from each interval in the arrangement can be computed in $\Oh(n^2\log n)$ the claim follows by \Cref{lem:pointpointscaleevents}.
\end{proof}

\subsection{Prefix and Suffix under Scaling}\label{sec:PrefScaling}
Similar to \Cref{sec:PrefTranslation}, we show how to keep track of whether a deadlock exists while scaling the time series $Q$ with the values in $\mathfrak{S}$. 


\begin{definition}[scaled preliminary assignment]
    Let $P$ and $Q$ be two time series and let $s\in \RR$. 
    Define the \emph{scaled preliminary assignment} $X_s$ of $P$ and $Q$ to be the preliminary assignment of $\pre{P}$ and $\pre{sQ}$. 
    Let similarly $\Y_s$ be the preliminary assignment of $\pre{sQ}$ and $\pre{P}$. 
    We say that $\X_s(k)$ and $\Y_s(l)$ form a \emph{deadlock}, if $l<{\X_s(k)}$ and $k<{\Y_s(l)}$. 
\end{definition}

Given two time series $P$ and $Q$, we show that we can compute the set $\mathcal{S}\subset\mathfrak{S}$ of scaling factors for which the scaled preliminary assignments $X_s$ and $Y_s$ do not form a deadlock in total time $\Oh(n^2\log n)$.

\begin{observation}
    Let $s, s'$ lie in the same interval of $\mathfrak{S}'$. Then, the extreme point sequences of $\pre{sQ}$ is the same as of $\pre{s'Q}$.
\end{observation}

\begin{observation}
    $\mathcal{S}\subset \{s\in\RR\mid X_s(1) = 1\} = \{s\in\RR\mid Y_s(1) = 1\}$.
\end{observation}

The next observation and the next lemma show that the preliminary assignments of two consecutive scaling representatives that lie in the same interval of $\mathfrak{S'}$ differ only slightly.
\begin{observation}\label{obs:oneStepScal}
    Let two consecutive scalings representatives $s,s'$ %in the scaling arrangement $\mathfrak{S}$ 
    that lie in the same interval of $\mathfrak{S'}$ be given. Then, $X_s$ and $X_{s'}$ (resp. $Y_s$ and $Y_{s'}$) agree everywhere except at the index that participates in the point-point distance inducing the arrangement boundary separating~$s$ and~$s'$.
\end{observation}

\begin{lemma}\label{lem:updateStepScal}
    Let two consecutive scaling representatives $s,s'$ be given that lie in the same interval of $\mathfrak{S'}$. Let $a_1, \dots, a_p$ be an extreme point sequence of $\pre{P}$ and $b_1, \dots, b_q$ of $\pre{sQ}$.
    Let $k$ be the index of $P$ and $l$ be the index of $Q$ participating in the point-point distance inducing the arrangement boundary separating $s$ and $s'$. 
    Then, it holds that
    \begin{compactenum}
        \item $|Y_s(l) - Y_{s'}(l)| \leq 2$,
        \item $Y_s(l) = \infty$ and $Y_{s'}(l) \in \{p-1,p\}$, or
        \item $Y_{s'}(l) = \infty$ and $Y_s(l) \in \{p-1,p\}$.
    \end{compactenum}
    Similarly, it holds that
    \begin{compactenum}
        \item $|X_s(k) - X_{s'}(k)| \leq 2$,
        \item $X_s(k) = \infty$ and $X_{s'}(k) \in \{q-1,q\}$, or
        \item $X_{s'}(k) = \infty$ and $X_s(k) \in \{q-1,q\}$.
    \end{compactenum}
\end{lemma}
\begin{proof}
    We define the following nested family of closed sets \(\mathcal\{{F}_i=\bigcup_{i'\leq i}B(P(a_i),\delta)\mid 1\leq i\leq p\}\cup\{F_\infty=\RR\}\). 
    Let $\mathcal{A}$ be the arrangement of $\RR$ defined by these sets.
    By definition of $P$ and $a_1,\ldots,a_p$, each $F_i$ is a contiguous interval in $\RR$ and for $i\leq j-2$ it holds that $F_i$ and $F_j$ do not share a boundary. % if $F_i$ and $F_j$ differ by two or more levels (in the nested family), then $F_i$ and $F_j$ do not share a boundary. 
    Further, we have that 
    $Y_s(l) = \min\{k' \in [p]\cup\{\infty\}\mid  sQ(b_l)\in F_{k'}\}$.

    If $s$, $s'$ are two consecutive scaling representatives then $sQ(b_l)$ and $s'Q(b_l)$ must lie in neighboring intervals in $\mathcal{A}$ and thus their level in the set family can differ by at most two, implying the claim for $Y_s$ and $Y_{s'}$. The claim for $X_s$ and $X_{s'}$ follows similarly.
\end{proof}

\begin{lemma}\label{lem:PrefixScaling}
    There is an algorithm that correctly computes the subset $\mathcal{S}\subset\mathfrak{S}$ of scalings for which~$X_s$ and~$Y_s$ do not form a deadlock in $\Oh(n^2\log n)$. This is the set of scalings in~$\mathfrak{S}$ for which the preliminary assignments of~$\pre{P}$ and~$\pre{sQ}$ do not form a deadlock. Similarly, we can compute the set of scalings in $\mathfrak{S}$ for which $\suf{P}$ and $\suf{sQ}$ do not form a deadlock in $\Oh(n^2\log n)$ time.
\end{lemma}
\begin{proof}
    We begin by computing the scaling representatives $\mathfrak{S}$ and store it as $\Oh(n^2)$ sorted intervals in $\Oh(n^2\log n)$ time. Next, compute from the contiguous interval $[a,b]=\{s\in\RR\mid X_s(1) = 1\}$ the set $\mathcal{S}'=\mathfrak{S}\cap [a,b]$, in $\Oh(n^2)$ time. Then, $\mathcal{S}'$ consists of $\mathcal{O}(n^2)$ values $s_1<\ldots< s_z$. 

    Let $I\in\mathfrak{S}'$ (the coarse scaling arrangement). Then, for all $s, s'\in I\cap \mathcal{S}'$, the domain of $X_s$ and $Y_s$ does not change.
    We handle each of these interval $I$ separately. Let $k_I$ be the cardinality of $I\cap \mathcal{S}'$.
    We proceed in the same way as in the proof of~\cref{lem:PrefixTranslation}.
    First, define $\mathcal{D}_s=\{k\mid\exists l:\text{$X_s(k)$ and $Y_s(l)$ form a deadlock}\}$.
    Initially, we compute $X_{s}$ and $Y_{s}$ for the smallest value $s\in \mathcal{S}'\cap I$. In addition, we store for every $1\leq k\leq \cpP$, whether $X_{s}(k)$ forms a deadlock with some $Y_{s}(l)$ or not, that is we decide whether $k\in\mathcal{D}_s$. Note that by \Cref{lem:preliminaryAssignmentStructure} (iv), it holds that $k\in \mathcal{D}_s$ if and only if $X_{s}(k)$ and $Y_{s}(X_{s}(k)-1)$ form a deadlock. Hence, this can be computed in $\mathcal{O}(n)$ time for all~$k$. Further, we store the number $d_s = |\mathcal{D}_s|$. Then, $X_{s}$ and $Y_{s}$ do not form a deadlock if and only $d_s=0$.

    Now let the above data be given for some scaling factor $s\in\mathcal{S}'$ and let $s'$ be the next scaling in $\mathcal{S}'\cap I$. Let $k\leq p$ and $l\leq q$ be the two indices that induced the arrangement boundary between $s$ and $s'$. We show how to update above data correctly.
    By \Cref{obs:oneStepScal} and \Cref{lem:updateStepScal}, for any $\hat{k}\in \mathcal{D}_s$ either $\hat{k} = k$ or $|\hat{k}-Y_s(l)|\leq 2$ or $\hat{k}\in \mathcal{D}_{s'}$. In the first two cases, we can check whether $\hat{k}\in\mathcal{D}_{s'}$ in $\Oh(1)$ time by \Cref{lem:preliminaryAssignmentStructure} (iv). Thus we can compute $d_{s'}$ given $d_s$ in time $\mathcal{O}(1)$. 
    Hence, we compute in $\mathcal{O}(n\log n+k_I)$ time the scaling factors $s\in I\cap \mathcal{S}'$ for which $X_s$ and $Y_s$ do not form a deadlock. 
    It holds that $\sum_{I\in \mathcal{S}'}k_I\in \mathcal{O}(n^2)$ as $\mathfrak{S}'$ consists of disjoint intervals.
    As we do this for all intervals in $\mathfrak{S}'$, the total running time is in $\sum_{i\in \mathfrak{S'}}\mathcal{O}(n\log n+k_I)=\mathcal{O}(n^2\log n)$.
    The claim for the suffix follows by~\Cref{obs:ConnectionSufPre}.
\end{proof}

\subsection{Solving the Decision Problem}
We are now ready to prove our result for the decision problem of the Fréchet distance under scaling of time series.

\begin{lemma} \label{lem:fus_decider}
    We can decide the Fréchet distance under scaling between two time series in time $\Oh(n^{8/3} \log^2 n)$.
\end{lemma}
\begin{proof}
% reduction to dynamic grid reachability problem
The goal is to apply \cref{thm:offline_dyn_grid_reachability} to maintain reachability in the modified free-space matrix defined in \cref{def:mod_free_space_matrix} for all scalings $\mathfrak{S}$ from \cref{cor:CompuScalingArrangement}. This set can be computed in $\Oh(n^2 \log n)$ time.
We scale the time series $Q$ with scaling factors in $\mathfrak{S}$ in increasing order. 

In contrast to the translation setting, for scalings, the signature of the scaled time series~$Q$ changes and hence also its prefix and suffix.
In a pre-processing step, we compute the $n$ different scalings where a new vertex is added to the signature of the scaled time series~$Q$ (which then stays in the signature until the end). This can be done in $\Oh(n \log n)$ time by \cref{lemma:orderSignatures}. Maintaining the extreme point sequence of $\pre{Q}, \suf{Q}$ over all scalings therefore also only takes $\Oh(n\log n)$ time.
We invoke \cref{lem:PrefixScaling} to compute the set $\mathcal{S} \subset \mathfrak{S}$ for which there are no deadlocks of the prefixes and suffixes using $\Oh(n^2 \log n)$ time.

The remaining proof is divided into two parts.
First, we argue that the changes to the $\delta$-signature (and therefore also to the prefix and suffix) that occur due to the scaling incur a quadratic number of updates in total to the modified free-space matrix.
Second, we show that all remaining updates (which are similar to the ones in the translation case) amount to $O(n^2)$ in total as well.

First, let us consider the updates that we have to perform on the modified free-space matrix of \cref{def:mod_free_space_matrix} for each type of entry (a) to (f) if the $\delta$-signature changes.
If, due to scaling, a new $\delta$-signature vertex is created, we might have to flip some entries that were previously of type (a); these amount to at most $\Oh(n)$ per new signature vertex, hence $\Oh(n^2)$ in total.
Also, if the vertex $j_2$ (resp. $j_{s_Q-1}$) becomes vertex $j_3$ (resp. $j_{s_Q-2}$) due to a new $\delta$-signature vertex, this potentially introduces some entries of type (b); these again amount to at most $O(n)$ entries per new signature vertex.
Since we recompute the entries of type (d) to (f) for each new scaling, we treat them in the next case.

For the second case, it remains to be shown that if we consider the scalings $\mathfrak{S}$ in order and we already applied the updates due to changes in the $\delta$-signature, then there are only $\Oh(1)$ many remaining updates per scaling to the modified free-space matrix of \cref{def:mod_free_space_matrix}, for each type of entry (a) to (f). Furthermore, we need to determine all of these updates in time $\Oh(n^2 \log n)$.
Combining \cref{cor:CompuScalingArrangement} and the information from the pre-computed signatures, we can pre-compute the $\Oh(1)$ many updates per scaling in $\mathfrak{S}$ of type (a),(b), and (c) in time $\Oh(n^2 \log n)$.
For entries of type (d) and (e), we first check whether the translation at hand incurs a deadlock or not (i.e., we check for containment in the pre-computed set $\mathcal{S}$).
If it does not incur a deadlock, then we use \cref{lem:(i_2j_2)} to determine in constant time whether $d_F(\pre{P}, \pre{Q})\leq \delta$ and $d_F(\suf{P}, \suf{Q})\leq \delta$.
For type (f), we use the pre-computed signatures and \cref{lem:searchprefixend} to compute $\wpre, \vpre, \wsuf, \vsuf$ in $\Oh(\log n)$ time.
Note that in this step we do not need to explicitly compute the scaled prefix and suffix.
By the above, each entry type incurs at most $\Oh(1)$ updates per translation, and we therefore have $\Oh(n^2)$ updates in total.

All of the updates above can be pre-determined, i.e., they are offline. Consequently, we can apply~\Cref{thm:offline_dyn_grid_reachability} and obtain a running time of $\Oh(n^2 \cdot n^{2/3} \log^2 n) = \Oh(n^{8/3} \log^2 n)$.
\end{proof}


\subsection{Solving the Optimization Problem}

Applying parametric search to the scaling variant is very similar to the translation variant. We nevertheless include a proof for completeness.
We again use the variant of Meggido's parametric search~\cite{Megiddo83} due to Cole~\cite{Cole87}, as was also used in~\cite{DBLP:journals/talg/BringmannKN21}.

% Let us again first consider a simple but inefficient variant to solve the optimization problem.
% To that end, we define the set of all scalings that align a pair of vertices within distance $\delta$ (see \cref{obs:arrangement1}):
% \[
% S_\delta = \left\{ \frac{P(i) \pm \delta}{Q(j)} \mid i,j \in\{1, \dotso, n\} \right\}.
% \]
% For the Fréchet distance under scaling $\delta^*$ we have that there exist $s(\,s' \in S_{\delta^*}$ such that $s = s'$.\andre{dumb way to phrase with a set}
% Hence, for each pair $s, s' \in S$ we can test what the corresponding $\delta$ is and use the decider on that value.
% The $s,s'$ with smallest $\delta$ such that the decision query is positive is the Fréchet distance under scaling $\delta^*$.
% The above algorithm has running time $\Oh(|T|^2) = \Oh(n^4)$.
% \andre{What, that's bullshit! The decider running time is not taken into account here.}
%
% Fortunately, we can use parametric search to significantly reduce the running time and only incur an additional logarithmic factor compared to the running time of the decision problem.

For all $i,j \in [n]$, we define the functions $f_{i,j}^+(\delta) \coloneqq \frac{P(i) + \delta}{Q(j)}$ and $f_{i,j}^-(\delta) \coloneqq \frac{P(i) - \delta}{Q(j)}$.
These are the functions that we want to sort in our parametric search.
Let
\[
F = \{f_{i,j}^+(\delta) \mid i,j \in [n]\} \cup \{f_{i,j}^-(\delta) \mid i,j \in [n]\}
\]
be the set of all these functions.
Note that the Fréchet distance under scaling is realized for some $\delta^*$ such that there exist two distinct $f_1,f_2 \in F$ with $f_1(\delta^*) = f_2(\delta^*)$.
To apply parametric search, we need two properties (see Section~3 in~\cite{Cole87}):
\begin{enumerate}
    \item Given any two functions $f_1(\delta), f_2(\delta) \in F$, we can decide whether $f_1(\delta^*) \leq f_2(\delta^*)$ in time $T(n)$.
    \item Given a set of such comparisons, we can order them such that resolving any single comparison will resolve all comparisons before or after in the order. Also, determining the order of two \emph{comparisons} can be done in $\Oh(1)$ time.
\end{enumerate}

Consider the first property and consider $f_{i,j}^+(\delta), f_{k,\ell}^-(\delta)$ with $\frac{P(i)}{Q(j)} < \frac{P(k)}{Q(\ell)}$; all other cases are simple (as the comparison has the same result for all $\delta > 0$) or analogous.
By simple calculations, we obtain that $f_{i,j}^+(\delta) = f_{k,\ell}^-(\delta)$ if and only if
\[
\delta = \delta_{i,j,k,\ell} \coloneqq \frac{P(k)Q(j) - P(i)Q(\ell)}{Q(j) + Q(\ell)},
\]
and $f_{i,j}^+(\delta) < f_{k,\ell}^-(\delta)$ for $\delta < \delta_{i,j,k,\ell}$ and $f_{i,j}^+(\delta) > f_{k,\ell}^-(\delta)$ for $\delta > \delta_{i,j,k,\ell}$.
Hence, using our decider of~\Cref{lem:fus_decider} to evaluate whether $\delta^* \leq \delta_{i,j,k,\ell}$, we can decide in which case we lie and hence decide $f_i^+(\delta^*) \leq f_j^-(\delta^*)$ in $T(n) = \Oh(n^{8/3} \log^2 n)$ time by~\Cref{lem:fus_decider} (without knowing $\delta^*$).

For the second property, consider that any pair of functions has a different threshold value at which the order flips.
Comparing the threshold value for two comparisons takes $\Oh(1)$ time.
If we now order the comparisons according to their threshold values, then deciding one of these comparisons will resolve either all comparisons before or after: if $f_{i,j}^+(\delta^*) \leq f_{k,\ell}^-(\delta^*)$, then this also holds for all comparisons with larger threshold value; if $f_{i,j}^+(\delta^*) > f_{k,\ell}^-(\delta^*)$, then this also holds for all comparisons with smaller threshold value.

Hence, we can apply parametric search as described in~\cite{Cole87} with a running time of $\Oh((|F| + T(n)) \cdot \log n) = \Oh((n^2 + n^{8/3}) \log^3 n) = \Oh(n^{8/3} \log^3 n)$, obtaining the following theorem:

\mainresultscaling*

