\subsection{Syntax: PCoR with transitive closure and complement}\label{section: syntax}
Let $\vsig$ be a set of \intro*\kl{variables}.
We consider \intro*\kl{terms} over the signature
\[\sig \defeq \set{\eps_{(0)}, \emp_{(0)}, \compo_{(2)}, \union_{(2)}, {\bl^{\smile}}_{(1)}, {\bl^{\kstar}}_{(1)}, {\bl^{\compl}}_{(1)}}.\]
We use parentheses in ambiguous situations.
We often abbreviate $\term[1] \compo \term[2]$ to $\term[1] \term[2]$.
For a sequence $\term[1]_1, \dots, \term[1]_n$ of \kl{terms},
we write $\sum_{i = 1}^{n} \term[1]_i$ (or we write $\sum X$ where $X = \set{\term[1]_1, \dots, \term[1]_n}$ as the ordering is not important)
for the \kl{term} $\emp \union \term[1]_1 \union \dots \union \term[1]_n$
and write $\bigcompo_{i = 1}^{n} \term[1]_i$
for the \kl{term} $\eps \compo \term[1]_1 \compo \dots \compo \term[1]_n$.
For $n \in \nat$, we write $\term[1]^{n}$ for the \kl{term} $\bigcompo_{i = 1}^{n} \term[1]$.
For a \kl{term} $\term$ over $\sig$, let $\com{\term}$ be $\term[2]$ if $\term = \term[2]^{-}$ for some $\term[2]$ and be $\term[1]^{-}$ otherwise.
We use the following abbreviations:
\begin{align*}
    %
    \top                   & \defeq \emp^{-},                               &
    %
    \term[1] \cap \term[2] & \defeq (\term[1]^{-} \union \term[2]^{-})^{-}, &
    \term[1]^{+}           & \defeq \term \term[1]^*,                       &
    \term^{\lop}           & \defeq \term \cap \eps,                        &
    \term^{\dom}           & \defeq (\term \top)^{\lop},&
    \term^{\adom}           & \defeq ((\term \top)^{-})^{\lop}.
\end{align*}
Here, $\term^{\lop}$ expresses the \intro*\kl{(graph) loop operator} (strong loop predicate) \cite{daneckiPropositionalDynamicLogic1984},
$\term^{\dom}$ expresses the \intro*\kl{domain operator} \cite{desharnaisKleeneAlgebraDomain2006},
and $\term^{\adom}$ expresses the \intro*\kl{antidomain operator} \cite{desharnaisInternalAxiomsDomain2011}.

For a set $X \subseteq \set{\eps, \emp, \top, \compo, \union, {\bl^{\smile}}, {\bl^{*}}, \cap, {\bl^{\lop}}, \com{\eps}, \com{x}, \bl^{-}, {\bl^{\dom}}, {\bl^{\adom}}}$,
the set of $X$-\kl{terms}, written $\mathcal{T}_{X}$, is defined as the minimal subset of the set of \kl{terms} over $\sig$ satisfying the following:
\begin{gather*}
    \begin{prooftree}
        \hypo{y \in \vsig}
        \infer1{y \in \mathcal{T}_{X}}
    \end{prooftree}
    \quad
    \begin{prooftree}
        \hypo{\eps \in X}
        \infer1{\eps \in \mathcal{T}_{X}}
    \end{prooftree}
    \quad
    \begin{prooftree}
        \hypo{\emp \in X}
        \infer1{\emp \in \mathcal{T}_{X}}
    \end{prooftree}
    \quad
    \begin{prooftree}
        \hypo{\top \in X}
        \infer1{\top \in \mathcal{T}_{X}}
    \end{prooftree}
    \quad
    \begin{prooftree}
        \hypo{\compo \in X}
        \hypo{\term[1] \in \mathcal{T}_{X}}
        \hypo{\term[2] \in \mathcal{T}_{X}}
        \infer3{\term[1] \compo \term[2] \in \mathcal{T}_{X}}
    \end{prooftree}
    \quad
    \begin{prooftree}
        \hypo{\union \in X}
        \hypo{\term[1] \in \mathcal{T}_{X}}
        \hypo{\term[2] \in \mathcal{T}_{X}}
        \infer3{\term[1] \union \term[2] \in \mathcal{T}_{X}}
    \end{prooftree}\\
    \begin{prooftree}
        \hypo{\bl^{\smile} \in X}
        \hypo{\term[1] \in \mathcal{T}_{X}}
        \infer2{\term[1]^{\smile} \in \mathcal{T}_{X}}
    \end{prooftree}
    \quad
    \begin{prooftree}
        \hypo{\bl^{*} \in X}
        \hypo{\term[1] \in \mathcal{T}_{X}}
        \infer2{\term[1]^{\kstar} \in \mathcal{T}_{X}}
    \end{prooftree}
    \quad
    \begin{prooftree}
        \hypo{\cap \in X}
        \hypo{\term[1] \in \mathcal{T}_{X}}
        \hypo{\term[2] \in \mathcal{T}_{X}}
        \infer3{\term[1] \cap \term[2] \in \mathcal{T}_{X}}
    \end{prooftree}
    \quad
    \begin{prooftree}
        \hypo{\bl^{\lop} \in X}
        \hypo{\term[1] \in \mathcal{T}_{X}}
        \infer2{\term[1]^{\lop} \in \mathcal{T}_{X}}
    \end{prooftree}
    \\
    \begin{prooftree}
        \hypo{\com{\eps} \in X}
        \infer1{\com{\eps} \in \mathcal{T}_{X}}
    \end{prooftree}
    \quad
    \begin{prooftree}
        \hypo{\com{x} \in X}
        \hypo{y \in \vsig}
        \infer2{\com{y} \in \mathcal{T}_{X}}
    \end{prooftree}
    \quad
    \begin{prooftree}
        \hypo{\bl^{-} \in X}
        \hypo{\term[1] \in \mathcal{T}_{X}}
        \infer2{\term[1]^{-} \in \mathcal{T}_{X}}
    \end{prooftree}
    \quad
    \begin{prooftree}
        \hypo{\bl^{\dom} \in X}
        \hypo{\term[1] \in \mathcal{T}_{X}}
        \infer2{\term[1]^{\dom} \in \mathcal{T}_{X}}
    \end{prooftree}
    \quad
    \begin{prooftree}
        \hypo{\bl^{\adom} \in X}
        \hypo{\term[1] \in \mathcal{T}_{X}}
        \infer2{\term[1]^{\adom} \in \mathcal{T}_{X}}
    \end{prooftree}
\end{gather*}
(In particular, $\mathcal{T}_{\sig}$ coincides with the set of \kl{terms} over $\sig$.)
Additionally, we let $\mathrm{PCoR} \defeq \mathcal{T}_{\set{\eps, \emp, \top, \compo, \union, \bl^{\smile}}}$,
and let $\mathrm{PCoR}_{X} \defeq \mathcal{T}_{X \cup \set{\eps, \emp, \top, \compo, \union, \bl^{\smile}}}$ for $X \subseteq \set{\bl^{*}, \com{\eps}, \com{x}, \bl^{-}}$.

An \intro*\kl{equation} $\term[1] = \term[2]$ is a pair of \kl{terms}.
An \intro*\kl{inequation} $\term[1] \le \term[2]$ is an abbreviation of the \kl{equation} $\term[1] \union \term[2] = \term[2]$.
The set of \intro*\kl{(quantifier-free) formulas} of a \kl{term} class $\mathcal{T}$ is defined by:
\begin{align*}
    \fml[1], \fml[2] \quad::=\quad \term[1] = \term[2] \mid \fml[1] \land \fml[2] \mid \lnot \fml[1]. \tag{$\term[1], \term[2] \in \mathcal{T}$} 
\end{align*}
We use the following abbreviations, as usual: $\fml[1] \lor \fml[2] \defeq \lnot (\lnot \fml[1] \land \lnot \fml[2])$,
$\fml[1] \to \fml[2] \defeq (\lnot \fml[1]) \lor \fml[2]$, $\fml[1] \leftrightarrow \fml[2] \defeq (\fml[1] \to \fml[2]) \land (\fml[2] \to \fml[1])$, $\mathsf{f} \defeq (\lnot \fml) \land \fml$, and $\mathsf{t} \defeq \lnot \mathsf{f}$.

Additionally, we write $\|\term[1]\|$ for the number of symbols occurring in a \kl{term} $\term[1]$.

\subsection{Semantics: relational models}\label{section: semantics}
An \intro*\kl{$\sig$-algebra} $\alg$ is a tuple $\tuple{\domain{\alg}, \set{f^{\alg}}_{f_{(k)} \in \sig}}$, where $\domain{\alg}$ is a non-empty set and $f^{\alg} \colon \domain{\alg}^{k} \to \domain{\alg}$ is a $k$-ary map for each $f_{(k)} \in \sig$.
A \intro*\kl{valuation} $\val$ of an \kl{$\sig$-algebra} $\alg$ is a map $\val \colon \vsig \to \domain{\alg}$.
For a \kl{valuation} $\val$, we write $\hat{\val} \colon \mathcal{T}_{\sig} \to \domain{\alg}$ for the unique homomorphism extending $\val$.
For a \kl{formula} $\fml$, we define $\hat{\val}(\fml) \in \set{\const{false}, \const{true}}$ as follows:
\begin{align*}
    \hat{\val}(\term[1] = \term[2]) & \hspace{.15em} \defiff\hspace{.15em} (\hat{\val}(\term[1]) = \hat{\val}(\term[2])),&
    \hat{\val}(\fml[1] \land \fml[2]) &\hspace{.15em} \defiff\hspace{.15em}  (\hat{\val}(\fml[1]) \mbox{ and } \hat{\val}(\fml[2])), &
    \hat{\val}(\lnot \fml[1]) &\hspace{.15em} \defiff\hspace{.15em}  (\mbox{not } \hat{\val}(\fml[1])).
\end{align*}
%

For a \kl{formula} $\fml$ and a class of \kl{valuations} (of \kl{$\sig$-algebras}) $\algclass$, we write
\begin{align*}
    \algclass \models \fml & \quad \defiff \quad \hat{\val}(\fml) \mbox{ holds for all \kl{valuations} $\val \in \algclass$}.
\end{align*}
We abbreviate $\set{\val} \models \fml$ to $\val \models \fml$.
We write $\algclass_{\fml}$ for the class $\set{\val \in \algclass \mid \val \models \fml}$.
For a set $\Gamma$ of \kl{formulas}, we write $\algclass_{\Gamma}$ for the class $\bigcap_{\fml \in \Gamma} \algclass_{\fml}$.
%

A \intro*\kl{relational model} $\alg$ over a non-empty set $B$ is an \kl{$\sig$-algebra} such that
$\domain{\alg} = \wp(B^2)$,
$\eps^{\alg} = \triangle_{B}$,
$\emp^{\alg} = \emptyset$,
and for all $\rel[1], \rel[2] \subseteq B^2$,
\begin{flalign*}
               \rel[1] \compo^{\alg} \rel[2] & = \rel[1] \compo \rel[2], &\hspace{-.4em}
               \rel[1] \union^{\alg} \rel[2] & = \rel[1] \cup \rel[2], &\hspace{-.4em}
               \rel[1]^{\kstar^{\alg}}       & = \rel[1]^{\kstar},       &\hspace{-.4em}
               R^{\smile^{\alg}} & = R^{\smile}, &\hspace{-.4em}
               \rel[1]^{\compl^{\alg}}       & = B^2 \setminus \rel[1].
\end{flalign*}
We write $\REL$ $[\REL^{\mathrm{fin}}]$ for the class of all \kl{valuations} of \kl{relational models} [over a finite set].
%
For $\algclass \subseteq \REL$, we write $\algclass^{\mathrm{fin}}$ for the class $\algclass \cap \REL^{\mathrm{fin}}$.
For a class $\algclass \subseteq \REL$ and $X \subseteq \mathcal{T}_{\sig}$,
the \intro*\kl{equational theory} with respect to $\algclass$ is the set
$\set{\term[1] = \term[2]  \in X^2 \mid \algclass \models \term[1] = \term[2]}$.
%
Additionally, for a \kl{valuation} $\val \colon \vsig \to \wp(A^2)$ in $\REL$ and a non-empty subset $B \subseteq A$,
the \intro*\kl{submodel} of $\val$ with respect to $B$ is the \kl{valuation} of $\REL$ defined by:
\begin{align*}
    \val \restriction B \colon \vsig &\to \wp(B^2)\\
                             x &\mapsto \val(x) \cap B^2.
\end{align*}

\subsubsection{Alternative semantics using graphs languages}
For $\mathrm{PCoR}_{\set{\bl^{*}, \com{\eps}, \com{x}}}$, we can use an alternative semantics using \kl{graph homomorphisms} \cite{nakamuraExistentialCalculiRelations2023} (see also e.g., \cite{andrekaEquationalTheoryUnionfree1995,brunetPetriAutomata2017,pousPositiveCalculusRelations2018} for fragments of $\mathrm{PCoR}_{\set{\bl^{*}, \com{\eps}, \com{x}}}$).
Let $\tilde{\vsig} \defeq \set{x, \com{x} \mid x \in \vsig} \cup \set{\com{\eps}}$ and let $\tilde{\vsig}_{\eps} \defeq \tilde{\vsig} \cup \set{\eps}$.
The \intro*\kl{graph language} $\glang(\term)$ of a $\mathrm{PCoR}_{\set{\bl^{*}, \com{\eps}, \com{x}}}$ \kl{term} $\term$ is the set of \kl{graphs} over $\tilde{\vsig}_{\eps}$ defined by:
\begin{align*}
