For a \kl{valuation} $\val \colon \vsig \to \wp(A^2)$ in $\REL$ and $x, y \in A$,
let $\const{G}(\val, x, y)$ be the \kl{graph} $\tuple{A, \set{\hat{\val}(a)}_{a \in \tilde{\vsig}_{\eps}}, x, y}$.
We define $\hat{\val}(\graph[2])$ and $\hat{\val}(\glang)$ as follows:
\begin{align*}
    \hat{\val}(\graph[2]) & \defeq \set{\tuple{x, y} \mid \graph[2] \homo \const{G}(\val, x, y)}, & \hat{\val}(\glang) \defeq \bigcup_{\graph[2] \in \glang} \hat{\val}(\graph[2]).
\end{align*}
We then have the following alternative semantics using \kl{graph languages}.
\begin{prop}[{\cite[Prop.\ 11]{nakamuraExistentialCalculiRelations2023}}]\label{prop: glang}
    Let $\val \in \REL$.
    For $\mathrm{PCoR}_{\set{\bl^{*}, \com{\eps}, \com{x}}}$ \kl{terms} $\term$,
    we have $\hat{\val}(\term) = \hat{\val}(\glang(\term))$.
\end{prop}
Using this characterization, we have the following bounded model property.
\begin{prop}[bounded model property]\label{prop: bounded model property}
    Suppose that $\algclass \subseteq \REL$ is \kl{submodel-closed}.
    Let $\term[1]$ and $\term[2]$ are $\mathrm{PCoR}_{\set{\bl^{*}, \com{\eps}, \com{x}}}$ \kl{terms}
    such that $\algclass \not\models \term[1] \le \term[2]$.
    We then have the following.
    \begin{enumerate}
        \item \label{prop: bounded model property 1} 
        There is some \kl{valuation} $\val \colon \vsig \to \wp(X^2)$ in $\algclass$ of $\#X$ finite such that
        $\hat{\val}(\term[1]) \not\subseteq \hat{\val}(\term[2])$.

        \item \label{prop: bounded model property 2}
        If $\term[1]$ is a $\mathrm{PCoR}_{\set{\com{\eps}, \com{x}}}$ \kl{term},
        then there is some \kl{valuation} $\val \colon \vsig \to \wp(X^2)$ in $\algclass$ of $\#X \le 1 + \|\term[1]\|$ such that
        $\hat{\val}(\term[1]) \not\subseteq \hat{\val}(\term[2])$.
    \end{enumerate}
\end{prop}
\begin{proof}
    For \ref{prop: bounded model property 1}:
    Suppose that $\tuple{x, y} \in \hat{\val}(\term[1]) \setminus \hat{\val}(\term[2])$ for some \kl{valuation} $\val \in \algclass$.
    By \Cref{prop: glang},
    there is some \kl{graph homomorphism} $f$ from some \kl{graph} $\graph[2] \in \glang(\term[1])$ into $\const{G}(\val, x, y)$.
    Let $\val' \defeq \val \restriction f(\graph[2])$.
    We then have $\tuple{x, y} \in \hat{\val}'(\term[1])$ by the same map $f$.
    Also, we have $\tuple{x, y} \not\in \hat{\val}'(\term[2])$ by $\tuple{x, y} \not\in \hat{\val}(\term[2])$ with \Cref{prop: glang}.
    We thus have $\hat{\val}'(\term[1]) \not\subseteq \hat{\val}'(\term[2])$.
    Because the number of \kl{vertices} of $\graph[2]$ is finite, this completes the proof.

    For \ref{prop: bounded model property 2}:
    By easy induction on $\term[1]$, we can show that the number of \kl{vertices} of $\graph[2] \in \glang(\term)$ is bounded by $1 + \|\term[1]\|$.
    Hence, in the same way as above, this completes the proof.
\end{proof}
From \Cref{prop: bounded model property}, we have the following complexity upper bounds (cf.\ \cite[Lemma 22 and Theorem 24]{nakamuraExistentialCalculiRelations2023} for $\REL$).
\begin{prop}\label{prop: upper bound}
    Suppose that $\algclass \subseteq \REL$ is \kl{submodel-closed} and that the membership $\val \in \algclass$ is in $\textsc{P}$.
    We then have the following.
    \begin{enumerate}
        \item \label{prop: upper bound 1}
        The \kl{equational theory} of $\PCoR_{\set{\bl^{*}, \com{\eps}, \com{x}}}$ with respect to $\algclass$ is in $\Pi^{0}_{1}$.
        \item \label{prop: upper bound 2}
        The \kl{equational theory} of $\PCoR_{\set{\com{\eps}, \com{x}}}$ with respect to $\algclass$ is in $\textsc{coNP}$.
        More precisely, the \kl{inclusion problem} $\term[1] \le \term[2]$ with respect to $\algclass$ (i.e., given $\term[1]$ and $\term[2]$, does $\algclass \models \term[1] \le \term[2]$ hold?),
        where $\term$ is a $\PCoR_{\set{\com{\eps}, \com{x}}}$ \kl{term} and $\term[2]$ is a $\PCoR_{\set{\bl^{*}, \com{\eps}, \com{x}}}$, is in $\textsc{coNP}$.
    \end{enumerate}
\end{prop}
\begin{proof}
    For \ref{prop: upper bound 1}:
    By the finite model property (\Cref{prop: bounded model property}.\ref{prop: bounded model property 1}) with that
    the model checking problem of $\PCoR_{\set{\bl^{*}, \com{\eps}, \com{x}}}$ is decidable (in $\textsc{P}$; see, e.g., \cite[Proposition 20]{nakamuraExistentialCalculiRelations2023}).
    By enumerating all finite \kl{valuations} $\val \in \algclass$, we have that the problem in co-recursively enumerable.

    For \ref{prop: upper bound 2}:
    By the linearly bounded model property (\Cref{prop: bounded model property}.\ref{prop: bounded model property 2}) with that
    the model checking problem of $\PCoR_{\set{\com{\eps}, \com{x}}}$ is decidable in $\textsc{P}$.
    By picking a \kl{valuation} $\val$ of size linear to the input size such that $\val \in \algclass$, nondeterministically,
    we have that the problem is in $\textsc{coNP}$.
\end{proof}

\subsection{Deterministic Propositional While Programs with Loop}\label{section: PWP with loop}
We define \kl{propositional while programs with loop} (\kl{$\mathrm{PWP}_{\lop}$ terms}, for short), as a syntactic fragment of $\PCoR_{\set{\bl^{*}}}$ with hypotheses.

Let $\psig$ be a set of \intro*\kl{primitive tests} with a fixpoint free involution $\tilde{\bl} \colon \psig \to \psig$
and let $\asig$ be a set of \intro*\kl{actions}, where $\psig, \asig \subseteq \vsig$ are disjoint.
Let $\mathtt{test}$ be the set of \kl{equations} given by:
\[\mathtt{test} \defeq \set{p \cap \tilde{p} = \emp, p \union \tilde{p} = \eps \mid p \in \psig}.\]
For every $\val \in \REL_{\mathtt{test}}$,
each $p \in \psig$ satisfies $\hat{\val}(p) \subseteq \hat{\val}(\eps)$ and $\hat{\val}(\tilde{p}) = \hat{\val}(\eps) \setminus \hat{\val}(p)$.
Thus $p$ behaves as a \kl{primitive test} and $\tilde{p}$ behaves as its complement, as expected.
%

\subsubsection{Syntax}
The set of \intro*\kl{tests}, written $\mathrm{B}$, is defined as the minimal set of $\PCoR_{\set{\bl^{*}}}$ \kl{terms} satisfying the following:
\begin{gather*}
    \begin{prooftree}
        \hypo{p \in \psig}
        \infer1{p \in \mathrm{B}}
    \end{prooftree}
    \quad
    \begin{prooftree}
        \hypo{\mathstrut}
        \infer1{\eps \in \mathrm{B}}
    \end{prooftree}
    \quad
    \begin{prooftree}
        \hypo{\mathstrut}
        \infer1{\emp \in \mathrm{B}}
    \end{prooftree}
    \quad
    \begin{prooftree}
        \hypo{\bterm[1] \in \mathrm{B}}
        \hypo{\bterm[2] \in \mathrm{B}}
        \infer2{\bterm[1] \compo \bterm[2] \in \mathrm{B}}
    \end{prooftree}
    \quad
    \begin{prooftree}
        \hypo{\bterm[1] \in \mathrm{B}}
        \hypo{\bterm[2] \in \mathrm{B}}
        \infer2{\bterm[1] \union \bterm[2] \in \mathrm{B}}
    \end{prooftree}.
\end{gather*}
For a \kl{test} $b \in \mathrm{B}$, we define the complement $\widetilde{b} \in \mathrm{B}$ as follows:
\begin{gather*}
    \widetilde{p} \defeq \tilde{p}, \quad \widetilde{\eps} \defeq \emp, \quad \widetilde{\emp} \defeq \eps, \quad \widetilde{b \union c} \defeq \widetilde{b} \compo \widetilde{c}, \quad \widetilde{b \compo c} \defeq \widetilde{b} \union \widetilde{c}.
\end{gather*}
Note that $\REL_{\mathtt{test}} \models \widetilde{b} = \eps \cap \com{b}$, thus $\widetilde{b}$ expresses the complement of $\com{b}$ with respect to $\eps$, as expected.
%

For \kl{terms} $\term[1], \term[2]$ and a \kl{test} $b$, we define the following operators for encoding ``$\mathbf{if}$-$\mathbf{then}$'' and ``$\mathbf{while}$''.
\begin{align*}
    \term[1] \union_{b} \term[2] & \quad\defeq\quad b \term[1] \union \widetilde{b} \term[2]  \tag{$\mathbf{if}$ $b$ $\mathbf{then}$ $\term[1]$ $\mathbf{else}$ $\term[2]$} \\
    \term[1]^{*_{b}}           & \quad\defeq\quad (b \term[1])^{*} \widetilde{b}           \tag{$\mathbf{while}$ $b$ $\mathbf{do}$ $\term[1]$}                           \\
    \term[1]^{+_{b}}           & \quad\defeq\quad \term[1] \term[1]^{*_{b}}          \tag{$\mathbf{do}$ $\term[1]$ $\mathbf{while}$ $b$}
\end{align*}
These encoding are well-known in propositional dynamic logic \cite{fischerPropositionalDynamicLogic1979,halpernPropositionalDynamicLogic1983} and Kleene algebra with tests (KAT) \cite{kozenKleeneAlgebraTests1996,smolkaGuardedKleeneAlgebra2019}.
The set of \intro*\kl{$\mathrm{PWP}_{\lop}$ terms} is the minimal subset $\mathrm{W}$ of $\PCoR_{\set{\bl^{*}}}$ satisfying the following:
\begin{gather*}
    \begin{prooftree}[separation = .5em]
        \hypo{b \in \mathrm{B}}
        \infer1{b \in \mathrm{W}}
    \end{prooftree}
    \quad
    \begin{prooftree}[separation = .5em]
        \hypo{x \in \asig}
        \infer1{x \in \mathrm{W}}
    \end{prooftree}
    \quad
    \begin{prooftree}[separation = .5em]
        \hypo{\term[1] \in \mathrm{W}}
        \hypo{\term[2] \in \mathrm{W}}
        \infer2{\term[1] \compo \term[2] \in \mathrm{W}}
    \end{prooftree}
    \quad
    \begin{prooftree}[separation = .5em]
        \hypo{\term[1] \in \mathrm{W}}
        \hypo{\term[2] \in \mathrm{W}}
        \hypo{b \in \mathrm{B}}
        \infer3{\term[1] \union_{b} \term[2] \in \mathrm{W}}
    \end{prooftree}
    \quad
    \begin{prooftree}[separation = .5em]
        \hypo{\term[1] \in \mathrm{W}}
        \hypo{b \in \mathrm{B}}
        \infer2{\term[1]^{*_{b}} \in \mathrm{W}}
    \end{prooftree}
    \quad
    \begin{prooftree}[separation = .5em]
        \hypo{\term[1] \in \mathrm{W}}
        \infer1{\term[1]^{\lop} \in \mathrm{W}}
    \end{prooftree}.
\end{gather*}

Similarly,
the set of \intro*\kl{propositional while programs with intersection} is the minimal subset $\mathrm{W} \subseteq \PCoR_{\set{\bl^{*}}}$ satisfying the rules for \kl{$\mathrm{PWP}_{\lop}$ terms} with
the rule \begin{prooftree}[separation = .5em]
    \hypo{\term[1] \in \mathrm{W}}
    \hypo{\term[2] \in \mathrm{W}}
    \infer2{\term[1] \cap \term[2] \in \mathrm{W}}
\end{prooftree}.
The set of \intro*\kl{propositional while programs with loop and atomic converse} (written, \kl{$\mathrm{PWP}_{\lop \breve{x}}$ terms}) is the minimal subset of $\mathrm{W} \subseteq \PCoR_{\set{\bl^{*}}}$ satisfying the rules for \kl{$\mathrm{PWP}_{\lop}$ terms} with
the rule \begin{prooftree}[separation = .5em]
    \hypo{x \in \asig}
    \infer1{x^{\smile} \in \mathrm{W}}
\end{prooftree}.

The notations above are similar to \cite{smolkaGuardedKleeneAlgebra2019} (where we use $\bl^{*_{b}}$ and $\bl^{+_{b}}$ instead of ``$\bl^{(b)}$''), which are useful in that we can give an over-approximation for \kl{$\mathrm{PWP}_{\lop}$ terms} by eliminating annotations, as follows:
\begin{prop}\label{prop: annotation elimination}
    For all \kl{$\mathrm{PWP}_{\lop}$ terms}, $\term$ and $\term[2]$, we have:
    \begin{align*}
        \REL_{\mathtt{test}} &\models \term[1] \union_{b} \term[2] \le \term[1] \union \term[2],&
        \REL_{\mathtt{test}} &\models \term[1]^{*_{b}} \le \term[1]^{*},&
        \REL_{\mathtt{test}} &\models \term[1]^{+_{b}} \le \term[1]^{+}.
    \end{align*}
\end{prop}

\subsubsection{Semantics: deterministic structures}
In this paper, we mainly consider \kl{$\mathrm{PWP}_{\lop}$ terms} on 
deterministic structures \cite[Section 10.1]{kozenHoareLogicKleene2000}.
For a set $V \subseteq \vsig$,
we write $\mathtt{func}^{V}$ for the set of \kl{equations} given by:
\begin{align*}
    \mathtt{func}^{V} &\defeq \set{a^{\smile} a \le \eps \mid a \in V}.
\end{align*}
Particularly, we let $\mathtt{func} \defeq \mathtt{func}^{\vsig}$.
Note that, for every $\val \in \REL$, we have that
$\val \models a^{\smile} a \le \eps$ iff $\val(a)$ is functional (i.e., for all $x, y, z$, if $\tuple{x, y}, \tuple{x, z} \in \val(a)$, then $y = z$).
We then define
\[\DREL \defeq \REL_{\mathtt{func}}.\]
Namely, $\DREL$ is the class of all \kl{valuations} of \emph{deterministic} \kl{relational models}.

In \Cref{section: while}, we consider \emph{deterministic} \kl{$\mathrm{PWP}_{\lop}$ terms}, namely \kl{$\mathrm{PWP}_{\lop}$ terms} on $\DREL_{\mathtt{test}}$.

\subsection{Domino Problems}
A \intro*\kl{domino system}\footnote{This system is essentially equivalent to the system using Wang tiles \cite[p. 89]{borgerClassicalDecisionProblem1997}.} is a tuple $\mathcal{D} = \tuple{C, H, V}$ where
\begin{itemize}
    \item $C$ is a finite set (of colors/dominoes),
    \item $H \subseteq C^2$ is a binary relation on $C$ (for constraints on pairs of horizontally adjacent colors),
    \item $V \subseteq C^2$ is a binary relation on $C$ (for constraints on pairs of vertically adjacent colors).
\end{itemize}
Given a \kl{domino system} $\mathcal{D} = \tuple{C, H, V}$, for a map $\tau \colon \Z^2 \to C$, we say that
\begin{itemize}
    \item $\tau$ is a \intro*\kl{tiling} if, for all $\tuple{x, y} \in \Z^2$,
    $\tuple{\tau(x, y), \tau(x+1, y)} \in H$ and $\tuple{\tau(x, y), \tau(x, y+1)} \in V$,
    \item for $h, v \ge 1$, $\tau$ is \intro*\kl{$\tuple{h,v}$-periodic} if, for all $\tuple{x, y} \in \Z^2$,
$\tau(x, y) = \tau(x + h, y) = \tau(x , y + v)$,
    \item $\tau$ is \reintro*\kl{periodic} if $\tau$ is \kl{$\tuple{h,v}$-periodic} for some $h, v \ge 1$.
\end{itemize}
