We recall the following undecidability results with respect to \kl{periodic tiling} and \kl{tiling}.
\begin{prop}[{\cite{bergerUndecidabilityDominoProblem1966,gurevichRemarksBergerPaper1972}}; see also {\cite[Theorem 3.1.7]{borgerClassicalDecisionProblem1997}}]
\label{prop: domino tiling undecidable}
    \begin{itemize}
        \item \intro*\kl{The periodic domino problem}---given a \kl{domino system} $\mathcal{D}$,
        does $\mathcal{D}$ have a \kl{periodic tiling}?---is $\mathrm{\Sigma}^{0}_{1}$-complete.
        %

        \item \intro*\kl{The domino problem}---given a \kl{domino system} $\mathcal{D}$,
        does $\mathcal{D}$ have a \kl{tiling}?---is $\mathrm{\Pi}^{0}_{1}$-complete.
    \end{itemize}
\end{prop}
Additionally, we use the following $\mathrm{NP}$-hard problem in \kl{periodic tiling}.
\begin{prop}[a minor change from {\cite[B1]{harelEffectiveTransformationsInfinite1986}\cite[Theorem 7.2.1]{lewisElementsTheoryComputation1997}}]\label{prop: bounded periodic tiling}
    The \intro*\kl{bounded periodic domino problem}---given a \kl{domino system} $\mathcal{D}$ and a unary encoded $n \ge 1$,
    does $\mathcal{D}$ have an \kl[$\tuple{h,v}$-periodic tiling]{$\tuple{n,n}$-periodic tiling}?---is $\mathrm{NP}$-complete.
\end{prop}
\begin{proof}
    From \cite[Theorem 7.2.1]{lewisElementsTheoryComputation1997}, the following problem is $\mathrm{NP}$-complete:
    given a \kl{domino system} $\mathcal{D} = \tuple{C, H, V}$, a unary encoded $n \ge 1$, and $c_0, \dots, c_{n-1} \in C$,
    does $\mathcal{D}$ have a map $\tau \colon \range{0, n-1}^2 \to C$ satisfying the following conditions?
    \begin{itemize}
        \item $\tuple{\tau(x, y),\tau(x+1, y)} \in H$ for $x \in \range{0, n-2}$ and $y \in \range{0,n-1}$,
        \item $\tuple{\tau(x, y),\tau(x, y+1)} \in V$ for $x \in \range{0, n-1}$ and $y \in \range{0,n-2}$,
        \item $\tau(x, 0) = c_x$ for $x \in \range{0, n-1}$.
    \end{itemize}
    Given an input, we define the \kl{domino system} $\mathcal{D}' = \tuple{D, H', V'}$ as follows:
    \begin{align*}
        D &\defeq (C \times \range{0, n-1} \times \range{1, n-1}) \cup \set{\tuple{c_x, x, 0} \mid x \in \range{0, n-1}},\\
        H' &\defeq \set{\tuple{\tuple{c, x, y}, \tuple{c', x', y'}} \in D^2 \mid x' = (x + 1) \bmod n, y' = y, \mbox{ and } (\tuple{c, c'} \in H \mbox{ or } x' = 0)},\\
        V' &\defeq \set{\tuple{\tuple{c, x, y}, \tuple{c', x', y'}} \in D^2 \mid x' = x, y' = (y + 1) \bmod n, \mbox{ and } (\tuple{c, c'} \in V \mbox{ or } y' = 0)}.
    \end{align*}
    We then have that $\mathcal{D}$ has a map satisfying the conditions above
    iff $\mathcal{D}'$ has an \kl[$\tuple{h,v}$-periodic tiling]{$\tuple{n, n}$-periodic tiling}.
    Hence, this completes the proof.
\end{proof}

\subsection{Encoding of periodic grids}\label{subsection: grids}
Let $\aE, \aN, \aW, \aS$ be pairwise distinct \kl{variables}.
Let $\mathtt{grid}$ be the set of the following \kl{hypotheses}:
\begin{align*}
    a b&= \eps & \mbox{ for $\tuple{a,b} \in \set{\tuple{\aE, \aW}, \tuple{\aW, \aE}, \tuple{\aN, \aS}, \tuple{\aS, \aN} }$} \tag{bijective-inverse}\label{equation: bijective} \\
    \aE \aN \aW \aS &\ge \eps \tag{4-cycle} \label{equation: cycle}\\
    (\aE \union \aN \union \aW \union \aS)^* &\ge \top \tag{strongly connected} \label{equation: strongly connected}
\end{align*}
\begin{prop}\label{prop: grid}
    Let $\val \in \REL^{\mathrm{fin}}_{\mathtt{grid}}$.
    Then, for some $h, v \ge 1$,
    the \kl{valuation} $\val$ is isomorphic to a \kl{valuation} $\val_0$ such that
    \begin{itemize}
        \item $\val_0(\aE) = \set{\tuple{\tuple{x \bmod h, y \bmod v}, \tuple{x + 1 \bmod h, y \bmod v}} \mid x \in \range{0, h - 1}, y \in \range{0, v - 1}}$,
        \item $\val_0(\aN) = \set{\tuple{\tuple{x \bmod h, y \bmod v}, \tuple{x \bmod h, y + 1 \bmod v}} \mid x \in \range{0, h - 1}, y \in \range{0, v - 1}}$,
        \item $\val_0(\aW) = \val_0(\aE)^{\smile}$ and $\val_0(\aS) = \val_0(\aN)^{\smile}$.
    \end{itemize}
\end{prop}
\begin{proof}
    Let $\val \colon \vsig \to \wp(X^2)$.
    By (\ref{equation: bijective}), $\val(\aE)$ and $\val(\aN)$ are bijections and $\val(\aW)$ and $\val(\aS)$ are their inverse functions.
    By (\ref{equation: cycle}), we have that $\aE$ and $\aN$ are commutative, as follows:
    \[\val \models \aE \aN  = \aE \aN \aW \aS \aN \aE \ge \aN \aE = \aN \aE \aS \aW \aE \aN = (\aE \aN \aW \aS)^{\smile} \aE \aN \ge \aE \aN.\]
    Let $o \in X$ be any and let $f \colon \nat^2 \to X$ be the unique map such that $f(0, 0) = o$ and $\tuple{o, f(x, y)} \in \hat{\val}(\aE^{x} \aN^{y})$.
    Because $\val(\aE)$ is bijective and $X$ is finite, there is some $h \ge 1$ such that $f(0, 0) = f(h, 0)$
    and $f(x, 0)$ are pairwise distinct for $x\in\range{0, h-1}$.
    Moreover, because $\val(\aN)$ is bijective and $X$ is finite, there is some $v \ge 1$ such that
    $f(0, y) = f(h, y)$ for each $y\in\range{0, v-1}$,
    $f(x, 0) = f(x, v)$ for each $x\in\range{0, h-1}$,
    and $f(x, y)$ are pairwise distinct for $\tuple{x, y} \in \range{0, h-1} \times \range{0, v-1}$.
    Also, by (\ref{equation: strongly connected}),
    we have $\set{f(x, y) \mid x, y \in \nat}
    = \set{z \mid \tuple{o, z} \in \hat{\val}((\aE \union \aN)^*)}
    = \set{z \mid \tuple{o, z} \in \hat{\val}((\aE \union \aN \union \aW \union \aS)^*)}
    = \set{z \mid \tuple{o, z} \in \hat{\val}(\top)} = X$, and thus $f$ is surjective.
    Thus, the restricted map $f \restriction (\range{0, h-1} \times \range{0, v-1})$ is bijective.
    Hence, this completes the proof.
\end{proof}

\paragraph*{Encoding (periodic) tilings}
We consider the following \kl{valuations}.
\begin{defi}[from {\cite{goldblattWellstructuredProgramEquivalence2012}}]\label{defi: valuation of periodic tiling}
    Let $\mathcal{D} = \tuple{C, H, V}$ be a \kl{domino system}.
    For an \kl{$\tuple{h,v}$-periodic tiling} $\tau \colon \Z^2 \to C$,
    let $\val_{\mathcal{D}, \tau} \colon \vsig \to \wp((\range{0, h-1} \times \range{0,v-1})^2)$ be the \kl{valuation} defined by:
    \begin{align*}
        \val_{\mathcal{D}, \tau}(\aE) & \defeq \set{\tuple{\tuple{x \bmod h, y \bmod v}, \tuple{(x+1) \bmod h, y \bmod v}} \mid \tuple{x, y} \in \Z^2},
        \val_{\mathcal{D}, \tau}(\aW) \defeq \val_{\mathcal{D}, \tau}(\aE)^{\smile}, \\
        \val_{\mathcal{D}, \tau}(\aN) & \defeq \set{\tuple{\tuple{x \bmod h, y \bmod v}, \tuple{x \bmod h, (y+1) \bmod v}} \mid \tuple{x, y} \in \Z^2}, 
        \val_{\mathcal{D}, \tau}(\aS) \defeq \val_{\mathcal{D}, \tau}(\aN)^{\smile},\\
        \val_{\mathcal{D}, \tau}(c)   & \defeq \set{\tuple{\tuple{x \bmod h, y \bmod v}, \tuple{x \bmod h, y \bmod v}} \mid \tuple{x, y} \in \Z^2 \mbox{ and } \tau(x, y) = c} \mbox{ for $c \in C$}.
    \end{align*}
