\section{Eliminating Loop Hypothesis under Certain Conditions}\label{section: Hypothesis elimination using graph loops}
We say that a \intro*\kl{loop hypothesis} is an \kl{equation} of the form $\term[3] \ge \eps$.
In this section, we consider eliminating \kl{loop hypotheses}.
Multiple \kl{loop hypotheses} can be into one \kl{loop hypothesis} by the equivalence:
$\REL \models (\term[1]\ge \eps \land \term[2]\ge \eps) \leftrightarrow \term[1]^{\lop} \term[2]^{\lop} \ge \eps$
(also note that $\REL \models \term[3]^{\lop \lop} = \term[3]^{\lop}$).
We consider the following translation.\footnote{A similar translation can be found in \cite{cohenHypothesesKleeneAlgebra1994} for eliminating $x \le \eps$ in general Kleene algebras.}
\begin{defi}\label{defi: loop transformation}
    For $\PCoR_{\set{\bl^{*}, \com{\eps}, \com{x}}}$ \kl{terms} $\term$ and $\term[3]$,
    let $\Tr_{\term[3]}(\term)$ be the $\PCoR_{\set{\bl^{*}, \com{\eps}, \com{x}}}$ \kl{term} defined as follows:
    \begin{align*}
        \Tr_{\term[3]}(x)                       & = \term[3] x \term[3]  \ \mbox{ for $x \in \tilde{\vsig}_{\eps}$}, &
        \Tr_{\term[3]}(\term[1]^{\smile})       & = \Tr_{\term[3]}(\term[1])^{\smile},& 
        \Tr_{\term[3]}(\emp)                   & = \emp,                     \\
        \Tr_{\term[3]}(\term[1] \cap \term[2])  & = \Tr_{\term[3]}(\term[1]) \cap \Tr_{\term[3]}(\term[2]), &
        \Tr_{\term[3]}(\term[1] \union \term[2]) & = \Tr_{\term[3]}(\term[1]) \union \Tr_{\term[3]}(\term[2]),      \\
        \Tr_{\term[3]}(\term[1] \compo \term[2]) & = \Tr_{\term[3]}(\term[1]) \compo \Tr_{\term[3]}(\term[2]), &
        \Tr_{\term[3]}(\term[1]^*)             & = \Tr_{\term[3]}(\term[1])^{*} \term[3].
    \end{align*}
\end{defi}
Below we list some easy facts.
\begin{prop}\label{prop: loop transformation}
    For all $\PCoR_{\set{\bl^{*}, \com{\eps}, \com{x}}}$ \kl{terms} $\term[1]$, $\term[3]$, $\term[3]_1$, $\term[3]_2$, we have:
    \begin{enumerate}
        \item \label{prop: loop transformation monotone} $\REL \models \term[3]_1 \le \term[3]_2 \to \Tr_{\term[3]_1}(\term[1]) \le \Tr_{\term[3]_2}(\term[1])$,
        \item \label{prop: loop transformation id} $\REL \models \Tr_{\eps}(\term[1]) = \term[1]$,
        \item \label{prop: loop transformation sub} $\REL \models \Tr_{\term[3]^{\lop}}(\term[1]) \le \term[1]$,
        \item \label{prop: loop transformation sup} $\REL \models \term[3] \ge \eps \to \term[1] \le \Tr_{\term[3]^{\lop}}(\term[1])$.
    \end{enumerate}
\end{prop}
\begin{proof}
\ref{prop: loop transformation monotone}, \ref{prop: loop transformation id}:
By easy induction on $\term$.
\ref{prop: loop transformation sub}, \ref{prop: loop transformation sup}:
By \ref{prop: loop transformation monotone} and \ref{prop: loop transformation id}.
\end{proof}
We recall the \kl{graph languages} for $\PCoR_{\set{\bl^{*}, \com{\eps}, \com{x}}}$ (\Cref{section: graph languages}).
In this view, the translation $\Tr_{\term[3]^{\lop}}(\term)$ extends each vertex of \kl{graphs} of $\glang(\term[1])$ with some \kl{graph} of $\glang(\term[3]^{\lop})$, as follows.
\begin{defi}\label{defi: loop transformation graph}
    For a \kl{graph} $\graph[2]$ and a map $f$ from $\domain{\graph[2]}$ to \kl{graphs},
    the \kl{(graph) loop extension} of $\graph[2]$ with respect to $f$, written $\graph[2][f]$, is the \kl{graph} $\graph[2]$ in which $f(z)$ is glued to $\graph[2]$ by merging $\src^{f(z)}$, $\tgt^{f(z)}$, and $z$, for each $z \in \domain{\graph[2]}$.
    \Cref{figure: graph loop} gives an illustrative example where edge labels are omitted:
    \begin{figure}[ht]
        %
        \begin{align*}
            \graph[2]    & = \begin{tikzpicture}[baseline = .5ex]
                                 \tikzstyle{mynodeg} = [mynode, fill= gray!20, draw, circle]
                                 \graph[grow right = .8cm, branch down = 2.5ex, nodes={font = \scriptsize}]{
                                 {1/{$1$}[mynodeg]}
                                 -!- {2/{$2$}[mynodeg, yshift = 4ex]}
                                 -!- {3/{$3$}[mynodeg]}
                                 };
                                 \node[left = 4pt of 1](1l){} edge[earrow, ->] (1);
                                 \node[right = 4pt of 3](3l){}; \path (3) edge[earrow, ->] (3l);
                                 \graph[use existing nodes, edges={color=black, pos = .5, earrow}, edge quotes={fill=white, inner sep=1pt,font= \scriptsize}]{
                                     1 -> 2 -> 3; 1 -> 3;
                                 };
                             \end{tikzpicture},                                   &
            \graph[2][f] & = \begin{tikzpicture}[baseline = .5ex]
                                 \tikzstyle{mynodeg} = [mynode, fill= gray!20, draw, circle]
                                 \graph[grow right = .8cm, branch down = 2.5ex, nodes={font = \scriptsize}]{
                                 {1/{$1$}[mynodeg]}
                                 -!- {2/{$2$}[mynodeg, yshift = 4ex]}
