    \label{figure: graph loop}
    \end{figure}
\end{defi}
Let $\glang_{\term[3]}(\term[1]) \defeq \set{\graph[2][f] \mid \mbox{$\graph[2] \in \glang(\term[1]) \ \land\  f \colon \domain{\graph[2]} \to \glang(\term[3]^{\lop})$}}$.
We have the following:
\begin{prop}\label{prop: glang u}
    Let $\val \in \REL$.
    For all $\mathrm{PCoR}_{\set{*, \com{\eps}, \com{x}}}$ \kl{terms} $\term[1]$ and $\term[3]$,
    we have $\hat{\val}(\Tr_{\term[3]^{\lop}}(\term[1])) = \hat{\val}(\glang_{\term[3]}(\term[1]))$.
\end{prop}
\begin{proof}
    By induction on $\term[1]$, in the same way as \Cref{prop: glang} \cite[Proposition 11]{nakamuraExistentialCalculiRelations2023}.
    (See \Cref{section: prop: glang u} for details.)
\end{proof}
Intuitively, the translation $\Tr_{\term[3]^{\lop}}(\term[1])$ encodes the \kl{loop hypothesis} $\term[3] \ge \eps$ ``\emph{partially}''.
Under \emph{certain conditions}, this translation corresponds to add $\term[3] \ge \eps$ exactly,
in that we have the following:
\begin{align*}
    \label{equation: loop HE} \algclass_{\term[3] \ge \eps} \models \term[1] \le \term[2] &\quad\Longleftrightarrow\quad \algclass \models \Tr_{\term[3]^{\lop}}(\term[1]) \le \term[2]. \tag{Loop HE}
\end{align*}
The direction $\Longleftarrow$ alway holds by \Cref{prop: loop transformation}.\ref{prop: loop transformation sup}.
For the direction $\Longrightarrow$, we need some conditions.
Below are counter-examples such that the direction $\Longrightarrow$ fails:
\begin{itemize}
    \item $\REL_{a b \ge \eps} \models \eps \le a a b b$, but $\REL \not\models \Tr_{(a b)^{\lop}}(\eps) \le a a b b$
    by the \kl{relational model}: \begin{tikzpicture}[baseline = -.5ex]
        \tikzstyle{mynodeg} = [mynode, fill= gray!20, draw, circle]
        \graph[grow right = .8cm, branch down = 4.ex, nodes={font = \scriptsize}]{
        {1/{}[mynodeg]} -!- {2/{}[mynodeg]}
        };
        \graph[use existing nodes, edges={color=black, pos = .5, earrow}, edge quotes={fill=white, inner sep=1pt,font= \scriptsize}]{
            1 ->["$a$", bend left] 2 ->["$b$", bend left] 1;
        };
    \end{tikzpicture}.
    \item $\REL_{\top \com{\eps} = \top, a \ge \eps} \models \eps \le \com{\eps} a \com{\eps}$, but $\REL_{\top \com{\eps} = \top} \not\models \Tr_{a^{\lop}}(\eps) \le \com{\eps} a \com{\eps}$ by the \kl{relational model}:
    \begin{tikzpicture}[baseline = -.5ex]
        \tikzstyle{mynodeg} = [mynode, fill= gray!20, draw, circle]
        \graph[grow right = .8cm, branch down = 4.ex, nodes={font = \scriptsize}]{
        {1/{}[mynodeg]} -!- {2/{}[mynodeg]}
        };
        \graph[use existing nodes, edges={color=black, pos = .5, earrow}, edge quotes={fill=white, inner sep=1pt,font= \scriptsize}]{
            1 ->["$a$", out = -150, in = 150, looseness = 15] 1;
        };
    \end{tikzpicture}.
\end{itemize}
Below, we give some sufficient conditions for the equivalence \eqref{equation: loop HE}.

\subsection{Condition 1: When all graph homomorphisms are surjective}\label{subsection: condition 1}
First, we give the following sufficient condition.
\begin{thm}\label{thm: hypothesis elimination using graph loops}
    Let $\algclass \subseteq \REL$.
    Let $\term[1]$, $\term[2]$, $\term[3]$ be $\PCoR_{\set{\bl^{*}, \com{\eps}, \com{x}}}$ \kl{terms}.
    Suppose that, for all $\val \in \algclass$, \kl{vertices} $o, o'$ of $\val$, $\graph[2] \in \glang(\term[1])$, and \kl{graph homomorphisms} $f \colon \graph[2] \homo \const{\graph}(\val, o, o')$ such that $\triangle_{f(\domain{\graph[2]})} \subseteq \hat{\val}(\term[3])$,
    we have that $f$ is \kl{surjective}.
%
    We then have:
    \[\algclass_{\term[3] \ge \eps} \models \term[1] \le \term[2] \quad\Longleftrightarrow\quad \algclass \models \Tr_{\term[3]^{\lop}}(\term[1]) \le \term[2].\]
\end{thm}
\begin{proof}
    ($\Longleftarrow$):
    By \Cref{prop: loop transformation}.\ref{prop: loop transformation sup}.
    ($\Longrightarrow$):
    Let $\tuple{o, o'} \in \hat{\val}(\Tr_{\term[3]^{\lop}}(\term))$ where $\val \in \algclass$ and $o, o'$ are \kl{vertices} of $\val$.
    %
    By \Cref{prop: glang u}, there are a \kl{graph} $\graph[2] \in \glang(\term[1])$ and a \kl{graph homomorphism} $f \colon \graph[2] \homo \const{\graph}(\val, o, o')$ such that $\triangle_{f(\domain{\graph[2]})} \subseteq \hat{\val}(\term[3])$.
    By assumption, $f$ is \emph{\kl{surjective}}, and thus $\val \models \term[3] \ge \eps$.
    By $\val \in \algclass_{\term[3] \ge \eps}$, we have $\val \models \Tr_{\term[3]^{\lop}}(\term) \le \term \le \term[2]$.
\end{proof}
Note that the condition of \Cref{thm: hypothesis elimination using graph loops} is (anti-)monotone with respect to $\term[3]$:
if $\algclass \models \term[3]' \le \term[3]$ and we can apply \Cref{thm: hypothesis elimination using graph loops} for $\term[3]$, then we can apply it also for $\term[3]'$.
It is also (anti-)monotone with respect to $\algclass$: if $\algclass' \subseteq \algclass$ and we can apply \Cref{thm: hypothesis elimination using graph loops} for $\algclass$, then we can apply it also for $\algclass'$.
Moreover, if $\term[1]$ satisfies the condition of \Cref{thm: hypothesis elimination using graph loops}, then, for all $\term[1]'$ such that $\algclass \models \term[1]' \le \term[1]$,
the equivalence of \Cref{thm: hypothesis elimination using graph loops} holds.
%

Below we give some examples of \Cref{thm: hypothesis elimination using graph loops}.
%

\subsubsection{Example 1: On cycles}\label{section: loop hypotheses on cycles}
Let 
\begin{align*}
\algclass_{\mathtt{cyc}} &\defeq \REL_{a^{\smile} a \le \eps, a^* \ge \top},
\quad \tag*{(functionality of $a$, and strongly connected with respect to $a$)}\\
\term[1]_{\mathtt{cyc}} &\defeq (a^{+})^{\lop}. \quad \tag*{(cycles of $a$ edges)}
\end{align*}
We then have the following.
\begin{lem}\label{lem: cycle surjective}
    Let $\val \in \algclass_{\mathtt{cyc}}$,
    let $o$ be a \kl{vertex} in $\val$,
    let $f$ be a \kl{graph homomorphism} from a \kl{graph} $\graph[2] \in \glang(\term[1]_{\mathtt{cyc}})$ to $\const{G}(\val, o, o)$.
    Then, $f$ is \kl{surjective}.
\end{lem}
\begin{proof}
    Let $\val \colon \vsig \to \wp(X^2)$.
    For each $x \in f(\domain{\graph[2]})$, we have 
    $\# (\set{z \mid \tuple{x, z} \in \val(a)}) = 1$ by the functionality of $a$ (for $\le 1$) and the form of $\graph[2]$ (for $\ge 1$).
    From this, there (uniquely) exists a map $g \colon \nat \to X$ such that, for all $x \in \nat$, the following hold:
    \begin{gather*}
        g(0) = o, \qquad \tuple{g(x), g(x+1)} \in \val(a), \qquad g(x) \in f(\domain{\graph[2]}).
    \end{gather*}
    By the functionality of $a$,
    we have $\set{g(x) \mid x \in \nat} = \set{z \mid \tuple{o, z} \in \hat{\val}(a^*)}$.
    By $\val \models a^* \ge \top$, the right-hand side is equal to $X$, and thus $g$ is \kl{surjective}.
    Hence, $f$ is \kl{surjective}.
\end{proof}
Hence, we have obtained the following \kl{hypothesis elimination}, as an example of \Cref{thm: hypothesis elimination using graph loops}.
\begin{ex}\label{ex: cycle surjective}
    By \Cref{thm: hypothesis elimination using graph loops,lem: cycle surjective},
    for all $\algclass \subseteq \algclass_{\mathtt{cyc}}$ and $\PCoR_{\set{\bl^{*}, \com{\eps}, \com{x}}}$ \kl{terms} $\term[1]$, $\term[2]$ and $\term[3]$
    such that $\algclass \models \term[1] \le \term[1]_{\mathtt{cyc}}$,
    we have:
    \[\algclass_{\term[3] \ge \eps} \models \term[1] \le \term[2] \quad\Longleftrightarrow\quad \algclass \models \Tr_{\term[3]^{\lop}}(\term[1]) \le \term[2].\]
\end{ex}

\subsubsection{Example 2: On periodic grids}\label{section: loop hypotheses on grids}
We recall the \kl{hypotheses} $\mathtt{grid}$ in \Cref{subsection: grids}.
Let
\begin{align*}
    \algclass_{\mathtt{gr}} &\defeq \REL_{\aE \aW \le \eps, \aW \aE \le \eps, \aN \aS \le \eps, \aS \aN \le \eps, (\aE \union \aN \union \aW \union \aS)^* \ge \top}    \\
    \term[1]_{\mathtt{gr}} &\defeq (((\aN^{+})^{\lop} \aE)^{+})^{\lop}\\
    \term[3]_{\mathtt{gr}} &\defeq (\aE \aW)^{\lop} (\aW \aE)^{\lop} (\aN \aS)^{\lop} (\aS \aN)^{\lop} (\aE \aN \aW \aS)^{\lop}.
\end{align*}
Note that $(\algclass_{\mathtt{gr}})_{\term[3]_{\mathtt{gr}} \ge \eps} = \REL_{\mathtt{grid}}$ holds.
We then have the condition for \Cref{thm: hypothesis elimination using graph loops}, as follows.
This is the key lemma in \Cref{thm: undecidable while emptiness}.
\begin{lem}\label{lem: grid surjective}
    Let $\val \in \algclass_{\mathtt{gr}}$,
    let $o$ be a \kl{vertex} in $\val$,
    let $f$ be a \kl{graph homomorphism} from a \kl{graph} $\graph[2] \in \glang(\term[1]_{\mathtt{gr}})$ to $\const{G}(\val, o, o)$ such that $\triangle_{f(\domain{\graph[2]})} \subseteq \hat{\val}(\term[3]_{\mathtt{gr}})$.
    Then, $f$ is \kl{surjective}.
\end{lem}
\begin{proof}
    Let $\val \colon \vsig \to \wp(X^2)$.
    \begin{cla}\label{cla: function and converse'}
        Let $\tuple{a, b} \in \set{\tuple{\aE, \aW}, \tuple{\aW, \aE}, \tuple{\aN, \aS}, \tuple{\aS, \aN}}$.
        For all $\tuple{x, y} \in X^2$, if $x \in f(\domain{\graph[2]})$, then we have the following two:
        \begin{description}
            \item[\label{cla: function'}(Function)] $\#(\set{z \mid \tuple{x, z} \in \val(a)}) = 1$,
            \item[\label{cla: converse'}(Converse)] If $\tuple{x, y} \in \val(a)$, then $\tuple{y, x} \in \val(b)$.
        \end{description}
    \end{cla}
    \begin{claproof}
        Case $a = \aE$:
        By $\tuple{x, x} \in \hat{\val}((\aE \aW)^{\lop})$ ($\subseteq \hat{\val}(\term[3]_{\mathtt{gr}})$),
        there is $z$ such that $\tuple{x, z} \in \val(\aE)$ and $\tuple{z, x} \in \val(\aW)$.
        If $\tuple{x, z'} \in \val(\aE)$ for some $z' \neq z$, then by $\tuple{z, z'} \in \hat{\val}(\aW \aE)$,
        it contradicts to $\val \models \aW \aE \le \eps$.
        Thus, we have \textbf{\ref{cla: function'}}.
        \textbf{\ref{cla: converse'}} is immediate from \textbf{\ref{cla: function'}}.
        Case $a = \aN, \aW, \aS$: Similarly.
    \end{claproof}
    By $\tuple{o, o} \in \hat{\val}(\term[1]_{\mathtt{gr}})$ with \textbf{\ref{cla: function'}},
    there is a map $g \colon \nat^2 \to X$ such that, for all $x, y \in \nat$, the following hold:
    \begin{align*}
        g(0, 0) &= o, & \tuple{g(x, 0), g(x+1, 0)} &\in \val(\aE),
        & \tuple{g(x, y), g(x, y+1)} &\in \val(\aN), & g(x, y) &\in f(\domain{\graph[2]}).
    \end{align*}
    Moreover, we have the following.
    \begin{cla}\label{cla: aE'}
        For all $x, y \in \nat$, we have $\tuple{g(x, y), g(x + 1, y)} \in \val(\aE)$.
    \end{cla}
    \begin{claproof}
        By induction on $y$.
        Case $y = 0$:
        Clear.
        Case $y \ge 1$:
        By $\tuple{g(x, y), g(x, y)} \in \hat{\val}((\aE \aN \aW \aS)^{\lop})$ ($\subseteq \hat{\val}(\term[3]_{\mathtt{gr}})$),
        there exist $z$ and $z'$ such that $\tuple{g(x, y), z} \in \hat{\val}(\aE \aN)$, $\tuple{z, z'} \in \hat{\val}(\aW)$, and $\tuple{z', g(x, y)} \in \hat{\val}(\aS)$.
        By $\tuple{g(x, y), g(x + 1, y)} \in \val(\aE)$ (IH),
        $\tuple{g(x + 1, y), g(x + 1, y + 1)} \in \val(\aN)$, and 
        $\tuple{g(x, y + 1), g(x, y)} \in \val(\aS)$ (by \textbf{\ref{cla: converse'}})
        with \textbf{\ref{cla: function'}} with respect to $\aS$, $\aE$, and $\aN$,
        we have that $z = g(x + 1, y + 1)$ and $z' = g(x, y + 1)$.
        Thus, $\tuple{g(x + 1, y + 1), g(x, y + 1)} \in \val(\aW)$.
        Hence, $\tuple{g(x, y + 1), g(x + 1, y + 1)} \in \val(\aE)$ (by \textbf{\ref{cla: converse'}}).
    \end{claproof}
    By \textbf{\ref{cla: function'}} with respect to  $\aE$ and $\aN$,
    we have $\set{g(x, y) \mid x, y \in \nat}
    = \set{z \mid \tuple{o, z} \in \hat{\val}((\aE \union \aN)^*)}
    = \set{z \mid \tuple{o, z} \in \hat{\val}((\aE \union \aN \union \aW \union \aS)^*)}$.
    By $\val \models (\aE \union \aN \union \aW \union \aS)^* \ge \top$, the right-hand side is equal to $X$,
    and thus $g$ is \kl{surjective}.
    Hence, $f$ is \kl{surjective}.
\end{proof}

\begin{ex}\label{ex: grid surjective}
    By \Cref{thm: hypothesis elimination using graph loops,lem: grid surjective},
    for all $\algclass \subseteq \algclass_{\mathtt{gr}}$ and $\PCoR_{\set{\bl^{*}, \com{\eps}, \com{x}}}$ \kl{terms} $\term[1]$, $\term[2]$, and $\term[3]$ such that
    $\algclass \models \term[1] \le \term[1]_{\mathtt{gr}}$ and
    $\algclass \models \term[3] \le \term[3]_{\mathtt{gr}}$,
    we have:
    \[\algclass_{\term[3] \ge \eps} \models \term[1] \le \term[2] \quad\Longleftrightarrow\quad \algclass \models \Tr_{\term[3]^{\lop}}(\term[1]) \le \term[2].\]
\end{ex}

\subsection{Condition 2: Taking submodels for surjectivity}\label{subsection: condition 2}
Additionally, we give another sufficient condition for eliminating \kl{loop hypotheses},
by taking \kl{submodels} for obtaining a \kl{surjective} map.
\begin{thm}\label{thm: hypothesis elimination using graph loops 2}
    Let $\algclass \subseteq \REL$ and let $\term[1]$, $\term[2]$, and $\term[3]$ be $\PCoR_{\set{\bl^{*}, \com{\eps}, \com{x}}}$ \kl{terms}.
    When $\algclass$ is \kl{submodel-closed} and $\algclass \models \term[3]^{\lop} \le \Tr_{\term[3]^{\lop}}(\term[3]^{\lop})$, 
    we have:
    \[\algclass_{\term[3] \ge \eps} \models \term[1] \le \term[2] \quad\Longleftrightarrow\quad \algclass \models \Tr_{\term[3]^{\lop}}(\term[1]) \le \term[2].\]
\end{thm}
\begin{proof}
    ($\Longleftarrow$):
    By \Cref{prop: loop transformation}.\ref{prop: loop transformation sup}.
    ($\Longrightarrow$):
    Let $\val \colon \vsig \to \wp(A^2)$ in $\algclass$.
    Suppose $\tuple{x, y} \in \hat{\val}(\Tr_{\term[3]^{\lop}}(\term[1]))$.
    We inductively define $B_n \subseteq A$ (where $n \ge 0$) as follows:
    \begin{itemize}
        \item Case $n = 0$:
        Let $\graph[2] \in \glang(\term[1])$ be a \kl{graph} such that
        there is a \kl{graph homomorphism} $h \colon \graph[2] \homo \const{\graph}(\val, x, y)$
        such that $\Delta_{h(\domain{\graph[2]})} \subseteq \hat{\val}(\term[3]^{\lop})$.
        Such an $\graph[2]$ exists by \Cref{prop: glang u}.
        We then let $B_0 \defeq h(\graph[2])$.
        \item Case $n + 1$:
        For each $z \in B_n$, by $\tuple{z, z} \in \hat{\val}(\term[3]^{\lop})$, we have $\tuple{z, z} \in \hat{\val}(\Tr_{\term[3]^{\lop}}(\term[3]^{\lop}))$.
        Let $\graph[3]_{z} \in \glang(\term[3])$ be a \kl{graph} such that
        there is a \kl{graph homomorphism} $h_z \colon \graph[3]_{z} \homo \const{\graph}(\val, z, z)$
        satisfying $\Delta_{h_z(\domain{\graph[3]_{z}})} \subseteq \hat{\val}(\term[3]^{\lop})$.
        Such $\graph[3]_{z}$ exists by \Cref{prop: glang u}.
        We then let $B_{n+1} \defeq \bigcup_{z \in B_{n}} h_{z}(\graph[3]_{z})$.
    \end{itemize}
    Finally, let $B \defeq \bigcup_{n \ge 0} B_n$.
    We then have:
    \begin{itemize}
        \item $\val \restriction B \models \term[3] \ge \eps$ (by the construction of $B$),
        and hence $\val \restriction B \in \algclass_{\term[3] \ge \eps}$ (as $\algclass$ is \kl{submodel-closed}),
        \item $\tuple{x, y} \in \widehat{\val \restriction B}(\term[1])$ (by the construction of $B_0$).
    \end{itemize}
    Thus, by the assumption with the \kl{graph homomorphism} from \Cref{prop: glang}, we have $\tuple{x, y} \in \hat{\val}(\term[2])$.
    Hence, this completes the proof.
\end{proof}
Below we give some examples of \Cref{thm: hypothesis elimination using graph loops 2}.
\begin{ex}\label{ex: size 1}
    Suppose that,
    for all $\val \in \algclass$,
    \kl{vertices} $o$ of $\val$,
    \kl{graphs} $\graph[2] \in \glang(\term[3]^{\lop})$,
    and \kl{graph homomorphisms} $f \colon \graph[2] \homo \const{\graph}(\val, o, o)$,
    the map $f$ maps to the same \kl{vertex} (i.e., $\# f(\domain{\graph[2]}) = 1$).
    Then, we have $\algclass \models \term[3]^{\lop} \le \Tr_{\term[3]^{\lop}}(\term[3]^{\lop})$
    and $\algclass \models \term[3] = \term[3]^{\lop}$ by the map $f$.
    Thus, when $\algclass \subseteq \REL$ is \kl{submodel-closed}, 
    we have:
    \[\algclass_{\term[3] \ge \eps} \models \term[1] \le \term[2] \quad\Longleftrightarrow\quad \algclass \models \Tr_{\term[3]^{\lop}}(\term[1]) \le \term[2].\]
    (Particularly,
    when $\algclass \models \term[3]^{\lop} = \term[3]$,
    the above is equivalent to $\algclass \models \Tr_{\term[3]}(\term[1]) \le \term[2]$
    (\Cref{prop: loop transformation}.\ref{prop: loop transformation monotone}).)
\end{ex}

\begin{ex}\label{ex: tests}
    We recall the set $\psig$ and $\mathtt{test}$ in \Cref{section: PWP with loop}.
    Using \Cref{ex: size 1}, we can give another hypothesis elimination for the hypotheses $\mathtt{test}$.
    Suppose that $\psig = \set{p_0, \dots, p_{2n-1}}$ and $\tilde{\bl}$ satisfies $\tilde{p}_i = p_{(n+i) \bmod 2n}$.
    Let us consider the following hypotheses (the set is similar to \cite[Section 4.2]{pousToolsCompletenessKleene2024}):
    \begin{align*}
        \mathtt{test}'_0 &\defeq \set{ p \tilde{p} \le \emp \mid p \in \psig},\\
        \mathtt{test}'_1 &\defeq \set{p \le \eps \mid p \in \psig},\\
        \mathtt{test}'_2 &\defeq \set{p \union \tilde{p} \ge \eps \mid p \in \psig}.
    \end{align*}
    Also, let $\mathtt{test}'_{S} \defeq \bigcup_{j \in S} \mathtt{test}'_{j}$ for $S \subseteq \set{0, 1, 2}$ and let $\mathtt{test}' \defeq \mathtt{test}'_{\set{0, 1, 2}}$ (clearly, $\REL_{\mathtt{test}'} = \REL_{\mathtt{test}}$ holds).
    Let $\term[3]_0 \defeq \top (\sum_{i = 0}^{n-1} p_i \tilde{p}_i) \top$.
    By combining hypotheses eliminations, we can eliminate all the hypotheses as follows: 
    \begin{align*}
        &\REL_{\mathtt{test}'} \models \term[1] \le \term[2] \Leftrightarrow \REL_{\mathtt{test}'_{\set{0, 1, 2}}} \models \term[1] \le \term[2] \\
        &\Leftrightarrow \REL_{\mathtt{test}'_{\set{1, 2}}} \models \term[1] \le \term[2] \union \term[3]_0 \tag{\Cref{prop: Hoare hypotheses}} \\
        &\Leftrightarrow \REL_{\mathtt{test}'_{\set{1}}} \models \Tr_{\bigcompo_{i = 0}^{n-1} p_i \union \tilde{p}_i}(\term[1]) \le \term[2] \union  \term[3]_0 \tag{\Cref{ex: size 1}}                                                      \\
        &\Leftrightarrow \REL \models
        \Tr_{\bigcompo_{i = 0}^{n-1} p_i \union \tilde{p}_i}(\term[1]) [p_0^{\lop}/p_0] \dots [p_{2n-1}^{\lop}/p_{2n-1}] \le \term[2] \union \term[3]_0. \tag*{(\Cref{ex: substitution id by loop})}
    \end{align*}
    Thus, we can encode \kl{tests} in $\PCoR_{\set{\bl^{*}}}$.
    Hence, we can reduce the \kl{equational theory} of $\PCoR_{\set{\bl^{*}}}$ with \kl{tests} to the \kl{equational theory} of $\PCoR_{\set{\bl^{*}}}$ (without \kl{tests}), via \kl{hypothesis eliminations} (cf.\ \cite{nakamuraDerivativesGraphsPositive2024} for encoding of tests in automata constructions).
    Additionally, we can replace $\bl^{\lop}$ with $\bl^{\dom}$ by using \Cref{ex: substitution id by dom} in the reduction above.
\end{ex}

