\begin{ex}[a generalization of \Cref{ex: size 1}]\label{ex: symmetric graph}
    Let $\term[3]$ be a $\PCoR_{\set{\bl^{*}, \com{\eps}, \com{x}}}$ \kl{term} such that $\glang(\term[3]^{\lop})$ is closed under changing the source/target vertex.
    We then have $\REL \models \term[3]^{\lop} \le \Tr_{\term[3]^{\lop}}(\term[3]^{\lop})$.
    (Proof: Suppose $\tuple{x, x} \in \hat{\val}(\term[3]^{\lop})$.
    Let $h$ be a \kl{graph homomorphism} from a \kl{graph} $\graph[2] \in \glang(\term[3]^{\lop})$ to $\const{\graph}(\val, x, x)$.
    For each $z \in h(\domain{\graph[2]})$,
    by letting $\graph[3]_{z}$ be the \kl{graph} $\graph[2]$ in which the source/target vertex has been changed to a vertex $v$ such that $h(v) = z$,
    there exists a \kl{graph homomorphism} $h_z$ from $\graph[3]_{z}$ to $\const{\graph}(\val, z, z)$.
    By $\graph[3]_{z} \in \glang(\term[3]^{\lop})$, we have $\tuple{x, x} \in \hat{\val}(\Tr_{\term[3]^{\lop}}(\term[3]^{\lop}))$ (\Cref{prop: glang u}).)
    Thus by \Cref{thm: hypothesis elimination using graph loops 2},
    when $\algclass \subseteq \REL$ is \kl{submodel-closed},
    we have:
    \[\algclass_{\term[3] \ge \eps} \models \term[1] \le \term[2] \quad\Longleftrightarrow\quad \algclass \models \Tr_{\term[3]^{\lop}}(\term[1]) \le \term[2].\]
    This is a generalization of \Cref{ex: size 1}.
    For instance, $\term[3] = aa$, $aaa$, $a^{+}$, and $(a \union b)^{+}$ newly satisfies the condition.
\end{ex}

\subsection{Eliminating loop hypothesis in propositional while programs}\label{section: hypothesis elimination loop while}
Similar to $\Tr$ (\Cref{defi: loop transformation}), we define the translation $\Tr'$ on \kl{$\mathrm{PWP}_{\lop}$ terms}, as follows:
\begin{defi}\label{defi: loop transformation GKAT}
    For \kl{$\mathrm{PWP}_{\lop}$ terms} $\term$ and $\term[3]$,
    let $\Tr'_{\term[3]}(\term)$ be the \kl{$\mathrm{PWP}_{\lop}$ term} defined by:
    \begin{align*}
        \Tr'_{\term[3]}(x)                       & \defeq \term[3] x \term[3]  \ \mbox{ for $x \in B \cup \asig$},  &
        \Tr'_{\term[3]}(\term[1] \union_{b} \term[2]) & \defeq \Tr'_{\term[3]}(\term[1]) \union_{b} \Tr'_{\term[3]}(\term[2]),  \\
        \Tr'_{\term[3]}(\term[1] \compo \term[2]) & \defeq \Tr'_{\term[3]}(\term[1]) \compo \Tr'_{\term[3]}(\term[2]),   &     
        \Tr'_{\term[3]}(\term[1]^{*_{b}})             & \defeq \Tr'_{\term[3]}(\term[1])^{*_{b}}, &
        \Tr'_{\term[3]}(\term[1]^{\lop})             & \defeq \Tr'_{\term[3]}(\term[1])^{\lop}.
    \end{align*}
\end{defi}
\begin{prop}\label{prop: loop transformation GKAT}
    For all \kl{$\mathrm{PWP}_{\lop}$ terms} $\term[1]$ and $\term[3]$,
    we have $\REL_{\mathtt{test}} \models \Tr'_{\term[3]^{\lop}}(\term) = \Tr_{\term[3]^{\lop}}(\term)$.
\end{prop}
\begin{proof}
    By easy induction on $\term[1]$.
\end{proof}
Hence, we can use the hypotheses eliminations given in \Cref{subsection: condition 1,subsection: condition 2} also inside \kl{$\mathrm{PWP}_{\lop}$ terms}.
