\section{Undecidability of Deterministic Propositional While Programs with Loop}\label{section: while}
%
The \intro*\kl{emptiness problem} of deterministic \kl{$\mathrm{PWP}_{\lop}$ terms} is the following problem:
given a \kl{$\mathrm{PWP}_{\lop}$ terms} $\term$, does $\DREL_{\mathtt{test}} \models \term \le \emp$?
In this section, we prove that this problem is $\mathrm{\Pi}^{0}_{1}$-hard (\Cref{thm: undecidable while emptiness}).

\subsection{Encoding periodic tilings using loop hypotheses}
Let $\aE, \aN, \aW, \aS \in \asig$.
Let $\mathcal{D} = \tuple{C, H, V}$ be a \kl{domino system} where $C \subseteq \psig$.
Let $C = \set{c_1, \dots, c_n}$ where $c_1, \dots, c_n$ are pairwise distinct.
Let $\Gamma_{\mathcal{D}}$ be the set of the following \kl{equations} in \Cref{figure: hypotheses GKAT}.
\begin{figure*}[ht]
    \begin{align*}
        \label{equation: serial-converse'} a b &\ge \eps  &&          \mbox{for $\tuple{a, b} \in \set{\tuple{\aE, \aW}, \tuple{\aW, \aE}, \tuple{\aN, \aS}, \tuple{\aS, \aN}}$} \span \tag{2-cycle}  \\
        \label{equation: cycle'} \aE \aN \aW \aS &\ge \eps  \span \tag{4-cycle}                                                                                                                      \\
        \label{equation: connected} (\aE \union \aN \union \aW \union \aS)^* &\ge \top \tag{strongly connected}\\
        \label{equation: color'} \term[3]_{c_1} \union_{c_1} (\term[3]_{c_2} \union_{c_2} \dots (\term[3]_{c_n} \union_{c_n} \emp) \dots) &\ge \eps     \tag{col$\ge$1 $+$ HV-con}\\
        \label{equation: color' le} \tilde{c}_i \union \tilde{c}_j &\ge \eps  && \mbox{for distinct $i, j \in \range{1, n}$}    \tag{col$\le$1}
    \end{align*}
    Here, $\term[3]_{c} \defeq (\aE (\sum H_c) \aW)(\aN (\sum V_c) \aS)$ for $c \in C$,
    where
    $H_c \defeq \set{d \mid \tuple{c, d} \in H}$ and
    $V_c \defeq \set{d \mid \tuple{c, d} \in V}$.
    \caption{The \kl{equation} set $\Gamma_{\mathcal{D}}$, where $\mathcal{D}$ is a \kl{domino system} $\tuple{C, H, V}$.}
    \label{figure: hypotheses GKAT}
\end{figure*}

In the following, we consider the class $\DREL_{\mathtt{test}, \Gamma_{\mathcal{D}}}^{\mathrm{fin}}$.
Note that $\DREL_{\mathtt{test}, \Gamma_{\mathcal{D}}}^{\mathrm{fin}} \subseteq \REL^{\mathrm{fin}}_{\Gamma_{\mathtt{grid}}}$ (recall \Cref{subsection: grids}) holds, because $\DREL_{ab \ge \eps} \models ab \le \eps$ holds by $\mathtt{func}$ as follows:
\begin{align*}
    \DREL_{ab \ge \eps} \models a b \le (a b)^{\smile} a b = b^{\smile} a^{\smile} a b \le \eps.
\end{align*}
Let $p, q \in \psig$ be \kl{fresh} \kl{primitive tests} (disjoint from $C$) and let 
\[\term[1]_{\mathtt{gr}}' \;\defeq\; (p ((q \aN^{+_{\tilde{q}}})^{\lop} \aE)^{+_{\tilde{p}}})^{\lop}.\]
We then have the following.
\begin{lem}\label{lem: connectivity'}
    Let $\mathcal{D}$ be a \kl{domino system}.
    We then have:
    \[\mbox{$\mathcal{D}$ has a \kl{periodic tiling}} \quad\iff\quad \mbox{$\DREL_{\mathtt{test}, \Gamma_{\mathcal{D}}}^{\mathrm{fin}} \not\models \term[1]_{\mathtt{gr}}' \le \emp$}.\]
\end{lem}
\begin{proof}
    ($\Leftarrow$)
    Clearly, $\DREL_{\mathtt{test}, \Gamma_{\mathcal{D}}}^{\mathrm{fin}} \neq \emptyset$.
    Let $\mathcal{D} = \tuple{C, H, V}$ and let $C = \set{c_1, \dots, c_n}$ where $c_1, \dots, c_n$ are pairwise distinct.
    Let $\val \in \DREL_{\mathtt{test}, \Gamma_{\mathcal{D}}}^{\mathrm{fin}}$.
    By $\val \in \REL^{\mathrm{fin}}_{\mathtt{grid}}$,
    up to isomorphisms, without loss of generality,
    we can assume that $\val$ and $h, v \ge 1$ are the ones obtained by \Cref{prop: grid}.
    Let $\tau \colon \Z^2 \to C$ be the unique map such that $\tuple{\tuple{x \bmod h, y \bmod v}, \tuple{x \bmod h, y \bmod v}} \in \val(\tau(x, y))$, by (\ref{equation: color'})(\ref{equation: color' le}).
    By (\ref{equation: color'}), we have $\tuple{\tau(x, y), \tau(x + 1, y)} \in H$ and $\tuple{\tau(x, y), \tau(x, y + 1)} \in V$.
    Hence, $\tau$ is a \kl{tiling}.
    Also, $\tau$ is \kl{periodic} by $h$ and $v$.

    ($\Rightarrow$):
    Let $\tau$ be an \kl{$\tuple{h,v}$-periodic tiling}.
    By the form of $\val_{\mathcal{D}, \tau}$ (recall \Cref{defi: valuation of periodic tiling}), we have $\val_{\mathcal{D}, \tau} \in \DREL_{\mathtt{test}, \Gamma_{\mathcal{D}}}^{\mathrm{fin}}$ by a routine verification.
    Let \[\val'(a) \defeq \begin{cases}
            \triangle_{\set{\tuple{0, 0}}} & (a = p)    \\
            \triangle_{\set{\tuple{x, 0} \mid x \in \range{0, h - 1}}} & (a = q)    \\
            \hat{\val}_{\mathcal{D}, \tau}(\eps) \setminus \triangle_{\set{\tuple{0, 0}}} & (a = \tilde{p})    \\
            \hat{\val}_{\mathcal{D}, \tau}(\eps) \setminus \triangle_{\set{\tuple{x, 0} \mid x \in \range{0, h - 1}}} & (a = \tilde{q})    \\
            \val_{\mathcal{D}, \tau}(a)                                                              & (\mbox{otherwise}).
        \end{cases}\]
    Since $p$ and $q$ are \kl{fresh}, we have $\val' \in \DREL_{\mathtt{test}, \Gamma_{\mathcal{D}}}^{\mathrm{fin}}$.
    Also, we have $\tuple{\tuple{0, 0}, \tuple{0, 0}} \in \hat{\val}'((p \aE^{+_{\tilde{p}}})^{\lop})$ by traversing vertices of $\tuple{x, 0}$ as $x = 0, 1, \dots, h - 1, 0$.
    Similarly, for each $x$, we have 
    $\tuple{\tuple{x, 0}, \tuple{x, 0}} \in \hat{\val}'((q \aN^{+_{\tilde{q}}})^{\lop})$ by traversing vertices of $\tuple{x, y}$ as $y = 0, 1, \dots, v - 1, 0$.
    Thus, we have $\tuple{\tuple{0, 0}, \tuple{0, 0}} \in \hat{\val}'((p ((q \aN^{+_{\tilde{q}}})^{\lop} \aE)^{+_{\tilde{p}}})^{\lop}) = \hat{\val}'(\term[1]_{\mathtt{gr}}')$.
    Hence, $\val' \not\models \term[1]_{\mathtt{gr}}' \le \emp$.
    %
\end{proof}

\subsection{Eliminating loop hypotheses}
