\begin{thm}\label{thm: undecidable while emptiness}
    The \kl{emptiness problem} of \kl{$\mathrm{PWP}_{\lop}$ terms} on $\DREL_{\mathtt{test}}$ (and also on $\DREL_{\mathtt{test}}^{\mathrm{fin}}$) is $\mathrm{\Pi}^{0}_{1}$-complete.
\end{thm}
\begin{proof}
    (In $\mathrm{\Pi}^{0}_{1}$):
    By \Cref{prop: upper bound} with that $\DREL_{\mathtt{test}}$ is \kl{submodel-closed}.
    (Hardness):
    We have:
    \begin{align*}
         & \mbox{$\mathcal{D}$ does not have a \kl{periodic tiling}}                                                                 \\
         & \Leftrightarrow\quad \DREL^{\mathrm{fin}}_{\mathtt{test}, (\aE \union \aN \union \aW \union \aS)^* \ge \top, \term[3]_{\mathcal{D}} \ge \eps} \models \term[1]_{\mathtt{gr}}' \le \emp \tag{\Cref{lem: connectivity'}}                                                                                 \\
         & \Leftrightarrow\quad \DREL^{\mathrm{fin}}_{\mathtt{test}, (\aE \union \aN \union \aW \union \aS)^* \ge \top} \models \Tr'_{\term[3]_{\mathcal{D}}}(\term[1]_{\mathtt{gr}}') \le \emp   \tag{\Cref{ex: grid surjective} ($\bigstar_1$) with \Cref{prop: loop transformation GKAT}}                                                                                           \\
         & \Leftrightarrow\quad \DREL_{\mathtt{test}} \models \Tr'_{\term[3]_{\mathcal{D}}}(\term[1]_{\mathtt{gr}}') \le \emp.   \tag{\Cref{ex: surjective} ($\bigstar_2$)}
    \end{align*}
    For ($\bigstar_1$),
    by
    $\DREL^{\mathrm{fin}}_{\mathtt{test}, (\aE \union \aN \union \aW \union \aS)^* \ge \top} \subseteq \algclass_{\mathtt{gr}}$,
    $\DREL_{\mathtt{test}} \models \term[1]_{\mathtt{gr}}' \le \term[1]_{\mathtt{gr}}$, and
    $\DREL_{\mathtt{test}} \models \term[3]_{\mathcal{D}} \le \term[3]_{\mathtt{gr}}$, we can apply \Cref{ex: grid surjective}.
    For ($\bigstar_2$),
    we have $\mathsf{Sur}_{\glang_{\term[3]_{\mathcal{D}}}(\term[1]_{\mathtt{gr}}')}(\DREL_{\mathtt{test}})
    \subseteq \DREL^{\mathrm{fin}}_{\mathtt{test}, (\aE \union \aN \union \aW \union \aS)^* \ge \top}$,
    because each \kl{graph} of $\mathsf{Sur}_{\glang_{\term[3]_{\mathcal{D}}}(\term[1]_{\mathtt{gr}}')}(\DREL_{\mathtt{test}})$ is connected with respect to $\aE$, $\aN$, $\aW$, and $\aS$ (see also \Cref{figure: graphs}).
    Thus, we can apply \Cref{ex: surjective}.
    Hence, we can reduce from the complement of \kl{the periodic domino problem}, which is $\mathrm{\Pi}^{0}_{1}$-hard (\Cref{prop: domino tiling undecidable}).
    Additionally, $\DREL_{\mathtt{test}} \models \term[3]_{\mathcal{D}} \le \term[3]_{\mathtt{gr}}$
    iff $\DREL_{\mathtt{test}}^{\mathrm{fin}} \models \term[3]_{\mathcal{D}} \le \term[3]_{\mathtt{gr}}$, because $\mathsf{Sur}_{\glang_{\term[3]_{\mathcal{D}}}(\term[1]_{\mathtt{gr}}')}(\DREL_{\mathtt{test}})
    \subseteq \DREL^{\mathrm{fin}}_{\mathtt{test}} \subseteq \DREL_{\mathtt{test}}$.
\end{proof}

\subsection{Comparison to the undecidability of SDIPDL}
We first give the syntax of \kl{SDIPDL} \cite{goldblattWellstructuredProgramEquivalence2012} as a fragment of $\PCoR_{\set{\bl^{*}, -}}$.
We use the following abbreviations (the \kl{antidomain operator} $\bl^{\adom}$ is used for encoding the negation of formulas):
\begin{align*}
    \const{f} &\defeq \emp,&
    \const{t} &\defeq \eps,&
    \fml[1] \land \fml[2] &\defeq \fml[1] \compo \fml[2],&
    \fml[1] \lor \fml[2] &\defeq \fml[1] \union \fml[2],&
    \lnot \fml[1] &\defeq \fml[1]^{\adom},\\
    \langle \term \rangle \fml[1] &\defeq (\term \compo \fml[1])^{\dom},&
    [\term] \fml[1] &\defeq (\term \compo \fml[1]^{\adom})^{\adom},&
    \term[1] \union_{\fml} \term[2] &\defeq \fml \term[1] \union (\lnot \fml) \term[2],&
    \term[1]^{*_{\fml}} &\defeq (\fml \term[1])^* (\lnot \fml), &
    \fml[1]? &\defeq \fml[1].
\end{align*}

The sets of \intro*\kl{SDIPDL} formulas and programs, written $\mathrm{F}$ and $\mathrm{P}$,
are mutually defined as the minimal set of $\PCoR_{\set{\bl^{*}, -}}$ \kl{terms} satisfying the following:
\begin{gather*}
    \begin{prooftree}[separation = .5em]
        \hypo{p \in \psig}
        \infer1{p \in \mathrm{F}}
    \end{prooftree}
    \hspace{.8em}
    \begin{prooftree}[separation = .5em]
        \hypo{\mathstrut}
        \infer1{\const{f} \in \mathrm{F}}
    \end{prooftree}
    \hspace{.8em}
    \begin{prooftree}[separation = .5em]
        \hypo{\mathstrut}
        \infer1{\const{t} \in \mathrm{F}}
    \end{prooftree}
    \hspace{.8em}
    \begin{prooftree}[separation = .5em]
        \hypo{\fml[1] \in \mathrm{F}}
        \hypo{\fml[2] \in \mathrm{F}}
        \infer2{\fml[1] \land \fml[2] \in \mathrm{F}}
    \end{prooftree}
    \hspace{.8em}
    \begin{prooftree}[separation = .5em]
        \hypo{\fml[1] \in \mathrm{F}}
        \hypo{\fml[2] \in \mathrm{F}}
        \infer2{\fml[1] \lor \fml[2] \in \mathrm{F}}
    \end{prooftree}
    \hspace{.8em}
    \begin{prooftree}[separation = .5em]
        \hypo{\fml[1] \in \mathrm{F}}
        \infer1{\lnot \fml[1] \in \mathrm{F}}
    \end{prooftree}
    \hspace{.8em}
    \begin{prooftree}[separation = .5em]
        \hypo{\term[1] \in \mathrm{P}}
        \hypo{\fml[1] \in \mathrm{F}}
        \infer2{\langle \term[1] \rangle \fml[1] \in \mathrm{F}}
    \end{prooftree}
    \hspace{.8em}
    \begin{prooftree}[separation = .5em]
        \hypo{\term[1] \in \mathrm{P}}
        \hypo{\fml[1] \in \mathrm{F}}
        \infer2{[\term[1]]\fml[1] \in \mathrm{F}}
    \end{prooftree}\\
    \begin{prooftree}[separation = .5em]
        \hypo{a \in \asig}
        \infer1{a \in \mathrm{P}}
    \end{prooftree}
    \hspace{.8em}
    \begin{prooftree}[separation = .5em]
        \hypo{\term[1] \in \mathrm{P}}
        \hypo{\term[2] \in \mathrm{P}}
        \infer2{\term[1] \compo \term[2] \in \mathrm{P}}
    \end{prooftree}
    \hspace{.8em}
    \begin{prooftree}[separation = .5em]
        \hypo{\fml \in \mathrm{F}}
        \hypo{\term[1] \in \mathrm{P}}
        \hypo{\term[2] \in \mathrm{P}}
        \infer3{\term[1] \union_{\fml} \term[2] \in \mathrm{P}}
    \end{prooftree}
    \hspace{.8em}
    \begin{prooftree}[separation = .5em]
        \hypo{\fml \in \mathrm{F}}
        \hypo{\term[1] \in \mathrm{P}}
        \infer2{\term[1]^{*_{\fml}} \in \mathrm{P}}
    \end{prooftree}
    \hspace{.8em}
    \begin{prooftree}[separation = .5em]
        \hypo{\term[1] \in \mathrm{P}}
        \hypo{\term[2] \in \mathrm{P}}
        \infer2{\term[1] \cap \term[2] \in \mathrm{P}}
    \end{prooftree}
    \hspace{.8em}
    \begin{prooftree}[separation = .5em]
        \hypo{\fml \in \mathrm{F}}
        \infer1{\fml[1]? \in \mathrm{P}}
    \end{prooftree}.
\end{gather*}
Additionally, we use the following abbreviations:
$\fml[1] \to \fml[2] \defeq \lnot \fml[1] \lor \fml[2]$ and $\fml[1] \leftrightarrow \fml[2] \defeq (\fml[1] \to \fml[2]) \land (\fml[2] \to \fml[1])$ in \kl{SDIPDL} formulas.

For \kl{SDIPDL} formulas $\fml$, we write $\DREL_{\mathtt{test}} \models \fml$ if $\DREL_{\mathtt{test}} \models \fml = \const{t}$ holds.
We then have $\DREL_{\mathtt{test}} \models \term \le \emp$ iff $\DREL_{\mathtt{test}} \models [\term] \const{f}$.
Thus, \Cref{thm: undecidable while emptiness} can be rephrased as follows.
\begin{cor}\label{cor: undecidable PDL}
    The \kl{validity problem} (and also the \kl{finite validity problem}) is $\mathrm{\Pi}^{0}_{1}$-complete for formulas of the form $[\term] \const{f}$ in \kl{SDIPDL} where $\term$ is a \kl{$\mathrm{PWP}_{\lop}$ term} \emph{without any modal operators}.
\end{cor}
Hence, \Cref{thm: undecidable while emptiness} refines the undecidability result of \kl{SDIPDL} \cite{goldblattWellstructuredProgramEquivalence2012} with respect to the nesting of modal operators.
Notably, the diamond operator $\langle \bl \rangle$ does not appear in the fragment of \Cref{cor: undecidable PDL}.
%
%

\begin{rem}[On nested modal operators in {\cite{goldblattWellstructuredProgramEquivalence2012}}]\label{rem: nested modal operators}
    The reduction of \cite{goldblattWellstructuredProgramEquivalence2012} (in particular, the formula ``$\rho_{1}$'' \cite[p.\ 5]{goldblattWellstructuredProgramEquivalence2012}) contains nested box and diamond operators, by unfolding notations.
    Note that:
    (1) the formula ``$\mathsf{fix}(\term)$'' \cite[p.\ 3]{goldblattWellstructuredProgramEquivalence2012} is equivalent to the formula $\langle\term^{\lop}\rangle \const{t}$ on deterministic structures,
    (2) the formula $[\term^*] \fml$ abbreviates the formula $[\term^{*_{\fml}}] \const{f}$,
    so the used formula contains \kl{tests} containing modal operators.
\end{rem}

\begin{rem}[On the complexity difference from {\cite{goldblattWellstructuredProgramEquivalence2012}}]\label{rem: difference}
    The \kl{validity problem} is $\mathrm{\Pi}^{0}_{1}$-complete for the fragment of \Cref{cor: undecidable PDL},
    whereas the \kl{validity problem} is $\mathrm{\Pi}^{1}_{1}$-complete for full \kl{SDIPDL} \cite[Theorem 4.1]{goldblattWellstructuredProgramEquivalence2012}.
    The $\mathrm{\Pi}^{0}_{1}$ upper bound is derived from the finite model property (\Cref{prop: upper bound}).
    Indeed, \kl{SDIPDL} does not have the finite model property.
    For instance, when we consider only deterministic structures,
    the formula $p \land [a][a^{*}](\lnot p \land \langle (b a)^{\lop} a \rangle \const{t})$ is satiable only on infinite structures.
    (Proof: Let $\fml$ be the formula above.
    When $\tuple{x_0,x_0} \in \hat{\val}(\fml)$ for some $\val \in \DREL_{\mathtt{test}}^{\mathrm{fin}}$,
    there are $x_1, x_2, \dots$ such that
    $\tuple{x_0,x_0} \in \hat{\val}(p)$ and
    for each $i \ge 1$,
    $\tuple{x_i, x_i} \not\in \hat{\val}(p)$ (hence, $x_0 \neq x_i$),
    $\tuple{x_{i-1}, x_{i}} \in \hat{\val}(a)$, and $\tuple{x_{i}, x_{i-1}} \in \hat{\val}(b)$ (by the functionality of $a$).
    As $\val$ is finite,
    there is some $i \ge 1$ such that $x_i = x_j$ for some $1 \le j < i$ and $x_0, \dots, x_{i-1}$ are pairwise distinct.
    Then, $\tuple{x_{j-1}, x_i} \in \hat{\val}(a)$ and $\tuple{x_{i-1}, x_i} \in \hat{\val}(a)$, which contradicts to the functionality of $b$.
    Hence, $\fml$ is unsatisfiable on $\DREL_{\mathtt{test}}^{\mathrm{fin}}$.
    In contrast, $\fml$ is clearly satisfiable on $\DREL_{\mathtt{test}}$.)
    Additionally, note that the \kl{finite validity problem} is $\mathrm{\Pi}^{0}_{1}$-complete
    for both the fragment of \Cref{cor: undecidable PDL} and full \kl{SDIPDL} \cite[Theorem 4.4]{goldblattWellstructuredProgramEquivalence2012}.
\end{rem}

