\section{On the number of primitive tests and actions}\label{section: on the number of primitive tests and actions}
In this section,
we consider the fragments of \kl{$\mathrm{PWP}_{\lop}$ terms} obtained by restricting the number of \kl{primitive tests} and \kl{actions}.
(In the sequel, we count the number of \kl{primitive tests} as the number of involution pairs of \kl{primitive tests};
for instance, the \kl{term} $p \tilde{p} q$ has $2$ \kl{primitive tests} $p$ / $\tilde{p}$ and $q$.)

We say that a \kl{$\mathrm{PWP}_{\lop}$ term} $\term$ is \intro*\kl{primitive} if every \kl{test} occurring in $\term$ is a \kl{primitive test}.
Namely, the set of \intro*\kl{primitive $\mathrm{PWP}_{\lop}$ terms} is the minimal subset $\mathrm{W}$ of $\mathrm{PCoR}_{\set{\bl^{*}}}$ satisfying the following:
\begin{gather*}
    \begin{prooftree}[separation = .5em]
        \hypo{\mathstrut}
        \infer1{\eps \in \mathrm{W}}
    \end{prooftree}
    \hspace{.8em}
    \begin{prooftree}[separation = .5em]
        \hypo{\mathstrut}
        \infer1{\emp \in \mathrm{W}}
    \end{prooftree}
    \hspace{.8em}
    \begin{prooftree}[separation = .5em]
        \hypo{p \in \psig}
        \infer1{p \in \mathrm{W}}
    \end{prooftree}
    \hspace{.8em}
    \begin{prooftree}[separation = .5em]
        \hypo{x \in \asig}
        \infer1{x \in \mathrm{W}}
    \end{prooftree}
    \hspace{.8em}
    \begin{prooftree}[separation = .5em]
        \hypo{\term[1] \in \mathrm{W}}
        \hypo{\term[2] \in \mathrm{W}}
        \infer2{\term[1] \compo \term[2] \in \mathrm{W}}
    \end{prooftree}
    \hspace{.8em}
    \begin{prooftree}[separation = .5em]
        \hypo{\term[1] \in \mathrm{W}}
        \hypo{\term[2] \in \mathrm{W}}
        \hypo{p \in \psig}
        \infer3{\term[1] \union_{p} \term[2] \in \mathrm{W}}
    \end{prooftree}
    \hspace{.8em}
    \begin{prooftree}[separation = .5em]
        \hypo{\term[1] \in \mathrm{W}}
        \hypo{p \in \psig}
        \infer2{\term[1]^{*_{p}} \in \mathrm{W}}
    \end{prooftree}
    \hspace{.8em}
    \begin{prooftree}[separation = .5em]
        \hypo{\term[1] \in \mathrm{W}}
        \infer1{\term[1]^{\lop} \in \mathrm{W}}
    \end{prooftree}.
\end{gather*}
Note that the \kl{term} $\Tr'_{\term[3]_{\mathcal{D}}^{\lop}}(\term[1]_{\mathtt{gr}}')$ given in \Cref{thm: undecidable while emptiness} is a \kl{primitive $\mathrm{PWP}_{\lop}$ term}, by replacing $\sum P$ with $\eps \union_{p_1} (\eps \union_{p_2} (\dots (\eps \union_{p_{n}} \emp) \dots))$,
where $P = \set{p_1, \dots, p_n}$.
For simplicity, we consider only \kl{primitive $\mathrm{PWP}_{\lop}$ terms} in this section.
This restriction will be useful in \Cref{defi: reducing primitive tests}.

\subsection{Reducing to one primitive test}\label{section: reducing primitive tests}
In this subsection, we strengthen the $\Pi^{0}_{1}$-hardness result of \Cref{thm: undecidable while emptiness}, by fixing the number of \kl{primitive tests}.\footnote{%
When the number of colors is fixed, the number of instances of the \kl{periodic domino problem} is finite, and hence the \kl[periodic domino problem]{problem} is trivially decidable.
Hence, we cannot immediately bound the number of \kl{primitive tests} from the reduction of \Cref{thm: undecidable while emptiness}.}
Let $P = \set{p_1, \dots, p_n}$ be a set of \kl{primitive tests}.
Let $m \defeq 2n + 1$ (a sufficiently large integer).
Let $\mathtt{P}$ be a \kl{fresh} \kl{primitive test}.
Let $U$ be the \kl{primitive $\mathrm{PWP}_{\lop}$ term} given by:
\[U \defeq \mathtt{P} \aE \mathtt{P} \aW.\]
We will use $U$ for distinguishing original vertices and newly added vertices in the transformation of \kl{valuations} given later (cf.\ \Cref{figure: encoding}).

We then transform \kl{terms} over \kl{primitive tests} $P$ to \kl[terms]{those} over one \kl{primitive test} $\mathtt{P}$, as follows.
\begin{defi}\label{defi: reducing primitive tests}
    For \kl{primitive $\mathrm{PWP}_{\lop}$ terms} $\term$ over \kl{actions} $\set{\aE,\aN,\aW,\aS}$ and over \kl{primitive tests} $P = \set{p_1, \dots, p_n}$,
    let $\Tr^{(1)}(\term)$ be the \kl{primitive $\mathrm{PWP}_{\lop}$ term} (over one \kl{primitive test} $\mathtt{P}$) defined by:
    \begin{align*}
        \Tr^{(1)}(\eps)                       & \defeq U, &
        \Tr^{(1)}(\emp)                       & \defeq \emp, \\
               \Tr^{(1)}(p_i)                       & \defeq U \aE^{2i+1} \mathtt{P} \aW^{2i+1} U \mbox{ for $i \in \range{1, n}$},  &
        \Tr^{(1)}(a)                       & \defeq U a^{m} U \mbox{ for $a \in \set{\aE,\aN,\aW,\aS}$}, \\
        \Tr^{(1)}(\term[1] \compo \term[2]) & \defeq \Tr^{(1)}(\term[1]) \compo \Tr^{(1)}(\term[2]),  &
        \Tr^{(1)}(\term[1] \union_{p_i} \term[2]) & \defeq \aE^{2i+1}(\aW^{2i+1} \Tr^{(1)}(\term[1]) \union_{\mathtt{P}} \aW^{2i+1} \Tr^{(1)}(\term[2]) ),  \\
        \Tr^{(1)}(\term[1]^{\lop})           & \defeq \Tr^{(1)}(\term[1])^{\lop}, &
        \Tr^{(1)}(\term[1]^{*_{p_i}})          & \defeq \aE^{2i+1} (\aW^{2i+1} \Tr^{(1)}(\term[1]) \aE^{2i+1})^{*_{\mathtt{P}}} \aW^{2i+1}.
    \end{align*}
    Furthermore, for \kl{(quantifier-free) formulas} $\fml$ of \kl{primitive $\mathrm{PWP}_{\lop}$ terms} (over \kl{primitive tests} $\psig$),
    let $\Tr^{(1)}(\fml)$ be the \kl{formula} $\fml$ in witch
    each \kl{primitive $\mathrm{PWP}_{\lop}$ term} $\term[3]$ has been replaced with $\Tr^{(1)}(\term[3])$.
\end{defi}

Let $\aE', \aN', \aW', \aS'$ be \kl{fresh} \kl{actions} and let
\[\Theta \defeq \set{p_i = U\aE^{2i+1} \mathtt{P} \aW^{2i+1}U \mid i \in \range{1, n}} \cup \set{a' = Ua^{m}U \mid a \in \set{\aE, \aN, \aW, \aS}}.\]
We then have the following.
