\begin{cla}\label{cla: reducing primitive tests}
    For all \kl{primitive $\mathrm{PWP}_{\lop}$ terms} $\term$ (over \kl{actions} $\set{\aE,\aN,\aW,\aS}$ and over \kl{primitive tests} $P = \set{p_1, \dots, p_n}$),
    we have:
    \[\REL_{\mathtt{test}, \aE \aW = \eps, \aW \aE = \eps, \Theta} \models \term[1]' = \Tr^{(1)}(\term[1]),\]
    where $\term[1]'$ is the \kl{term} $\term$ in which each $a \in \set{\aE,\aN,\aW,\aS}$ has been replaced with $a'$.
\end{cla}
\begin{claproof}
    By easy induction on $\term[1]$.
    Here, we use the following facts for the operators $+_{p_i}$ and $\bl^{*_{p_i}}$:
    \begin{itemize}
        \item \label{cla: reducing primitive tests 1}
        $\REL_{\mathtt{test}, \aE \aW = \eps, \aW \aE = \eps, \Theta} \models \aE^{2i+1} \tilde{\mathtt{P}} \aW^{2i+1} = \tilde{p}_i$.\\
        (We have $\REL_{\mathtt{test}, \aW \aE = \eps} \models
        p_i \compo \aE^{2i+1} \tilde{\mathtt{P}}\aW^{2i+1}
        = \aE^{2i+1} \mathtt{P}\aW^{2i+1} \compo \aE^{2i+1} \tilde{\mathtt{P}}\aW^{2i+1}
        = \emp$ and we have $\REL_{\mathtt{test}, \aE \aW = \eps} \models
        p_i \union \aE^{2i+1} \tilde{\mathtt{P}}\aW^{2i+1}
        = \aE^{2i+1} \mathtt{P}\aW^{2i+1} \union \aE^{2i+1} \tilde{\mathtt{P}}\aW^{2i+1}
        = \eps$.
        We thus have that $\REL_{\mathtt{test}, \aE \aW = \eps, \aW \aE = \eps, \Theta} \models
            \aE^{2i+1} \tilde{\mathtt{P}} \aW^{2i+1}
            = (p_i \union \tilde{p}_i) \aE^{2i+1} \tilde{\mathtt{P}} \aW^{2i+1}
            = \tilde{p}_i \aE^{2i+1} \tilde{\mathtt{P}} \aW^{2i+1} 
            = \tilde{p}_i p_i \union \aE^{2i+1} \tilde{\mathtt{P}} \aW^{2i+1}
            = \tilde{p}_i (p_i \union \aE^{2i+1} \tilde{\mathtt{P}} \aW^{2i+1})
            = \tilde{p}_i$.)
        \item \label{cla: reducing primitive tests 2}
        $\REL_{\mathtt{test}, \aE \aW = \eps, \aW \aE = \eps, \Theta} \models \aE^{2i+1}(\aW^{2i+1} \term[1] \union_{\mathtt{P}} \aW^{2i+1} \term[2]) = \term[1] \union_{p_i} \term[2]$, for all \kl{terms} $\term[1]$ and $\term[2]$.\\
        (Because $\REL_{\mathtt{test}, \aE \aW = \eps, \aW \aE = \eps, \Theta} \models \aE^{2i+1}(\aW^{2i+1} \term[1] \union_{\mathtt{P}} \aW^{2i+1} \term[2])
        = \aE^{2i+1} \mathtt{P} \aW^{2i+1} \term[1] \union \aE^{2i+1} \tilde{\mathtt{P}}\aW^{2i+1} \term[2]
        = p_i \term[1] \union \tilde{p}_i \term[2]
        = \term[1] \union_{p_i} \term[2]$.)
        \item \label{cla: reducing primitive tests 3}
        $\REL_{\mathtt{test}, \aE \aW = \eps, \aW \aE = \eps, \Theta} \models \aE^{2i+1}(\aW^{2i+1} \term[1] \aE^{2i+1})^{*_{\mathtt{P}}} \aW^{2i+1} = \term[1]^{*_{p_i}}$, for all \kl{terms} $\term[1]$.\\
        (Because $\REL_{\mathtt{test}, \aE \aW = \eps, \aW \aE = \eps, \Theta} \models \aE^{2i+1}(\aW^{2i+1} \term[1] \aE^{2i+1})^{*_{\mathtt{P}}} \aW^{2i+1}
        = \aE^{2i+1}(\mathtt{P} \aW^{2i+1} \term[1] \aE^{2i+1})^{*} \tilde{\mathtt{P}} \aW^{2i+1}
        = (\aE^{2i+1} \mathtt{P} \aW^{2i+1} \term[1])^{*} \aE^{2i+1} \tilde{\mathtt{P}} \aW^{2i+1}
        = (p_i \term[1])^{*} \tilde{p}_i
        = \term[1]^{*_{p_i}}$.) 
    \end{itemize}
    Hence, this completes the proof.
\end{claproof}
Using this, we have the following transformation.
\begin{lem}\label{lem: reducing primitive tests}
    For all \kl{quantifier-free formulas} $\fml[1]$ of \kl{primitive $\mathrm{PWP}_{\lop}$ terms}, we have:
    \begin{align*}
        \DREL^{\mathrm{fin}}_{\mathtt{test}, (\aE \union \aN \union \aW \union \aS)^* \ge \top, \term[3]_{\mathtt{gr}} \ge \eps} \models \fml[1]
        & \quad\Longleftrightarrow\quad \DREL^{\mathrm{fin}}_{\mathtt{test}, (\aE \union \aN \union \aW \union \aS)^* \ge \top, \term[3]_{\mathtt{gr}} \ge \eps} \models \Tr^{(1)}(\fml[1]).
    \end{align*}
\end{lem}
\begin{proof}
    Let $\fml[1]'$ and $\term[3]_{\mathtt{gr}}'$
    be the $\fml[1]$ and $\term[3]_{\mathtt{gr}}$
    in which each $a \in \set{\aE, \aN, \aW, \aS}$ has been replaced with $a'$.
    By renaming \kl{variables},
    the left-hand side is equivalent to $\DREL^{\mathrm{fin}}_{\mathtt{test}, (\aE' \union \aN' \union \aW' \union \aS')^* \ge \top, \term[3]_{\mathtt{gr}}' \ge \eps} \models \fml[1]'$.

    ($\Rightarrow$):
    By $\DREL^{\mathrm{fin}}_{\mathtt{test}, (\aE \union \aN \union \aW \union \aS)^* \ge \top, \term[3]_{\mathtt{gr}} \ge \eps, \Theta} \subseteq \DREL^{\mathrm{fin}}_{\mathtt{test}, (\aE' \union \aN' \union \aW' \union \aS')^* \ge \top, \term[3]_{\mathtt{gr}}' \ge \eps}$
    and \Cref{cla: reducing primitive tests},
    we have $\DREL^{\mathrm{fin}}_{\mathtt{test}, (\aE \union \aN \union \aW \union \aS)^* \ge \top, \term[3]_{\mathtt{gr}} \ge \eps, \Theta} \models \Tr^{(1)}(\fml[1])$.
    As $\aE'$, $\aN'$, $\aW'$, $\aS'$, and $p_i$ are not occurring in $\Tr^{(1)}(\fml)$,
    we have $\DREL^{\mathrm{fin}}_{\mathtt{test}, (\aE \union \aN \union \aW \union \aS)^* \ge \top, \term[3]_{\mathtt{gr}} \ge \eps} \models \Tr^{(1)}(\fml[1])$.

    ($\Leftarrow$):
    Let $\val \colon \vsig \to \wp(X^2)$ in $\DREL^{\mathrm{fin}}_{\mathtt{test}, (\aE' \union \aN' \union \aW' \union \aS')^* \ge \top, \term[3]_{\mathtt{gr}}' \ge \eps}$.
    By $\val \in \REL^{\mathrm{fin}}_{\mathtt{grid}}$,
    up to isomorphisms, without loss of generality,
    we can assume that $\val$ and $h, v \ge 1$ are the ones obtained by \Cref{prop: grid}
    (then, $X = \range{0, h - 1} \times \range{0, v - 1}$).
    %
    Let $Y \defeq \range{0, mh - 1} \times \range{0, mv - 1}$ and let $\val' \colon \vsig \to \wp(Y^2)$ be the \kl{valuation} defined by
    \begin{align*}
        \val'(\mathtt{P}) &\defeq
        \set{\tuple{\tuple{mx, my}, \tuple{mx, my}} \mid 
        x \in \range{0, h - 1}, y \in \range{0, v - 1}}\\
        &\cup \set{\tuple{\tuple{mx + 1, my}, \tuple{mx + 1, my}} \mid 
        x \in \range{0, h - 1}, y \in \range{0, v - 1}}\\
        &\cup 
        \set{\tuple{\tuple{mx + 2i + 1, my}, \tuple{mx + 2i + 1, my}} \mid \tuple{x, y} \in \hat{\val}(p_i \aE)},\\
        \val'(\aE) &\defeq \set{\tuple{\tuple{mx + i, my + j}, \tuple{(mx + i + 1) \bmod h, my + j}} \mid \tuple{x, y} \in \hat{\val}(\aE),\; i, j \in \range{0, m-1}}, \\
        \val'(\aN) &\defeq \set{\tuple{\tuple{mx + i, my + j}, \tuple{mx + i, (my + j + 1) \bmod v}} \mid \tuple{x, y} \in \hat{\val}(\aN),\; i, j \in \range{0, m-1}}, \\
        \val'(\aW) &\defeq \val'(\aE)^{\smile}, \quad \val'(\aS) \defeq \val'(\aN)^{\smile},\\
        \val'(a) &\defeq \set{\tuple{\tuple{mx, my},\tuple{mx, my}} \mid \tuple{x, y} \in \hat{\val}(a)} \mbox{ for $a = p_i, \aE', \aN', \aW', \aS'$}.
    \end{align*}
