\begin{thm}\label{thm: reducing primitive tests}
    The \kl{emptiness problem} on $\DREL_{\mathtt{test}}$ (resp.\ $\DREL_{\mathtt{test}}^{\mathrm{fin}}$) is 
    $\Pi^{0}_{1}$-complete for \kl{$\mathrm{PWP}_{\lop}$ terms} where the number of \kl{actions} is (at most) $4$ and the number of \kl{primitive tests} is $1$.
\end{thm}
\begin{proof}
    We recall the \kl{primitive $\mathrm{PWP}_{\lop}$ term} $\Tr'_{\term[3]_{\mathcal{D}}}(\term[1]_{\mathtt{gr}}')$ in \Cref{thm: undecidable while emptiness}.
    We then have:
    \begin{align*}
        & \mbox{$\mathcal{D}$ does not have a \kl{periodic tiling}}
        \;\Leftrightarrow\; \DREL^{\mathrm{fin}}_{\mathtt{test}, (\aE \union \aN \union \aW \union \aS)^* \ge \top, \term[3]_{\mathcal{D}} \ge \eps} \models \term[1]_{\mathtt{gr}}' \le \emp \tag{\Cref{lem: connectivity'}}                                                                                 \\
        & \Leftrightarrow\; \DREL^{\mathrm{fin}}_{\mathtt{test}, (\aE \union \aN \union \aW \union \aS)^* \ge \top, \term[3]_{\mathtt{gr}} \ge \eps, \term[3]_{\mathcal{D}} \ge \eps} \models \term[1]_{\mathtt{gr}}' \le \emp \tag{By $\REL \models \term[3]_{\mathtt{gr}} \ge \term[3]_{\mathcal{D}}$} \\
        & \Leftrightarrow\; \DREL^{\mathrm{fin}}_{\mathtt{test}, (\aE \union \aN \union \aW \union \aS)^* \ge \top, \term[3]_{\mathtt{gr}} \ge \eps} \models \Tr^{(1)}(\term[3]_{\mathcal{D}} \ge \eps \to \term[1]_{\mathtt{gr}}' \le \emp) \tag{\Cref{lem: reducing primitive tests}}     \\
        & \Leftrightarrow\; \DREL^{\mathrm{fin}}_{\mathtt{test}, (\aE \union \aN \union \aW \union \aS)^* \ge \top, \term[3]_{\mathtt{gr}} \ge \eps} \models \Tr^{(1)}(\term[3]_{\mathcal{D}}) \ge U \to \Tr^{(1)}(\term[1]_{\mathtt{gr}}') \le \emp            \tag{By definition of $\Tr^{(1)}$}                                                                  \\
        & \Leftrightarrow\; \DREL^{\mathrm{fin}}_{\mathtt{test}, (\aE \union \aN \union \aW \union \aS)^* \ge \top, \term[3]_{\mathtt{gr}} \ge \eps} \models \eps \union_{\tilde{\mathtt{P}}} \aE (\aW \union_{\tilde{\mathtt{P}}} \aW \Tr^{(1)}(\term[3]_{\mathcal{D}})) \ge \eps \to \Tr^{(1)}(\term[1]_{\mathtt{gr}}') \le \emp \tag{$\bigstar$}                                                                                 \\
        & \Leftrightarrow\; \DREL^{\mathrm{fin}}_{\mathtt{test}, (\aE \union \aN \union \aW \union \aS)^* \ge \top} \models \Tr'_{\term[3]_{\mathtt{gr}} \compo (\eps \union_{\tilde{\mathtt{P}}} \aE (\aW \union_{\tilde{\mathtt{P}}} \aW \Tr^{(1)}(\term[3]_{\mathcal{D}})))}(\Tr^{(1)}(\term[1]_{\mathtt{gr}}')) \le \emp   \tag{\Cref{ex: grid surjective}}                                                                                           \\
        & \Leftrightarrow\; \DREL_{\mathtt{test}} \models \Tr'_{\term[3]_{\mathtt{gr}} \compo (\eps \union_{\tilde{\mathtt{P}}} \aE (\aW \union_{\tilde{\mathtt{P}}} \aW \Tr^{(1)}(\term[3]_{\mathcal{D}})))}(\Tr^{(1)}(\term[1]_{\mathtt{gr}}')) \le \emp.   \tag{\Cref{ex: surjective}}
    \end{align*}
    Here, ($\bigstar$) is shown by
    $\REL_{\mathtt{test}, \aE \aW = \eps, \aW \aE = \eps} \models \term[3] \ge \mathtt{P} \aE \mathtt{P} \aW  \leftrightarrow \eps \union_{\tilde{\mathtt{P}}} \aE (\aW \union_{\tilde{\mathtt{P}}} \aW \term[3]) \ge \eps$ for any \kl{term} $\term[3]$.
    Because the \kl{primitive $\mathrm{PWP}_{\lop}$ term} $\Tr'_{\term[3]_{\mathtt{gr}} \compo (\eps \union_{\tilde{\mathtt{P}}} \aE (\aW \union_{\tilde{\mathtt{P}}} \aW \Tr^{(1)}(\term[3]_{\mathcal{D}})))}(\Tr^{(1)}(\term[1]_{\mathtt{gr}}'))$ contains four \kl{actions} $\aW, \aE, \aN, \aS$ and one \kl{primitive test} $\mathtt{P}$,
    this completes the proof.
\end{proof}
Particularly, when we can use the converse operator for \kl{actions}, the following holds.
\begin{cor}\label{cor: reducing primitive tests conv}
    The \kl{emptiness problem} on $\DREL_{\mathtt{test}}$ is 
    $\Pi^{0}_{1}$-complete for \kl{$\mathrm{PWP}_{\lop \breve{x}}$ terms} where the number of \kl{actions} is $2$ and the number of \kl{primitive tests} is $1$.
\end{cor}
\begin{proof}
    Because we can eliminate $\aW$ and $\aS$ using the fact that $\aW = \aE^{\smile}$ and $\aS = \aN^{\smile}$ hold in the reduction of \Cref{thm: reducing primitive tests}.
\end{proof}

\begin{rem}\label{rem: reducing primitive tests}
    By \Cref{thm: reducing primitive tests,cor: reducing primitive tests conv},
    we can also show that
    each of \Cref{cor: undecidable PDL,cor: undecidable PCoR* func,cor: undecidable PCoR* difference,cor: undecidable PCoR* variable emptiness}
    is $\Pi^{0}_{1}$-complete even if the number of \kl{actions} is $4$ and the number of \kl{primitive tests} is $1$,
    and even if the number of \kl{actions} is $2$ and the number of \kl{primitive tests} is $1$ when we admit the converse operators.
\end{rem}

