\subsection{On the coNP-hardness for the while-free fragment (where the number of primitive tests is fixed)}\label{section: NP-hardness}
Additionally,
we show that the \kl{emptiness problem} is $\textsc{coNP}$-complete
when the while operator $\bl^{*_{b}}$ does not occur and the number of primitive tests is fixed.
\begin{cor}\label{cor: NP-complete while emptiness}
    The \kl{emptiness problem} on $\DREL_{\mathtt{test}}$ is $\textsc{coNP}$-complete
    for \kl{$\mathrm{PWP}_{\lop}$ terms} without $\bl^{*_{b}}$ where the number of \kl{actions} is $4$ and the number of \kl{primitive tests} is $1$.
\end{cor}
\begin{proof}
    (in $\textsc{coNP}$):
    By \Cref{prop: upper bound}.
    (Hardness):
    We define the $n$-th iteration operator $\term^{(n)_{b}}$ as follows:
    \begin{align*}
        \term^{(n)_{b}} &\quad\defeq\quad (b t)^{n} \tilde{b}.
    \end{align*}
    Let $\term[1]_{\mathtt{gr}}'' \defeq (p ((q \aN^{(n)_{\tilde{q}}})^{\lop} \aE)^{(n)_{\tilde{p}}})^{\lop}$ (i.e., the \kl{term} $\term[1]_{\mathtt{gr}}'$ (used in \Cref{thm: undecidable while emptiness}) in which the two $\bl^{+_{r}}$ has been replaced with $\bl^{(n)_{r}}$).
    As an analog of \Cref{thm: undecidable while emptiness}, we have:
    \[\mbox{$\mathcal{D}$ does not have an \kl[$\tuple{h,v}$-periodic tiling]{$\tuple{n,n}$-periodic tiling}}                                                                
    \;\Leftrightarrow\; \DREL^{\mathrm{fin}}_{\mathtt{test}, (\aE \union \aN \union \aW \union \aS)^* \ge \top, \term[3]_{\mathcal{D}} \ge \eps} \models \term[1]_{\mathtt{gr}}'' \le \emp.\]
    Thus, in the same way as \Cref{thm: reducing primitive tests}, we have:
    \[\mbox{$\mathcal{D}$ does not have an \kl[$\tuple{h,v}$-periodic tiling]{$\tuple{n,n}$-periodic tiling}}                                                                
    \;\Leftrightarrow\; \DREL_{\mathtt{test}} \models
    \Tr'_{\term[3]_{\mathtt{gr}} \compo (\eps \union_{\tilde{\mathtt{P}}} \aE (\aW \union_{\tilde{\mathtt{P}}} \aW \Tr^{(1)}(\term[3]_{\mathcal{D}})))}(\Tr^{(1)}(\term[1]_{\mathtt{gr}}'')) \le \emp.\]
    Hence, this completes the proof.
\end{proof}

\begin{rem}\label{rem: NP-complete}
    \Cref{cor: NP-complete while emptiness} is trivial when the number of \kl{primitive tests} is not bounded.
    Because $\DREL_{\mathtt{test}} \models b \le \emp$ iff the propositional logic formula obtained from $b$ by replacing each $p, \tilde{p}, \union, \compo$ with $p, \lnot p, \lor, \land$ is unsatisfiable, there is a reduction from the unsatisfiability problem of propositional logic formulas, which is well-known $\textsc{coNP}$-complete \cite{cookComplexityTheoremprovingProcedures1971}.
\end{rem}

\section{Undecidability of PCoR* with Difference}\label{section: undecidable PCoR* with difference}
In this section, we show that the \kl{equational theory} of $\PCoR_{\set{\bl^{*}, \com{\eps}}}$ (on $\REL$) is $\mathrm{\Pi}^{0}_{1}$-complete (\Cref{cor: undecidable PCoR* difference}).
We prove it as a corollary of \Cref{thm: undecidable while emptiness} via \kl{hypothesis eliminations}.
\begin{cor}\label{cor: undecidable PCoR* func}
    The \kl{equational theory} of $\PCoR_{\set{\bl^{*}}}$ on $\DREL$ is $\mathrm{\Pi}^{0}_{1}$-complete.
    More precisely, the \kl{inclusion problem} $\term[1] \le \term[2]$ on $\DREL$, where $\term[1]$ is a $\set{\compo, \union, \bl^{*}, \bl^{\lop}}$-\kl{term} and $\term[2]$ is a $\set{\compo, \union, \top}$-\kl{term}, is $\mathrm{\Pi}^{0}_{1}$-complete.
\end{cor}
\begin{proof}
    By eliminating $\mathtt{test}$ using \Cref{ex: tests}, the last line in \Cref{thm: undecidable while emptiness} is equivalent to the following:
    \[\DREL \models \Tr_{\bigcompo_{i = 0}^{n-1} p_i \union \tilde{p}_i}(\Tr'_{\term[3]_{\mathcal{D}}^{\lop}}(\term[1]_{\mathtt{gr}}')) [p_0^{\lop}/p_0] \dots [p_{2n-1}^{\lop}/p_{2n-1}] \le \top (\sum_{i = 0}^{n-1} p_i \tilde{p}_i) \top.\]
    Hence, this completes the proof.
\end{proof}
Moreover, by eliminating $\mathtt{func}$ using the argument of \Cref{ex: tests}, we also have the following.
\begin{cor}\label{cor: undecidable PCoR* difference}
    The \kl{equational theory} of $\PCoR_{\set{\bl^{*}, \com{\eps}}}$ on $\REL$ is $\mathrm{\Pi}^{0}_{1}$-complete.
    More precisely, the \kl{inclusion problem} $\term[1] \le \term[2]$ on $\REL$, where $\term[1]$ is a $\set{\compo, \union, \bl^{*}, \bl^{\lop}}$-\kl{term} and $\term[2]$ is a $\set{\compo, \union, \bl^{\lop}, \com{\eps}}$-\kl{term}, is $\mathrm{\Pi}^{0}_{1}$-complete.
\end{cor}
\begin{proof}
    Let $\mathtt{func}' \defeq \set{\aE \aW \le \eps, \aW \aE \le \eps, \aN \aS \le \eps, \aS \aN \le \eps}$ and let $\asig = \set{\aE, \aN, \aW, \aS}$.
    Then $\DREL_{\term[3]_{\mathcal{D}} \ge \eps} = \REL_{\mathtt{func}', \term[3]_{\mathcal{D}} \ge \eps}$, as $\aE, \aN$ are bijective maps and $\aW, \aS$ are their inverse maps in both $\DREL_{\term[3]_{\mathcal{D}} \ge \eps}$ and $\REL_{\mathtt{func}', \term[3]_{\mathcal{D}} \ge \eps}$.
    By eliminating $\mathtt{func}'$ (using \Cref{ex: tests}), the \kl{equation} of \Cref{cor: undecidable PCoR* func} is transformed into the following:
    \begin{align*}
        \REL &\models \Tr_{\bigcompo_{i = 0}^{n-1} p_i \union \tilde{p}_i}(\Tr'_{\term[3]_{\mathcal{D}}^{\lop}}(\term[1]_{\mathtt{gr}}')) [p_0^{\lop}/p_0] \dots [p_{2n-1}^{\lop}/p_{2n-1}]\\
        &\qquad \le \top ((\sum_{i = 0}^{n-1} p_i \tilde{p}_i) \union (\aE \aW \com{\eps})^{\lop} \union (\aW \aE \com{\eps})^{\lop} \union (\aN \aS \com{\eps})^{\lop}\union (\aS \aN \com{\eps})^{\lop}) \top.  
    \end{align*}
    %
    Hence, this completes the proof.
\end{proof}
Hence, we have that the \kl{equational theory} of $\PCoR_{\set{\bl^{*}, \com{\eps}}}$ is $\mathrm{\Pi}^{0}_{1}$-complete.

\subsection*{Remark: Comparison to the reduction from the universality problem of CFGs}\label{section: variable complements}
The \kl{equational theory} is $\mathrm{\Pi}^{0}_{1}$-complete for $\PCoR_{\set{\bl^{*}, \com{x}}}$ \cite[Theorem 50]{nakamuraExistentialCalculiRelations2023}.
This result can be shown as a corollary of \Cref{cor: undecidable PCoR* difference}.
We can give a (polynomial-time) reduction from the \kl{equational theory} of $\PCoR_{\set{\bl^{*}, \com{\eps}}}$ into \kl[equational theory]{that} of $\PCoR_{\set{\bl^{*}, \com{x}}}$, by encoding an equivalence relation using hypotheses and eliminating them (see \Cref{section: differnce encoding} for a detail).
Hence, in certain settings, extending with the \kl{difference constant} does not make the \kl{equational theory} strictly harder than extending with \kl{variable complements}.

The reduction of \cite[Theorem 50]{nakamuraExistentialCalculiRelations2023} is a reduction from the universality problem of context-free grammars (CFGs).
In a nutshell, each rewriting rule $x \leftarrow w$ (where, $x$ is a \kl{variable} and $w$ is a $\set{\compo}$-\kl{term}) of a given CFG is encoded as the hypothesis $w \le x$.
By $\REL \models w \le x \leftrightarrow w \cap \com{x} \le \emp$ (\Cref{ex: u le x}), we can eliminate these \kl{Hoare hypotheses}.
Using this approach, we can show the following undecidability.
(Additionally, this approach is also useful to show the undecidability with respect to language models $\LANG$ \cite{nakamuraFiniteRelationalSemantics2025}.)
\begin{prop}[Corollary of {\cite[Theorem 50]{nakamuraExistentialCalculiRelations2023}}, cf.\ \Cref{cor: undecidable PCoR* difference}]\label{prop: undecidable PCoR* variable}
    The \kl{inclusion problem} $\term[1] \le \term[2]$ on $\REL$, where $\term[1]$ is a $\set{\compo, \union, \bl^{*}}$-\kl{term} and $\term[2]$ is a $\set{\compo, \union, \bl^{\lop}, \com{x}}$-\kl{term}, is $\mathrm{\Pi}^{0}_{1}$-complete.
\end{prop}
\begin{proof}
    (In $\mathrm{\Pi}^{0}_{1}$):
    By \Cref{prop: upper bound}.
    (Hardness):
    By using the hypothesis elimination of \Cref{ex: u le x 2} instead of \Cref{ex: u le x} in the proof of \cite[Theorem 50]{nakamuraExistentialCalculiRelations2023}.
\end{proof}
Below we give an open question arisen from \Cref{cor: undecidable PCoR* difference} and \Cref{prop: undecidable PCoR* variable}.
\begin{ques}[cf.\ \Cref{cor: undecidable PCoR* difference}]
    Is it (un)decidable for the \kl{inclusion problem} $\term[1] \le \term[2]$ on $\REL$, where $\term[1]$ is a $\set{\compo, \union, \bl^{*}}$-\kl{term} and $\term[2]$ is a $\set{\compo, \union, \bl^{\lop}, \com{\eps}}$-\kl{term}?
\end{ques}

\section{On the emptiness problem}\label{section: emptiness}
In this section, we focus on the emptiness problem of fragments of $\PCoR_{\set{\bl^{*}, \com{\eps}, \com{x}}}$
on $\DREL$ and $\REL$.

\subsection{Undecidable fragments on DREL}\label{section: emptiness undecidability DREL}
By \Cref{thm: undecidable while emptiness},
we can show that the following undecidability result.
\begin{cor}\label{cor: undecidable PCoR* variable emptiness}
    The \kl{emptiness problem} of $\PCoR_{\set{\bl^{*}, \com{x}}}$ (precisely, $\set{\compo, \union, \bl^{*}, \bl^{\lop}, \com{x}}$-\kl{terms}) on $\DREL$ is $\mathrm{\Pi}^{0}_{1}$-complete.
\end{cor}
\begin{proof}
    By eliminating $\mathtt{test}$ (\Cref{ex: substitution tests}), the last line in \Cref{thm: undecidable while emptiness} is equivalent to the following:
    \[\DREL \models \Tr'_{\term[3]_{\mathcal{D}}^{\lop}}(\term[1]_{\mathtt{gr}}')[q_0^{\lop}, \dots, q_{n-1}^{\lop}, \com{q}_0^{\lop}, \dots \com{q}_{n-1}^{\lop}/p_0, \dots, p_{2n-1}] \le \emp.\]
    Hence, this completes the proof.
\end{proof}

Furthermore, by eliminating $\mathtt{test}$ using the \kl{difference constant} $\com{\eps}$ in the reduction of \Cref{thm: undecidable while emptiness},
we also have the following undecidability result.
\begin{cor}\label{cor: undecidable PCoR* difference emptiness}
    The \kl{emptiness problem} of $\PCoR_{\set{\bl^{*}, \com{\eps}}}$ (precisely, $\set{\compo, \union, \bl^{*}, \bl^{\lop}, \com{\eps}}$-\kl{terms}) on $\DREL$ is $\mathrm{\Pi}^{0}_{1}$-complete.
\end{cor}
\begin{proof}
    We recall the proof of \Cref{thm: undecidable while emptiness}.
    Let $\Gamma_{\mathcal{D}}'$ be the set $\Gamma_{\mathcal{D}}$ extended with the \kl{equation} $\aW \com{\eps} \ge \eps$.
    Note that $\DREL_{\aW \top \ge \eps} \models \aW \com{\eps} \ge \eps \leftrightarrow \aW^{\lop} \le \emp$, as $\aW$ is a function relation in $\DREL_{\aW \top \ge \eps}$.
    As an analog of \Cref{lem: connectivity'},
    $\mathcal{D}$ has an \kl{$\tuple{h,v}$-periodic tiling} for some $h \ge 2$ and $v \ge 1$ iff 
    $\DREL_{\mathtt{test}, \Gamma_{\mathcal{D}}'}^{\mathrm{fin}} \not\models \term[1]_{\mathtt{gr}}' \le \emp$.
    The left-hand side is still $\mathrm{\Pi}^{0}_{1}$-hard by \Cref{prop: domino tiling undecidable},
    because it is decidable whether $\mathcal{D}$ has an \kl{$\tuple{h,v}$-periodic tiling} for $h = 1$ and some $v \ge 1$.
    Let $\term[3]_{\mathcal{D}}' \defeq \term[3]_{\mathcal{D}} \compo (\aW \com{\eps})^{\lop}$.
    By $\REL \models \bigwedge \Gamma_{\mathcal{D}}' \leftrightarrow ((\aE \union \aN \union \aW \union \aS)^* \ge \top \land \term[3]_{\mathcal{D}}' \ge \eps)$,
    we have that $\DREL_{\mathtt{test}, \Gamma_{\mathcal{D}}'}^{\mathrm{fin}} \models \term[1]_{\mathtt{gr}}' \le \emp$
    iff $\DREL_{\mathtt{test}, (\aE \union \aN \union \aW \union \aS)^* \ge \top, \term[3]_{\mathcal{D}}' \ge \eps}^{\mathrm{fin}} \models \term[1]_{\mathtt{gr}}' \le \emp$.
    We now give a special hypothesis elimination of $\mathtt{test}$.
    Let $\psig = \set{p_0, \dots, p_{2n-1}}$, let $q_0, \dots, q_{n-1}$ be \kl{fresh} \kl{variables}, and let
    \begin{align*}
        \Theta &\;\defeq\; \set{p_i = q_i^{\lop}, p_{n+i} = (q_i \aW)^{\lop} \mid i \in \range{0, n-1}}, &
        \term[3]_{\mathcal{D}}'' &\;\defeq\; \term[3]_{\mathcal{D}}' \compo \bigcompo_{i = 0}^{n-1} (q_i (\eps \union \aW))^{\lop}.
    \end{align*}
    Intuitively, for $\val \in \DREL_{\term[3]_{\mathcal{D}}'' \ge \eps, \Theta}$,
    by $\val \models (q_i (\eps \union \aW))^{\lop} \ge \eps$ with the functionality,
    for each $x$, either one of $\tuple{x, x} \in \hat{\val}(q_i^{\lop})$ and $\tuple{x, x} \in \hat{\val}((q_i \aW)^{\lop})$ hold
    (we encode \kl{tests} by using this fact).
    %
    %
    %
    %
    We then have:
    \begin{align*}
        &\DREL^{\mathrm{fin}}_{\mathtt{test}, (\aE \union \aN \union \aW \union \aS)^* \ge \top, \term[3]_{\mathcal{D}}' \ge \eps} \models \term[1]_{\mathtt{gr}}' \le \emp\\
        &\Leftrightarrow \DREL^{\mathrm{fin}}_{\mathtt{test}, (\aE \union \aN \union \aW \union \aS)^* \ge \top, \Theta, \term[3]_{\mathcal{D}}'' \ge \eps} \models \term[1]_{\mathtt{gr}}' \le \emp \tag{$\Rightarrow$: Trivial. $\Leftarrow$: ($\bigstar_1$)}\\
        &\Leftrightarrow \DREL_{(\aE \union \aN \union \aW \union \aS)^* \ge \top, \Theta, \term[3]_{\mathcal{D}}'' \ge \eps}^{\mathrm{fin}} \models \term[1]_{\mathtt{gr}}' \le \emp \tag{$\Leftarrow$: Trivial. $\Rightarrow$: By ($\bigstar_2$)} \\
        &\Leftrightarrow \DREL^{\mathrm{fin}}_{(\aE \union \aN \union \aW \union \aS)^* \ge \top, \Theta} \models \Tr_{\term[3]_{\mathcal{D}}''}(\term[1]_{\mathtt{gr}}') \le \emp \tag{By ($\bigstar_3$)} \\
        &\Leftrightarrow \DREL^{\mathrm{fin}}_{(\aE \union \aN \union \aW \union \aS)^* \ge \top} \models \Tr_{\term[3]_{\mathcal{D}}''}(\term[1]_{\mathtt{gr}}')[q_0^{\lop}, \dots, q_{n-1}^{\lop}, (q_0 \aW)^{\lop}, \dots, (q_{n-1} \aW)^{\lop}/p_0, \dots, p_{2n-1}] \le \emp \tag{\Cref{prop: REL axiom = substitution}}\\ 
        &\Leftrightarrow \DREL \models \Tr_{\term[3]_{\mathcal{D}}''}(\term[1]_{\mathtt{gr}}')[q_0^{\lop}, \dots, q_{n-1}^{\lop}, (q_0 \aW)^{\lop}, \dots, (q_{n-1} \aW)^{\lop}/p_0, \dots, p_{2n-1}] \le \emp. \tag{\Cref{ex: surjective}} 
    \end{align*}
    Here, each ($\bigstar_i$) is shown as follows.

    ($\bigstar_1$): 
    for each $\val \in \DREL^{\mathrm{fin}}_{\mathtt{test}, (\aE \union \aN \union \aW \union \aS)^* \ge \top, \term[3]_{\mathcal{D}}' \ge \eps}$,
    let $\val'$ be the \kl{valuation} $\val$ in which each $\val(q_i)$ has been replaced with the function relation given by \[x \mapsto \begin{cases}
        x & (\mbox{if $\tuple{x, x} \in\val(p_i)$})\\
        \mbox{the \kl{vertex} } y \mbox{ s.t. $\tuple{y, x} \in \val(\aW)$} & (\mbox{otherwise}).
    \end{cases}\]
    (Such a $y$ uniquely exists, as $\val(\aW)$ is a bijection by $\val \in \REL_{\aW \aE = \eps, \aE \aW = \eps}$.)
    By construction with that $q_0, \dots, q_{n-1}$ are \kl{fresh}, we have $\val' \in \DREL^{\mathrm{fin}}_{\mathtt{test}, (\aE \union \aN \union \aW \union \aS)^* \ge \top, \Theta, \term[3]_{\mathcal{D}}'' \ge \eps}$.
    Thus $\val' \models \term[1]_{\mathtt{gr}}' \le \emp$.
    Since $q_0, \dots, q_{n-1}$ are \kl{fresh} in $\term[1]_{\mathtt{gr}}'$, we have $\val \models \term[1]_{\mathtt{gr}}' \le \emp$.

    ($\bigstar_2$):
    Each of $\mathtt{test}_i$ ($i = 1, 2, 3$) is shown as follows:
    \begin{itemize}
        \item For $\mathtt{test}_1$:
        By $\aW \com{\eps} \ge \eps$ and the functionality of $q_i$ and $\aW$,
        we have $\DREL_{\term[3]_{\mathcal{D}}'' \ge \eps} \models q_i^{\lop} \compo (q_i \aW)^{\lop} = (q_i \cap (q_i \aW))^{\lop} \le ((q_i \aW \com{\eps}) \cap (q_i \aW \eps))^{\lop} \le (q_i \aW (\com{\eps} \cap \eps))^{\lop} = \emp$.
        \item For $\mathtt{test}_2$:
        Clearly, we have $\REL \models q_i^{\lop} \le \eps \land (q_i \aW)^{\lop} \le \eps$.
        \item For $\mathtt{test}_3$:
        By $\DREL_{\term[3]_{\mathcal{D}}'' \ge \eps} \models q_i^{\lop} \union (q_i \aW)^{\lop} = (q_i (\eps \union \aW))^{\lop} \ge \eps$.
    \end{itemize}

    ($\bigstar_3$):
    By \Cref{ex: grid surjective} with $\DREL^{\mathrm{fin}}_{(\aE \union \aN \union \aW \union \aS)^* \ge \top, \Theta} \subseteq \algclass_{\mathtt{gr}}$ and $\DREL^{\mathrm{fin}}_{(\aE \union \aN \union \aW \union \aS)^* \ge \top, \Theta} \models \term[3]_{\mathcal{D}}'' \le \term[3]_{\mathcal{D}} \le \term[3]_{\mathtt{gr}}$.
\end{proof}

\subsection{Decidable fragments on DREL}\label{section: emptiness decidability DREL}
Below we give two decidable fragments on $\DREL$.
The following shows that the \kl{emptiness problem} is decidable for purely \emph{positive} fragments.
\begin{prop}\label{prop: decidable PCoR* DREL emptiness}
    The \kl{emptiness problem} on $\DREL$ (resp.\ $\REL$) is $\textsc{NC}^{1}$-complete for $\PCoR_{\set{\bl^{*}}}$.
\end{prop}
\begin{proof}
    (In $\textsc{NC}^{1}$):
    Let $\algclass = \REL$ or $\DREL$.
    Let $\val_1 \colon \vsig \to \wp(\set{o}^2)$ be the \kl{valuation} defined as $\val_1(a) \defeq \set{\tuple{o, o}}$ for $a \in \vsig$ (i.e., the \kl{graph} of $\val_1$ is the singleton \kl{graph} \begin{tikzpicture}[baseline = -.5ex]
        \graph[grow up= 3.cm, branch right = 3.cm, nodes={font=\tiny}]{
        {0/{$o$}[mynode, inner sep = .1em]}
        };
        \graph[use existing nodes, edges={color=black, pos = .5, earrow}, edge quotes={fill = white, inner sep=1pt,font= \scriptsize}]{
        0 ->["$\vsig$", out = 150, in = 210, looseness = 10] 0; 
        };
    \end{tikzpicture}).
    Clearly, $\val_1 \in \DREL$.
    Because every $\vsig$-labelled \kl{graph} is \kl{graph homomorphic} to $\const{G}(\val_1, o, o)$, we have that $\algclass \models \term \le \emp$ iff $\glang(\term) = \emptyset$,
    as a corollary of \Cref{prop: glang}.
    The right-hand side can be inductively calculated by the following properties:
    \begin{gather*}
        \glang(a) \neq \emptyset,\quad
        \glang(\eps) \neq \emptyset,\quad
        \glang(\emp) = \emptyset,\quad
        \glang(\term[1]^*) \neq \emptyset,\\
        \glang(\term[1] \compo \term[2]) \neq \emptyset \iff \glang(\term[1]) \neq \emptyset \mbox{ and } \glang(\term[2]) \neq \emptyset,\quad
        \glang(\term[1] \union \term[2]) \neq \emptyset \iff \glang(\term[1]) \neq \emptyset \mbox{ or } \glang(\term[2]) \neq \emptyset, \\
        \glang(\term[1]^{\smile}) \neq \emptyset \iff \glang(\term[1]) \neq \emptyset,\quad
        \glang(\term[1] \cap \term[2]) \neq \emptyset \iff \glang(\term[1]) \neq \emptyset \mbox{ and } \glang(\term[2]) \neq \emptyset.
    \end{gather*}
    Thus, we can reduce this problem into the evaluation of a fixed finite algebra (with $2$ values of ``$= \emptyset$'' and ``$\neq \emptyset$''),
    which is in $\textsc{NC}^{1}$ \cite[Corollary 1]{lohreyParallelComplexityTree2001}\cite[Theorem 8]{bussBooleanFormulaValue1987}.
    (Hardness):
    Because the \kl{emptiness problem} of $\set{\emp, \eps, \union, \compo}$-\kl{terms} is equal to the boolean formula value problem \cite{bussBooleanFormulaValue1987}, which is $\textsc{NC}^{1}$-hard.
\end{proof}
The following shows that the \kl{emptiness problem} is decidable for the intersection-free fragments.
\begin{prop}\label{prop: decidable KA emptiness}
    The \kl{emptiness problem} on $\DREL$ (resp.\ $\REL$) is $\textsc{NC}^{1}$-complete for $\set{\eps, \emp, \compo, \union, \bl^{*}, \bl^{\smile}, \com{\eps}, \com{x}}$-\kl{terms}.
\end{prop}
\begin{proof}
    (In $\textsc{NC}^{1}$):
    Let $\algclass = \REL$ or $\DREL$.
    Let $\val_2 \colon \vsig \to \wp(\set{o,o'}^2)$ be the \kl{valuation} defined as $\val_2(a) \defeq \set{\tuple{o, o}, \tuple{o',o'}}$ for $a \in \vsig$, where $o \neq o'$
    (i.e., the \kl{graph} of $\val_2$ is the \kl{graph} \begin{tikzpicture}[baseline = -.5ex]
        \graph[grow up= 3.cm, branch right = .8cm, nodes={font=\tiny}]{
        {0/{$o$}[mynode, inner sep = .1em, minimum width = 1.2em], 1/{$o'$}[mynode, inner sep = .1em, minimum width = 1.2em]}
        };
        \graph[use existing nodes, edges={color=black, pos = .5, earrow}, edge quotes={fill = white, inner sep=1pt,font= \scriptsize}]{
        0 ->["$\vsig$", out = 150, in = 210, looseness = 8] 0; 
        1 ->["$\vsig$", out = 30, in = -30, looseness = 8] 1; 
        };
    \end{tikzpicture}).
    Clearly, $\val_2 \in \DREL$.
    Then, for all $\set{\eps, \emp, \compo, \union, \bl^{*}, \bl^{\smile}, \com{\eps}, \com{x}}$-\kl{terms} $\term$,
    every $\tilde{\vsig}_{\com{\eps}}$-labelled \kl{graph} in $\glang(\term)$ is \kl{graph homomorphic} to $\const{G}(\val_2, o, o)$ or $\const{G}(\val_2, o, o')$,
    by the form of the \kl{graph}.
    Thus, we have that $\algclass \models \term \le \emp$ iff $\glang(\term) = \emptyset$, as a corollary of \Cref{prop: glang}.
    Hence, in the same way as \Cref{prop: decidable PCoR* DREL emptiness}, this completes the proof.
    (Hardness):
    By the same proof as \Cref{prop: decidable PCoR* DREL emptiness}.
\end{proof}
