\subsection{Decidability on REL}\label{section: emptiness decidability REL}
Below, we show that, the \kl{emptiness problem} for $\PCoR_{\set{\bl^{*}, \com{\eps}, \com{x}}}$ is decidable on $\REL$.
\begin{thm}\label{thm: decidable ECoR* emptiness}
    The \kl{emptiness problem} on $\REL$ is $\textsc{PSpace}$-complete for $\PCoR_{\set{\bl^{*}, \com{\eps}, \com{x}}}$ and $\PCoR_{\set{\bl^{*}, \com{x}}}$.
\end{thm}
\begin{proof}
    (In $\textsc{PSpace}$):
    We recall the characterization using \emph{edge saturations} given in \cite[Theorem 18]{nakamuraExistentialCalculiRelations2023}.
    We say that a \kl{graph} $\graph[2]$ is \intro*\kl{consistent} if,
    for every $x, y \in \domain{\graph[2]}$,
    \begin{itemize}
        \item for each $a \in \vsig$, either $\tuple{x, y} \not\in a^{\graph[2]}$ or $\tuple{x, y} \not\in \com{a}^{\graph[2]}$ holds,
        \item if $x = y$, then $\tuple{x, y} \not\in \com{\eps}^{\graph[2]}$.
    \end{itemize}
    As a corollary of \cite[Theorem 18]{nakamuraExistentialCalculiRelations2023},
    we have that 
    \[\REL \not\models \term \le \emp \quad\iff\quad
    \mbox{there is some \kl{consistent} \kl{graph} in $\glang(\term)$.}\]
    To determine the right-hand side,
    it suffices to view only the source and target vertices in each inductive step of the construction of $\glang(\term)$.
    Let $\graph[1] \mathbin{\tilde{\compo}} \graph[2]$ be the \kl{subgraph} of the \kl{series-composition} $\graph[1] \compo \graph[2]$ with respect to the \kl{source} and \kl{target} vertex
    if the \kl{graph} $\graph[1] \compo \graph[2]$ is \kl{consistent},
    and undefined otherwise.
    For instance, if $\graph[1] = \left(\hspace{-.5em}\begin{tikzpicture}[baseline= 0.ex]
        \graph[grow up= 1.cm, branch right = .8cm, nodes={font=\tiny}]{
            {0/{}[mynode, fill = black, inner sep = .1em], 1/{}[mynode, fill = black, inner sep = .1em]};
        };
        \node[left = 4pt of 0](s){};\node[right = 4pt of 1](t){};
        \graph[use existing nodes, edges={color=black, pos = .5, earrow}, edge quotes={fill = white, inner sep=1pt,font= \scriptsize}]{
        (s) -> (0); (1) -> (t);
        (0) ->["$a$"] (1);
        0 ->["$a$", out = 60, in = 120, looseness = 50, loop] 0;
        1 ->["$b$", out = 60, in = 120, looseness = 50, loop] 1;
        };
    \end{tikzpicture}\hspace{-.5em}\right)$ and $\graph[2] = \left(\hspace{-.5em}\begin{tikzpicture}[baseline= 0.ex]
        \graph[grow up= 1.cm, branch right = .8cm, nodes={font=\tiny}]{
            {0/{}[mynode, fill = black, inner sep = .1em], 1/{}[mynode, fill = black, inner sep = .1em]};
        };
        \node[left = 4pt of 0](s){};\node[right = 4pt of 1](t){};
        \graph[use existing nodes, edges={color=black, pos = .5, earrow}, edge quotes={fill = white, inner sep=1pt,font= \scriptsize}]{
        (s) -> (0); (1) -> (t);
        (0) ->["$b$"] (1);
        0 ->["$b$", out = 60, in = 120, looseness = 50, loop] 0;
        1 ->["$\com{a}$", out = 60, in = 120, looseness = 50, loop] 1;
        };
    \end{tikzpicture}\hspace{-.5em}\right)$, then
    $\graph[1] \mathbin{\tilde{\compo}} \graph[2] = \left(\hspace{-.5em}\begin{tikzpicture}[baseline= 0.ex]
            \graph[grow up= 1.cm, branch right = .8cm, nodes={font=\tiny}]{
                {0/{}[mynode, fill = black, inner sep = .1em], 1/{}[mynode, fill = black, inner sep = .1em]};
            };
            \node[left = 4pt of 0](s){};\node[right = 4pt of 1](t){};
            \graph[use existing nodes, edges={color=black, pos = .5, earrow}, edge quotes={fill = white, inner sep=1pt,font= \scriptsize}]{
            (s) -> (0); (1) -> (t);
            %
            0 ->["$a$", out = 60, in = 120, looseness = 50, loop] 0;
            1 ->["$\com{a}$", out = 60, in = 120, looseness = 50, loop] 1;
            };
        \end{tikzpicture}\hspace{-.5em}\right)$ and $\graph[2] \mathbin{\tilde{\compo}} \graph[1]$ is undefined
        (as $\graph[1] \compo \graph[2]$ is \kl{consistent} and $\graph[2] \compo \graph[1]$ is not \kl{consistent}).
    We then define the \kl{graph language} $\tilde{\glang}(\term)$ in the same way as $\glang(\term)$ (\Cref{section: graph languages}),
    where the definition of $\glang(\term[1] \compo \term[2])$ has been replaced with
    $\tilde{\glang}(\term[1] \compo \term[2]) \defeq \set{\graph[1] \mathbin{\tilde{\compo}} \graph[2] \mid \graph[1] \in \tilde{\glang}(\term[1]), \graph[2] \in \tilde{\glang}(\term[2]),
    \mbox{ and $\graph[1] \mathbin{\tilde{\compo}} \graph[2]$ is defined}}$.
    By easy induction on $\term$, we have that
    $\glang(\term)$ has some \kl{consistent} \kl{graph} iff $\tilde{\glang}(\term)$ has some \kl{consistent} \kl{graph}.
    By definition, each \kl{graph} in $\tilde{\glang}(\term)$ has one or two \kl{vertices}, so we can memorize it in a space polynomial to the number of \kl{variables}.
    Thus, there is a naive non-deterministic polynomial space algorithm to determine whether $\REL \not\models \term \le \emp$.
    By the Savitch's theorem ($\mathsf{NPSPACE} = \textsc{PSpace}$) \cite{savitchRelationshipsNondeterministicDeterministic1970}, this completes the proof.

    (Hardness):
    From the proof of \cite[Theorem 5.1]{kozenHoareLogicKleene2000}
    (for showing the $\textsc{PSpace}$-hardness of propositional Hoare logic), the following problem is $\textsc{PSpace}$-complete:
    Given a set $\psig = \set{p_0, \dots, p_{2m-1}}$ (where $p_0, \dots, p_{2m-1}$ are pairwise distinct) of \kl{primitive tests} and \kl{tests} $b_1, \dots, b_n, b, c_1, \dots, c_n, c$ over \kl{primitive tests} $\psig$,
    to decide whether $\REL_{\mathtt{test}} \models b_1 \mathtt{x} c_1 \le \emp \to \dots \to b_n \mathtt{x} c_n \le \emp \to b \mathtt{x}^* c \le \emp$,\footnote{Note that $\REL_{\mathtt{test}} \models b \mathtt{x}^{*_{(c)}} \le \emp
    \leftrightarrow b \mathtt{x}^* c \le \emp$, cf. \cite[Theorem 5.1]{kozenHoareLogicKleene2000}.} where $\mathtt{x}$ is a fixed \kl{action}.
    We then have:
    \begin{align*}
        &\REL_{\mathtt{test}} \models b_1 \mathtt{x} c_1 \le \emp \to \dots \to b_n \mathtt{x} c_n \le \emp \to b \mathtt{x}^* c \le \emp\\
        &\Longleftrightarrow
        \REL_{\mathtt{test}} \models \mathtt{x} \le \tilde{b}_1 \mathtt{x} \union \mathtt{x} \tilde{c}_1 \to \dots \to \mathtt{x} \le \tilde{b}_n \mathtt{x} \union \mathtt{x} \tilde{c}_n \to b \mathtt{x}^* c \le \emp
        \tag{By $\REL_{\mathtt{test}} \models b \mathtt{x} c \le \emp \leftrightarrow \mathtt{x} \le \tilde{b} \mathtt{x} \union \mathtt{x} \tilde{c}$}\\
        &\Longleftrightarrow
        \REL_{\mathtt{test}} \models \mathtt{x} \le \bigcap_{i = 1}^{n} (\tilde{b}_i \mathtt{x} \union \mathtt{x} \tilde{c}_i) \to b \mathtt{x}^* c \le \emp \tag{By $\REL \models (\term[3] \le \term[1] \land \term[3] \le \term[2]) \leftrightarrow \term[3] \le \term[1] \cap \term[2]$}\\
        &\Longleftrightarrow
        \REL_{\mathtt{test}} \models \mathtt{x} = \bigcap_{i = 1}^{n} (\tilde{b}_i \mathtt{x} \union \mathtt{x} \tilde{c}_i) \to b \mathtt{x}^* c \le \emp \tag{By $\REL_{\mathtt{test}} \models \mathtt{x} \ge \bigcap_{i = 1}^{n} (\tilde{b}_i \mathtt{x} \union \mathtt{x} \tilde{c}_i)$}\\
        &\Longleftrightarrow
        \REL_{\mathtt{test}} \models b (\bigcap_{i = 1}^{n} (\tilde{b}_i \mathtt{x} \union \mathtt{x} \tilde{c}_i))^* c \le \emp \tag{By eliminating the hypothesis (\Cref{prop: REL axiom = substitution})}\\
        &\Longleftrightarrow
        \REL \models (b (\bigcap_{i = 1}^{n} (\tilde{b}_i \mathtt{x} \union \mathtt{x} \tilde{c}_i))^* c)[q_0^{\lop}/p_0] \dots [q_{m-1}^{\lop}/p_{m-1}][\com{q}_0^{\lop}/p_m] \dots [\com{q}_{m-1}^{\lop}/p_{2m-1}] \le \emp. \tag{By eliminating $\mathtt{test}$ (\Cref{ex: substitution tests})}
    \end{align*}
    Here, $q_0, \dots, q_{m-1}$ are \kl{fresh} \kl{variables}.
    As the left-hand side term is a $\PCoR_{\set{\bl^{*}, \com{x}}}$-\kl{term}, this completes the proof.
\end{proof}
For the $\bl^{*}$-free fragment,
the \kl{emptiness problem} is $\textsc{coNP}$-complete, as follows.
\begin{cor}\label{cor: decidable ECoR* emptiness}
    The \kl{emptiness problem} on $\REL$ is $\textsc{coNP}$-complete for $\PCoR_{\set{\com{\eps}, \com{x}}}$.
\end{cor}
\begin{proof}
    (In $\textsc{coNP}$):
    By the same algorithm as \Cref{thm: decidable ECoR* emptiness}.
    When Kleene-star $\bl^{*}$ does not occur, the non-deterministic algorithm terminates in polynomial time.
    (Hardness):
    Because the \kl{emptiness problem} of $\set{\union, \compo, \com{x}}$-\kl{terms} is equal to the boolean unsatisfiability problem \cite{bussBooleanFormulaValue1987}, which is $\textsc{coNP}$-hard.
\end{proof}
For the $\com{x}$-free fragment,
the \kl{emptiness problem} is $\textsc{NC}^{1}$-complete, as follows.
\begin{cor}\label{cor: decidable PCoR* emptiness difference}
    The \kl{emptiness problem} on $\REL$ is $\textsc{NC}^{1}$-complete for $\PCoR_{\set{\bl^{*}, \com{\eps}}}$.
\end{cor}
\begin{proof}
    (In $\textsc{NC}^{1}$):
    We recall the proof of \Cref{thm: decidable ECoR* emptiness}.
    Similarly,
    we define $\tilde{\glang}'(\term)$ as the same as $\tilde{\glang}(\term)$,
    where the definition of $\tilde{\glang}'(x)$ has been replaced with $\tilde{\glang}'(x) \defeq \set{\hspace{-.5em}\begin{tikzpicture}[baseline= -.5ex]
        \graph[grow up= 1.cm, branch right = .8cm, nodes={font=\tiny}]{
            {0/{}[mynode, fill = black, inner sep = .1em], 1/{}[mynode, fill = black, inner sep = .1em]};
        };
        \node[left = 4pt of 0](s){};\node[right = 4pt of 1](t){};
        \graph[use existing nodes, edges={color=black, pos = .5, earrow}, edge quotes={fill = white, inner sep=1pt,font= \scriptsize}]{
        (s) -> (0); (1) -> (t);
        };
    \end{tikzpicture}\hspace{-.5em}}$ for $x \in \vsig$.
    Because $\com{x}$ does not appear in $\PCoR_{\set{\bl^{*}, \com{\eps}}}$, we have that ($\REL \models \term \le \emp$ iff) $\tilde{\glang}(\term)$ has a \kl{consistent} \kl{graph} iff $\tilde{\glang}'(\term)$ has a \kl{consistent} \kl{graph}.
    The universe of $\tilde{\glang}'(\term)$ is bounded by a fixed finite set (of $2^{1^2} + 2^{2^2} = 18$ $\com{\eps}$-labelled \kl{graphs} up to \kl{graph isomorphisms}).
    Thus, we can reduce this problem into the evaluation of a fixed finite algebra (with $2^{18}$ values),
    which is in $\textsc{NC}^{1}$ \cite[Corollary 1]{lohreyParallelComplexityTree2001}.
    (Hardness):
    By the same proof as \Cref{prop: decidable PCoR* DREL emptiness}.
\end{proof}

\subsection{Remark on the coNP-hardness when the number of primitive tests is fixed}
Additionally, 
we have the following two $\textsc{coNP}$-hardness results by a similar argument as \Cref{cor: NP-complete while emptiness}.
(When the number of \kl{primitive tests} is not fixed, they are trivially $\textsc{coNP}$-complete in the same way as \Cref{rem: NP-complete}.)
\begin{cor}\label{cor: undecidable PCoR variable emptiness}
    The \kl{emptiness problem} on $\DREL$ is $\textsc{coNP}$-complete
    for $\PCoR_{\set{\com{x}}}$ \kl{terms} (more precisely, $\set{\compo, \union, \bl^{\lop}, \com{x}}$-\kl{terms}) such that
    the number of \kl{actions} is $4$ and the number of \kl{primitive tests} is $1$.
\end{cor}
\begin{proof}
    (In $\textsc{coNP}$):
    By \Cref{prop: upper bound}.
    (Hardness):
    By replacing each $\bl^{+_{b}}$ with $\bl^{(n)_{b}}$
    in the proof of \Cref{cor: undecidable PCoR* variable emptiness} (similar to \Cref{cor: NP-complete while emptiness}).
\end{proof}

\begin{cor}\label{cor: undecidable PCoR difference emptiness}
    The \kl{emptiness problem} on $\DREL$ is $\textsc{coNP}$-complete
    for $\PCoR_{\set{\com{\eps}}}$ \kl{terms} (more precisely, $\set{\compo, \union, \bl^{\lop}, \com{\eps}}$-\kl{terms}) such that
    the number of \kl{actions} is $4$ and the number of \kl{primitive tests} is $1$.
\end{cor}
\begin{proof}
    (In $\textsc{coNP}$):
    By \Cref{prop: upper bound}.
    (Hardness):
    By replacing each $\bl^{+_{b}}$ with $\bl^{(n)_{b}}$
    in the proof of \Cref{cor: undecidable PCoR* difference emptiness} (similar to \Cref{cor: NP-complete while emptiness}).
\end{proof}

