\section{On \Cref{rem: Hoare KA}: $\top$ vs $A^*$ in Hoare hypothesis eliminations}\label{section: Hoare hypothesis KA}
In this section, we give the \kl{Hoare hypothesis} elimination using $A^*$ (of \Cref{rem: Hoare KA}) via \Cref{prop: Hoare hypotheses}.
In the sequel, we consider \kl{Kleene lattice} (\kl{KL}) terms: the class of $\set{\eps, \emp, \compo, \union, \bl^{*}, \cap}$-\kl{terms}.
We use the following property of \kl{KL} \kl{terms}.
\begin{prop}\label{prop: KL graph}
    Let $A$ be a set.
    Let $\term$ be a \kl{KL} \kl{term} with $\vsig(\term) \subseteq A$, and let $\graph[2] \in \glang(\term)$ be a \kl{graph}.
    Then, every vertex in $\graph[2]$ has an $A^*$-path from the \kl{source} and has an $A^*$-path to the \kl{target}.
\end{prop}
\begin{proof}
    By easy induction on $\term$.
\end{proof}
For a \kl{valuation} $\val \colon \vsig \to \wp(Z^2)$, sets $X, Y \subseteq Z$,
and a \kl{term} $\term[3]$, 
the $\term[3]$-\intro*\kl{interval} $[X, Y]_{\val, \term[3]}$ is defined as
\[ [X, Y]_{\val, \term[3]} \defeq \set{z \in Z \mid \exists x \in X, y \in Y, \tuple{x, z} \in \hat{\val}(\term[3]) \land \tuple{z, y} \in \hat{\val}(\term[3])}.\]
Namely, $[X, Y]_{\val, \term[3]}$ is the set of vertices having an $\term[3]$-path from some vertex in $X$ and an $\term[3]$-path to some vertex in $Y$.
Using \Cref{prop: KL graph}, we have the following.
\begin{prop}\label{prop: interval}
    Let $Z$ be a set.
    Let $\val \colon \vsig \to \wp(Z^2)$ in $\REL$.
    Let $X, Y \subseteq Z^2$ and $x_0, y_0 \in [X, Y]_{\val, A^*}$.
    For all \kl{KL} \kl{terms} $\term[1]$ with $\vsig(\term[1]) \subseteq A$,
    we have:
    \[\tuple{x_0, y_0} \in \hat{\val}(\term[1]) \quad\Longrightarrow\quad \tuple{x_0, y_0} \in \reallywidehat{(\val \restriction [X, Y]_{\val, A^*})}(\term[1]).\]
\end{prop}
\begin{proof}
    By $\tuple{x_0, y_0} \in \hat{\val}(\term[1])$ with \Cref{prop: glang}, there is a \kl{graph homomorphism} $h \colon \graph[2] \homo \const{G}(\val, x, y)$ for some $\graph[2] \in \glang(\term[1])$.
    By the form of $\graph[2]$ (\Cref{prop: KL graph}) with $h(x_0), h(y_0) \in [X, Y]_{\val, A^*}$,
    we have $h(\graph[2]) \subseteq [X, Y]_{\val, A^*}$.
    Thus, $\tuple{x_0, y_0} \in \reallywidehat{\val \restriction [X, Y]_{\val, A^*}}(\term)$ still holds, by the same $h$.
\end{proof}
We also prepare the following fact.
\begin{prop}\label{prop: point extension}
    Let $\algclass \subseteq \REL$.
    For all \kl{terms} $\term[1], \term[2]$, when $x$ and $y$ are \kl{fresh} in $\algclass \models \term[1] \le \term[2]$, we have:
    \[\algclass \models \term[1] \le \term[2] \quad\Longleftrightarrow\quad \algclass_{x \le \eps, y \le \eps} \models x \term[1] y \le x \term[2] y.\]
\end{prop}
\begin{proof}
    ($\Longleftarrow$):
    By
    $\algclass_{x = \eps, y = \eps} \models x \term[1] y \le x \term[2] y$
    iff $\algclass_{x = \eps, y = \eps} \models \term[1] \le \term[2]$
    iff $\algclass \models \term[1] \le \term[2]$ ($x, y$ are fresh).
    ($\Longrightarrow$):
    By the congruence law.
\end{proof}
By applying \Cref{prop: interval,prop: point extension} to \Cref{prop: Hoare hypotheses}, we have the \kl{Hoare hypothesis} elimination of \Cref{rem: Hoare KA}.
\begin{thm}\label{thm: Hoare hypothesis elimination interval}
    Let $A$ be a finite set.
    Let $\algclass \subseteq \REL$ be such that $\algclass$ is closed under taking \kl{submodels} with respect to $A^*$-\kl{intervals}.
    Let $\term[1]$ be a \kl{KL} \kl{terms} with $\vsig(\term[1]) \subseteq A$ and let $\term[2], \term[3]$ be $\PCoR_{\set{\bl^{*}, \com{\eps}, \com{x}}}$ \kl{terms}.
    Then,
    \[\algclass_{\term[3] \le \emp} \models \term[1] \le \term[2] \quad\Longleftrightarrow\quad \algclass \models \term[1] \le \term[2] \union A^* \term[3] A^*.\]
\end{thm}
\begin{proof}
    Let $x$ and $y$ be distinct fresh \kl{variables} in $\algclass_{\term[3] \le \emp} \models \term[1] \le \term[2]$.
    By \Cref{prop: Hoare hypotheses,prop: point extension}, it suffices to show the following:
    \[\algclass_{x \le \eps, y \le \eps} \models x \term[1] y \le x (\term[2] \union \top \term[3] \top) y \quad\Longleftrightarrow\quad \algclass_{x \le \eps, y \le \eps} \models x \term[1] y \le x (\term[2] \union A^* \term[3] A^*) y.\]
    Let $\algclass' \defeq \set{\val \restriction [X_{\val}, Y_{\val}]_{\val, A^*} \mid \val \in \algclass_{x \le \eps, y \le \eps}}$
    where 
    $X_{\val}$ and $Y_{\val}$ are such that $\Delta_{X_{\val}} = \hat{\val}(x)$ and $\Delta_{Y_{\val}} = \hat{\val}(y)$.
    Then, $\algclass' \subseteq \algclass$ (as $\algclass$ is closed under taking \kl{submodels} with respect to $A^*$-\kl{intervals}).
    Also, $\algclass'$ is a \kl{witness-basis} of $\algclass$ for $x \term y$, by applying \Cref{prop: interval} to $\term$.
    Thus by applying \Cref{prop: submodel cover} to both sides of the above equivalence, it suffices to show the following:
    \[\algclass' \models x \term[1] y \le x (\term[2] \union \top \term[3] \top) y \quad\Longleftrightarrow\quad \algclass' \models x \term[1] y \le x (\term[2] \union A^* \term[3] A^*) y.\]
    Then by the definition of $[X_{\val}, Y_{\val}]_{\val, A^*}$, we have $\algclass' \models x \top = x A^* \land \top y = A^* y$.
    Hence, this completes the proof.
\end{proof}

\begin{rem}
    \Cref{thm: Hoare hypothesis elimination interval} 
    does not hold for arbitrary class $\algclass \subseteq \REL$, cf.\ \Cref{prop: Hoare hypotheses}.
    For example, let us consider the class $\algclass \defeq \set{\val}$ where the \kl{valuation} $\val$ is given by the following \kl{graph}:
    $\begin{tikzpicture}[baseline = -.5ex]
            \graph[grow up= 1.cm, branch right = 1.cm, nodes={font=\tiny}]{
            {0/{$0$}[mynode, fill = gray!30], 1/{$1$}[mynode, fill = gray!30], 2/{$2$}[mynode, fill = gray!30]}
            };
            \graph[use existing nodes, edges={color=black, pos = .5, earrow}, edge quotes={fill = white, inner sep=1pt,font= \scriptsize}]{
            (0) ->["$a$"] (1) ->["$a$"] (2);
            };
        \end{tikzpicture}$.
    Then, $\algclass_{a a \le \emp} \models a \le \emp$ (by $\algclass_{a a \le \emp} = \emptyset$) and $\algclass \not\models a \le \emp \union A^* a a A^*$ where $A =\set{a}$ (by $\tuple{0,1} \in \hat{\val}(a) \setminus \hat{\val}(A^* a a A^*)$).
\end{rem}

\subsection{On REL with hypotheses}\label{subsection: Hoare Hypothesis elimination hypotheses}
\Cref{thm: Hoare hypothesis elimination interval} can apply to the \kl{Hoare hypothesis} elimination for $\REL_{\Gamma}$, as follows.
\begin{cor}\label{cor: Hoare hypothesis elimination}
    Let $A$ be a finite set.
    Let $\term[2]_i', \term[1]$ be \kl{KL} \kl{terms} with $\vsig(\term[2]_i'), \vsig(\term[1]) \subseteq A$
    and let $\term[1]_i', \term[2], \term[3]$ be $\PCoR_{\set{\bl^{*}, \com{\eps}, \com{x}}}$ \kl{terms} where $i$ ranges over an indexed set $I$,
    and let $\Gamma \defeq \set{\term[1]_i' \le \term[2]_i' \mid i \in I}$.
    We have:
    \[\REL_{\Gamma, \term[3] \le \emp} \models \term[1] \le \term[2] \quad\Longleftrightarrow\quad \REL_{\Gamma} \models \term[1] \le \term[2] \union A^* \term[3] A^*.\]
\end{cor}
\begin{proof}
    By using the \kl{graph homomorphism} from \Cref{prop: glang} and \Cref{prop: interval} for $\term[1]_i'$,
    we have:
    $\val \models \term[1]_i' \le \term[2]_i' \Longrightarrow \val \restriction [X, Y]_{\val, A^*} \models \term[1]_i' \le \term[2]_i'$.
    Thus, $\REL_{\Gamma}$ is closed under taking \kl{submodels} with respect to $A^*$-\kl{intervals}.
    This completes the proof by \Cref{thm: Hoare hypothesis elimination interval}.
\end{proof}
\Cref{cor: Hoare hypothesis elimination} is an extension of the \kl{Hypothesis elimination} known in \kl{KA} \kl{terms} (see \cite[Theorem 27]{hardinProofTheoryKleene2005}\cite[Theorem 3.2 (3.3)]{hardinModularizingElimination$r0$2005} for $\REL_{\Gamma}$); below is a slightly simplified version of \Cref{cor: Hoare hypothesis elimination} for \kl{KL} \kl{terms}.
\begin{cor}\label{cor: Hoare hypothesis elimination KL}
    Let $A$ be a finite set.
    Let $\Gamma$ be a set of \kl{KL} \kl{equations} and let $\term[1], \term[2], \term[3]$ be \kl{KL} \kl{terms}.
    When $\vsig(\Gamma), \vsig(\term[1]) \subseteq A$, we have:
    \[\REL_{\Gamma, \term[3] \le \emp} \models \term[1] \le \term[2] \quad\Longleftrightarrow\quad \REL_{\Gamma} \models \term[1] \le \term[2] \union A^* \term[3] A^*.\]
\end{cor}
\begin{proof}
    By \Cref{cor: Hoare hypothesis elimination}.
\end{proof}

\subsection{On the converse extension}\label{subsection: Hoare Hypothesis elimination converse}
As a corollary of \Cref{thm: Hoare hypothesis elimination interval},
when we extend \kl{KL} \kl{terms} $\term$ with converse ($\bl^{\smile}$) (so-called \kl{Kleene allegory} \kl{terms}), we have the following \kl{Hoare hypothesis} elimination.
\begin{cor}\label{thm: Hoare hypothesis elimination interval KAL}
    Let $A$ be a finite set.
    Let $\breve{A} \defeq \set{a, a^{\smile} \mid a \in A}$.
    Let $\algclass \subseteq \REL$ be such that $\algclass$ is closed under taking \kl{submodels} with respect to $\breve{A}^*$-\kl{intervals}.
    Let $\term[1]$ be a \kl{Kleene allegory} \kl{terms} with $\vsig(\term[1]) \subseteq A$ and let $\term[2], \term[3]$ be $\PCoR_{\set{\bl^{*}, \com{\eps}, \com{x}}}$ \kl{terms}.
    Then,
    \[\algclass_{\term[3] \le \emp} \models \term[1] \le \term[2] \quad\Longleftrightarrow\quad \algclass \models \term[1] \le \term[2] \union \breve{A}^{*} \term[3] \breve{A}^{*}.\]
\end{cor}
\begin{proof}[Proof Sketch]
    By pushing the converse operator inside as much as possible and viewing each $a^{\smile}$ (where $a \in A$) as a \kl{variable},
    we can apply \Cref{thm: Hoare hypothesis elimination interval}.
\end{proof}

