\section{More examples of substitution hypotheses}\label{section: substitution examples}
In this section, we give more examples of \kl{substitution hypotheses} (\Cref{prop: REL axiom = substitution}).
\begin{ex}[{\cite[Lem. 3.8 (v)]{pousToolsCompletenessKleene2024}}]\label{ex: substitution transitive}
    Consider $xx \le x$ where $x$ is a \kl{variable}.
    Let $\Gamma$ be a set of \kl{equations} such that $x \not\in \vsig(\Gamma)$.
    Then $x$ is \kl{fresh} in $\REL_{\Gamma}$.
    Thus we have:
    \[\REL_{\Gamma, xx \le x} \models \term[1] = \term[2] \quad\Longleftrightarrow\quad \REL_{\Gamma} \models (\term[1] = \term[2])[x^+/x],\]
    because $\REL \models x x \le x \leftrightarrow x = x^{+}$
    and $\REL \models x^{+} = x^{+}[x^{+}/x]$.
\end{ex}
\begin{ex}[{\cite[Lem. 3.8 (iv)]{pousToolsCompletenessKleene2024}}]\label{ex: substitution transitive 2}
    Consider $x \term[3] \le x$ where $x$ is a \kl{variable} and $x \not\in \vsig(\term[3])$.
    When $x \not\in \vsig(\Gamma)$, we have:
    \[\REL_{\Gamma, x\term[3] \le x} \models \term[1] = \term[2] \quad\Longleftrightarrow\quad \REL_{\Gamma} \models (\term[1] = \term[2])[x \term[3]^*/x],\]
    because $\REL \models x \term[3] \le x \leftrightarrow x = x \term[3]^*$
    and $\REL \models x \term[3]^* = (x \term[3]^*)[x \term[3]^*/x]$.
\end{ex}
\begin{ex}[{\cite[Lem. 3.4]{hardinEliminationHypothesesKleene2002}}]\label{ex: substitution unused code}
    Consider $b x = b$ where $x$ is a \kl{variable} and $b$ is a \kl{test} (here, $x \not\in \vsig(b)$).
    When $x \not \in \vsig(\Gamma)$, we have:
    \[\REL_{\mathtt{test}, \Gamma, b x = b} \models \term[1] = \term[2] \quad\Longleftrightarrow\quad \REL_{\mathtt{test}, \Gamma} \models (\term[1] = \term[2])[\tilde{b} x \union b/x],\]
    because $\REL_{\mathtt{test}} \models b x = b \leftrightarrow x = \tilde{b} x \union b$ \cite[Lem. 2.1]{hardinEliminationHypothesesKleene2002} and $\REL \models \tilde{b} x \union b = (\tilde{b} x \union b)[\tilde{b} x \union b/x]$.
\end{ex}

