\section{A reduction from the difference constant into variable complements}\label{section: differnce encoding}
In this section,
we show that we can eliminate the difference constant $\com{\eps}$ using variable complements.
Let $\mathtt{Q}$ be a special \kl{variable}.
We recall the translation $\Tr$ given in \Cref{defi: loop transformation}.
For each \kl{valuation} $\val$ such that $\val(\mathtt{Q})$ is an equivalence relation,
we write $[x]_{\sim_{\mathtt{Q}}}$ for the equivalence class of $x$ with respect to the equivalence relation $\val(\mathtt{Q})$
and write $\val/\mathtt{Q}$ for the \intro*\kl{quotient} of $\val$ with respect to the equivalence relation $\hat{\val}(\mathtt{Q})$,
i.e., $(\val/\mathtt{Q})(a) \defeq \set{\tuple{[x]_{\sim_{\mathtt{Q}}}, [y]_{\sim_{\mathtt{Q}}}} \mid \tuple{x, y} \in \val(a)}$.
We say that $\val$ is \emph{consistent} for a \kl{variable} set $A$ if $\hat{\val}((\mathtt{Q} a \mathtt{Q}) \cap (\mathtt{Q} \com{a} \mathtt{Q})) = \emptyset$ for each $a \in A$.
\begin{lem}\label{lem: id}
    Let $\val \in \REL$.
    Suppose that $\val(\mathtt{Q})$ is an equivalence relation and $\val$ is consistent for a set $A$.
    For all \kl{terms} $\term[1]$ such that $\vsig(\term[1]) \subseteq A$, we have:
    \[\tuple{[x]_{\sim_{\mathtt{Q}}}, [y]_{\sim_{\mathtt{Q}}}} \in \widehat{\val/{\mathtt{Q}}}(\term[1]) \quad\iff\quad \tuple{x, y} \in \hat{\val}(\Tr_{\mathtt{Q}}(\term[1])).\]
\end{lem}
\begin{proof}
    By easy induction on $\term$.
\end{proof}

\begin{prop}\label{prop: id}
    Let $\algclass \subseteq \REL$ and $A \subseteq \vsig$ be a set.
    Suppose that, for all $\val \in \algclass$, $\val(\mathtt{Q})$ is an equivalence relation and $\val$ is consistent for $A$.
    When $\algclass$ is closed under \kl{quotients} with respect to $\mathtt{Q}$,
    we have that, for all $\term[1], \term[2]$ such that $\vsig(\term[1]) \cup \vsig(\term[2]) \subseteq A$,
    \[\algclass_{\mathtt{Q} = \eps} \models \term[1] \le \term[2] \quad\iff\quad \algclass \models \Tr_{\mathtt{Q}}(\term[1]) \le \Tr_{\mathtt{Q}}(\term[2]).\]
\end{prop}
\begin{proof}
    ($\Longleftarrow$):
    Because $\algclass \models \mathtt{Q} = \eps \to \term[3][\mathtt{Q}/\eps] = \term[3]$ for all $\term[3]$.
    ($\Longrightarrow$):
    By \Cref{lem: id} with $\val/{\mathtt{Q}} \in \algclass_{\mathtt{Q} = \eps}$ for all $\val \in \algclass$ (as $\algclass$ is closed under \kl{quotients} with respect to $\mathtt{Q}$ and $\val/{\mathtt{Q}} \models \mathtt{Q} = \eps$).
\end{proof}

\begin{thm}\label{thm: id}
    For $\set{\union, \compo, \bl^{+}, \bl^{\lop}} \subseteq S$,
    there is a polynomial-time reduction from the \kl{equational theory} for $S$-\kl{terms} to \kl[equational theory]{that} for the term class $((S \setminus \set{\com{\eps}}) \cup \set{\com{x}})$-\kl{terms}, with respect to $\REL$.
\end{thm}
\begin{proof}
    Let $A = \set{a_1, \dots, a_n}$ be a finite set (of \kl{variables}) such that $\vsig(\term[1]) \cup \vsig(\term[2]) \subseteq A$
    and let $\mathtt{Q}$ be a fresh \kl{variable}.
    Let us consider the following hypotheses:
    \begin{align*}
        \mathtt{i}_0 &\defeq \set{\mathtt{Q} \le \eps},\\
        \mathtt{i}_1 &\defeq \set{\mathtt{Q} \ge \eps},\\
        \mathtt{i}_2 &\defeq \set{(\mathtt{Q} \com{\mathtt{Q}}^{\smile})^{\lop} = \emp }, \tag*{($\REL \models (\mathtt{Q} \com{\mathtt{Q}}^{\smile})^{\lop} = \emp \leftrightarrow \mathtt{Q} = \mathtt{Q}^{\smile}$)}\\
        \mathtt{i}_3 &\defeq \set{\mathtt{Q} = \mathtt{Q}^{+}}, \tag*{($\REL \models \mathtt{Q} = \mathtt{Q}^{+} \leftrightarrow \mathtt{Q} \mathtt{Q} \le \mathtt{Q}$; \Cref{ex: substitution transitive})}\\
        \mathtt{i}_4 &\defeq \set{(a \mathtt{Q} \com{a}^{\smile} \mathtt{Q})^{\lop} = \emp \mid a \in A}. \tag*{($\REL_{\mathtt{i}_{\set{0, 1, 2, 3}}} \models (a \mathtt{Q} \com{a}^{\smile} \mathtt{Q})^{\lop} = \emp \leftrightarrow (\mathtt{Q} a \mathtt{Q}) \cap (\mathtt{Q} \com{a} \mathtt{Q}) = \emp$)}
    \end{align*}
    We also let $\mathtt{i}_{S} \defeq \bigcup_{j \in S} \mathtt{i}_j$ for $S \subseteq \set{0,1,2,3,4}$.
    By construction, for each $\val \in \REL$, $\val \models \mathtt{i}_{\set{1, 2, 3, 4}}$ iff $\val(\mathtt{Q})$ is an equivalence relation (by $\mathtt{i}_{1,2,3}$) and $\val$ is consistent for $A$ (by $\mathtt{i}_{4}$).
    Let $\term[3]_{\set{2, 4}} \defeq (\mathtt{Q} \mathtt{Q}^{\smile})^{\lop} \union \sum_{a \in A} (\mathtt{Q} a \mathtt{Q} \com{a}^{\smile} \mathtt{Q})^{\lop}$.
    We then have:
    \begin{align*}
        & \REL \models \term[1] \le \term[2]\\
        & \Leftrightarrow \REL_{\mathtt{i}_{\set{0, 1, 2, 3, 4}}} \models \term[1] \le \term[2] \tag{by replacing $\val(\mathtt{Q})$ with the identity relation, as $\mathtt{Q}$ is fresh}\\
        & \Leftrightarrow \REL_{\mathtt{i}_{\set{1, 2, 3, 4}}} \models \Tr_{\mathtt{Q}}(\term[1]) \le \Tr_{\mathtt{Q}}(\term[2]) \tag{\Cref{prop: id}}\\
        & \Leftrightarrow \REL_{\mathtt{i}_{\set{1, 3}}} \models \Tr_{\mathtt{Q}}(\term[1]) \le \Tr_{\mathtt{Q}}(\term[2]) \union \top \term[3]_{\set{2,4}} \top \tag{\Cref{prop: Hoare hypotheses}}\\
        & \Leftrightarrow \REL_{\mathtt{i}_{\set{3}}} \models \mathtt{T}_{\mathtt{Q}^{\lop}}(\Tr_{\mathtt{Q}}(\term[1])) \le \Tr_{\mathtt{Q}}(\term[2]) \union \top \term[3]_{\set{2,4}} \top \tag{\Cref{thm: hypothesis elimination using graph loops 2}}\\
        & \Leftrightarrow \REL \models \mathtt{T}_{\mathtt{Q}^{\lop}}(\Tr_{\mathtt{Q}}(\term[1]))[\mathtt{Q}^{+}/\mathtt{Q}] \le (\Tr_{\mathtt{Q}}(\term[2]) \union \top \term[3]_{\set{2,4}} \top)[\mathtt{Q}^{+}/\mathtt{Q}]. \tag{\Cref{ex: substitution transitive}}
    \end{align*}
    Thus, we can reduce the \kl{equational theory} for $S$-\kl{terms} to the \kl{equational theory} for $((S \setminus \set{\com{\eps}}) \cup \set{\com{x}, \bl^{\smile}})$-\kl{terms},
and thus to \kl[equational theory]{that} for $((S \setminus \set{\com{\eps}}) \cup \set{\com{x}})$-\kl{terms} by the reduction of \Cref{ex: converse}.
\end{proof}

