\section{Detailed proof of \Cref{prop: glang u}}\label{section: prop: glang u}
(The following proof is in the same way as \cite[Prop.\ 8 and 11]{nakamuraExistentialCalculiRelations2023}.
Similar arguments can be found, e.g., in \cite{andrekaEquationalTheoryUnionfree1995,brunetPetriAutomata2017,pousPositiveCalculusRelations2018}.)

We use the two notations for \kl{graphs}, \kl{series-composition} ($\compo$) and \kl{parallel-composition} ($\cap$):
\begin{align*}
       G \compo H
        & \quad\defeq\quad \begin{tikzpicture}[baseline = -.5ex]
                        \graph[grow right = 1.cm, branch down = 2.5ex, nodes={mynode, font = \scriptsize}]{
                        {s1/{}[draw, circle]}
                        -!- {c/{}[draw, circle]}
                        -!- {t1/{}[draw, circle]}
                        };
                        \node[left = 4pt of s1](s1l){} edge[earrow, ->] (s1);
                        \node[right = 4pt of t1](t1l){}; \path (t1) edge[earrow, ->] (t1l);
                        \graph[use existing nodes, edges={color=black, pos = .5, earrow}, edge quotes={fill=white, inner sep=1pt,font= \scriptsize}]{
                        s1 ->["$G$"] c;
                        c ->["$H$"] t1;
                        };
                 \end{tikzpicture}
        & G \cap H
        & \quad\defeq\quad \begin{tikzpicture}[baseline = -.5ex]
                        \graph[grow right = 1.cm, branch down = 2.5ex, nodes={mynode, font = \scriptsize}]{
                        {s1/{}[draw, circle]}
                        -!- {t1/{}[draw, circle]}
                        };
                        \node[left = 4pt of s1](s1l){} edge[earrow, ->] (s1);
                        \node[right = 4pt of t1](t1l){}; \path (t1) edge[earrow, ->] (t1l);
                        \graph[use existing nodes, edges={color=black, pos = .5, earrow}, edge quotes={fill=white, inner sep=1pt,font= \scriptsize}]{
                        s1 ->["$G$", bend left = 25] t1;
                        s1 ->["$H$", bend right = 25] t1;
                        };
                 \end{tikzpicture}.
\end{align*}

\begin{prop}\label{lem: glang val op}
       Let $\val \in \REL$ and $\graph[1], \graph[2]$ be \kl{graphs}.
       \begin{align*}
              \label{lem: glang val cap} \hat{\val}(\graph[1] \cap \graph[2])     & = \hat{\val}(\graph[1]) \cap \hat{\val}(\graph[2]) \tag{\Cref{lem: glang val op}$\cap$}     \\
              \label{lem: glang val compo} \hat{\val}(\graph[1] \compo \graph[2]) & = \hat{\val}(\graph[1]) \compo \hat{\val}(\graph[2]) \tag{\Cref{lem: glang val op}$\compo$}
       \end{align*}
\end{prop}
\begin{proof}
       (\ref{lem: glang val cap}):
       It suffices to prove that for every $x, y$, the following are equivalent:
       \begin{itemize}
        \item $\exists f, f \colon (\graph[1] \cap \graph[2]) \homo \const{\graph}(\val, x, y)$;
        \item $\exists f_{\graph[1]}, f_{\graph[2]},\  f_{\graph[1]} \colon \graph[1] \homo \const{\graph}(\val, x, y) \land f_{\graph[2]} \colon \graph[2] \homo \const{\graph}(\val, x, y)$.
       \end{itemize}
       $\Rightarrow$:
       By letting $f_{\graph[1]} = \set{\tuple{x', f(x')} \mid x' \in |\graph[1]|}$ and $f_{\graph[2]} = \set{\tuple{x', f(x')} \mid x' \in |H|}$.
       $\Leftarrow$:
       By letting $f = f_{\graph[1]} \cup f_{\graph[2]}$.
       Note that $f_{\graph[1]}(\src^{\graph[1]}) = x = f_{\graph[2]}(\src^{\graph[2]})$ and $f_{\graph[1]}(\tgt^{\graph[1]}) = y = f_{\graph[2]}(\tgt^{\graph[2]})$; so $f$ is indeed a map.

       (\ref{lem: glang val compo}):
       It suffices to prove that for every $x, y$, the following are equivalent:
       \begin{itemize}
        \item $\exists f, f \colon (\graph[1] \compo \graph[2]) \homo \const{\graph}(\val, x, y)$;
        \item $\exists z, \exists f_{\graph[1]}, f_{\graph[2]},\  f_{\graph[1]} \colon \graph[1] \homo \const{\graph}(\val, x, z) \land f_{\graph[2]} \colon \graph[2] \homo \const{\graph}(\val, z, y)$.
       \end{itemize}
       $\Rightarrow$:
       By letting $z = f(\tgt^{\graph[1]})$, $f_{\graph[1]} = \set{\tuple{x', f(x')} \mid x' \in |\graph[1]|}$, and $f_{\graph[2]} = \set{\tuple{x', f(x')} \mid x' \in |\graph[2]|}$.
       $\Leftarrow$:
       By letting $f = f_{\graph[1]} \cup f_{\graph[2]}$.
       Note that $f_{\graph[1]}(\tgt^{\graph[1]}) = z = f_{\graph[2]}(\src^{\graph[2]})$; so $f$ is indeed a map.
\end{proof}

\begin{prop}\label{lem: glang val op u}
    Let $\val \in \REL$ and $\graph[1], \graph[2]$ be \kl{graphs}.
    Let $\glang$ be a set of \kl{graphs}.
    \begin{align*}
           \label{lem: glang val cap u} \bigcup_{\substack{f \colon \domain{\graph[1]} \to \glang,\\
           g \colon \domain{\graph[2]} \to \glang}} \hat{\val}(\graph[1][f] \cap \graph[2][g])
           &= \bigcup_{\substack{h \colon \domain{\graph[1] \cap \graph[2]} \to \glang}}          \hat{\val}((\graph[1] \cap \graph
           [2])[h]) \tag{\Cref{lem: glang val op u}$\cap$}     \\
           \label{lem: glang val compo u} \bigcup_{\substack{f \colon \domain{\graph[1]} \to \glang,\\
           g \colon \domain{\graph[2]} \to \glang}} \hat{\val}(\graph[1][f] \compo \graph[2][g])
           &= \bigcup_{\substack{h \colon \domain{\graph[1] \compo \graph[2]} \to \glang}}          \hat{\val}((\graph[1] \compo \graph
           [2])[h]) \tag{\Cref{lem: glang val op u}$\compo$}    
    \end{align*}
\end{prop}
\begin{proof}
    ($\supseteq$): By letting $f(z) = h(z)$ and $g(z) = h(z)$.
    ($\subseteq$): By letting $h(z) = \begin{cases}
    f(z) & (z \in \domain{\graph[1]})\\
    g(z) & (\mbox{otherwise})
\end{cases}$ (either one is fine for $z \in \domain{\graph[1]} \cap \domain{\graph[2]}$). %
\end{proof}

\begin{proof}[Proof of \Cref{prop: glang u}]
       By easy induction on $\term$.

       Case $a$ where $a \in \tilde{\vsig} = \set{a, \com{a} \mid a \in \vsig} \cup \set{\com{\eps}, \top}$:
       For $\tuple{x, y} \in \hat{\val}(\top)$, we have
       \begin{align*}
              \tuple{x, y} \in \hat{\val}(\Tr_{\term[3]}(a)) & \quad\Leftrightarrow\quad \tuple{x, y} \in \hat{\val}(\term[3]^{\lop} a \term[3]^{\lop})\\
              & \quad\Leftrightarrow\quad \tuple{x, y} \in \hat{\val}(\left\{\begin{tikzpicture}[baseline = -.5ex]
                \graph[grow right = 1.2cm, branch down = 6ex, nodes={mynode}]{
                {0/{}[draw, circle]}-!-{1/{}[draw, circle]}
                };
                \node[left = .5em of 0](l){};
                \node[right = .5em of 1](r){};
                \node[above = 1.em of 0](0e0){\scriptsize $\graph[1]$};
                \node[above = 1.em of 1](1e1){\scriptsize $\graph[2]$};
                \graph[use existing nodes, edges={color=black, pos = .5, earrow}, edge quotes={fill=white, inner sep=1pt,font= \scriptsize}]{
                   0 ->["$a$"] 1;
                   0 ->[bend right] 0e0 ->[bend right] 0;
                   1 ->[bend right] 1e1 ->[bend right] 1;
                   l -> 0; 1 -> r;
                };
         \end{tikzpicture} \mid \graph[1],\graph[2] \in \glang(\term[3]^{\lop}) \right\}) \tag{\Cref{prop: glang}}                           \\
                                             & \quad\Leftrightarrow\quad \tuple{x, y} \in \hat{\val}(\glang_{\term[3]}(a)). \tag{Definition of $\glang_{\term[3]}$}
       \end{align*}

       Case $\eps$:
       For every $\tuple{x, y} \in \hat{\val}(\top)$, we have
       \begin{align*}
              \tuple{x, y} \in \hat{\val}(\Tr_{\term[3]}(\eps))  & \quad\Leftrightarrow\quad \tuple{x, y} \in \hat{\val}(\term[3]^{\lop})\\
              & \quad\Leftrightarrow\quad \tuple{x, y} \in \hat{\val}(\left\{\begin{tikzpicture}[baseline = -.5ex]
                \graph[grow right = 1.2cm, branch down = 6ex, nodes={mynode}]{
                {0/{}[draw, circle]}
                };
                \node[left = .5em of 0](l){};
                \node[right = .5em of 0](r){};
                \node[above = 1.em of 0](0e0){\scriptsize $\graph[1]$};
                \graph[use existing nodes, edges={color=black, pos = .5, earrow}, edge quotes={fill=white, inner sep=1pt,font= \scriptsize}]{
                   0 ->[bend right] 0e0 ->[bend right] 0;
                   l -> 0; 0 -> r;
                };
         \end{tikzpicture} \mid \graph[1] \in \glang(\term[3]^{\lop}) \right\}) \tag{\Cref{prop: glang}}                           \\
                                                & \quad\Leftrightarrow\quad \tuple{x, y} \in \hat{\val}(\glang_{\term[3]}(\eps)). \tag{Definition of $\glang_{\term[3]}$}
       \end{align*}

       Case $\emp$:
       For every $\tuple{x, y}$, we have
       \begin{align*}
              \tuple{x, y} \in \hat{\val}(\emp) & \Leftrightarrow \const{false}  \Leftrightarrow \tuple{x, y} \in \hat{\val}(\emptyset) \Leftrightarrow \tuple{x, y} \in \hat{\val}(\glang_{\term[3]}(\emp)). \tag{Definition of $\hat{\val}$ and $\glang_{\term[3]}$}
       \end{align*}

       Case $\term[1] \compo \term[2]$:
       \begin{align*}
              &\hat{\val}(\Tr_{\term[3]}(\term[1] \compo \term[2])) \\
              & \quad=\quad \hat{\val}(\Tr_{\term[3]}(\term[1])) \compo \hat{\val}(\Tr_{\term[3]}(\term[2]))  \tag{Definition of $\hat{\val}$}                                                                                                                     \\
                                                  & \quad=\quad \hat{\val}(\glang_{\term[3]}(\term[1])) \compo \hat{\val}(\glang_{\term[3]}(\term[2]))          \tag{IH}                                                                                                                \\
                                                  & \quad=\quad \bigcup_{\substack{ \graph[1] \in \glang(\term[1])\\\graph[2] \in \glang(\term[2])}}
                                                  \bigcup_{\substack{f \colon \domain{\graph[1]} \to \glang(\term[3]^{\lop}),\\
                                                  g \colon \domain{\graph[2]} \to \glang(\term[3]^{\lop})}}
                                                  \hat{\val}(\graph[1][f]) \compo \hat{\val}(\graph[2][g])                 \tag{$\compo$ is distributive with respect to $\cup$} \\
                                                  & \quad=\quad \bigcup_{\substack{ \graph[1] \in \glang(\term[1])\\\graph[2] \in \glang(\term[2])}}
                                                  \bigcup_{\substack{f \colon \domain{\graph[1]} \to \glang(\term[3]^{\lop}),\\
                                                  g \colon \domain{\graph[2]} \to \glang(\term[3]^{\lop})}} \hat{\val}(\graph[1][f] \compo \graph[2][g]) \tag{\Cref{lem: glang val compo}}                                      \\
                                                  & \quad=\quad \bigcup_{\substack{ \graph[1] \in \glang(\term[1])\\\graph[2] \in \glang(\term[2])}}
                                                  \bigcup_{\substack{h \colon \domain{\graph[1] \compo \graph[2]} \to \glang(\term[3]^{\lop})}}          \hat{\val}((\graph[1] \compo \graph
                                                  [2])[h])
                                                  \tag{\ref{lem: glang val compo u}}\\
                                                  & \quad=\quad \hat{\val}(\glang_{\term[3]}(\term[1] \compo \term[2])). \tag{Definition of $\glang_{\term[3]}$}
       \end{align*}

       Case $\term[1] \cap \term[2]$:
       \begin{align*}
             & \hat{\val}(\Tr_{\term[3]}(\term[1] \cap \term[2])) \\
             & \quad=\quad \hat{\val}(\Tr_{\term[3]}(\term[1])) \cap \hat{\val}(\Tr_{\term[3]}(\term[2]))                     \tag{Definition of $\hat{\val}$}                                                                                                  \\
                                                 & \quad=\quad \hat{\val}(\glang_{\term[3]}(\term[1])) \cap \hat{\val}(\glang_{\term[3]}(\term[2]))            \tag{IH}                                                                                                              \\
                                                 &\quad=\quad \bigcup_{\substack{ \graph[1] \in \glang(\term[1])\\\graph[2] \in \glang(\term[2])}}
                                                 \bigcup_{\substack{f \colon \domain{\graph[1]} \to \glang(\term[3]^{\lop}),\\
                                                 g \colon \domain{\graph[2]} \to \glang(\term[3]^{\lop})}}
                                                 \hat{\val}(\graph[1][f]) \cap \hat{\val}(\graph[2][g])           \tag{$\cap$ is distributive with respect to $\cup$} \\
                                                 & \quad=\quad \bigcup_{\substack{ \graph[1] \in \glang(\term[1])\\\graph[2] \in \glang(\term[2])}}
                                                 \bigcup_{\substack{f \colon \domain{\graph[1]} \to \glang(\term[3]^{\lop}),\\
                                                 g \colon \domain{\graph[2]} \to \glang(\term[3]^{\lop})}} \hat{\val}(\graph[1][f] \cap \graph[2][g]) \tag{\Cref{lem: glang val cap}}                                       \\
                                                 & \quad=\quad \bigcup_{\substack{ \graph[1] \in \glang(\term[1])\\\graph[2] \in \glang(\term[2])}}
                                                 \bigcup_{\substack{h \colon \domain{\graph[1] \cap \graph[2]} \to \glang(\term[3]^{\lop})}}          \hat{\val}((\graph[1] \cap \graph
                                                 [2])[h])
                                                 \tag{\ref{lem: glang val cap u}}\\
                                                 & \quad=\quad \hat{\val}(\glang_{\term[3]}(\term[1] \cap \term[2])). \tag{Definition of $\glang_{\term[3]}$}
       \end{align*}

       Case $\term[1] \union \term[2]$:
       \begin{align*}
              \hat{\val}(\Tr_{\term[3]}(\term[1] \union \term[2])) & \quad=\quad \hat{\val}(\Tr_{\term[3]}(\term[1])) \cup \hat{\val}(\Tr_{\term[3]}(\term[2]))                     \tag{Definition of $\hat{\val}$} \\
                                                 & \quad=\quad \hat{\val}(\glang_{\term[3]}(\term[1])) \cup \hat{\val}(\glang_{\term[3]}(\term[2]))            \tag{IH}             \\
                                                 & \quad=\quad \hat{\val}(\glang_{\term[3]}(\term[1]) \cup \glang_{\term[3]}(\term[2])) = \hat{\val}(\glang_{\term[3]}(\term[1] \union \term[2])). \tag{Definition of $\glang_{\term[3]}$}
       \end{align*}

       Case $\term[1]^*$:

       \begin{align*}
             \hat{\val}(\Tr_{\term[3]}(\term[1]^{*})) &\quad=\quad \hat{\val}(\Tr_{\term[3]}(\term[1])^{*} \compo \term[3]^{\lop}) \tag{Definition of $\hat{\val}$} \\
             &\quad=\quad \hat{\val}(\Tr_{\term[3]}(\term[1])^{+} \union \term[3]^{\lop})  \\
             &\quad=\quad \hat{\val}(\glang_{\term[3]}(\term[1])^+) \cup \hat{\val}(\term[3]^{\lop})       \tag{IH}                                                                  \\
             &\quad=\quad \hat{\val}(\glang_{\term[3]}(\term[1]^+)) \cup \hat{\val}(\term[3]^{\lop})      \tag{By the same argument as that for Case $\term \compo \term[2]$}    \\
             &\quad=\quad \hat{\val}(\glang_{\term[3]}(\term[1]^*)).      \tag{Definition of $\glang_{\term[3]}$}
       \end{align*}
\end{proof}

\section{Note: the equational theories with respect to DREL and REL coincide for propositional while programs}\label{section: DREL KAT}
In this section, we note that the equational theories with respect to $\DREL$ and $\REL$ coincide for propositional while programs.
We use this fact in \Cref{table: complexity SDIPDL}.
This equivalence holds even for \emph{\kl{regular programs}}.
We recall $\mathrm{B}$ the set of \kl{tests} given in \Cref{section: syntax}.
The set of \intro*\kl{regular programs} is the minimal subset $\mathrm{W} \subseteq \PCoR_{\set{\bl^{*}}}$ satisfying the following:
\begin{gather*}
    \begin{prooftree}[separation = .5em]
        \hypo{b \in \mathrm{B}}
        \infer1{b \in \mathrm{W}}
    \end{prooftree}
    \quad
    \begin{prooftree}[separation = .5em]
        \hypo{x \in \asig}
        \infer1{x \in \mathrm{W}}
    \end{prooftree}
    \quad
    \begin{prooftree}[separation = .5em]
        \hypo{\term[1] \in \mathrm{W}}
        \hypo{\term[2] \in \mathrm{W}}
        \infer2{\term[1] \compo \term[2] \in \mathrm{W}}
    \end{prooftree}
    \quad
    \begin{prooftree}[separation = .5em]
        \hypo{\term[1] \in \mathrm{W}}
        \hypo{\term[2] \in \mathrm{W}}
        \infer2{\term[1] \union \term[2] \in \mathrm{W}}
    \end{prooftree}
    \quad
    \begin{prooftree}[separation = .5em]
        \hypo{\term[1] \in \mathrm{W}}
        \infer1{\term[1]^{*} \in \mathrm{W}}
    \end{prooftree}.
\end{gather*}
We then have the following.
\begin{prop}\label{prop: KAT DREL and REL}
For \kl{regular programs} $\term[1]$ and $\term[2]$, we have the following:
\[\DREL_{\mathtt{test}} \models \term[1] \le \term[2] \quad\iff\quad \REL_{\mathtt{test}} \models \term[1] \le \term[2].\]
\end{prop}
\begin{proof}
($\Leftarrow$):
By $\DREL_{\mathtt{test}} \subseteq \REL_{\mathtt{test}}$.
($\Rightarrow$):
We show the contraposition.
Let $\tuple{x, y} \in \hat{\val}(\term[1]) \setminus \hat{\val}(\term[2])$ where $\val \in \REL_{\mathtt{test}}$.
By \Cref{prop: glang},
there is some \kl{graph homomorphism} $f$ from some \kl{graph} $\graph[2] \in \glang(\term[1])$ into $\const{G}(\val, x, y)$.
By the definition of $\glang(\term[1])$, the \kl{graph} $\graph[2]$ is a path, more precisely, of the following form:
\[\begin{tikzpicture}[baseline = -.5ex]
       \graph[grow up= 1.cm, branch right = 1.5cm, nodes={font=\tiny}]{
       {0/{$0$}[mynode, fill = gray!30],
       1/{$1$}[mynode, fill = gray!30],
       2/{$2$}[mynode, fill = gray!30],
       /{$\dots$},
       nm1/{}[mynode, fill = gray!30],
       n/{$n$}[mynode, fill = gray!30]}
       };
       \node[left = 4pt of 0](0l){}; \path (0l) edge[earrow, ->] (0);
       \node[right = 4pt of n](nr){}; \path (n) edge[earrow, ->] (nr);
       \graph[use existing nodes, edges={color=black, pos = .5, earrow}, edge quotes={fill = white, inner sep=1pt,font= \scriptsize}]{
       (0) ->["$a_1$"] (1) ->["$a_2$"] (2); (nm1) ->["$a_{n}$"] (n);
       };
\end{tikzpicture}.\]
Let $\graph[2]'$ be the \kl{graph} $\graph[2]$ obtained by merging all adjacent \kl{vertices} $i-1$ and $i$ such that $a_i \in \psig$.
The \kl{graph} $\graph[2]'$ is of the following form (up to \kl{graph isomorphisms}):
\[\begin{tikzpicture}[baseline = -.5ex]
       \graph[grow up= 1.cm, branch right = 1.5cm, nodes={font=\tiny}]{
       {0/{$0$}[mynode, fill = gray!30],
       1/{$1$}[mynode, fill = gray!30],
       2/{$2$}[mynode, fill = gray!30],
       /{$\dots$},
       nm1/{}[mynode, fill = gray!30],
       n/{$m$}[mynode, fill = gray!30]}
       };
       \node[left = 4pt of 0](0l){}; \path (0l) edge[earrow, ->] (0);
       \node[right = 4pt of n](nr){}; \path (n) edge[earrow, ->] (nr);
       \graph[use existing nodes, edges={color=black, pos = .5, earrow}, edge quotes={fill = white, inner sep=1pt,font= \scriptsize}]{
       (0) ->["$a_1'$"] (1) ->["$a_2'$"] (2); (nm1) ->["$a_{m}'$"] (n);
       0 ->["$P_0$",out = 60, in = 120, looseness = 8] 0;
       1 ->["$P_1$",out = 60, in = 120, looseness = 8] 1;
       2 ->["$P_2$",out = 60, in = 120, looseness = 8] 2;
       n ->["$P_m$",out = 60, in = 120, looseness = 8] n;
       };
\end{tikzpicture},\]
where $P_i \subseteq \psig$ and $a_i' \in \asig$.
By the map $f$ with $\hat{\val}(p) \subseteq \hat{\val}(\eps)$ for each $p \in \psig$,
we have $\graph[2]' \homo \const{G}(\val, x, y)$.
From $\graph[2]'$,
we define the \kl{valuation} $\val' \colon \vsig \to \range{0, m}$ so that
\begin{itemize}
\item $\hat{\val}'(p) \defeq \set{\tuple{i, i} \mid i \in \range{0, m} \mbox{ and } \tuple{f'(i), f'(i)} \in \hat{\val}(p)}$ for $p \in \psig$, and
\item $\hat{\val}'(a) \defeq \set{\tuple{i-1, i} \mid i \in \range{1,m} \mbox{ and } a_i' = a}$ for $a \in \asig$.
\end{itemize}
By construction, $\val' \in \DREL_{\mathtt{test}}$.
We then have $\graph[2]' \homo \const{G}(\val', 0, m)$ by the identity map, and hence $\graph[2] \homo \const{G}(\val', 0, m)$.
We thus have $\tuple{0, m} \in \hat{\val}'(\term[1])$ by \Cref{prop: glang}.
Also,
by $\const{G}(\val', 0, m) \homo \const{G}(\val, x, y)$ and $\tuple{x, y} \not\in \hat{\val}(\term[2])$,
we have $\tuple{0, m} \not\in \hat{\val}'(\term[2])$.
Thus, $\tuple{0, m} \in \hat{\val}'(\term[1]) \setminus \hat{\val}'(\term[2])$.
Hence, this completes the proof.
\end{proof}
Consequently, by combining with \cite[Theorems 6]{kozenKleeneAlgebraTests1996}, we have:
\[\DREL_{\mathtt{test}} \models \term[1] \le \term[2] 
\quad\iff\quad \REL_{\mathtt{test}} \models \term[1] \le \term[2]
\quad\iff\quad G(\term[1]) \subseteq G(\term[2]).\]
Here, $G(\term)$ is the guarded string language \cite[Section 3.1]{kozenKleeneAlgebraTests1996} of a \kl{regular program} $\term$ where,
precisely, the definition for \kl{primitive tests} is replaced
as follows (assuming $\psig = \set{p_0, \dots, p_{2n - 1}}$ and 
$\tilde{p_i} = p_{n+1}$):
\begin{align*}
G(p_i) &\defeq \set{P \subseteq \set{p_0, \dots, p_{n-1}} \mid p \in P}, & 
G(\tilde{p_i}) &\defeq \set{P \subseteq \set{p_0, \dots, p_{n-1}} \mid p \not\in P}
\end{align*}
for $i \in \range{0, n-1}$.
Hence, the \kl{equational theory} above can be characterized 
by \kl[equational theory]{that} of Kleene algebra with tests \cite[Theorem 8]{kozenKleeneAlgebraTests1996}.

